// v0 - Unaudited: This is an initial version that has not yet been formally audited.
// A fully audited version will be published as a subsequent release.
// Use in production at your own risk.
//
// Package avl provides a gas-efficient AVL tree implementation for storing
// key-value data in Gno realms.
package avl

package avl

//----------------------------------------
// Node

// Node represents a node in an AVL tree.
type Node struct {
	key       string // key is the unique identifier for the node.
	value     any    // value is the data stored in the node.
	height    int8   // height is the height of the node in the tree.
	size      int    // size is the number of leaf nodes (key-value pairs) in the subtree rooted at this node.
	leftNode  *Node  // leftNode is the left child of the node.
	rightNode *Node  // rightNode is the right child of the node.
}

// NewNode creates a new node with the given key and value.
func NewNode(key string, value any) *Node {
	return &Node{
		key:    key,
		value:  value,
		height: 0,
		size:   1,
	}
}

// Size returns the size of the subtree rooted at the node.
func (node *Node) Size() int {
	if node == nil {
		return 0
	}
	return node.size
}

// IsLeaf checks if the node is a leaf node (has no children).
func (node *Node) IsLeaf() bool {
	return node.height == 0
}

// Key returns the key of the node.
func (node *Node) Key() string {
	return node.key
}

// Value returns the value of the node.
func (node *Node) Value() any {
	return node.value
}

func (node *Node) _copy() *Node {
	if node.height == 0 {
		panic("Why are you copying a value node?")
	}
	return &Node{
		key:       node.key,
		height:    node.height,
		size:      node.size,
		leftNode:  node.leftNode,
		rightNode: node.rightNode,
	}
}

// Has checks if a node with the given key exists in the subtree rooted at the node.
func (node *Node) Has(key string) (has bool) {
	if node == nil {
		return false
	}
	if node.key == key {
		return true
	}
	if node.height == 0 {
		return false
	} else {
		if key < node.key {
			return node.getLeftNode().Has(key)
		} else {
			return node.getRightNode().Has(key)
		}
	}
}

// Get searches for a node with the given key in the subtree rooted at the node
// and returns its index, value, and whether it exists.
func (node *Node) Get(key string) (index int, value any, exists bool) {
	if node == nil {
		return 0, nil, false
	}

	if node.height == 0 {
		if node.key == key {
			return 0, node.value, true
		} else if node.key < key {
			return 1, nil, false
		} else {
			return 0, nil, false
		}
	} else {
		if key < node.key {
			return node.getLeftNode().Get(key)
		} else {
			rightNode := node.getRightNode()
			index, value, exists = rightNode.Get(key)
			index += node.size - rightNode.size
			return index, value, exists
		}
	}
}

// GetByIndex retrieves the key-value pair of the node at the given index
// in the subtree rooted at the node.
func (node *Node) GetByIndex(index int) (key string, value any) {
	if node.height == 0 {
		if index == 0 {
			return node.key, node.value
		} else {
			panic("GetByIndex asked for invalid index")
		}
	} else {
		// TODO: could improve this by storing the sizes
		leftNode := node.getLeftNode()
		if index < leftNode.size {
			return leftNode.GetByIndex(index)
		} else {
			return node.getRightNode().GetByIndex(index - leftNode.size)
		}
	}
}

// Set inserts a new node with the given key-value pair into the subtree rooted at the node,
// and returns the new root of the subtree and whether an existing node was updated.
//
// XXX consider a better way to do this... perhaps split Node from Node.
func (node *Node) Set(key string, value any) (newSelf *Node, updated bool) {
	if node == nil {
		return NewNode(key, value), false
	}
	if node.height == 0 {
		if key < node.key {
			return &Node{
				key:       node.key,
				height:    1,
				size:      2,
				leftNode:  NewNode(key, value),
				rightNode: node,
			}, false
		} else if key == node.key {
			return NewNode(key, value), true
		} else {
			return &Node{
				key:       key,
				height:    1,
				size:      2,
				leftNode:  node,
				rightNode: NewNode(key, value),
			}, false
		}
	} else {
		node = node._copy()
		if key < node.key {
			node.leftNode, updated = node.getLeftNode().Set(key, value)
		} else {
			node.rightNode, updated = node.getRightNode().Set(key, value)
		}
		if updated {
			return node, updated
		} else {
			node.calcHeightAndSize()
			return node.balance(), updated
		}
	}
}

// Remove deletes the node with the given key from the subtree rooted at the node.
// returns the new root of the subtree, the new leftmost leaf key (if changed),
// the removed value and the removal was successful.
func (node *Node) Remove(key string) (
	newNode *Node, newKey string, value any, removed bool,
) {
	if node == nil {
		return nil, "", nil, false
	}
	if node.height == 0 {
		if key == node.key {
			return nil, "", node.value, true
		} else {
			return node, "", nil, false
		}
	} else {
		if key < node.key {
			var newLeftNode *Node
			newLeftNode, newKey, value, removed = node.getLeftNode().Remove(key)
			if !removed {
				return node, "", value, false
			} else if newLeftNode == nil { // left node held value, was removed
				return node.rightNode, node.key, value, true
			}
			node = node._copy()
			node.leftNode = newLeftNode
			node.calcHeightAndSize()
			node = node.balance()
			return node, newKey, value, true
		} else {
			var newRightNode *Node
			newRightNode, newKey, value, removed = node.getRightNode().Remove(key)
			if !removed {
				return node, "", value, false
			} else if newRightNode == nil { // right node held value, was removed
				return node.leftNode, "", value, true
			}
			node = node._copy()
			node.rightNode = newRightNode
			if newKey != "" {
				node.key = newKey
			}
			node.calcHeightAndSize()
			node = node.balance()
			return node, "", value, true
		}
	}
}

func (node *Node) getLeftNode() *Node {
	return node.leftNode
}

func (node *Node) getRightNode() *Node {
	return node.rightNode
}

// rotateRight performs a right rotation on the node and returns the new root.
// NOTE: overwrites node
// TODO: optimize balance & rotate
func (node *Node) rotateRight() *Node {
	node = node._copy()
	l := node.getLeftNode()
	_l := l._copy()

	_lrCached := _l.rightNode
	_l.rightNode = node
	node.leftNode = _lrCached

	node.calcHeightAndSize()
	_l.calcHeightAndSize()

	return _l
}

// rotateLeft performs a left rotation on the node and returns the new root.
// NOTE: overwrites node
// TODO: optimize balance & rotate
func (node *Node) rotateLeft() *Node {
	node = node._copy()
	r := node.getRightNode()
	_r := r._copy()

	_rlCached := _r.leftNode
	_r.leftNode = node
	node.rightNode = _rlCached

	node.calcHeightAndSize()
	_r.calcHeightAndSize()

	return _r
}

// calcHeightAndSize updates the height and size of the node based on its children.
// NOTE: mutates height and size
func (node *Node) calcHeightAndSize() {
	node.height = maxInt8(node.getLeftNode().height, node.getRightNode().height) + 1
	node.size = node.getLeftNode().size + node.getRightNode().size
}

// calcBalance calculates the balance factor of the node.
func (node *Node) calcBalance() int {
	return int(node.getLeftNode().height) - int(node.getRightNode().height)
}

// balance balances the subtree rooted at the node and returns the new root.
// NOTE: assumes that node can be modified
// TODO: optimize balance & rotate
func (node *Node) balance() (newSelf *Node) {
	balance := node.calcBalance()
	if balance > 1 {
		if node.getLeftNode().calcBalance() >= 0 {
			// Left Left Case
			return node.rotateRight()
		} else {
			// Left Right Case
			left := node.getLeftNode()
			node.leftNode = left.rotateLeft()
			return node.rotateRight()
		}
	}
	if balance < -1 {
		if node.getRightNode().calcBalance() <= 0 {
			// Right Right Case
			return node.rotateLeft()
		} else {
			// Right Left Case
			right := node.getRightNode()
			node.rightNode = right.rotateRight()
			return node.rotateLeft()
		}
	}
	// Nothing changed
	return node
}

// Shortcut for TraverseInRange.
func (node *Node) Iterate(start, end string, cb func(*Node) bool) bool {
	return node.TraverseInRange(start, end, true, true, cb)
}

// Shortcut for TraverseInRange.
func (node *Node) ReverseIterate(start, end string, cb func(*Node) bool) bool {
	return node.TraverseInRange(start, end, false, true, cb)
}

// TraverseInRange traverses all nodes, including inner nodes.
// Start is inclusive and end is exclusive when ascending,
// Start and end are inclusive when descending.
// Empty start and empty end denote no start and no end.
// If leavesOnly is true, only visit leaf nodes.
// NOTE: To simulate an exclusive reverse traversal,
// just append 0x00 to start.
func (node *Node) TraverseInRange(start, end string, ascending bool, leavesOnly bool, cb func(*Node) bool) bool {
	if node == nil {
		return false
	}
	afterStart := (start == "" || start < node.key)
	startOrAfter := (start == "" || start <= node.key)
	beforeEnd := false
	if ascending {
		beforeEnd = (end == "" || node.key < end)
	} else {
		beforeEnd = (end == "" || node.key <= end)
	}

	// Run callback per inner/leaf node.
	stop := false
	if (!node.IsLeaf() && !leavesOnly) ||
		(node.IsLeaf() && startOrAfter && beforeEnd) {
		stop = cb(node)
		if stop {
			return stop
		}
	}
	if node.IsLeaf() {
		return stop
	}

	if ascending {
		// check lower nodes, then higher
		if afterStart {
			stop = node.getLeftNode().TraverseInRange(start, end, ascending, leavesOnly, cb)
		}
		if stop {
			return stop
		}
		if beforeEnd {
			stop = node.getRightNode().TraverseInRange(start, end, ascending, leavesOnly, cb)
		}
	} else {
		// check the higher nodes first
		if beforeEnd {
			stop = node.getRightNode().TraverseInRange(start, end, ascending, leavesOnly, cb)
		}
		if stop {
			return stop
		}
		if afterStart {
			stop = node.getLeftNode().TraverseInRange(start, end, ascending, leavesOnly, cb)
		}
	}

	return stop
}

// TraverseByOffset traverses all nodes, including inner nodes.
// A limit of math.MaxInt means no limit.
func (node *Node) TraverseByOffset(offset, limit int, ascending bool, leavesOnly bool, cb func(*Node) bool) bool {
	if node == nil {
		return false
	}

	// fast paths. these happen only if TraverseByOffset is called directly on a leaf.
	if limit <= 0 || offset >= node.size {
		return false
	}
	if node.IsLeaf() {
		if offset > 0 {
			return false
		}
		return cb(node)
	}

	// go to the actual recursive function.
	return node.traverseByOffset(offset, limit, ascending, leavesOnly, cb)
}

// TraverseByOffset traverses the subtree rooted at the node by offset and limit,
// in either ascending or descending order, and applies the callback function to each traversed node.
// If leavesOnly is true, only leaf nodes are visited.
func (node *Node) traverseByOffset(offset, limit int, ascending bool, leavesOnly bool, cb func(*Node) bool) bool {
	// caller guarantees: offset < node.size; limit > 0.
	if !leavesOnly {
		if cb(node) {
			return true // Stop traversal if callback returns true
		}
	}
	first, second := node.getLeftNode(), node.getRightNode()
	if !ascending {
		first, second = second, first
	}
	if first.IsLeaf() {
		// either run or skip, based on offset
		if offset > 0 {
			offset--
		} else {
			if cb(first) {
				return true // Stop traversal if callback returns true
			}
			limit--
			if limit <= 0 {
				return true // Stop traversal when limit is reached
			}
		}
	} else {
		// possible cases:
		// 1 the offset given skips the first node entirely
		// 2 the offset skips none or part of the first node, but the limit requires some of the second node.
		// 3 the offset skips none or part of the first node, and the limit stops our search on the first node.
		if offset >= first.size {
			offset -= first.size // 1
		} else {
			if first.traverseByOffset(offset, limit, ascending, leavesOnly, cb) {
				return true
			}
			// number of leaves which could actually be called from inside
			delta := first.size - offset
			offset = 0
			if delta >= limit {
				return true // 3
			}
			limit -= delta // 2
		}
	}

	// because of the caller guarantees and the way we handle the first node,
	// at this point we know that limit > 0 and there must be some values in
	// this second node that we include.

	// => if the second node is a leaf, it has to be included.
	if second.IsLeaf() {
		return cb(second)
	}
	// => if it is not a leaf, it will still be enough to recursively call this
	// function with the updated offset and limit
	return second.traverseByOffset(offset, limit, ascending, leavesOnly, cb)
}

// Only used in testing...
func (node *Node) lmd() *Node {
	if node.height == 0 {
		return node
	}
	return node.getLeftNode().lmd()
}

// Only used in testing...
func (node *Node) rmd() *Node {
	if node.height == 0 {
		return node
	}
	return node.getRightNode().rmd()
}

func maxInt8(a, b int8) int8 {
	if a > b {
		return a
	}
	return b
}

package avl

type ITree interface {
	// read operations

	Size() int
	Has(key string) bool
	Get(key string) (value any, exists bool)
	GetByIndex(index int) (key string, value any)
	Iterate(start, end string, cb IterCbFn) bool
	ReverseIterate(start, end string, cb IterCbFn) bool
	IterateByOffset(offset int, count int, cb IterCbFn) bool
	ReverseIterateByOffset(offset int, count int, cb IterCbFn) bool

	// write operations

	Set(key string, value any) (updated bool)
	Remove(key string) (value any, removed bool)
}

type IterCbFn func(key string, value any) bool

//----------------------------------------
// Tree

// The zero struct can be used as an empty tree.
type Tree struct {
	node *Node
}

// NewTree creates a new empty AVL tree.
func NewTree() *Tree {
	return &Tree{
		node: nil,
	}
}

// Size returns the number of key-value pair in the tree.
func (tree *Tree) Size() int {
	return tree.node.Size()
}

// Has checks whether a key exists in the tree.
// It returns true if the key exists, otherwise false.
func (tree *Tree) Has(key string) (has bool) {
	return tree.node.Has(key)
}

// Get retrieves the value associated with the given key.
// It returns the value and a boolean indicating whether the key exists.
func (tree *Tree) Get(key string) (value any, exists bool) {
	_, value, exists = tree.node.Get(key)
	return
}

// GetByIndex retrieves the key-value pair at the specified index in the tree.
// It returns the key and value at the given index.
func (tree *Tree) GetByIndex(index int) (key string, value any) {
	return tree.node.GetByIndex(index)
}

// Set inserts a key-value pair into the tree.
// If the key already exists, the value will be updated.
// It returns a boolean indicating whether the key was newly inserted or updated.
func (tree *Tree) Set(key string, value any) (updated bool) {
	newnode, updated := tree.node.Set(key, value)
	tree.node = newnode
	return updated
}

// Remove removes a key-value pair from the tree.
// It returns the removed value and a boolean indicating whether the key was found and removed.
func (tree *Tree) Remove(key string) (value any, removed bool) {
	newnode, _, value, removed := tree.node.Remove(key)
	tree.node = newnode
	return value, removed
}

// Iterate performs an in-order traversal of the tree within the specified key range.
// It calls the provided callback function for each key-value pair encountered.
// If the callback returns true, the iteration is stopped.
func (tree *Tree) Iterate(start, end string, cb IterCbFn) bool {
	return tree.node.TraverseInRange(start, end, true, true,
		func(node *Node) bool {
			return cb(node.Key(), node.Value())
		},
	)
}

// ReverseIterate performs a reverse in-order traversal of the tree within the specified key range.
// It calls the provided callback function for each key-value pair encountered.
// If the callback returns true, the iteration is stopped.
func (tree *Tree) ReverseIterate(start, end string, cb IterCbFn) bool {
	return tree.node.TraverseInRange(start, end, false, true,
		func(node *Node) bool {
			return cb(node.Key(), node.Value())
		},
	)
}

// IterateByOffset performs an in-order traversal of the tree starting from the specified offset.
// It calls the provided callback function for each key-value pair encountered, up to the specified count.
// If the callback returns true, the iteration is stopped.
func (tree *Tree) IterateByOffset(offset int, count int, cb IterCbFn) bool {
	return tree.node.TraverseByOffset(offset, count, true, true,
		func(node *Node) bool {
			return cb(node.Key(), node.Value())
		},
	)
}

// ReverseIterateByOffset performs a reverse in-order traversal of the tree starting from the specified offset.
// It calls the provided callback function for each key-value pair encountered, up to the specified count.
// If the callback returns true, the iteration is stopped.
func (tree *Tree) ReverseIterateByOffset(offset int, count int, cb IterCbFn) bool {
	return tree.node.TraverseByOffset(offset, count, false, true,
		func(node *Node) bool {
			return cb(node.Key(), node.Value())
		},
	)
}

// Verify that Tree implements TreeInterface
var _ ITree = (*Tree)(nil)

// Admin operations — DAO-gated, with a 2-step admin handoff and a hard fee ceiling.
// There is intentionally NO Pause() here (see config.gno SAFETY note): pausing the
// fee spine would brick every engine at once. Per-engine Pause() is the kill switch.
package memba_market_config

import (
	"strconv"

	"chain"
)

func itoa(n int64) string { return strconv.FormatInt(n, 10) }

func assertAdmin() {
	if caller() != admin {
		panic("admin only")
	}
}

// SetFeeBPS sets a lane's protocol fee in basis points, clamped to [0, MaxFeeBPS].
// A value above the 5% ceiling is rejected so a misconfiguration can never overcharge.
func SetFeeBPS(cur realm, lane string, bps int64) {
	assertAdmin()
	if lane == "" {
		panic("empty lane")
	}
	if bps < 0 || bps > MaxFeeBPS {
		panic("feeBPS out of range")
	}
	feeByLane.Set(lane, bps)
	chain.Emit("FeeBPSChanged", "lane", lane, "bps", itoa(bps))
}

// SetTreasury repoints where every lane's protocol fee flows.
func SetTreasury(cur realm, addr address) {
	assertAdmin()
	if addr == "" {
		panic("empty treasury")
	}
	treasury = addr
	chain.Emit("TreasuryChanged", "treasury", addr.String())
}

// TransferAdmin proposes a new admin (the memba_dao executor). The 2-step handoff
// requires the new admin to AcceptAdmin, so a transfer to a wrong or uncontrolled
// address cannot lock the realm.
func TransferAdmin(cur realm, newAdmin address) {
	assertAdmin()
	if newAdmin == "" {
		panic("empty admin")
	}
	if !newAdmin.IsValid() {
		panic("invalid address: " + newAdmin.String())
	}
	if newAdmin == admin {
		panic("newAdmin is the current admin")
	}
	pendingAdmin = newAdmin
	chain.Emit("AdminTransferProposed", "pending", newAdmin.String())
}

// CancelAdminTransfer withdraws a staged handoff. Admin only.
func CancelAdminTransfer(cur realm) {
	assertAdmin()
	if pendingAdmin == "" {
		panic("no pending admin")
	}
	cancelled := pendingAdmin
	pendingAdmin = ""
	chain.Emit("AdminTransferCancelled", "pending", cancelled.String())
}

// AcceptAdmin completes the handoff. Only the pending admin can call it.
func AcceptAdmin(cur realm) {
	if pendingAdmin == "" {
		panic("no pending admin")
	}
	if caller() != pendingAdmin {
		panic("not pending admin")
	}
	admin = pendingAdmin
	pendingAdmin = ""
	chain.Emit("AdminAccepted", "admin", admin.String())
}

// GetPendingAdmin returns the staged successor, or the empty address.
func GetPendingAdmin() address { return pendingAdmin }

// Package memba_market_config is the DAO-owned fee spine for the Memba marketplace.
// It is the single source of truth for the per-lane protocol fee (basis points) and
// the treasury that receives it. Every trade engine (NFT, services, token-OTC, agents)
// reads GetFeeBPS(lane) + GetTreasury() at settlement, so the DAO sets the rate ONCE
// and it applies everywhere — that shared read is what makes the lanes one marketplace.
//
// SAFETY (panel finding C1): the read getters are PURE and NON-FAILING — they never
// panic, and there is intentionally NO Pause(). A per-trade cross-realm read that
// could fail or halt would be a single point of failure able to brick every engine at
// once; instead an engine always gets a usable, bounded value here and clamps locally,
// while each engine keeps its OWN Pause() as the real kill switch. The fee is bounded
// to [0, MaxFeeBPS] on write, so a reader can trust the bound without re-checking.
package memba_market_config

import (
	"chain"
	"chain/runtime/unsafe"

	"gno.land/p/samcrew/avl"
)

// No authority address is compiled in. The publishing transaction's signer (on
// gnoland-1 the samcrew namespace multisig, the stamped creator at enable time)
// is seeded as admin AND treasury at package load; the DAO takes over through the
// two-step TransferAdmin/AcceptAdmin and repoints fees with SetTreasury.
//
// Under `gno test` every package is initialized with an empty origin caller, and
// this realm is read cross-realm by every engine's test suite, so an empty seed
// would leave the engines' fee-spine tests nothing to assert against. In that
// one case the seed becomes unseededAuthority: a sub-address of this realm that
// no code ever mints, so no on-chain caller can ever be it, while a test can
// impersonate it with testing.NewUserRealm. On chain the origin caller at load
// is never empty, so this branch is unreachable there.

const (
	// MaxFeeBPS is the 5% hard ceiling. SetFeeBPS rejects anything above it, so a
	// fat-finger or a compromised proposal can never make a lane overcharge.
	MaxFeeBPS = int64(500)
	// DefaultFeeBPS is returned for an unset/unknown lane so engines always get a
	// usable value (2.0%).
	DefaultFeeBPS = int64(200)
)

var (
	admin        address
	pendingAdmin address
	treasury     address
	feeByLane    = avl.NewTree() // lane string -> int64 bps
)

// unseededAuthority is the test-VM stand-in for a publisher; see the note above.
var unseededAuthority = chain.DerivePkgSubAddr("gno.land/r/samcrew/memba_market_config", "unseeded")

// seedAuthority makes the publisher admin and treasury. It runs once at load.
func seedAuthority(publisher address) {
	if publisher == "" {
		publisher = unseededAuthority
	}
	admin = publisher
	pendingAdmin = ""
	treasury = publisher
}

func init() {
	seedAuthority(unsafe.OriginCaller())
	// Seed the launch lanes. "agent" is intentionally unset (TBD) and resolves to
	// DefaultFeeBPS until the DAO sets it when that lane is built.
	feeByLane.Set("nft", int64(200))     // 2.0%
	feeByLane.Set("service", int64(200)) // 2.0% release fee (the 5% cancel fee is escrow-internal → freelancer)
	feeByLane.Set("token", int64(50))    // 0.5% OTC — competitive vs DEX ~0.3%
}

func caller() address { return unsafe.PreviousRealm().Address() }

// ── Read getters — PURE, NON-FAILING (never panic, no Pause) ──────────────────

// GetFeeBPS returns the protocol fee in basis points for a lane. An unset or unknown
// lane returns DefaultFeeBPS. The result is always within [0, MaxFeeBPS] (enforced on
// write). Never panics — an engine must always be able to settle.
func GetFeeBPS(lane string) int {
	v, ok := feeByLane.Get(lane)
	if !ok {
		return int(DefaultFeeBPS)
	}
	return int(v.(int64))
}

// GetTreasury returns the address that receives the protocol fee on every lane.
func GetTreasury() address { return treasury }

// GetLaneConfig returns (feeBPS, treasury) in one read for an engine's settlement path.
func GetLaneConfig(lane string) (int, address) {
	return GetFeeBPS(lane), treasury
}

// GetAdmin returns the current admin (the multisig, or the memba_dao executor after
// the 2-step handoff).
func GetAdmin() address { return admin }

// Render — public read-only view + audit surface for the fee config.
package memba_market_config

import (
	"strings"

	"gno.land/p/nt/ufmt/v0"
)

func Render(path string) string {
	var sb strings.Builder
	sb.WriteString("# Memba Marketplace — Fee Config\n\n")
	sb.WriteString("DAO-owned per-lane protocol fee + treasury. Engines read this at settlement.\n\n")
	sb.WriteString(ufmt.Sprintf("**Admin:** %s\n", admin.String()))
	if pendingAdmin != "" {
		sb.WriteString(ufmt.Sprintf("**Pending admin:** %s\n", pendingAdmin.String()))
	}
	sb.WriteString(ufmt.Sprintf("**Treasury:** %s\n", treasury.String()))
	sb.WriteString(ufmt.Sprintf("**Fee ceiling:** %d bps (5%%)\n\n", MaxFeeBPS))

	sb.WriteString("| Lane | Fee (bps) |\n|------|-----------|\n")
	feeByLane.Iterate("", "", func(key string, val interface{}) bool {
		sb.WriteString(ufmt.Sprintf("| %s | %d |\n", key, val.(int64)))
		return false
	})
	sb.WriteString(ufmt.Sprintf("\n*Unset lanes default to %d bps.*\n", DefaultFeeBPS))
	return sb.String()
}

package escrow_v4

// Milestone-based escrow: on-chain freelance service contracts for Memba.
// Successor of escrow_v3 with the same user API; see DESIGN.md for what
// changed and why.
//
// Flow: CreateContract → FundMilestone → CompleteMilestone → ReleaseFunds
// Disputes: RaiseDispute → admin ResolveDispute (or ClaimDisputeTimeout after
//           AutoResolveBlks)
// Timeouts: ClaimRefund (a funded milestone nobody completed, after
//           AutoRefundBlks); ExpireUnfunded (a contract never funded, after
//           UnfundedExpiryBlks)
// Cleanup:  ArchiveContract (client deletes a settled contract; the chain
//           refunds the freed storage deposit to the signer)
//
// Invariants:
//   - State is updated before any coins are sent.
//   - realm balance >= TotalLiabilities() (NF-2).
//   - A contract is open until it is completed or cancelled; an open contract
//     holds one of its client's MaxActivePerClient slots.
//   - completed and cancelled are absorbing and hold no escrowed funds.
//
// Caller authentication: every crossing entrypoint checks cur.IsCurrent() and
// reads the caller from cur.Previous(). Every use of the unsafe runtime
// package is in origin.gno. Read-only views are in views.gno.

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/p/samcrew/avl"
	cfg "gno.land/r/samcrew/memba_market_config"
)

// ── Constants ────────────────────────────────────────────────

// laneService is this engine's lane key into the DAO fee spine
// (memba_market_config), seeded there at 200 bps.
const laneService = "service"

const (
	// PlatformFeePct is only the fail-safe fallback rate (see resolveFee); the
	// live rate is cfg.GetFeeBPS(laneService), read at each payout.
	PlatformFeePct = 2
	// CancelFeePct is paid to the freelancer from each funded milestone when
	// the client cancels. Escrow-internal, not a protocol fee.
	CancelFeePct = 5
	// Timeouts, in blocks, as in v3 (sized at 3 s per block; at gnoland-1's
	// ~3.3 s they are ~33 and ~31 days). Blocks inside a pause's blocking
	// window do not count (see the pause section).
	AutoRefundBlks  = int64(864000)
	AutoResolveBlks = int64(806400)
	// UnfundedExpiryBlks: a contract none of whose milestones was ever funded
	// can be cancelled by anyone after this many blocks, freeing its slot.
	UnfundedExpiryBlks = AutoRefundBlks

	MaxTitleLen        = 200  // bytes, after sanitising (also bounds the input)
	MaxDescLen         = 5000 // bytes, after sanitising (also bounds the input)
	MaxMilestones      = 20
	MinMilestoneAmount = int64(1000) // 0.001 GNOT: below ~50 ugnot a 2% fee truncates to 0
	// maxMilestonesArgLen bounds the raw milestones argument before parsing:
	// 20 entries of a 200-byte title, a 19-digit amount and separators, with
	// room for surrounding spaces.
	maxMilestonesArgLen = MaxMilestones * (MaxTitleLen + 64)

	// MaxActivePerClient bounds the open contracts one client address may
	// hold. It counts only contracts the address created, never those naming
	// it as freelancer, so nobody can use up someone else's slots, and it
	// bounds what one key can lock (five of the largest contracts are about
	// 15 GNOT of storage deposit). There is no global cap: nothing iterates
	// over every contract, so a global number would bound no gas and would
	// only give a funded attacker a switch to turn escrow off for everyone.
	MaxActivePerClient = 5
)

// ── Types ────────────────────────────────────────────────────

type ContractStatus string

const (
	StatusActive    ContractStatus = "active"
	StatusCompleted ContractStatus = "completed"
	StatusDisputed  ContractStatus = "disputed"
	StatusCancelled ContractStatus = "cancelled"
)

type MilestoneStatus string

const (
	MsPending   MilestoneStatus = "pending"
	MsFunded    MilestoneStatus = "funded"
	MsCompleted MilestoneStatus = "completed"
	MsReleased  MilestoneStatus = "released"
	MsDisputed  MilestoneStatus = "disputed"
	MsRefunded  MilestoneStatus = "refunded"
)

type Contract struct {
	ID          string
	Client      address
	Freelancer  address
	Title       string
	Description string
	Status      ContractStatus
	CreatedAt   int64 // block height
	Milestones  []Milestone

	createdPauseMark int64 // pausedBlocksAt(CreatedAt), for UnfundedExpiryBlks
}

type Milestone struct {
	ID               int // equals the milestone's index
	Title            string
	Amount           int64 // ugnot
	Status           MilestoneStatus
	FundedAt         int64           // block height (0 if not funded)
	CompletedAt      int64           // block height (0 if not completed)
	DisputedAt       int64           // block height (0 if not disputed)
	PreDisputeStatus MilestoneStatus // status before dispute (MsFunded or MsCompleted)

	fundedPauseMark   int64 // pausedBlocksAt(FundedAt), for AutoRefundBlks
	disputedPauseMark int64 // pausedBlocksAt(DisputedAt), for AutoResolveBlks
}

// ── State ────────────────────────────────────────────────────

var (
	contracts     *avl.Tree // id -> *Contract; live (not archived) contracts only
	clientSlots   *avl.Tree // client address -> int open contracts (removed on archive once 0); "c/<client>/<id>" -> nil client index
	nextID        int       // monotonic, never reused
	activeCount   int       // open contracts
	archivedCount int
	totalLiable   int64 // NF-2: ugnot owed to funded, completed and disputed milestones
)

func init() {
	contracts = avl.NewTree()
	clientSlots = avl.NewTree()
}

// resolveFee reads the "service" lane fee (bps) and treasury from the DAO fee
// spine at payout time. The config getters are pure and non-failing; on an
// out-of-range rate or an empty or malformed treasury this falls back to the
// frozen rate and the realm's fee recipient rather than reverting a payout, so
// a config mistake never strands escrowed funds.
func resolveFee() (int64, address) {
	bps := int64(cfg.GetFeeBPS(laneService))
	if bps < 0 || bps > cfg.MaxFeeBPS {
		bps = int64(PlatformFeePct) * 100
	}
	treasury := cfg.GetTreasury()
	if treasury == "" || !treasury.IsValid() {
		treasury = feeRecipient
	}
	return bps, treasury
}

// callerOf returns the immediate caller of a crossing entrypoint.
func callerOf(cur realm) address {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	return cur.Previous().Address()
}

// ── Contract lifecycle ───────────────────────────────────────

// CreateContract creates a new escrow contract with milestones, as the
// caller's client. Milestones format: "title1:amount1,title2:amount2".
// The caller must be a user (a direct call or the user's own run script), so a
// realm cannot mint client identities with cur.Sub to hold slots.
func CreateContract(cur realm, freelancer address, title, description, milestones string) string {
	assertAcceptsNewMoney()
	caller := callerOf(cur)
	if !cur.Previous().IsUser() {
		panic("CreateContract must be called by a user, not a realm")
	}
	if !freelancer.IsValid() {
		panic("invalid freelancer address")
	}
	if freelancer == caller {
		panic("cannot hire yourself")
	}
	if len(title) == 0 {
		panic(ufmt.Sprintf("title must be 1-%d characters", MaxTitleLen))
	}
	cleanTitle := cleanText(title, "title", MaxTitleLen)
	if strings.TrimSpace(cleanTitle) == "" {
		panic("title must contain visible characters")
	}
	cleanDesc := cleanText(description, "description", MaxDescLen)

	ms := parseMilestones(milestones)
	if len(ms) == 0 {
		panic("at least one milestone required")
	}
	if len(ms) > MaxMilestones {
		panic(ufmt.Sprintf("maximum %d milestones allowed", MaxMilestones))
	}

	takeSlot(caller)
	n := nextID
	id := strconv.Itoa(n)
	nextID++
	clientSlots.Set(indexKey(caller, n), nil) // client index (views.gno)
	now := runtime.ChainHeight()
	contracts.Set(id, &Contract{
		ID:               id,
		Client:           caller,
		Freelancer:       freelancer,
		Title:            cleanTitle,
		Description:      cleanDesc,
		Status:           StatusActive,
		CreatedAt:        now,
		Milestones:       ms,
		createdPauseMark: pausedBlocksAt(now),
	})

	chain.Emit("ContractCreated",
		"id", id,
		"client", caller.String(),
		"freelancer", freelancer.String(),
		"milestones", strconv.Itoa(len(ms)),
	)
	return id
}

// FundMilestone deposits exactly the milestone amount. Client only, and only
// as a direct user call: the tx-level send lands on the message's target
// realm, so from an intermediary realm the coins would never reach escrow
// while the milestone was marked funded.
func FundMilestone(cur realm, contractId string, milestoneIdx int) {
	assertAcceptsNewMoney()
	caller := callerOf(cur)
	if !cur.Previous().IsUserCall() {
		panic("FundMilestone must be a direct user call")
	}
	c := getContract(contractId)
	if c.Client != caller {
		panic("only client can fund")
	}
	if c.Status != StatusActive {
		panic("contract not active")
	}
	ms := milestoneAt(c, milestoneIdx)
	if ms.Status != MsPending {
		panic("milestone already funded or processed")
	}
	requireExactSend(ms.Amount, cur.Previous())

	now := runtime.ChainHeight()
	ms.Status = MsFunded
	ms.FundedAt = now
	ms.fundedPauseMark = pausedBlocksAt(now)
	totalLiable += ms.Amount

	chain.Emit("MilestoneFunded",
		"contractId", contractId,
		"milestone", strconv.Itoa(milestoneIdx),
		"amount", strconv.FormatInt(ms.Amount, 10),
	)
}

// CompleteMilestone marks a funded milestone delivered. Freelancer only.
func CompleteMilestone(cur realm, contractId string, milestoneIdx int) {
	assertOpen()
	caller := callerOf(cur)
	c := getContract(contractId)
	if c.Freelancer != caller {
		panic("only freelancer can mark complete")
	}
	// A disputed contract is frozen until the dispute is resolved.
	if c.Status != StatusActive {
		panic("contract is " + string(c.Status) + " — cannot complete milestones during dispute")
	}
	ms := milestoneAt(c, milestoneIdx)
	if ms.Status != MsFunded {
		panic("milestone not funded")
	}

	ms.Status = MsCompleted
	ms.CompletedAt = runtime.ChainHeight()

	chain.Emit("MilestoneCompleted",
		"contractId", contractId,
		"milestone", strconv.Itoa(milestoneIdx),
		"freelancer", caller.String(),
	)
}

// ReleaseFunds pays a completed milestone to the freelancer, minus the fee.
// Client, or admin as the trusted arbiter (v3 behaviour).
func ReleaseFunds(cur realm, contractId string, milestoneIdx int) {
	assertOpen()
	caller := callerOf(cur)
	c := getContract(contractId)
	if c.Client != caller && caller != admin {
		panic("only client or admin can release")
	}
	if c.Status != StatusActive {
		panic("contract is " + string(c.Status) + " — cannot release funds during dispute")
	}
	ms := milestoneAt(c, milestoneIdx)
	if ms.Status != MsCompleted {
		panic("milestone not completed")
	}

	ms.Status = MsReleased
	settleIfFinished(c)
	totalLiable -= ms.Amount

	p := payFreelancer(cur, c, ms.Amount)

	chain.Emit("FundsReleased",
		"contractId", contractId,
		"milestone", strconv.Itoa(milestoneIdx),
		"freelancer", c.Freelancer.String(),
		"amount", strconv.FormatInt(p.net, 10),
		"fee", strconv.FormatInt(p.fee, 10),
		"bps", strconv.FormatInt(p.bps, 10),
		"treasury", p.treasury.String(),
		"status", string(c.Status),
	)
}

// ── Disputes ─────────────────────────────────────────────────

// RaiseDispute escalates a funded or completed milestone to the admin.
// Client or freelancer.
func RaiseDispute(cur realm, contractId string, milestoneIdx int) {
	assertOpen()
	caller := callerOf(cur)
	c := getContract(contractId)
	if c.Client != caller && c.Freelancer != caller {
		panic("only client or freelancer can dispute")
	}
	if !isOpen(c) {
		panic("contract is " + string(c.Status))
	}
	ms := milestoneAt(c, milestoneIdx)
	if ms.Status != MsFunded && ms.Status != MsCompleted {
		panic("can only dispute funded or completed milestones")
	}

	// ClaimDisputeTimeout pays the freelancer if the work had been delivered
	// (MsCompleted) and refunds the client otherwise.
	now := runtime.ChainHeight()
	ms.PreDisputeStatus = ms.Status
	ms.Status = MsDisputed
	ms.DisputedAt = now
	ms.disputedPauseMark = pausedBlocksAt(now)
	c.Status = StatusDisputed

	chain.Emit("DisputeRaised",
		"contractId", contractId,
		"milestone", strconv.Itoa(milestoneIdx),
		"raisedBy", caller.String(),
	)
}

// ResolveDispute settles a disputed milestone. Admin only.
// refundClient=true refunds the client in full; false pays the freelancer
// minus the fee. The contract then returns to active, stays disputed if
// another milestone still is, or settles: completed if every milestone is
// released, cancelled if every milestone is released or refunded.
func ResolveDispute(cur realm, contractId string, milestoneIdx int, refundClient bool) {
	assertOpen()
	if callerOf(cur) != admin {
		panic("only admin can resolve disputes")
	}
	c := getContract(contractId)
	ms := milestoneAt(c, milestoneIdx)
	if ms.Status != MsDisputed {
		panic("milestone not in dispute")
	}

	if refundClient {
		ms.Status = MsRefunded
	} else {
		ms.Status = MsReleased
	}
	c.Status = StatusActive
	if anyMilestoneDisputed(c) {
		c.Status = StatusDisputed
	}
	settleIfFinished(c)
	totalLiable -= ms.Amount

	var p payout
	resolution := "released-to-freelancer"
	if refundClient {
		resolution = "refunded-to-client"
		send(cur, c.Client, ms.Amount)
		p = payout{net: ms.Amount, recipient: c.Client}
	} else {
		p = payFreelancer(cur, c, ms.Amount)
	}
	chain.Emit("DisputeResolved",
		"contractId", contractId,
		"milestone", strconv.Itoa(milestoneIdx),
		"resolution", resolution,
		"recipient", p.recipient.String(),
		"amount", strconv.FormatInt(p.net, 10),
		"fee", strconv.FormatInt(p.fee, 10),
		"bps", strconv.FormatInt(p.bps, 10),
		"treasury", p.treasury.String(),
		"status", string(c.Status),
	)
}

// ── Cancellation and expiry ──────────────────────────────────

// CancelContract cancels an active contract. Client only. Funded milestones
// are refunded minus CancelFeePct, which goes to the freelancer; completed
// milestones are paid to the freelancer minus the service fee.
func CancelContract(cur realm, contractId string) {
	assertOpen()
	caller := callerOf(cur)
	c := getContract(contractId)
	if c.Client != caller {
		panic("only client can cancel")
	}
	if c.Status != StatusActive {
		panic("contract not active")
	}

	// Only milestones transitioned here are paid, so a milestone already
	// refunded or released is never paid twice.
	var refunded, released []int
	for i := range c.Milestones {
		switch c.Milestones[i].Status {
		case MsFunded:
			c.Milestones[i].Status = MsRefunded
			refunded = append(refunded, i)
		case MsCompleted:
			c.Milestones[i].Status = MsReleased
			released = append(released, i)
		}
	}
	settle(c, StatusCancelled)
	for _, i := range refunded {
		totalLiable -= c.Milestones[i].Amount
	}
	for _, i := range released {
		totalLiable -= c.Milestones[i].Amount
	}

	var toClient, compensation, toFreelancer, fees, bps int64
	var treasury address
	for _, i := range refunded {
		amount := c.Milestones[i].Amount
		fee := basisPointsFee(amount, int64(CancelFeePct)*100)
		send(cur, c.Client, amount-fee)
		send(cur, c.Freelancer, fee)
		toClient += amount - fee
		compensation += fee
	}
	for _, i := range released {
		p := payFreelancer(cur, c, c.Milestones[i].Amount)
		toFreelancer += p.net
		fees += p.fee
		bps, treasury = p.bps, p.treasury
	}

	chain.Emit("ContractCancelled",
		"contractId", contractId,
		"client", c.Client.String(),
		"freelancer", c.Freelancer.String(),
		"refunded", strconv.Itoa(len(refunded)),
		"released", strconv.Itoa(len(released)),
		"refundToClient", strconv.FormatInt(toClient, 10),
		"cancelCompensation", strconv.FormatInt(compensation, 10),
		"cancelFeeBps", strconv.FormatInt(int64(CancelFeePct)*100, 10),
		"releasedToFreelancer", strconv.FormatInt(toFreelancer, 10),
		"fee", strconv.FormatInt(fees, 10),
		"bps", strconv.FormatInt(bps, 10),
		"treasury", treasury.String(),
	)
}

// ExpireUnfunded cancels a contract none of whose milestones was ever funded,
// once UnfundedExpiryBlks have passed since creation (blocking-window blocks
// excluded). Anyone may call. It frees the client's slot and moves no coins;
// it does not delete, so the storage deposit stays for the client's
// ArchiveContract.
func ExpireUnfunded(cur realm, contractId string) {
	assertOpen()
	caller := callerOf(cur)
	c := getContract(contractId)
	if c.Status != StatusActive {
		panic("contract not active")
	}
	for _, m := range c.Milestones {
		if m.Status != MsPending {
			panic("contract was funded; use ClaimRefund or CancelContract")
		}
	}
	elapsed := elapsedOpen(c.CreatedAt, c.createdPauseMark)
	if elapsed < UnfundedExpiryBlks {
		panic(ufmt.Sprintf("too early: %d blocks remaining", UnfundedExpiryBlks-elapsed))
	}

	settle(c, StatusCancelled)

	chain.Emit("ContractExpired",
		"contractId", contractId,
		"client", c.Client.String(),
		"expiredBy", caller.String(),
	)
}

// ── Timeouts (permissionless) ────────────────────────────────

// ClaimRefund refunds a funded milestone nobody completed within
// AutoRefundBlks (blocking-window blocks excluded). Anyone may call; the
// client receives the funds. If no milestone then holds funds the contract is
// cancelled, pending milestones included (v3 behaviour).
func ClaimRefund(cur realm, contractId string, milestoneIdx int) {
	assertOpen()
	c := getContract(contractId)
	ms := milestoneAt(c, milestoneIdx)
	if ms.Status != MsFunded {
		panic("milestone not funded")
	}
	if ms.FundedAt == 0 {
		panic("milestone has no funding record")
	}
	elapsed := elapsedOpen(ms.FundedAt, ms.fundedPauseMark)
	if elapsed < AutoRefundBlks {
		panic(ufmt.Sprintf("too early: %d blocks remaining", AutoRefundBlks-elapsed))
	}

	ms.Status = MsRefunded
	if allMilestonesTerminal(c) {
		settle(c, StatusCancelled)
	}
	totalLiable -= ms.Amount

	send(cur, c.Client, ms.Amount)

	chain.Emit("RefundClaimed",
		"contractId", contractId,
		"milestone", strconv.Itoa(milestoneIdx),
		"recipient", c.Client.String(),
		"amount", strconv.FormatInt(ms.Amount, 10),
		"status", string(c.Status),
	)
}

// ClaimDisputeTimeout resolves a dispute the admin has not acted on within
// AutoResolveBlks (blocking-window blocks excluded), following the pre-dispute
// status: a delivered milestone (MsCompleted) pays the freelancer minus the
// fee, an undelivered one (MsFunded) refunds the client. Anyone may call.
func ClaimDisputeTimeout(cur realm, contractId string, milestoneIdx int) {
	assertOpen()
	c := getContract(contractId)
	ms := milestoneAt(c, milestoneIdx)
	if ms.Status != MsDisputed {
		panic("milestone not in dispute")
	}
	if ms.DisputedAt == 0 {
		panic("milestone has no dispute record")
	}
	elapsed := elapsedOpen(ms.DisputedAt, ms.disputedPauseMark)
	if elapsed < AutoResolveBlks {
		panic(ufmt.Sprintf("too early: %d blocks remaining", AutoResolveBlks-elapsed))
	}

	payToFreelancer := ms.PreDisputeStatus == MsCompleted
	if payToFreelancer {
		ms.Status = MsReleased
	} else {
		ms.Status = MsRefunded
	}
	c.Status = StatusActive
	if anyMilestoneDisputed(c) {
		c.Status = StatusDisputed
	}
	if allMilestonesReleased(c) {
		settle(c, StatusCompleted)
	} else if allMilestonesTerminal(c) {
		settle(c, StatusCancelled)
	}
	totalLiable -= ms.Amount

	var p payout
	resolution := "refunded-client-no-delivery"
	if payToFreelancer {
		resolution = "paid-freelancer-work-delivered"
		p = payFreelancer(cur, c, ms.Amount)
	} else {
		send(cur, c.Client, ms.Amount)
		p = payout{net: ms.Amount, recipient: c.Client}
	}
	chain.Emit("DisputeTimedOut",
		"contractId", contractId,
		"milestone", strconv.Itoa(milestoneIdx),
		"resolution", resolution,
		"recipient", p.recipient.String(),
		"amount", strconv.FormatInt(p.net, 10),
		"fee", strconv.FormatInt(p.fee, 10),
		"bps", strconv.FormatInt(p.bps, 10),
		"treasury", p.treasury.String(),
		"status", string(c.Status),
	)
}

// ── Archive ──────────────────────────────────────────────────

// ArchiveContract deletes a settled contract (completed or cancelled, with
// nothing escrowed). Client only. The freed bytes shrink the realm's storage,
// and the chain refunds their storage deposit to the signer of this message
// (see DESIGN.md), so the client, who paid for the contract when creating it,
// gets that deposit back. The id is never reused. The ContractArchived event
// is the permanent record; nothing of the contract stays in realm state.
func ArchiveContract(cur realm, contractId string) {
	assertOpen()
	caller := callerOf(cur)
	c := getContract(contractId)
	if c.Client != caller {
		panic("only client can archive")
	}
	if isOpen(c) {
		panic("contract not settled: status is " + string(c.Status))
	}
	var released, refunded int64
	for _, m := range c.Milestones {
		switch m.Status {
		case MsReleased:
			released += m.Amount
		case MsRefunded:
			refunded += m.Amount
		case MsPending:
		default:
			panic("escrowed funds remain in milestone " + strconv.Itoa(m.ID))
		}
	}
	hash := contentHash(c)

	contracts.Remove(contractId)
	n, _ := strconv.Atoi(contractId)
	clientSlots.Remove(indexKey(c.Client, n))
	if clientActive(c.Client) == 0 {
		clientSlots.Remove(c.Client.String())
	}
	archivedCount++

	// milestone*Total are escrow principal, gross of fees and of the cancel
	// compensation. The storage-deposit refund is not an escrow amount: the
	// chain reports it in its own StorageUnlockEvent.
	chain.Emit("ContractArchived",
		"contractId", contractId,
		"client", c.Client.String(),
		"freelancer", c.Freelancer.String(),
		"status", string(c.Status),
		"milestoneReleasedTotal", strconv.FormatInt(released, 10),
		"milestoneRefundedTotal", strconv.FormatInt(refunded, 10),
		"contentHash", hash,
	)
}

// ── Slots and settlement ─────────────────────────────────────

// isOpen reports whether c still holds an active slot.
func isOpen(c *Contract) bool {
	return c.Status != StatusCompleted && c.Status != StatusCancelled
}

func clientActive(client address) int {
	v, ok := clientSlots.Get(client.String())
	if !ok {
		return 0
	}
	return v.(int)
}

func takeSlot(client address) {
	n := clientActive(client)
	if n >= MaxActivePerClient {
		panic(ufmt.Sprintf("limit of %d active contracts for this client reached", MaxActivePerClient))
	}
	clientSlots.Set(client.String(), n+1)
	activeCount++
}

// settle moves an open contract to a terminal status and releases its slot.
// Terminal statuses are absorbing, so this runs at most once per contract.
func settle(c *Contract, status ContractStatus) {
	if !isOpen(c) {
		panic("contract already settled")
	}
	c.Status = status
	n := clientActive(c.Client)
	if n <= 0 || activeCount <= 0 {
		panic("slot accounting underflow")
	}
	// A zero count is kept until the client archives: the client paid for
	// this tree node, and removing it here would refund its deposit to
	// whoever signs the settling message (a permissionless ClaimRefund
	// caller, the admin, the freelancer).
	clientSlots.Set(c.Client.String(), n-1)
	activeCount--
}

// settleIfFinished settles an open contract whose milestones are all released
// (completed) or all released or refunded (cancelled). A pending, funded,
// completed or disputed milestone keeps it open.
func settleIfFinished(c *Contract) {
	if !isOpen(c) {
		return
	}
	allReleased := true
	for _, m := range c.Milestones {
		if m.Status != MsReleased && m.Status != MsRefunded {
			return
		}
		if m.Status != MsReleased {
			allReleased = false
		}
	}
	if allReleased {
		settle(c, StatusCompleted)
	} else {
		settle(c, StatusCancelled)
	}
}

// ── Payments ─────────────────────────────────────────────────

type payout struct {
	recipient address
	net, fee  int64
	bps       int64
	treasury  address
}

func send(cur realm, to address, amount int64) {
	if amount <= 0 {
		return
	}
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(cur.Address(), to, chain.Coins{chain.NewCoin("ugnot", amount)})
}

// payFreelancer pays amount to the freelancer minus the service fee read live
// from the fee spine, which goes to the treasury.
func payFreelancer(cur realm, c *Contract, amount int64) payout {
	bps, treasury := resolveFee()
	fee := basisPointsFee(amount, bps)
	send(cur, c.Freelancer, amount-fee)
	send(cur, treasury, fee)
	return payout{recipient: c.Freelancer, net: amount - fee, fee: fee, bps: bps, treasury: treasury}
}

// ── Helpers ──────────────────────────────────────────────────

func getContract(id string) *Contract {
	val, exists := contracts.Get(id)
	if !exists {
		panic("contract not found: " + id)
	}
	return val.(*Contract)
}

func milestoneAt(c *Contract, idx int) *Milestone {
	if idx < 0 || idx >= len(c.Milestones) {
		panic("invalid milestone index")
	}
	return &c.Milestones[idx]
}

func allMilestonesReleased(c *Contract) bool {
	for _, m := range c.Milestones {
		if m.Status != MsReleased {
			return false
		}
	}
	return true
}

func anyMilestoneDisputed(c *Contract) bool {
	for _, m := range c.Milestones {
		if m.Status == MsDisputed {
			return true
		}
	}
	return false
}

// allMilestonesTerminal reports whether no milestone holds funds (pending with
// no funds counts as terminal).
func allMilestonesTerminal(c *Contract) bool {
	for _, m := range c.Milestones {
		if m.Status == MsFunded || m.Status == MsCompleted || m.Status == MsDisputed {
			return false
		}
	}
	return true
}

// parseMilestones parses "title1:amount1,title2:amount2". Blank entries are
// skipped; any other malformed entry panics.
func parseMilestones(input string) []Milestone {
	if len(input) > maxMilestonesArgLen {
		panic(ufmt.Sprintf("milestones argument too long: %d/%d bytes", len(input), maxMilestonesArgLen))
	}
	var result []Milestone
	total := int64(0)
	for i, p := range strings.Split(input, ",") {
		p = strings.TrimSpace(p)
		if len(p) == 0 {
			continue
		}
		kv := strings.SplitN(p, ":", 2)
		if len(kv) != 2 {
			panic(ufmt.Sprintf("invalid milestone format at position %d: expected 'title:amount'", i))
		}
		title := strings.TrimSpace(kv[0])
		if len(title) == 0 {
			panic(ufmt.Sprintf("empty milestone title at position %d", i))
		}
		title = cleanText(title, ufmt.Sprintf("milestone title at position %d", i), MaxTitleLen)
		if strings.TrimSpace(title) == "" {
			panic(ufmt.Sprintf("milestone title at position %d has no visible characters", i))
		}
		amount, err := strconv.ParseInt(strings.TrimSpace(kv[1]), 10, 64)
		if err != nil || amount <= 0 {
			panic(ufmt.Sprintf("invalid milestone amount at position %d: must be positive integer", i))
		}
		if amount < MinMilestoneAmount {
			panic(ufmt.Sprintf("milestone amount too small at position %d: minimum %d ugnot", i, MinMilestoneAmount))
		}
		if amount > 9223372036854775807-total {
			panic("contract total overflows int64")
		}
		total += amount
		result = append(result, Milestone{
			ID:     len(result),
			Title:  title,
			Amount: amount,
			Status: MsPending,
		})
	}
	return result
}

// Time-boxed emergency pause.
//
// Pause (admin) has two effects:
//   - New money stops: CreateContract and FundMilestone abort until Unpause.
//   - Every other state-changing entrypoint (settlement, disputes, timeouts,
//     cancellation, expiry, archive) aborts only during the BLOCKING WINDOW,
//     the first MaxPauseBlks blocks of the pause. After that it reopens even if
//     nobody unpauses.
//
// The timeout clocks (AutoRefundBlks, AutoResolveBlks, UnfundedExpiryBlks) do
// not run inside a blocking window: each deadline moves by the paused blocks
// that fell inside it. After Unpause, a new Pause is refused for
// PauseCooldownBlks, so pause, unpause, pause cannot keep exits shut.
//
// Without the time box one admin key (after the DAO handoff, any single member
// allowed to call the emergency pause) could freeze every exit forever, and
// losing the admin key during a pause would do the same: admin rotation needs
// the admin key.
//
// Admin controls (Pause, Unpause, admin and fee-recipient rotation) are never
// paused.

const (
	// MaxPauseBlks is the blocking window: about 7 days at gnoland-1's
	// observed average of about 3.3 s per block (7*24*3600/3.3 = 183,273).
	MaxPauseBlks = int64(183273)
	// PauseCooldownBlks is the minimum gap between an Unpause and the next
	// Pause, so a pause can hold exits shut at most half of the time.
	PauseCooldownBlks = MaxPauseBlks
)

var (
	paused             bool
	pausedAt           int64 // height of the current pause; 0 when not paused
	pauseCooldownUntil int64 // first height at which Pause is accepted again
	pausedBlocksDone   int64 // blocking-window blocks of finished pauses
)

// PauseInfo is the read-back of the pause state.
type PauseInfo struct {
	Paused        bool  // set by Pause, cleared only by Unpause
	PausedAt      int64 // height of the current pause (0 when not paused)
	ExitsReopenAt int64 // PausedAt + MaxPauseBlks (0 when not paused)
	ExitsOpen     bool  // false only inside a blocking window
	CooldownUntil int64 // first height at which Pause is accepted
	PausedBlocks  int64 // total blocking-window blocks so far (clocks skip them)
}

// PauseState returns the pause state at the current height.
func PauseState() PauseInfo {
	now := runtime.ChainHeight()
	s := PauseInfo{
		Paused:        paused,
		ExitsOpen:     !inBlockingWindow(now),
		CooldownUntil: pauseCooldownUntil,
		PausedBlocks:  pausedBlocksAt(now),
	}
	if paused {
		s.PausedAt = pausedAt
		s.ExitsReopenAt = pausedAt + MaxPauseBlks
	}
	return s
}

// IsPaused reports whether the pause flag is set. Exits may already have
// reopened: see PauseState().ExitsOpen.
func IsPaused() bool { return paused }

// Pause stops new money and, for MaxPauseBlks, every other state change.
// Admin only. Refused while paused and during the cooldown after an Unpause.
func Pause(cur realm) {
	assertAdmin(cur)
	now := runtime.ChainHeight()
	if paused {
		panic("already paused")
	}
	if now < pauseCooldownUntil {
		panic("pause cooldown: next pause allowed at block " + strconv.FormatInt(pauseCooldownUntil, 10))
	}
	paused = true
	pausedAt = now
	chain.Emit("Paused",
		"at", strconv.FormatInt(now, 10),
		"exitsReopenAt", strconv.FormatInt(now+MaxPauseBlks, 10),
	)
}

// Unpause resumes normal operation and starts the cooldown. Admin only.
func Unpause(cur realm) {
	assertAdmin(cur)
	now := runtime.ChainHeight()
	if !paused {
		panic("not paused")
	}
	pausedBlocksDone = pausedBlocksAt(now)
	paused = false
	pausedAt = 0
	pauseCooldownUntil = now + PauseCooldownBlks
	chain.Emit("Unpaused",
		"at", strconv.FormatInt(now, 10),
		"cooldownUntil", strconv.FormatInt(pauseCooldownUntil, 10),
	)
}

// inBlockingWindow reports whether now falls in the first MaxPauseBlks blocks
// of the current pause.
func inBlockingWindow(now int64) bool {
	return paused && now < pausedAt+MaxPauseBlks
}

// pausedBlocksAt returns the blocking-window blocks up to now, finished pauses
// included. Timeout clocks subtract the growth of this value.
func pausedBlocksAt(now int64) int64 {
	total := pausedBlocksDone
	if paused {
		end := now
		if end > pausedAt+MaxPauseBlks {
			end = pausedAt + MaxPauseBlks
		}
		total += end - pausedAt
	}
	return total
}

// assertAcceptsNewMoney guards CreateContract and FundMilestone.
func assertAcceptsNewMoney() {
	if paused {
		panic("realm is paused — no new contracts or funding until unpaused")
	}
}

// assertOpen guards every other state-changing user and admin entrypoint.
func assertOpen() {
	if inBlockingWindow(runtime.ChainHeight()) {
		panic("realm is paused — exits reopen at block " + strconv.FormatInt(pausedAt+MaxPauseBlks, 10))
	}
}

// elapsedOpen returns the blocks since `since` that fell outside any blocking
// window, given pausedBlocksAt(since) recorded as mark.
func elapsedOpen(since, mark int64) int64 {
	now := runtime.ChainHeight()
	return now - since - (pausedBlocksAt(now) - mark)
}

// ── Admin authority and the fallback fee recipient ──────────────────────
//
// No authority is compiled in. `admin` and `feeRecipient` are seeded at
// package load from the publishing transaction's signer (on gnoland-1 the
// samcrew namespace multisig), and every gate reads the mutable variables.
// Realms are immutable and mainnet has no faucet, so a compile-time authority
// could never be corrected; losing it would disable Pause/Unpause and
// ResolveDispute, the only path that settles a dispute before its timeout.
//
// Both rotations are TWO-STEP: the current admin stages an address, and that
// address must accept with its own transaction. A one-step setter could hand
// the role to an address that cannot act (a typo, an unfunded key), with no
// way back. The admin can abort a staged proposal without the target.
//
// Rotation stays available while paused. It needs the current admin key, so
// it cannot rescue a pause after that key is lost; the pause's time box
// (pause section above) is what keeps exits from freezing.

var (
	// admin is the live authority, seeded with the publisher at load.
	admin address = publisherAtLoad()
	// pendingAdmin is the staged successor; "" when none.
	pendingAdmin address

	// feeRecipient receives the protocol fee only when memba_market_config
	// reports no treasury (see resolveFee). Seeded with the publisher.
	feeRecipient address = publisherAtLoad()
	// pendingFeeRecipient is the staged successor; "" when none.
	pendingFeeRecipient address
)

// assertAdmin rejects a stale or sibling `cur`, then checks the caller.
func assertAdmin(cur realm) {
	if callerOf(cur) != admin {
		panic("unauthorized: only admin may perform this action")
	}
}

// ── Admin rotation ───────────────────────────────────────────

// TransferOwnership stages a handoff to newAdmin. Admin only. Calling it again
// replaces the staged address.
func TransferOwnership(cur realm, newAdmin address) {
	assertAdmin(cur)
	if !newAdmin.IsValid() {
		panic("newAdmin must be a valid address")
	}
	pendingAdmin = newAdmin
	chain.Emit("OwnershipTransferStarted", "pending", newAdmin.String())
}

// AcceptOwnership completes the handoff. Only the staged address may call it,
// so the outgoing admin cannot collapse the two steps into one.
func AcceptOwnership(cur realm) {
	caller := callerOf(cur)
	if pendingAdmin == "" {
		panic("no pending ownership transfer")
	}
	if caller != pendingAdmin {
		panic("unauthorized: only the pending admin may accept")
	}
	admin = pendingAdmin
	pendingAdmin = ""
	chain.Emit("OwnershipTransferAccepted", "admin", admin.String())
}

// CancelOwnershipTransfer clears a staged handoff. Admin only.
func CancelOwnershipTransfer(cur realm) {
	assertAdmin(cur)
	if pendingAdmin == "" {
		panic("no pending ownership transfer")
	}
	cancelled := pendingAdmin
	pendingAdmin = ""
	chain.Emit("OwnershipTransferCancelled", "cancelled", cancelled.String())
}

// GetAdmin returns the address that holds admin.
func GetAdmin() string { return admin.String() }

// GetPendingAdmin returns the staged successor ("" when none).
func GetPendingAdmin() string { return pendingAdmin.String() }

// ── Fee recipient rotation ───────────────────────────────────

// ProposeFeeRecipient stages a new fallback fee recipient. Admin only.
func ProposeFeeRecipient(cur realm, recipient address) {
	assertAdmin(cur)
	if !recipient.IsValid() {
		panic("fee recipient must be a valid address")
	}
	pendingFeeRecipient = recipient
	chain.Emit("FeeRecipientProposed", "pending", recipient.String())
}

// AcceptFeeRecipient completes the rotation. Only the staged address may call
// it, which proves it can transact.
func AcceptFeeRecipient(cur realm) {
	caller := callerOf(cur)
	if pendingFeeRecipient == "" {
		panic("no pending fee recipient")
	}
	if caller != pendingFeeRecipient {
		panic("unauthorized: only the pending fee recipient may accept")
	}
	feeRecipient = pendingFeeRecipient
	pendingFeeRecipient = ""
	chain.Emit("FeeRecipientAccepted", "recipient", feeRecipient.String())
}

// CancelFeeRecipientProposal clears a staged fee recipient. Admin only.
func CancelFeeRecipientProposal(cur realm) {
	assertAdmin(cur)
	if pendingFeeRecipient == "" {
		panic("no pending fee recipient")
	}
	cancelled := pendingFeeRecipient
	pendingFeeRecipient = ""
	chain.Emit("FeeRecipientProposalCancelled", "cancelled", cancelled.String())
}

// GetFeeRecipient returns the fallback fee recipient.
func GetFeeRecipient() string { return feeRecipient.String() }

// GetPendingFeeRecipient returns the staged fee recipient ("" when none).
func GetPendingFeeRecipient() string { return pendingFeeRecipient.String() }

// basisPointsFee computes floor(amount*bps/10000) without overflowing the
// intermediate product. For nonnegative amount and bps <= 10000, the quotient
// product and final sum are <= amount; the remainder product is < 100000000.
// Callers retain their existing configured rates, recipients and rounding.
func basisPointsFee(amount, bps int64) int64 {
	if amount < 0 || bps < 0 || bps > 10000 {
		panic("invalid fee inputs")
	}
	return (amount/10000)*bps + ((amount%10000)*bps)/10000
}

// cleanText validates and sanitises user text before it is stored and
// rendered. It refuses input longer than max bytes, input that is not valid
// UTF-8 (the sanitiser would otherwise turn each bad byte into a 3-byte
// U+FFFD, storing up to three times the limit), and control or format
// characters (\p{Cc}, \p{Cf}: bidi overrides, zero-width characters), which
// could hide or reorder text. It then strips markdown-sensitive characters and
// line breaks and tabs, as v3 did. Stripping only removes bytes, so the result
// is within max; that is checked again because storage is bounded by it.
func cleanText(s, what string, max int) string {
	if len(s) > max {
		panic(ufmt.Sprintf("%s must be at most %d bytes", what, max))
	}
	if !utf8.ValidString(s) {
		panic(what + " must be valid UTF-8")
	}
	strip := false
	for _, c := range s {
		if isStripped(c) {
			strip = true
			continue
		}
		if c < 0x20 || c == 0x7f || (c >= 0x80 && c < 0xa0) || (mayBeFormat(c) && unicode.Is(unicode.Cf, c)) {
			panic(what + " contains invisible or control characters")
		}
	}
	if !strip {
		return s
	}
	var out strings.Builder
	for _, c := range s {
		if !isStripped(c) {
			out.WriteRune(c)
		}
	}
	clean := out.String()
	if len(clean) > max {
		panic(ufmt.Sprintf("%s must be at most %d bytes", what, max))
	}
	return clean
}

// isStripped reports the markdown-sensitive characters and line breaks and
// tabs removed from stored text, as in v3.
func isStripped(c rune) bool {
	switch c {
	case '[', ']', '(', ')', '#', '*', '`', '!', '<', '>', '|', '\\', '_', '~', '\n', '\r', '\t':
		return true
	}
	return false
}

// mayBeFormat is a cheap superset test for \p{Cf} (every format character is
// U+00AD, in U+0600..U+206F, or at or above U+FEFF), so common text skips the
// table lookup.
func mayBeFormat(c rune) bool {
	return c == 0xad || (c >= 0x600 && c <= 0x206f) || c >= 0xfeff
}

package escrow_v4

// The only chain/runtime/unsafe uses in this realm. Nothing here reads a
// caller from the stack and no crossing entrypoint is declared in this file:
// entrypoints authenticate with cur.IsCurrent() and cur.Previous(), and
// requireExactSend only checks the kind of the frame-verified caller it is
// handed.

import (
	"chain/runtime/unsafe"

	"gno.land/p/nt/ufmt/v0"
)

// publisherAtLoad captures the AddPackage signer during package
// initialization; it seeds admin and the fallback fee recipient.
func publisherAtLoad() address { return unsafe.OriginCaller() }

// requireExactSend panics unless caller (the entrypoint's cur.Previous()) is
// a direct user call and the transaction's send envelope holds exactly amount
// ugnot and no other denom. Only for a direct user call is the envelope
// credited to this realm, the message target; any other denom would be
// stranded here. The guard sits in this function, before the read, so the
// deployer's per-function fund-safety scan (lib/deploy.sh) sees it.
func requireExactSend(amount int64, caller realm) {
	if !caller.IsUserCall() {
		panic("FundMilestone must be a direct user call")
	}
	sent := int64(0)
	for _, coin := range unsafe.OriginSend() {
		if coin.Denom != "ugnot" {
			panic("only ugnot is accepted, got " + coin.Denom)
		}
		sent += coin.Amount
	}
	if sent != amount {
		panic(ufmt.Sprintf("must send exactly %d ugnot (sent %d)", amount, sent))
	}
}

// realmAddress is this realm's own address, for the NF-2 solvency getter.
func realmAddress() address { return unsafe.CurrentRealm().Address() }

package escrow_v4

// Read-only views: NF-2 solvency getters, counters, governance reads, JSON
// views for frontends and Render. Nothing here changes state. (All of this
// sits in one file, like the state-changing code in escrow.gno, because every
// extra file costs AddPackage storage.)

import (
	"chain/runtime"
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"strings"

	"gno.land/p/nt/ufmt/v0"
	cfg "gno.land/r/samcrew/memba_market_config"
)

// ── NF-2 solvency getters (MAINNET_READINESS.md §3) ─────────────────────────
//
// Invariant the solvency monitor reconciles: realm balance >=
// TotalLiabilities(). totalLiable rises by the milestone amount in
// FundMilestone and falls by it at every point funds leave the realm.

// TotalLiabilities returns the ugnot the realm owes across funded, completed
// and disputed milestones.
func TotalLiabilities() int64 { return totalLiable }

// RealmAddress is the NF-2 canonical name for the realm's own address.
func RealmAddress() string { return realmAddress().String() }

// ── Slot and archive counters ─────────────────────────────────────────────

// GetActiveCount returns the number of open contracts (not completed or
// cancelled).
func GetActiveCount() int { return activeCount }

// GetClientActiveCount returns the open contracts created by client, bounded
// by MaxActivePerClient.
func GetClientActiveCount(client address) int { return clientActive(client) }

// GetLiveCount returns the contracts still stored: open ones plus settled ones
// their client has not archived.
func GetLiveCount() int { return contracts.Size() }

// GetArchivedCount returns the contracts deleted by ArchiveContract.
func GetArchivedCount() int { return archivedCount }

// GetCreatedCount returns every contract ever created; ids run from 0 to
// GetCreatedCount()-1 and are never reused.
func GetCreatedCount() int { return nextID }

// Value-only reads for the memba_dao escrow adapter, unchanged from escrow_v3:
// no Contract pointer or persistent milestone slice escapes. An archived
// contract reads as absent (Exists false).

type GovernanceMilestone struct {
	ID                                int
	Amount                            int64
	Status                            string
	FundedAt, CompletedAt, DisputedAt int64
	PreDisputeStatus                  string
}

type GovernanceContract struct {
	Exists                  bool
	ID, ContentHash, Status string
	Client, Freelancer      address
	Count                   int
	Milestones              [20]GovernanceMilestone
}

func GetGovernanceContract(id string) GovernanceContract {
	v, ok := contracts.Get(id)
	if !ok {
		return GovernanceContract{}
	}
	c := v.(*Contract)
	if len(c.Milestones) > MaxMilestones {
		panic("invalid escrow milestone count")
	}
	s := GovernanceContract{Exists: true, ID: c.ID, Status: string(c.Status), Client: c.Client, Freelancer: c.Freelancer, Count: len(c.Milestones), ContentHash: contentHash(c)}
	for i, m := range c.Milestones {
		s.Milestones[i] = GovernanceMilestone{ID: m.ID, Amount: m.Amount, Status: string(m.Status), FundedAt: m.FundedAt, CompletedAt: m.CompletedAt, DisputedAt: m.DisputedAt, PreDisputeStatus: string(m.PreDisputeStatus)}
	}
	return s
}

// contentHash digests the immutable metadata of a contract (parties, texts,
// creation height, milestone titles and amounts), not its state.
func contentHash(c *Contract) string {
	metadata := "escrow-metadata/v1" + escrowMetadataField(c.ID) + escrowMetadataField(string(c.Client)) + escrowMetadataField(string(c.Freelancer)) + escrowMetadataField(c.Title) + escrowMetadataField(c.Description) + escrowMetadataField(strconv.FormatInt(c.CreatedAt, 10)) + escrowMetadataField(strconv.Itoa(len(c.Milestones)))
	for _, m := range c.Milestones {
		metadata += escrowMetadataField(strconv.Itoa(m.ID)) + escrowMetadataField(m.Title) + escrowMetadataField(strconv.FormatInt(m.Amount, 10))
	}
	digest := sha256.Sum256([]byte(metadata))
	return hex.EncodeToString(digest[:])
}

type GovernanceFeeTerms struct {
	RawBPS, EffectiveBPS                             int64
	RawTreasury, FallbackTreasury, EffectiveTreasury address
}

func GetGovernanceFeeTerms() GovernanceFeeTerms {
	bps, treasury := resolveFee()
	return GovernanceFeeTerms{RawBPS: int64(cfg.GetFeeBPS(laneService)), EffectiveBPS: bps, RawTreasury: cfg.GetTreasury(), FallbackTreasury: feeRecipient, EffectiveTreasury: treasury}
}

func escrowMetadataField(value string) string { return strconv.Itoa(len(value)) + ":" + value }

// Structured read-only views for frontends (additive to the frozen API; they
// change no state and no existing behaviour). Every integer is a decimal
// string, absent values are null, and an unknown or archived id reads as
// {"exists":false,...}. Heights such as refundAt are pause-adjusted deadlines,
// assuming no further pause. Contract listings walk at most limit+1 entries
// of a per-party index, newest first.

const maxPageSize = 50

// indexPrefix keys the client index inside clientSlots (the per-client slot
// counters are keyed by the bare address, which never starts with "c/"): one
// tree instead of two keeps the package smaller.
const indexPrefix = "c/"

// GetContractJSON returns one contract as JSON.
func GetContractJSON(id string) string {
	v, ok := contracts.Get(id)
	if !ok {
		return `{"exists":false,"id":` + jstr(id) + `}`
	}
	c := v.(*Contract)
	var total, escrowed, released, refunded, fundedAt, refundAt, resolveAt int64
	pending := true
	var ms strings.Builder
	for i, m := range c.Milestones {
		total += m.Amount
		mRefund, mResolve := int64(0), int64(0)
		switch m.Status {
		case MsFunded:
			mRefund = deadline(m.FundedAt, m.fundedPauseMark, AutoRefundBlks)
			refundAt = minHeight(refundAt, mRefund)
			escrowed += m.Amount
		case MsDisputed:
			mResolve = deadline(m.DisputedAt, m.disputedPauseMark, AutoResolveBlks)
			resolveAt = minHeight(resolveAt, mResolve)
			escrowed += m.Amount
		case MsCompleted:
			escrowed += m.Amount
		case MsReleased:
			released += m.Amount
		case MsRefunded:
			refunded += m.Amount
		}
		if m.Status != MsPending {
			pending = false
		}
		fundedAt = minHeight(fundedAt, m.FundedAt)
		if i > 0 {
			ms.WriteString(",")
		}
		ms.WriteString(`{"index":` + jint(int64(i)) + `,"title":` + jstr(m.Title) +
			`,"amountUgnot":` + jint(m.Amount) + `,"status":` + jstr(string(m.Status)) +
			`,"fundedAtHeight":` + jheight(m.FundedAt) + `,"completedAtHeight":` + jheight(m.CompletedAt) +
			`,"disputedAtHeight":` + jheight(m.DisputedAt) + `,"refundAt":` + jheight(mRefund) +
			`,"resolveAt":` + jheight(mResolve) + `}`)
	}
	expireAt := int64(0)
	if pending && c.Status == StatusActive {
		expireAt = deadline(c.CreatedAt, c.createdPauseMark, UnfundedExpiryBlks)
	}
	return `{"exists":true,"id":` + jstr(c.ID) + `,"client":` + jstr(c.Client.String()) +
		`,"freelancer":` + jstr(c.Freelancer.String()) + `,"title":` + jstr(c.Title) +
		`,"description":` + jstr(c.Description) + `,"status":` + jstr(string(c.Status)) +
		`,"createdAtHeight":` + jint(c.CreatedAt) + `,"fundedAtHeight":` + jheight(fundedAt) +
		`,"refundAt":` + jheight(refundAt) + `,"expireAt":` + jheight(expireAt) + `,"resolveAt":` + jheight(resolveAt) +
		`,"milestones":[` + ms.String() + `],"totals":{"amountUgnot":` + jint(total) +
		`,"escrowedUgnot":` + jint(escrowed) + `,"releasedUgnot":` + jint(released) +
		`,"refundedUgnot":` + jint(refunded) + `}}`
}

// GetClientContractsJSON pages the live contracts a client created, newest
// first: {"items":[{"id","status","createdAtHeight"}...],"next":cursor|null}.
// before is "" for the first page or the previous page's next cursor; limit
// is clamped to 1..50.
func GetClientContractsJSON(client address, before string, limit int) string {
	return contractsPage(client, before, limit)
}

// GetPauseStateJSON returns PauseState() as JSON.
func GetPauseStateJSON() string {
	p := PauseState()
	return `{"paused":` + strconv.FormatBool(p.Paused) + `,"pausedAt":` + jheight(p.PausedAt) +
		`,"exitsReopenAt":` + jheight(p.ExitsReopenAt) + `,"exitsOpen":` + strconv.FormatBool(p.ExitsOpen) +
		`,"cooldownUntil":` + jint(p.CooldownUntil) + `,"pausedBlocks":` + jint(p.PausedBlocks) + `}`
}

func contractsPage(who address, before string, limit int) string {
	if limit < 1 {
		limit = 1
	} else if limit > maxPageSize {
		limit = maxPageSize
	}
	prefix := indexPrefix + who.String() + "/"
	end := prefix + "~" // after every digit
	if before != "" {
		n, err := strconv.Atoi(before)
		if err != nil || n < 0 || strconv.Itoa(n) != before {
			panic("invalid cursor: " + before)
		}
		end = indexKey(who, n)
	}
	var sb strings.Builder
	count, next, last := 0, "null", ""
	clientSlots.ReverseIterate(prefix, end, func(key string, _ any) bool {
		n, _ := strconv.Atoi(key[len(prefix):])
		id := strconv.Itoa(n)
		if id == before {
			return false // end is inclusive; the cursor itself was on the previous page
		}
		if count == limit {
			next = jstr(last)
			return true
		}
		c := getContract(id)
		if count > 0 {
			sb.WriteString(",")
		}
		sb.WriteString(`{"id":` + jstr(id) + `,"status":` + jstr(string(c.Status)) +
			`,"createdAtHeight":` + jint(c.CreatedAt) + `}`)
		count++
		last = id
		return false
	})
	return `{"items":[` + sb.String() + `],"next":` + next + `}`
}

// indexKey orders a party's contracts by id: 10-digit zero padding.
func indexKey(who address, id int) string {
	s := strconv.Itoa(id)
	return indexPrefix + who.String() + "/" + strings.Repeat("0", 10-len(s)) + s
}

// deadline is the height at which a clock started at since (pause mark taken
// then) reaches span unpaused blocks, assuming no pause after the current one.
func deadline(since, mark, span int64) int64 {
	now := runtime.ChainHeight()
	if inBlockingWindow(now) {
		now = pausedAt + MaxPauseBlks
	}
	return since + span + pausedBlocksAt(now) - mark
}

func minHeight(a, b int64) int64 {
	if a == 0 || (b != 0 && b < a) {
		return b
	}
	return a
}

func jint(n int64) string { return `"` + strconv.FormatInt(n, 10) + `"` }

// jheight encodes 0 (not set) as null.
func jheight(n int64) string {
	if n == 0 {
		return "null"
	}
	return jint(n)
}

// jstr quotes s as a JSON string. Stored text is valid UTF-8 without control
// characters; ids passed by callers are escaped the same way.
func jstr(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range s {
		switch {
		case r == '"' || r == '\\':
			b.WriteByte('\\')
			b.WriteRune(r)
		case r < 0x20:
			b.WriteString(`\u00`)
			b.WriteByte("0123456789abcdef"[r>>4])
			b.WriteByte("0123456789abcdef"[r&15])
		default:
			b.WriteRune(r)
		}
	}
	b.WriteByte('"')
	return b.String()
}

// Render() contract:
//   Home — Render("") or Render("page/N"):
//     # Escrow Contracts
//     | ID | Title | Client | Freelancer | Status | Total |
//     (RenderPageSize live contracts per page, in tree order)
//   Detail — Render("contract/ID"):
//     # Title
//     **Client:** g1...
//     **Freelancer:** g1...
//     **Status:** active
//     ## Milestones
//     - **Milestone Title** — 1000000 ugnot [funded]
//   Stats — Render("stats"): counters only, no iteration.
// Archived contracts are gone from every view.

// RenderPageSize is the number of contracts listed per home page.
const RenderPageSize = 20

func Render(path string) string {
	switch {
	case path == "":
		return renderHome(1)
	case strings.HasPrefix(path, "page/"):
		page, err := strconv.Atoi(strings.TrimPrefix(path, "page/"))
		if err != nil || page < 1 {
			return "# 404\nNot found: " + path
		}
		return renderHome(page)
	case strings.HasPrefix(path, "contract/"):
		return renderContract(strings.TrimPrefix(path, "contract/"))
	case path == "stats":
		return renderStats()
	}
	return "# 404\nNot found: " + path
}

func renderHome(page int) string {
	var sb strings.Builder
	sb.WriteString("# Escrow Contracts\n\n")
	sb.WriteString("Milestone-based escrow for freelance services on Gno.\n\n")

	live := contracts.Size()
	if live == 0 {
		sb.WriteString("*No contracts yet.*\n")
		return sb.String()
	}
	offset := (page - 1) * RenderPageSize
	if offset >= live {
		return "# 404\nNo page " + strconv.Itoa(page)
	}

	sb.WriteString("| ID | Title | Client | Freelancer | Status | Total |\n")
	sb.WriteString("| --- | --- | --- | --- | --- | --- |\n")
	contracts.IterateByOffset(offset, RenderPageSize, func(_ string, value any) bool {
		c := value.(*Contract)
		sb.WriteString(ufmt.Sprintf("| %s | [%s](:contract/%s) | %s | %s | %s | %d ugnot |\n",
			c.ID, c.Title, c.ID, truncAddr(c.Client), truncAddr(c.Freelancer),
			string(c.Status), contractTotal(c)))
		return false
	})
	if offset+RenderPageSize < live {
		sb.WriteString(ufmt.Sprintf("\n[Next page](:page/%d)\n", page+1))
	}
	return sb.String()
}

func renderContract(id string) string {
	val, exists := contracts.Get(id)
	if !exists {
		return "# 404\nContract not found: " + id
	}
	c := val.(*Contract)

	var sb strings.Builder
	sb.WriteString("# " + c.Title + "\n\n")
	if len(c.Description) > 0 {
		sb.WriteString(c.Description + "\n\n")
	}
	sb.WriteString("**ID:** " + c.ID + "\n")
	sb.WriteString("**Client:** " + c.Client.String() + "\n")
	sb.WriteString("**Freelancer:** " + c.Freelancer.String() + "\n")
	sb.WriteString("**Status:** " + string(c.Status) + "\n")
	sb.WriteString("**Created:** block " + strconv.FormatInt(c.CreatedAt, 10) + "\n\n")
	sb.WriteString("**Total Value:** " + strconv.FormatInt(contractTotal(c), 10) + " ugnot\n\n")

	sb.WriteString("## Milestones\n\n")
	for _, ms := range c.Milestones {
		sb.WriteString(ufmt.Sprintf("- **%s** — %d ugnot [%s]", ms.Title, ms.Amount, string(ms.Status)))
		if ms.FundedAt > 0 {
			sb.WriteString(ufmt.Sprintf(" (funded block %d)", ms.FundedAt))
		}
		if ms.CompletedAt > 0 {
			sb.WriteString(ufmt.Sprintf(" (completed block %d)", ms.CompletedAt))
		}
		if ms.DisputedAt > 0 {
			sb.WriteString(ufmt.Sprintf(" (disputed block %d)", ms.DisputedAt))
		}
		sb.WriteString("\n")
	}
	return sb.String()
}

func renderStats() string {
	var sb strings.Builder
	sb.WriteString("# Escrow Stats\n\n")
	sb.WriteString(ufmt.Sprintf("**Created:** %d\n", nextID))
	sb.WriteString(ufmt.Sprintf("**Open:** %d (at most %d per client)\n", activeCount, MaxActivePerClient))
	sb.WriteString(ufmt.Sprintf("**Settled, not archived:** %d\n", contracts.Size()-activeCount))
	sb.WriteString(ufmt.Sprintf("**Archived:** %d\n", archivedCount))
	sb.WriteString(ufmt.Sprintf("**Liabilities:** %d ugnot\n", totalLiable))
	p := PauseState()
	switch {
	case !p.Paused:
		sb.WriteString("**Paused:** no\n")
	case !p.ExitsOpen:
		sb.WriteString(ufmt.Sprintf("**Paused:** yes, since block %d; exits reopen at block %d\n", p.PausedAt, p.ExitsReopenAt))
	default:
		sb.WriteString(ufmt.Sprintf("**Paused:** new contracts and funding only, since block %d\n", p.PausedAt))
	}
	return sb.String()
}

// contractTotal cannot overflow: CreateContract refuses totals above int64.
func contractTotal(c *Contract) int64 {
	total := int64(0)
	for _, ms := range c.Milestones {
		total += ms.Amount
	}
	return total
}

func truncAddr(addr address) string {
	s := addr.String()
	if len(s) > 13 {
		return s[:10] + "..."
	}
	return s
}

package gnobuilders_badges_v2

// gnobuilders_badges — GRC721 badge collection for GnoBuilders quests.
//
// Features:
//   - Admin-only minting (backend triggers mint after quest verification)
//   - Two badge types: Quest badges (transferable) and Rank badges (soulbound)
//   - Per-quest deduplication (one badge per quest per user)
//   - Standard GRC721: BalanceOf, OwnerOf, TokenURI, TransferFrom, Approve
//   - Render() contract for badge gallery display
//
// Security:
//   - Only admin can mint (prevents self-minting)
//   - Soulbound badges: TransferFrom panics for rank badges
//   - Owner can add/remove admins
//   - Token ID format: "{address}:{questId}" (globally unique)

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/samcrew/avl"
	"gno.land/p/nt/ufmt/v0"
)

// ── Constants ────────────────────────────────────────────────

const (
	CollectionName   = "GnoBuilders Badges"
	CollectionSymbol = "GNOBADGE"
	MaxAdmins        = 10
)

// ── Types ────────────────────────────────────────────────────

type Badge struct {
	TokenID   string  // "{address}:{questId}"
	Owner     address
	QuestID   string
	TokenURI  string  // IPFS CID or URL to badge metadata JSON
	Soulbound bool    // true for rank badges (non-transferable)
	MintedAt  int64   // block height
}

// ── State ────────────────────────────────────────────────────

var (
	badges      *avl.Tree // tokenID -> *Badge
	ownerIndex  *avl.Tree // address -> comma-separated tokenIDs (secondary index)
	balances    *avl.Tree // address -> int (badge count)
	approvals   *avl.Tree // tokenID -> approved address
	opApprove   *avl.Tree // "owner:operator" -> bool (approval for all)
	admins      *avl.Tree // address -> bool
	// owner is the publishing transaction's signer, captured at package load (on
	// gnoland-1 the samcrew namespace multisig, the stamped creator at enable
	// time). pendingOwner is the staged successor of a two-step handoff, or empty.
	owner        = unsafe.OriginCaller()
	pendingOwner address
	totalMinted uint64
	paused      bool
)

func init() {
	badges = avl.NewTree()
	ownerIndex = avl.NewTree()
	balances = avl.NewTree()
	approvals = avl.NewTree()
	opApprove = avl.NewTree()
	admins = avl.NewTree()

	admins.Set(owner.String(), true)
}

// ── Emergency Pause ────────────────────────────────────────

func assertNotPaused() {
	if paused {
		panic("realm is paused — emergency maintenance")
	}
}

func Pause(cur realm) {
	assertCallerIsOwner()
	paused = true
}

func Unpause(cur realm) {
	assertCallerIsOwner()
	paused = false
}

func IsPaused() bool { return paused }

// ── GRC721 Standard ─────────────────────────────────────────

func Name() string   { return CollectionName }
func Symbol() string { return CollectionSymbol }

func TotalSupply() uint64 { return totalMinted }

func BalanceOf(addr address) uint64 {
	val, exists := balances.Get(addr.String())
	if !exists {
		return 0
	}
	return uint64(val.(int))
}

func OwnerOf(tokenID string) address {
	val, exists := badges.Get(tokenID)
	if !exists {
		panic("token not found: " + tokenID)
	}
	return val.(*Badge).Owner
}

func TokenURI(tokenID string) string {
	val, exists := badges.Get(tokenID)
	if !exists {
		panic("token not found: " + tokenID)
	}
	return val.(*Badge).TokenURI
}

func Approve(cur realm, approved address, tokenID string) {
	assertNotPaused()
	caller := unsafe.PreviousRealm().Address()
	val, exists := badges.Get(tokenID)
	if !exists {
		panic("token not found")
	}
	badge := val.(*Badge)
	if badge.Owner != caller {
		panic("only owner can approve")
	}
	if badge.Soulbound {
		panic("soulbound badges cannot be approved for transfer")
	}
	approvals.Set(tokenID, approved.String())

	// GRC721 Approval event
	chain.Emit("Approval",
		"owner", caller.String(),
		"approved", approved.String(),
		"tokenId", tokenID,
	)
}

func SetApprovalForAll(cur realm, operator address, approved bool) {
	assertNotPaused()
	if operator == "" {
		panic("operator address cannot be empty")
	}
	caller := unsafe.PreviousRealm().Address()
	if operator == caller {
		panic("cannot approve self")
	}
	key := caller.String() + ":" + operator.String()
	if approved {
		opApprove.Set(key, true)
	} else {
		opApprove.Remove(key)
	}
}

func IsApprovedForAll(ownerAddr address, operator address) bool {
	key := ownerAddr.String() + ":" + operator.String()
	_, exists := opApprove.Get(key)
	return exists
}

func GetApproved(tokenID string) address {
	val, exists := approvals.Get(tokenID)
	if !exists {
		return ""
	}
	return address(val.(string))
}

func TransferFrom(cur realm, from address, to address, tokenID string) {
	assertNotPaused()
	caller := unsafe.PreviousRealm().Address()

	val, exists := badges.Get(tokenID)
	if !exists {
		panic("token not found")
	}
	badge := val.(*Badge)

	// Soulbound check
	if badge.Soulbound {
		panic("soulbound badges cannot be transferred")
	}

	// Auth check
	if badge.Owner != caller {
		approved := GetApproved(tokenID)
		if approved != caller && !IsApprovedForAll(from, caller) {
			panic("not authorized to transfer")
		}
	}

	if badge.Owner != from {
		panic("from address is not the owner")
	}

	// Transfer
	badge.Owner = to
	badges.Set(tokenID, badge)
	approvals.Remove(tokenID) // Clear approval

	// Update balances and owner index
	removeFromOwnerIndex(from, tokenID)
	addToOwnerIndex(to, tokenID)
	decBalance(from)
	incBalance(to)

	// GRC721 Transfer event
	chain.Emit("Transfer",
		"from", from.String(),
		"to", to.String(),
		"tokenId", tokenID,
	)
}

// ── Minting (Admin Only) ────────────────────────────────────

// MintQuestBadge mints a quest completion badge to a user.
// Token ID is "{address}:{questId}" to enforce one badge per quest per user.
// Quest badges are transferable by default.
func MintQuestBadge(cur realm, to address, questID string, tokenURI string) string {
	assertNotPaused()
	assertCallerIsAdmin()
	if len(questID) == 0 {
		panic("questID cannot be empty")
	}
	if containsChar(questID, ',') || containsChar(questID, ':') {
		panic("questID must not contain ',' or ':'")
	}

	tokenID := to.String() + ":" + questID

	// Check dedup
	if _, exists := badges.Get(tokenID); exists {
		panic("badge already minted for this quest: " + tokenID)
	}

	badge := &Badge{
		TokenID:   tokenID,
		Owner:     to,
		QuestID:   questID,
		TokenURI:  tokenURI,
		Soulbound: false,
		MintedAt:  runtime.ChainHeight(),
	}

	badges.Set(tokenID, badge)
	addToOwnerIndex(to, tokenID)
	incBalance(to)
	totalMinted++

	// GRC721 Transfer event from zero address (mint convention)
	chain.Emit("Transfer",
		"from", "",
		"to", to.String(),
		"tokenId", tokenID,
	)
	chain.Emit("QuestBadgeMinted",
		"to", to.String(),
		"questId", questID,
		"tokenId", tokenID,
	)

	return tokenID
}

// MintRankBadge mints a soulbound rank badge to a user.
// Token ID is "{address}:rank:{tier}" to enforce one rank badge per tier per user.
// Rank badges are NON-transferable (soulbound).
func MintRankBadge(cur realm, to address, tier int, tokenURI string) string {
	assertNotPaused()
	assertCallerIsAdmin()

	tokenID := to.String() + ":rank:" + strconv.Itoa(tier)

	// Check dedup
	if _, exists := badges.Get(tokenID); exists {
		panic("rank badge already minted for tier " + strconv.Itoa(tier))
	}

	badge := &Badge{
		TokenID:   tokenID,
		Owner:     to,
		QuestID:   "rank:" + strconv.Itoa(tier),
		TokenURI:  tokenURI,
		Soulbound: true,
		MintedAt:  runtime.ChainHeight(),
	}

	badges.Set(tokenID, badge)
	addToOwnerIndex(to, tokenID)
	incBalance(to)
	totalMinted++

	chain.Emit("Transfer",
		"from", "",
		"to", to.String(),
		"tokenId", tokenID,
	)
	chain.Emit("RankBadgeMinted",
		"to", to.String(),
		"tier", strconv.Itoa(tier),
		"tokenId", tokenID,
	)

	return tokenID
}

// UpdateTokenURI allows an admin to update the metadata URI of a badge.
// This is critical because realm code is immutable once deployed — if badge
// metadata needs correction (e.g., broken IPFS CID), this is the only mechanism.
func UpdateTokenURI(cur realm, tokenID string, newURI string) {
	assertNotPaused()
	assertCallerIsAdmin()
	val, exists := badges.Get(tokenID)
	if !exists {
		panic("token not found: " + tokenID)
	}
	badge := val.(*Badge)
	badge.TokenURI = newURI
	badges.Set(tokenID, badge)
}

// ── Burn / Revoke ───────────────────────────────────────────

// BurnBadge permanently removes a badge. Admin-only for soulbound badges,
// owner or admin for transferable badges.
func BurnBadge(cur realm, tokenID string) {
	assertNotPaused()
	caller := unsafe.PreviousRealm().Address()
	val, exists := badges.Get(tokenID)
	if !exists {
		panic("token not found: " + tokenID)
	}
	badge := val.(*Badge)

	if badge.Soulbound {
		// Soulbound: admin-only burn (revocation)
		assertCallerIsAdmin()
	} else {
		// Transferable: owner or admin can burn
		isAdmin := false
		if _, aok := admins.Get(caller.String()); aok {
			isAdmin = true
		}
		if badge.Owner != caller && !isAdmin {
			panic("only badge owner or admin can burn")
		}
	}

	badgeOwner := badge.Owner
	badges.Remove(tokenID)
	approvals.Remove(tokenID)
	removeFromOwnerIndex(badgeOwner, tokenID)
	decBalance(badgeOwner)
	if totalMinted > 0 {
		totalMinted--
	}

	// GRC721 Transfer event to zero address (burn convention)
	chain.Emit("Transfer",
		"from", badgeOwner.String(),
		"to", "",
		"tokenId", tokenID,
	)
}

// ── Admin Management ────────────────────────────────────────

func AddAdmin(cur realm, addr address) {
	assertCallerIsOwner()
	if addr == "" {
		panic("address cannot be empty")
	}
	if admins.Size() >= MaxAdmins {
		panic("admin limit reached")
	}
	admins.Set(addr.String(), true)
}

func RemoveAdmin(cur realm, addr address) {
	assertCallerIsOwner()
	if addr == owner {
		panic("cannot remove owner")
	}
	if _, exists := admins.Get(addr.String()); !exists {
		panic("address is not an admin: " + addr.String())
	}
	admins.Remove(addr.String())
}

// TransferOwnership stages a successor owner. Nothing moves until that address
// calls AcceptOwnership with its own transaction, so ownership can never land on
// an address that cannot act. A later call replaces the staged address;
// CancelOwnershipTransfer withdraws it.
func TransferOwnership(cur realm, newOwner address) {
	assertCallerIsOwner()
	if newOwner == "" {
		panic("address cannot be empty")
	}
	if !newOwner.IsValid() {
		panic("invalid address: " + newOwner.String())
	}
	if newOwner == owner {
		panic("already owner")
	}
	pendingOwner = newOwner
	chain.Emit("OwnershipTransferStarted", "pending", newOwner.String())
}

// CancelOwnershipTransfer withdraws a staged handoff. Owner only.
func CancelOwnershipTransfer(cur realm) {
	assertCallerIsOwner()
	if pendingOwner == "" {
		panic("no pending ownership transfer")
	}
	cancelled := pendingOwner
	pendingOwner = ""
	chain.Emit("OwnershipTransferCancelled", "pending", cancelled.String())
}

// AcceptOwnership completes the handoff. Only the staged pendingOwner may call
// it. The successor becomes an admin and the former owner's admin grant is
// revoked in the same transaction. Other explicitly appointed admins remain.
func AcceptOwnership(cur realm) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	caller := cur.Previous().Address()
	if pendingOwner == "" || caller != pendingOwner {
		panic("unauthorized: caller " + caller.String() + " is not the pending owner")
	}
	prev := owner
	admins.Set(caller.String(), true)
	admins.Remove(prev.String())
	owner = caller
	pendingOwner = ""
	chain.Emit("OwnershipTransferred",
		"previousOwner", prev.String(),
		"newOwner", caller.String(),
	)
}

// GetPendingOwner returns the staged successor, or the empty address.
func GetPendingOwner() address { return pendingOwner }

func IsAdmin(addr address) bool {
	_, exists := admins.Get(addr.String())
	return exists
}

func GetOwner() address { return owner }

// ── Queries ─────────────────────────────────────────────────

// GetBadge returns badge info as a pipe-delimited string.
func GetBadge(tokenID string) string {
	val, exists := badges.Get(tokenID)
	if !exists {
		return ""
	}
	b := val.(*Badge)
	sb := strconv.FormatBool(b.Soulbound)
	return ufmt.Sprintf("%s|%s|%s|%s|%s|%d",
		b.TokenID, b.Owner, b.QuestID, b.TokenURI, sb, b.MintedAt)
}

// GetUserBadges returns all badge token IDs for a user as comma-separated string.
// Uses the ownerIndex for O(1) lookup instead of full table scan.
func GetUserBadges(addr address) string {
	val, exists := ownerIndex.Get(addr.String())
	if !exists {
		return ""
	}
	return val.(string)
}

// GetUserBadgeDetails returns full badge details for a user as a multi-line string.
// Each line: tokenID|owner|questID|tokenURI|soulbound|mintedAt
// This avoids N+1 queries from the frontend — one call returns all badge data.
func GetUserBadgeDetails(addr address) string {
	tokenIDsStr := GetUserBadges(addr)
	if tokenIDsStr == "" {
		return ""
	}

	var lines []string
	for _, tokenID := range strings.Split(tokenIDsStr, ",") {
		info := GetBadge(tokenID)
		if info != "" {
			lines = append(lines, info)
		}
	}
	return strings.Join(lines, "\n")
}

// ── Render ──────────────────────────────────────────────────

func Render(path string) string {
	if path == "" {
		return renderHome()
	}
	if strings.HasPrefix(path, "badge/") {
		tokenID := strings.TrimPrefix(path, "badge/")
		return renderBadge(tokenID)
	}
	if strings.HasPrefix(path, "user/") {
		addr := strings.TrimPrefix(path, "user/")
		return renderUserBadges(addr)
	}
	return "# 404\nPage not found: " + path
}

func renderHome() string {
	var sb strings.Builder
	sb.WriteString("# GnoBuilders Badges\n\n")
	sb.WriteString(ufmt.Sprintf("**Collection:** %s (%s)\n", CollectionName, CollectionSymbol))
	sb.WriteString(ufmt.Sprintf("**Total Minted:** %d\n", totalMinted))
	sb.WriteString(ufmt.Sprintf("**Owner:** %s\n", owner))
	sb.WriteString(ufmt.Sprintf("**Admins:** %d\n\n", admins.Size()))

	// Recent badges (last 20)
	count := 0
	sb.WriteString("## Recent Badges\n\n")
	sb.WriteString("| Token | Quest | Owner | Soulbound |\n")
	sb.WriteString("|-------|-------|-------|-----------|\n")
	badges.ReverseIterate("", "", func(key string, value any) bool {
		if count >= 20 {
			return true
		}
		b := value.(*Badge)
		soul := ""
		if b.Soulbound {
			soul = "yes"
		}
		sb.WriteString(ufmt.Sprintf("| %s | %s | %s | %s |\n",
			truncStr(b.TokenID, 30), b.QuestID, truncAddr(b.Owner), soul))
		count++
		return false
	})

	return sb.String()
}

func renderBadge(tokenID string) string {
	val, exists := badges.Get(tokenID)
	if !exists {
		return "# Badge Not Found\nNo badge with ID: " + tokenID
	}
	b := val.(*Badge)
	var sb strings.Builder
	sb.WriteString(ufmt.Sprintf("# Badge: %s\n\n", b.QuestID))
	sb.WriteString(ufmt.Sprintf("**Token ID:** %s\n", b.TokenID))
	sb.WriteString(ufmt.Sprintf("**Owner:** %s\n", b.Owner))
	sb.WriteString(ufmt.Sprintf("**Quest:** %s\n", b.QuestID))
	sb.WriteString(ufmt.Sprintf("**Soulbound:** %s\n", strconv.FormatBool(b.Soulbound)))
	sb.WriteString(ufmt.Sprintf("**Minted at block:** %d\n", b.MintedAt))
	if b.TokenURI != "" {
		sb.WriteString(ufmt.Sprintf("**Metadata:** %s\n", b.TokenURI))
	}
	return sb.String()
}

func renderUserBadges(addr string) string {
	var sb strings.Builder
	sb.WriteString(ufmt.Sprintf("# Badges for %s\n\n", addr))

	// Use ownerIndex for O(1) lookup instead of full table scan
	tokenIDsStr := GetUserBadges(address(addr))
	if tokenIDsStr == "" {
		sb.WriteString("*No badges yet.*\n")
		return sb.String()
	}

	tokenIDs := strings.Split(tokenIDsStr, ",")
	for _, tokenID := range tokenIDs {
		val, exists := badges.Get(tokenID)
		if !exists {
			continue
		}
		b := val.(*Badge)
		soul := ""
		if b.Soulbound {
			soul = " (soulbound)"
		}
		sb.WriteString(ufmt.Sprintf("- **%s** — %s%s (block %d)\n",
			b.QuestID, truncStr(b.TokenURI, 40), soul, b.MintedAt))
	}

	return sb.String()
}

// ── Helpers ─────────────────────────────────────────────────

func assertCallerIsAdmin() {
	caller := unsafe.PreviousRealm().Address()
	if _, exists := admins.Get(caller.String()); !exists {
		panic("unauthorized: caller " + caller.String() + " is not an admin")
	}
}

func assertCallerIsOwner() {
	caller := unsafe.PreviousRealm().Address()
	if caller != owner {
		panic("unauthorized: caller " + caller.String() + " is not the owner")
	}
}

func incBalance(addr address) {
	val, exists := balances.Get(addr.String())
	if !exists {
		balances.Set(addr.String(), 1)
	} else {
		balances.Set(addr.String(), val.(int)+1)
	}
}

func decBalance(addr address) {
	val, exists := balances.Get(addr.String())
	if !exists {
		return
	}
	n := val.(int) - 1
	if n <= 0 {
		balances.Remove(addr.String())
	} else {
		balances.Set(addr.String(), n)
	}
}

func truncAddr(addr address) string {
	s := addr.String()
	if len(s) > 13 {
		return s[:10] + "..."
	}
	return s
}

func truncStr(s string, maxLen int) string {
	if len(s) > maxLen {
		return s[:maxLen-3] + "..."
	}
	return s
}

// ── Owner Index Management ──────────────────────────────────

func addToOwnerIndex(addr address, tokenID string) {
	key := addr.String()
	val, exists := ownerIndex.Get(key)
	if !exists {
		ownerIndex.Set(key, tokenID)
	} else {
		ownerIndex.Set(key, val.(string)+","+tokenID)
	}
}

func containsChar(s string, ch rune) bool {
	for _, c := range s {
		if c == ch {
			return true
		}
	}
	return false
}

func removeFromOwnerIndex(addr address, tokenID string) {
	key := addr.String()
	val, exists := ownerIndex.Get(key)
	if !exists {
		return
	}
	ids := strings.Split(val.(string), ",")
	var remaining []string
	for _, id := range ids {
		if id != tokenID {
			remaining = append(remaining, id)
		}
	}
	if len(remaining) == 0 {
		ownerIndex.Remove(key)
	} else {
		ownerIndex.Set(key, strings.Join(remaining, ","))
	}
}

package gnobuilders_badges_v2

// GetAdminCount is a value-only governance readback. It lets a proposal freeze
// the exact admin capacity before voting and verify the count after dispatch.
func GetAdminCount() int { return admins.Size() }

package memba_appstore_v3

import "chain"

// Admin surface — owner-gated. The owner is the samcrew multisig at launch and can
// be handed to the memba_dao executor via the 2-step TransferOwnership/AcceptOwnership
// (never a 1-step transfer to a mistyped/dead address).

// SetRegistrationFee sets the flat listing fee in ugnot (0..MaxRegistrationFee).
// Zero is allowed (a fee waiver). Owner only.
func SetRegistrationFee(cur realm, fee int64) {
	assertOwner()
	if fee < 0 || fee > MaxRegistrationFee {
		panic("fee out of range [0, MaxRegistrationFee]")
	}
	registrationFee = fee
	chain.Emit("RegistrationFeeSet", "fee", itoa64(uint64(fee)))
}

// SetTreasury repoints the fee recipient. Must be non-empty (an empty treasury would
// fail-close RegisterApp). Owner only. Keep this in sync with
// memba_market_config.GetTreasury().
func SetTreasury(cur realm, addr address) {
	assertOwner()
	if addr == "" {
		panic("treasury must be non-empty")
	}
	treasury = addr
	chain.Emit("TreasurySet", "treasury", addr.String())
}

// AddCurator grants the curate role (approve pending listings). Owner only.
func AddCurator(cur realm, addr address) {
	assertOwner()
	if addr == "" {
		panic("curator must be non-empty")
	}
	curators.Set(addr.String(), true)
	chain.Emit("CuratorAdded", "curator", addr.String())
}

// RemoveCurator revokes the curate role. Owner only.
func RemoveCurator(cur realm, addr address) {
	assertOwner()
	curators.Remove(addr.String())
	chain.Emit("CuratorRemoved", "curator", addr.String())
}

// Pause is the kill switch: while paused, RegisterApp aborts (reads stay available).
// Owner only.
func Pause(cur realm, state bool) {
	assertOwner()
	paused = state
	chain.Emit("PauseSet", "paused", boolStr(state))
}

// TransferOwnership stages a new owner; it takes effect only after AcceptOwnership
// is called BY that address (2-step, so a typo can't brick admin). A later call
// replaces the staged address; CancelOwnershipTransfer withdraws it.
func TransferOwnership(cur realm, newOwner address) {
	assertOwner()
	if newOwner == "" {
		panic("newOwner must be non-empty")
	}
	if !newOwner.IsValid() {
		panic("invalid address: " + newOwner.String())
	}
	if newOwner == owner {
		panic("newOwner is the current owner")
	}
	pendingOwner = newOwner
	chain.Emit("OwnershipTransferStarted", "pending", newOwner.String())
}

// CancelOwnershipTransfer withdraws a staged handoff. Owner only.
func CancelOwnershipTransfer(cur realm) {
	assertOwner()
	if pendingOwner == "" {
		panic("no pending ownership transfer")
	}
	cancelled := pendingOwner
	pendingOwner = ""
	chain.Emit("OwnershipTransferCancelled", "pending", cancelled.String())
}

// GetPendingOwner returns the staged successor, or the empty address.
func GetPendingOwner() address { return pendingOwner }

// AcceptOwnership completes the handoff. Only the staged pendingOwner may call it.
// The former owner's curator grant is revoked atomically; the successor can
// curate immediately and may explicitly re-appoint the former owner later.
func AcceptOwnership(cur realm) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	if pendingOwner == "" {
		panic("no pending ownership transfer")
	}
	if cur.Previous().Address() != pendingOwner {
		panic("unauthorized: only the pending owner may accept")
	}
	previous := owner
	curators.Set(pendingOwner.String(), true)
	curators.Remove(previous.String())
	owner = pendingOwner
	pendingOwner = ""
	chain.Emit("OwnershipTransferAccepted", "owner", owner.String())
}

func boolStr(b bool) string {
	if b {
		return "true"
	}
	return "false"
}

// Package memba_appstore_v3 is a curated App Store for gno.land dApps: publishers
// pay a flat listing fee to register an app; a curator flips it live (or rejects it).
//
// MONEY PATH (the only one): RegisterApp collects a flat `registrationFee` in ugnot
// and forwards 100% to the treasury in the SAME call — nothing is ever custodied.
// The safety contract mirrors memba_token_otc_v1 + the O-13 lesson:
//   1. IsUserCall() guard BEFORE reading OriginSend — an ephemeral `maketx run`
//      realm can never attach unrecoverable coins (the guard agent_registry missed).
//   2. exact-coin via unsafe.OriginSend() (the coins on THIS call, not the wallet
//      balance) — closes the overpay-trap and the wallet-balance bypass.
//   3. treasury-misconfig is fail-closed: an unset treasury panics (→ tx reverts →
//      coins refunded), never silent custody.
//   4. CEI: state is written before the banker moves funds. All attacker-controlled
//      input (screenshots, appURL scheme) is validated BEFORE OriginSend is read.
//   5. NewBanker(RealmSend, cur) sends the fee from the realm's own address to the
//      treasury — no custody, no escrow (which is why no escrow is needed to be safe).
//
// v3 over v2: a `rejected` state + RejectApp/EditListing lifecycle, ≤6 screenshots,
// an on-chain appURL scheme allowlist, FlagApp extended to pending listings (the
// public Unverified tab's safety valve), composite-key status/publisher indexes with
// O(1) per-status counters (so status/publisher reads are bounded, not full scans),
// and a sealed SeedListing migration primitive (FinalizeSeed closes the backdoor).
//
// TREASURY: stored LOCALLY (admin-settable, 2-step handoff, defaults to the samcrew
// multisig) rather than read from memba_market_config — keeps the money path locally
// unit-testable. Keep it in sync with memba_market_config.GetTreasury().
package memba_appstore_v3

import (
	"strings"

	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"

	"gno.land/p/samcrew/avl"
	"gno.land/p/nt/ufmt/v0"
)

// No authority is compiled in. The publishing transaction's signer (on
// gnoland-1 the samcrew namespace multisig, the stamped creator at enable time)
// is seeded as owner, treasury and first curator at package load, and every
// later change goes through the owner-gated admin surface: SetTreasury repoints
// the fee recipient, and TransferOwnership/AcceptOwnership hand admin to the
// memba_dao executor in two steps.

const (
	// DefaultRegistrationFee is the launch listing fee: 1 GNOT (1_000_000 ugnot).
	DefaultRegistrationFee = int64(1_000_000)
	// MaxRegistrationFee caps a fat-finger / compromised-proposal fee at 100 GNOT.
	MaxRegistrationFee = int64(100_000_000)

	MaxNameLen     = 80
	MaxTaglineLen  = 140
	MaxDescrLen    = 2000
	MaxCategoryLen = 40
	MaxURLLen      = 400
	MaxPkgPathLen  = 200
	MaxCIDLen      = 100
	MaxReasonLen   = 500
	// MaxScreenshots bounds the per-listing screenshot gallery.
	MaxScreenshots = 6
	// MaxResubmits bounds how many times a publisher can edit/resubmit a listing, so a
	// reject→edit→pending loop can't grief the curator queue indefinitely.
	MaxResubmits = 5
	// FlagHideThreshold auto-hides a listing (live OR pending) from the public lists once
	// this many distinct addresses have flagged it.
	FlagHideThreshold = 5
)

// Listing lifecycle states.
const (
	StatusPending  = "pending"
	StatusLive     = "live"
	StatusRejected = "rejected"
	StatusDelisted = "delisted"
)

// Listing is one app. PkgPath (the realm/package path) is the unique key.
type Listing struct {
	Id                 uint64
	PkgPath            string
	Name               string
	Tagline            string
	Descr              string
	Category           string
	IconCID            string
	ScreenshotCIDs     []string
	AppURL             string
	Publisher          address
	Status             string
	RejectReason       string
	PaidResubmitCredit bool
	ResubmitCount      int
	FlagCount          int
	CreatedAt          int64
}

var (
	owner          address
	pendingOwner   address
	treasury       address
	registrationFee int64
	paused         bool
	seedingSealed  bool
	curators       = avl.NewTree() // address string -> bool
	listings       = avl.NewTree() // pkgPath -> *Listing
	flaggedBy      = avl.NewTree() // pkgPath + "\x00" + addr -> bool (one flag per addr)
	// statusIndex/publisherIndex: composite-key indexes for bounded status/publisher reads.
	// key = status|pub + "\x00" + zeroPad(id) -> pkgPath, so a prefix range-iterate yields a
	// true O(offset+limit) window ordered by submission id, never a full-catalog scan.
	statusIndex    = avl.NewTree()
	publisherIndex = avl.NewTree()
	// O(1) per-status counters, maintained on every status transition.
	liveCount     int
	pendingCount  int
	rejectedCount int
	delistedCount int
	nextId uint64 = 1
)

func init() {
	registrationFee = DefaultRegistrationFee
	seedAuthority(unsafe.OriginCaller())
}

// seedAuthority makes the publisher the owner, the fee recipient and the first
// curator. It runs once at package load; there is no other way to obtain owner.
func seedAuthority(publisher address) {
	owner = publisher
	pendingOwner = ""
	treasury = publisher
	curators.Set(publisher.String(), true)
}

func caller() address { return unsafe.PreviousRealm().Address() }

func assertOwner() {
	if caller() != owner {
		panic("unauthorized: owner only")
	}
}

func assertNotPaused() {
	if paused {
		panic("appstore is paused")
	}
}

// ── Money path ────────────────────────────────────────────────────────────────

// RegisterApp lists a new app. The caller pays EXACTLY registrationFee ugnot with the call;
// the whole fee is forwarded to the treasury (no custody). The listing starts `pending`.
func RegisterApp(
	cur realm,
	pkgPath, name, tagline, descr, category, iconCID, screenshotsCSV, appURL string,
) uint64 {
	assertNotPaused()

	// O-13 guard: a payable entrypoint MUST be a direct user call.
	if !unsafe.PreviousRealm().IsUserCall() {
		panic("RegisterApp must be a direct user call")
	}

	// Validate ALL attacker-controlled input BEFORE reading the attached coins.
	pkgPath = validatePkgPath(pkgPath)
	if _, dup := listings.Get(pkgPath); dup {
		panic("app already registered for this package path")
	}
	validateListingFields(name, tagline, descr, category, iconCID, appURL)
	shots := parseScreenshots(screenshotsCSV)

	// Exact-coin: read the coins attached to THIS call (not the wallet balance).
	sent := unsafe.OriginSend()
	if sent.AmountOf("ugnot") != registrationFee {
		panic(ufmt.Sprintf("must send exactly %d ugnot (sent %d)", registrationFee, sent.AmountOf("ugnot")))
	}
	// Fail-closed on a misconfigured treasury — reverting refunds the coins.
	if treasury == "" {
		panic("treasury unset — registration disabled")
	}

	// CEI: write state before moving funds.
	id := nextId
	nextId++
	l := &Listing{
		Id:             id,
		PkgPath:        pkgPath,
		Name:           name,
		Tagline:        tagline,
		Descr:          descr,
		Category:       category,
		IconCID:        iconCID,
		ScreenshotCIDs: shots,
		AppURL:         appURL,
		Publisher:      caller(),
		Status:         StatusPending,
		CreatedAt:      runtime.ChainHeight(),
	}
	listings.Set(pkgPath, l)
	indexInsert(l)

	// Forward the whole fee to the treasury from the realm's own account.
	if registrationFee > 0 {
		bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
		bnk.SendCoins(
			unsafe.CurrentRealm().Address(),
			treasury,
			chain.Coins{chain.NewCoin("ugnot", registrationFee)},
		)
	}

	chain.Emit("AppRegistered", "pkgPath", pkgPath, "id", itoa64(id), "publisher", caller().String())
	return id
}

// ── Curation & moderation ───────────────────────────────────────────────────

// ApproveApp flips a pending (or previously-live) listing live. Curator-only.
func ApproveApp(cur realm, pkgPath string) {
	if !isCurator(caller()) {
		panic("unauthorized: curator only")
	}
	l := mustGet(pkgPath)
	if l.Status == StatusDelisted {
		panic("cannot approve a delisted app")
	}
	if l.Status != StatusLive {
		changeStatus(l, StatusLive)
	}
	chain.Emit("AppApproved", "pkgPath", pkgPath)
}

// RejectApp declines a pending submission, recording a reason and granting a one-time free
// resubmit credit. Curator-only; only a pending app can be rejected.
func RejectApp(cur realm, pkgPath, reason string) {
	if !isCurator(caller()) {
		panic("unauthorized: curator only")
	}
	if len(reason) > MaxReasonLen {
		panic("reason too long")
	}
	l := mustGet(pkgPath)
	if l.Status != StatusPending {
		panic("only a pending app can be rejected")
	}
	changeStatus(l, StatusRejected)
	l.RejectReason = reason
	l.PaidResubmitCredit = true
	listings.Set(pkgPath, l)
	chain.Emit("AppRejected", "pkgPath", pkgPath)
}

// EditListing lets the publisher update a listing that is NOT live/delisted — i.e. a pending
// or rejected one — and resets it to `pending` for (re-)review. Editing a live listing is
// structurally forbidden so a Verified badge can never be bait-and-switched. Bounded by
// MaxResubmits so a reject→edit loop can't grief the queue.
func EditListing(
	cur realm,
	pkgPath, name, tagline, descr, category, iconCID, screenshotsCSV, appURL string,
) {
	l := mustGet(pkgPath)
	if caller() != l.Publisher {
		panic("unauthorized: publisher only")
	}
	if l.Status != StatusPending && l.Status != StatusRejected {
		panic("cannot edit a live or delisted listing")
	}
	if l.ResubmitCount >= MaxResubmits {
		panic("resubmit limit reached")
	}
	validateListingFields(name, tagline, descr, category, iconCID, appURL)
	shots := parseScreenshots(screenshotsCSV)

	l.Name = name
	l.Tagline = tagline
	l.Descr = descr
	l.Category = category
	l.IconCID = iconCID
	l.ScreenshotCIDs = shots
	l.AppURL = appURL
	l.RejectReason = ""
	l.ResubmitCount++
	if l.Status != StatusPending {
		changeStatus(l, StatusPending) // rejected → pending (re-review); persists via Set
	} else {
		listings.Set(pkgPath, l)
	}
	chain.Emit("AppEdited", "pkgPath", pkgPath)
}

// DelistApp removes a listing from public view. The publisher or a curator may do it.
func DelistApp(cur realm, pkgPath string) {
	l := mustGet(pkgPath)
	if caller() != l.Publisher && !isCurator(caller()) {
		panic("unauthorized: publisher or curator only")
	}
	if l.Status != StatusDelisted {
		changeStatus(l, StatusDelisted)
	}
	chain.Emit("AppDelisted", "pkgPath", pkgPath)
}

// RestoreApp brings a delisted app back to `pending` (re-curation required). Curator-only.
func RestoreApp(cur realm, pkgPath string) {
	if !isCurator(caller()) {
		panic("unauthorized: curator only")
	}
	l := mustGet(pkgPath)
	if l.Status != StatusDelisted {
		panic("only a delisted app can be restored")
	}
	changeStatus(l, StatusPending)
	chain.Emit("AppRestored", "pkgPath", pkgPath)
}

// FlagApp lets any user flag a publicly-listed (live OR pending) listing once. At
// FlagHideThreshold distinct flags the listing drops from the public lists (isVisible), giving
// the public Unverified/pending tab a community safety valve; a curator can then Delist/Reject.
func FlagApp(cur realm, pkgPath string) {
	l := mustGet(pkgPath)
	if l.Status != StatusLive && l.Status != StatusPending {
		panic("can only flag a live or pending app")
	}
	key := pkgPath + "\x00" + caller().String()
	if _, done := flaggedBy.Get(key); done {
		panic("already flagged")
	}
	flaggedBy.Set(key, true)
	l.FlagCount++
	listings.Set(pkgPath, l)
	chain.Emit("AppFlagged", "pkgPath", pkgPath, "count", itoa(l.FlagCount))
}

// MaxClearBatch bounds how many per-address flag marks one ClearFlags call removes,
// so a mega-brigade (thousands of sybil flags) cannot gas-lock the reset — the
// curator just calls ClearFlags repeatedly until the count reaches zero.
const MaxClearBatch = 200

// ClearFlags resets a listing's community-flag state after curator review. Curator-only.
// Without it a flag-hidden listing stays hidden FOREVER: FlagCount never decrements and
// survives every status transition, so FlagHideThreshold (5) sybil addresses could
// permanently disappear any live app. Clearing also deletes the per-address dedupe marks —
// the community can re-flag if the concern is real, and every clear is an emitted event,
// so a curator whitewashing a bad listing is publicly visible on-chain.
func ClearFlags(cur realm, pkgPath string) {
	if !isCurator(caller()) {
		panic("unauthorized: curator only")
	}
	l := mustGet(pkgPath)
	if l.FlagCount == 0 {
		panic("no flags to clear")
	}
	// Collect up to MaxClearBatch marks over the listing's prefix range (the same
	// [prefix+"\x00", prefix+"\x01") window idiom as reads.gno), then remove them.
	// Keys are collected BEFORE removal — never mutate a tree mid-Iterate.
	var keys []string
	flaggedBy.Iterate(pkgPath+"\x00", pkgPath+"\x01", func(k string, _ any) bool {
		keys = append(keys, k)
		return len(keys) >= MaxClearBatch
	})
	for _, k := range keys {
		flaggedBy.Remove(k)
	}
	l.FlagCount -= len(keys)
	if l.FlagCount < 0 {
		l.FlagCount = 0
	}
	listings.Set(pkgPath, l)
	chain.Emit("AppFlagsCleared", "pkgPath", pkgPath,
		"cleared", itoa(len(keys)), "remaining", itoa(l.FlagCount))
}

// ── Migration (owner-only, sealable) ──────────────────────────────────────────

// SeedListing imports a listing verbatim (Id, CreatedAt, FlagCount, Status, Publisher) during a
// v2→v3 migration. Owner-only, NON-payable (never reads OriginSend / moves funds), dedupe-guarded.
// After the migration the owner calls FinalizeSeed, permanently sealing this entrypoint — without
// that latch it would be a standing backdoor to forge fee-free listings with arbitrary publisher.
func SeedListing(
	cur realm,
	id uint64,
	pkgPath, name, tagline, descr, category, iconCID, screenshotsCSV, appURL, publisherStr, status string,
	flagCount int,
	createdAt int64,
) {
	assertOwner()
	if seedingSealed {
		panic("seeding sealed — migration is finalized")
	}
	pkgPath = validatePkgPath(pkgPath)
	if _, dup := listings.Get(pkgPath); dup {
		panic("app already registered for this package path")
	}
	if !validStatus(status) {
		panic("invalid status")
	}
	// A duplicate id would collide on the composite index key (statusKey/pubKey), silently
	// overwriting one entry while double-counting — so reject an id already present in ANY status
	// (covers both a repeat seed and a seeded id that a prior RegisterApp already used).
	if idInUse(id) {
		panic("id already in use")
	}
	// Seeded data is historical user input — validate it against the SAME field + appURL-scheme
	// rules as a fresh registration, so an unsafe v2 appURL can't be imported past the allowlist.
	validateListingFields(name, tagline, descr, category, iconCID, appURL)
	shots := parseScreenshots(screenshotsCSV)
	l := &Listing{
		Id:             id,
		PkgPath:        pkgPath,
		Name:           name,
		Tagline:        tagline,
		Descr:          descr,
		Category:       category,
		IconCID:        iconCID,
		ScreenshotCIDs: shots,
		AppURL:         appURL,
		Publisher:      address(publisherStr),
		Status:         status,
		FlagCount:      flagCount,
		CreatedAt:      createdAt,
	}
	listings.Set(pkgPath, l)
	indexInsert(l)
	if id >= nextId {
		nextId = id + 1
	}
	chain.Emit("AppSeeded", "pkgPath", pkgPath, "id", itoa64(id))
}

// FinalizeSeed permanently seals SeedListing (one-way latch). Owner-only.
func FinalizeSeed(cur realm) {
	assertOwner()
	seedingSealed = true
	chain.Emit("SeedingFinalized")
}

// ── Read getters (pure, non-failing) ─────────────────────────────────────────

// GetRegistrationFee returns the current flat listing fee in ugnot.
func GetRegistrationFee() int64 { return registrationFee }

// GetTreasury returns the address that receives listing fees.
func GetTreasury() address { return treasury }

// GetOwner returns the current owner (multisig, or a DAO executor after handoff).
func GetOwner() address { return owner }

// AppCount returns the total number of registered listings (any status).
func AppCount() int { return listings.Size() }

// IsCurator reports whether an address may approve/reject listings (the curator-dashboard gate).
func IsCurator(a string) bool {
	_, ok := curators.Get(a)
	return ok
}

// GetCuratorsJSON returns a JSON array of curator addresses (small, bounded).
func GetCuratorsJSON() string {
	var sb strings.Builder
	sb.WriteString("[")
	first := true
	curators.Iterate("", "", func(k string, _ any) bool {
		if !first {
			sb.WriteString(",")
		}
		first = false
		sb.WriteString(`"`)
		sb.WriteString(k) // a bech32 address — no JSON metachars
		sb.WriteString(`"`)
		return false
	})
	sb.WriteString("]")
	return sb.String()
}

// GetStatsJSON returns per-status counts (served from O(1) counters) for the store header.
func GetStatsJSON() string {
	return ufmt.Sprintf(
		`{"total":%d,"live":%d,"pending":%d,"rejected":%d,"delisted":%d,"registrationFee":%d,"paused":%t}`,
		listings.Size(), liveCount, pendingCount, rejectedCount, delistedCount, registrationFee, paused)
}

// ── internal helpers ─────────────────────────────────────────────────────────

func isCurator(a address) bool {
	_, ok := curators.Get(a.String())
	return ok
}

func mustGet(pkgPath string) *Listing {
	v, ok := listings.Get(pkgPath)
	if !ok {
		panic("app not found: " + pkgPath)
	}
	return v.(*Listing)
}

func validStatus(s string) bool {
	return s == StatusPending || s == StatusLive || s == StatusRejected || s == StatusDelisted
}

// validateListingFields checks the length + appURL-scheme invariants shared by RegisterApp and
// EditListing. The appURL scheme allowlist (http/https/leading-slash/empty) is the on-chain
// defense behind the frontend AppLink — it blocks javascript:/data:/other-scheme phishing URLs.
func validateListingFields(name, tagline, descr, category, iconCID, appURL string) {
	if len(name) == 0 || len(name) > MaxNameLen {
		panic("name must be 1.." + itoa(MaxNameLen) + " chars")
	}
	if len(tagline) > MaxTaglineLen {
		panic("tagline too long")
	}
	if len(descr) > MaxDescrLen {
		panic("description too long")
	}
	if len(category) > MaxCategoryLen {
		panic("category too long")
	}
	if len(iconCID) > MaxCIDLen {
		panic("iconCID too long")
	}
	if len(appURL) > MaxURLLen {
		panic("appURL too long")
	}
	validateAppURL(appURL)
}

// validateAppURL enforces the scheme allowlist: empty, http://, https://, or a leading-slash
// in-app path. Anything else (javascript:, data:, ftp:, mailto:, …) aborts. A leading-slash path
// must NOT be protocol-relative (`//host` or `/\host`) — browsers navigate those off-site, which
// would defeat the allowlist.
func validateAppURL(u string) {
	if u == "" {
		return
	}
	if hasPrefix(u, "http://") || hasPrefix(u, "https://") {
		return
	}
	if u[0] == '/' {
		if len(u) > 1 && (u[1] == '/' || u[1] == '\\') {
			panic("appURL scheme: protocol-relative //host is not an in-app path")
		}
		return
	}
	panic("appURL scheme must be http(s):// or a leading-slash path")
}

// parseScreenshots splits a comma-separated CID list, enforcing ≤MaxScreenshots and per-CID
// length. Blank entries are dropped. Empty input → nil.
func parseScreenshots(csv string) []string {
	if csv == "" {
		return nil
	}
	parts := strings.Split(csv, ",")
	if len(parts) > MaxScreenshots {
		panic("too many screenshots (max " + itoa(MaxScreenshots) + ")")
	}
	out := make([]string, 0, len(parts))
	for _, p := range parts {
		p = strings.TrimSpace(p)
		if p == "" {
			continue
		}
		if len(p) > MaxCIDLen {
			panic("screenshot CID too long")
		}
		out = append(out, p)
	}
	return out
}

// ── index + counter maintenance ───────────────────────────────────────────────

func statusKey(status string, id uint64) string { return status + "\x00" + zeroPad(id) }

func pubKey(pub address, id uint64) string { return pub.String() + "\x00" + zeroPad(id) }

// idInUse reports whether `id` is already present in the status index under ANY status (every
// listing — registered or seeded — is in exactly one statusIndex entry). Used to reject a
// duplicate SeedListing id before it silently collides on the composite key.
func idInUse(id uint64) bool {
	for _, s := range []string{StatusPending, StatusLive, StatusRejected, StatusDelisted} {
		if _, ok := statusIndex.Get(statusKey(s, id)); ok {
			return true
		}
	}
	return false
}

// zeroPad renders id as a fixed-width 20-digit string so lexical avl order == numeric order.
func zeroPad(id uint64) string {
	s := itoa64(id)
	for len(s) < 20 {
		s = "0" + s
	}
	return s
}

func adjustCounter(status string, d int) {
	switch status {
	case StatusLive:
		liveCount += d
	case StatusPending:
		pendingCount += d
	case StatusRejected:
		rejectedCount += d
	case StatusDelisted:
		delistedCount += d
	}
}

// indexInsert adds a brand-new listing to the status + publisher indexes and bumps its status
// counter. (publisherIndex never changes afterward — Publisher + Id are immutable.)
func indexInsert(l *Listing) {
	statusIndex.Set(statusKey(l.Status, l.Id), l.PkgPath)
	publisherIndex.Set(pubKey(l.Publisher, l.Id), l.PkgPath)
	adjustCounter(l.Status, 1)
}

// changeStatus moves a listing between statuses, keeping statusIndex + counters exact, and
// persists the listing. Every status transition MUST go through here.
func changeStatus(l *Listing, newStatus string) {
	statusIndex.Remove(statusKey(l.Status, l.Id))
	adjustCounter(l.Status, -1)
	l.Status = newStatus
	statusIndex.Set(statusKey(newStatus, l.Id), l.PkgPath)
	adjustCounter(newStatus, 1)
	listings.Set(l.PkgPath, l)
}

// validatePkgPath normalizes + sanity-checks a realm/package path.
func validatePkgPath(p string) string {
	if len(p) == 0 || len(p) > MaxPkgPathLen {
		panic("pkgPath must be 1.." + itoa(MaxPkgPathLen) + " chars")
	}
	// Reject control and space bytes: composite avl keys separate on "\x00" and
	// ClearFlags range-iterates the pkgPath prefix ([p+"\x00", p+"\x01")), so an
	// embedded control byte could bleed one listing's key range into another's.
	// Applies to RegisterApp, EditListing (via mustGet key use) AND SeedListing —
	// a migration must not import such a path either.
	for i := 0; i < len(p); i++ {
		if p[i] <= 0x20 || p[i] == 0x7f {
			panic("pkgPath contains control or space characters")
		}
	}
	if !hasPrefix(p, "gno.land/r/") && !hasPrefix(p, "gno.land/p/") {
		panic("pkgPath must be a gno.land/r/... or gno.land/p/... path")
	}
	return p
}

func hasPrefix(s, pre string) bool {
	return len(s) >= len(pre) && s[:len(pre)] == pre
}

func itoa(n int) string      { return ufmt.Sprintf("%d", n) }
func itoa64(n uint64) string { return ufmt.Sprintf("%d", n) }

package memba_appstore_v3

import (
	"crypto/sha256"
	"encoding/hex"
	"strings"
)

func IsPaused() bool        { return paused }
func IsSeedingSealed() bool { return seedingSealed }

// Scalars only: no persistent Listing pointer or screenshot slice escapes.
type GovernanceListing struct {
	Exists                      bool
	ContentHash, Status, Reason string
	Credit                      bool
	Flags                       int
	ClearKeys                   string
}

func GetGovernanceListing(pkgPath string, clearBatch bool) GovernanceListing {
	v, ok := listings.Get(pkgPath)
	if !ok {
		return GovernanceListing{}
	}
	l := v.(*Listing)
	snapshot := *l
	snapshot.Status = ""
	snapshot.RejectReason = ""
	snapshot.PaidResubmitCredit = false
	snapshot.FlagCount = 0
	digest := sha256.Sum256([]byte(listingJSON(&snapshot, true)))
	s := GovernanceListing{Exists: true, ContentHash: hex.EncodeToString(digest[:]), Status: l.Status, Reason: l.RejectReason, Credit: l.PaidResubmitCredit, Flags: l.FlagCount}
	if clearBatch {
		keys := []string{}
		flaggedBy.Iterate(pkgPath+"\x00", pkgPath+"\x01", func(k string, _ any) bool {
			keys = append(keys, strings.TrimPrefix(k, pkgPath+"\x00"))
			return len(keys) >= MaxClearBatch
		})
		s.ClearKeys = strings.Join(keys, ",")
	}
	return s
}
func HasGovernanceFlag(pkgPath, who string) bool {
	_, ok := flaggedBy.Get(pkgPath + "\x00" + who)
	return ok
}

package memba_appstore_v3

import (
	"strings"

	"gno.land/p/samcrew/avl"
	"gno.land/p/nt/ufmt/v0"
)

const (
	DefaultPageSize = 20  // default JSON window
	MaxPageLimit    = 100 // hard cap on any JSON read window (read-DoS guard)
)

func clampLimit(limit int) int {
	if limit <= 0 {
		return DefaultPageSize
	}
	if limit > MaxPageLimit {
		return MaxPageLimit
	}
	return limit
}

// jsonEscape escapes a string for embedding in a JSON string literal — every listing text field
// is attacker-supplied, so this is the only thing between a malicious name/tagline/reason/CID and
// a broken/injected JSON payload on the read path.
func jsonEscape(s string) string {
	var sb strings.Builder
	for _, r := range s {
		switch r {
		case '"':
			sb.WriteString("\\\"")
		case '\\':
			sb.WriteString("\\\\")
		case '\n':
			sb.WriteString("\\n")
		case '\r':
			sb.WriteString("\\r")
		case '\t':
			sb.WriteString("\\t")
		default:
			if r < 0x20 {
				sb.WriteString(ufmt.Sprintf("\\u%04x", r))
			} else {
				sb.WriteString(string(r))
			}
		}
	}
	return sb.String()
}

// screenshotsJSON renders a CID slice as a JSON string array body (each element escaped).
func screenshotsJSON(cids []string) string {
	var sb strings.Builder
	for i, c := range cids {
		if i > 0 {
			sb.WriteString(",")
		}
		sb.WriteString(`"`)
		sb.WriteString(jsonEscape(c))
		sb.WriteString(`"`)
	}
	return sb.String()
}

// listingJSON renders one listing. `full` adds the (large) description + the screenshot gallery —
// omitted from list windows so a bounded page stays small. rejectReason is short and always
// included (the My-Submissions view needs it in list windows).
func listingJSON(l *Listing, full bool) string {
	extra := ""
	if full {
		extra = ufmt.Sprintf(`,"descr":"%s","screenshotCIDs":[%s]`,
			jsonEscape(l.Descr), screenshotsJSON(l.ScreenshotCIDs))
	}
	return ufmt.Sprintf(
		`{"id":%d,"pkgPath":"%s","name":"%s","tagline":"%s","category":"%s","iconCID":"%s","appURL":"%s","publisher":"%s","status":"%s","rejectReason":"%s","paidResubmitCredit":%t,"resubmitCount":%d,"flagCount":%d,"createdAt":%d%s}`,
		l.Id,
		jsonEscape(l.PkgPath),
		jsonEscape(l.Name),
		jsonEscape(l.Tagline),
		jsonEscape(l.Category),
		jsonEscape(l.IconCID),
		jsonEscape(l.AppURL),
		l.Publisher.String(),
		l.Status,
		jsonEscape(l.RejectReason),
		l.PaidResubmitCredit,
		l.ResubmitCount,
		l.FlagCount,
		l.CreatedAt,
		extra,
	)
}

// windowByPrefix iterates a composite-key index (statusIndex or publisherIndex) over the prefix
// range [prefix+"\x00", prefix+"\x01") — a true O(offset+limit) window ordered by zero-padded id.
// When flagFilter is set, flag-hidden listings are excluded (the public live/pending lists).
func windowByPrefix(index *avl.Tree, prefix string, offset, limit int, flagFilter bool) string {
	limit = clampLimit(limit)
	if offset < 0 {
		offset = 0
	}
	var sb strings.Builder
	sb.WriteString("[")
	skipped, taken := 0, 0
	first := true
	index.Iterate(prefix+"\x00", prefix+"\x01", func(_ string, v any) bool {
		lv, ok := listings.Get(v.(string))
		if !ok {
			return false
		}
		l := lv.(*Listing)
		if flagFilter && l.FlagCount >= FlagHideThreshold {
			return false
		}
		if skipped < offset {
			skipped++
			return false
		}
		if taken >= limit {
			return true // window full — stop
		}
		if !first {
			sb.WriteString(",")
		}
		first = false
		sb.WriteString(listingJSON(l, false))
		taken++
		return false
	})
	sb.WriteString("]")
	return sb.String()
}

// ListLiveJSON returns a bounded JSON array of the visible (live, un-flag-hidden) listings —
// the Verified tab. Bounded by scanning only the "live" index slice.
func ListLiveJSON(offset, limit int) string {
	return windowByPrefix(statusIndex, StatusLive, offset, limit, true)
}

// ListByStatusJSON returns a bounded window of listings in `status`. Public tabs (live, pending)
// exclude flag-hidden listings; rejected/delisted are returned raw (used by curator/owner views).
// An unknown status returns an empty array — the client passes a fixed enum, never free text.
func ListByStatusJSON(status string, offset, limit int) string {
	if !validStatus(status) {
		return "[]"
	}
	flagFilter := status == StatusLive || status == StatusPending
	return windowByPrefix(statusIndex, status, offset, limit, flagFilter)
}

// ListByPublisherJSON returns a bounded window of a publisher's listings across ALL statuses
// (the My-Submissions view) — no flag filter, since a publisher sees their own flagged/rejected.
func ListByPublisherJSON(publisher string, offset, limit int) string {
	return windowByPrefix(publisherIndex, publisher, offset, limit, false)
}

// GetListingJSON returns a single listing (any status) with its full detail (descr + screenshots),
// or the JSON literal `null` if the package path is not registered.
func GetListingJSON(pkgPath string) string {
	v, ok := listings.Get(pkgPath)
	if !ok {
		return "null"
	}
	return listingJSON(v.(*Listing), true)
}

package memba_appstore_v3

import (
	"chain/runtime"

	"gno.land/p/nt/ufmt/v0"
)

// RenderMaxRows bounds the Render() output so a large catalog can never make the
// realm render-DoS (mirrors the feed's live-only bounded render).
const RenderMaxRows = 100

// Render shows the live catalog (bounded) — a read-only trust surface for gnoweb.
// The frontend reads structured data via the getters, not this markdown.
func Render(path string) string {
	sb := ""
	sb += "# Memba App Store\n\n"
	sb += ufmt.Sprintf("Curated gno.land dApps. **Listing fee:** %d ugnot → treasury.\n\n", registrationFee)
	if paused {
		sb += "> ⏸️ Registration is paused.\n\n"
	}

	rows := 0
	live := 0
	sb += "| App | Package | Category |\n|---|---|---|\n"
	listings.Iterate("", "", func(_ string, v any) bool {
		l := v.(*Listing)
		// Curated gnoweb view: live (Verified) + un-flag-hidden only — never pending/rejected.
		if l.Status != StatusLive || l.FlagCount >= FlagHideThreshold {
			return false
		}
		live++
		if rows >= RenderMaxRows {
			return false // stop appending, keep counting via the header below
		}
		rows++
		sb += ufmt.Sprintf("| %s | `%s` | %s |\n", esc(l.Name), esc(l.PkgPath), esc(l.Category))
		return false
	})

	if live == 0 {
		sb += "\n*No live apps yet.*\n"
	} else {
		sb += ufmt.Sprintf("\n*%d live app(s)%s. Block %d.*\n", live, moreNote(live), runtime.ChainHeight())
	}
	return sb
}

func moreNote(live int) string {
	if live > RenderMaxRows {
		return ufmt.Sprintf(" (showing first %d)", RenderMaxRows)
	}
	return ""
}

// esc neutralizes the markdown/table metachars that could break the table or inject
// layout from an attacker-supplied listing field.
func esc(s string) string {
	out := ""
	for _, r := range s {
		switch r {
		case '|':
			out += "\\|"
		case '\n', '\r':
			out += " "
		case '`':
			out += "'"
		default:
			out += string(r)
		}
	}
	return out
}

package memba_arcade_leaderboard_v1

import "chain"

// Admin surface — owner-gated. The owner is the samcrew multisig at launch and can be handed to
// the memba_dao executor via the 2-step TransferOwnership/AcceptOwnership (never a 1-step transfer
// to a mistyped/dead address).

// AddAttester allowlists an ADDRESS (the backend verifier's dedicated low-privilege key — never the
// deploy multisig itself) as an authorized result source. Owner only.
func AddAttester(cur realm, addr address) {
	assertOwner(cur)
	if addr == "" {
		panic("attester address must be non-empty")
	}
	attesters.Set(addr.String(), true)
	chain.Emit("AttesterAdded", "addr", addr.String())
}

// RemoveAttester revokes an attester key. Owner only.
func RemoveAttester(cur realm, addr address) {
	assertOwner(cur)
	attesters.Remove(addr.String())
	chain.Emit("AttesterRemoved", "addr", addr.String())
}

// Pause freezes all attestation + receipt requests (reads stay available). Owner only.
func Pause(cur realm, state bool) {
	assertOwner(cur)
	paused = state
	chain.Emit("PauseSet", "paused", boolStr(state))
}

// TransferOwnership stages a new owner; it takes effect only after AcceptOwnership is called BY
// that address (2-step, so a typo can't brick admin).
func TransferOwnership(cur realm, newOwner address) {
	assertOwner(cur)
	if newOwner == "" {
		panic("newOwner must be non-empty")
	}
	if !newOwner.IsValid() {
		panic("invalid address: " + newOwner.String())
	}
	if newOwner == owner {
		panic("newOwner is the current owner")
	}
	pendingOwner = newOwner
	chain.Emit("OwnershipTransferStarted", "pending", newOwner.String())
}

// CancelOwnershipTransfer withdraws a staged handoff. Owner only.
func CancelOwnershipTransfer(cur realm) {
	assertOwner(cur)
	if pendingOwner == "" {
		panic("no pending ownership transfer")
	}
	cancelled := pendingOwner
	pendingOwner = ""
	chain.Emit("OwnershipTransferCancelled", "pending", cancelled.String())
}

// GetPendingOwner returns the staged successor, or the empty address.
func GetPendingOwner() address { return pendingOwner }

// AcceptOwnership completes the handoff. Only the staged pendingOwner may call it.
func AcceptOwnership(cur realm) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	if pendingOwner == "" {
		panic("no pending ownership transfer")
	}
	if cur.Previous().Address() != pendingOwner {
		panic("unauthorized: only the pending owner may accept")
	}
	owner = pendingOwner
	pendingOwner = ""
	chain.Emit("OwnershipTransferAccepted", "owner", owner.String())
}

// Package memba_arcade_leaderboard_v1 is the funds-free, verified-score ledger for the Memba
// arcade (BARRICADE, Space Invaders, and future games — one realm, boards keyed per game slug).
// Nothing here trusts a client number: an authorized ATTESTER (the backend verifier's key)
// re-simulates a submitted input log and attests only the reproduced result. The chain stores the
// attested result plus a commitment to the log (its sha256) — the log itself stays off-chain;
// "verified, never trustless" is the public contract.
//
// SAFETY: there is NO banker, NO transfer, and NO OriginSend anywhere — the fund-drain risk class
// does not apply. The only trust boundary is who may attest (owner ∪ the attester allowlist); every
// write emits an event. Two buckets never mix: the competitive DAILY BOARD (one best entry per
// address per game per day, shared seed) and personal TRAINING RECEIPTS (practice runs — a
// verified flex, never ranked).
//
// The game slug is shape-validated only — there is deliberately NO on-chain game registry: the
// realm is funds-free, so the worst a typo'd slug can do is fragment a board, and the attester
// (not the player) authors the slug.
package memba_arcade_leaderboard_v1

import (
	"chain"
	"chain/runtime"

	"gno.land/p/samcrew/avl"
	"gno.land/p/nt/ufmt/v0"
)

// No owner is compiled in: the publishing transaction's signer (on gnoland-1 the samcrew
// namespace multisig, the stamped creator at enable time) is seeded as owner at package load;
// hand it to the memba_dao executor post-deploy via the 2-step ownership transfer.

const (
	// MaxScore bounds a single attested score — a fat-finger / overflow guard far above any
	// reachable sim score (arcade sim scores live in the tens of thousands).
	MaxScore = int64(1_000_000_000)
	// MaxGameLen bounds the game slug. The slug charset is [a-z0-9-], which EXCLUDES '|' —
	// load-bearing: '|' is the composite-key separator in every scoped tree below.
	MaxGameLen = 32
	// MaxStatsLen bounds the attester-authored per-game stats JSON blob. Ranking never reads
	// it; reads only ever emit it JSON-escaped.
	MaxStatsLen = 256
	// ReceiptsCap bounds one address's training-receipt ring (oldest evicted first; the ring is
	// mixed-game, so this is the per-address bound).
	ReceiptsCap = 100
	// ReceiptDailyCap bounds how many receipts one address may mint per (game, day) (spam cap).
	ReceiptDailyCap = 5
	// RequestCap bounds one address's PENDING receipt requests (fulfilled ones free their slot):
	// the only unprivileged write path must not grow realm state unboundedly.
	RequestCap = 8
)

// Entry is one attested, verifier-reproduced run result.
type Entry struct {
	Addr           address
	Game           string // slug, 1..MaxGameLen chars of [a-z0-9-] (never '|', the key separator)
	Day            string // YYYY-MM-DD (the shared daily seed's date; receipt = submission day)
	Mode           string // "daily" | "practice"
	Seed           string
	Score          int64  // the ONLY ranked field
	Stats          string // compact attester-authored JSON (game-specific; ≤ MaxStatsLen; opaque here)
	SimVersion     int64
	StateHash      string // the sim's canonical terminal-state digest
	InputLogSha256 string // commitment to the off-chain input log (the proof)
	AttestedAt     int64  // block height
}

var (
	owner        address
	pendingOwner address
	paused       bool
	attesters    = avl.NewTree() // attester address string -> bool
	boards       = avl.NewTree() // "game|day|addr" -> *Entry (competitive, one best per addr/game/day)
	receipts     = avl.NewTree() // addr string -> []*Entry (training ring, mixed-game, capped)
	logHashes    = avl.NewTree() // "game|day|sha256" -> addr string (board slot: first-submitter-per-day)
	hashOwners   = avl.NewTree() // sha256 -> addr string (GLOBAL: a log binds to ONE address, ever)
	requests     = avl.NewTree() // "addr|sha256" -> int64 height (player-paid receipt requests)
	requestCount = avl.NewTree() // addr string -> int (pending requests, capped at RequestCap)
	boardCount   = avl.NewTree() // "game|day" -> int (entries per game-day, O(1) reads)
)

func init() { seedAuthority(publisherAtLoad()) }

// seedAuthority installs the publisher as owner. It runs once at package load.
func seedAuthority(publisher address) {
	owner = publisher
	pendingOwner = ""
}

func assertOwner(cur realm) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	if cur.Previous().Address() != owner {
		panic("unauthorized: owner only")
	}
}

func assertNotPaused() {
	if paused {
		panic("attestation is paused")
	}
}

func isAttester(addr string) bool {
	_, ok := attesters.Get(addr)
	return ok
}

// assertAttester is the single trust boundary: only the owner or an allowlisted attester key (the
// backend verifier) may write results. The verifier's own re-simulation gate is what makes an
// attested score meaningful — this realm only enforces that the source is trusted.
func assertAttester(cur realm) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	pr := cur.Previous().Address()
	if pr != owner && !isAttester(pr.String()) {
		panic("unauthorized: owner or allowlisted attester only")
	}
}

func assertEntryShape(game string, addr address, day, mode, seed string, score, simVersion int64, stateHash, logHash, stats string) {
	if addr == "" {
		panic("addr must be non-empty")
	}
	assertGameSlug(game)
	if len(day) != 10 || day[4] != '-' || day[7] != '-' {
		panic("day must be YYYY-MM-DD")
	}
	for _, i := range []int{0, 1, 2, 3, 5, 6, 8, 9} {
		if day[i] < '0' || day[i] > '9' {
			panic("day must be YYYY-MM-DD")
		}
	}
	if mode != "daily" && mode != "practice" {
		panic("mode must be daily or practice")
	}
	if seed == "" {
		panic("seed must be non-empty")
	}
	if score < 0 || score > MaxScore {
		panic("score out of range")
	}
	if simVersion <= 0 {
		panic("simVersion must be positive")
	}
	if stateHash == "" || logHash == "" {
		panic("stateHash and inputLogSha256 must be non-empty")
	}
	if len(stats) > MaxStatsLen {
		panic("stats too long")
	}
}

// assertGameSlug validates the game slug shape: 1..MaxGameLen bytes of [a-z0-9-]. The charset
// excludes '|' (and everything else), so a slug can never forge or split a composite key.
func assertGameSlug(game string) {
	if len(game) < 1 || len(game) > MaxGameLen {
		panic("game must be 1-32 chars of [a-z0-9-]")
	}
	for i := 0; i < len(game); i++ {
		c := game[i]
		if (c < 'a' || c > 'z') && (c < '0' || c > '9') && c != '-' {
			panic("game must be 1-32 chars of [a-z0-9-]")
		}
	}
}

// AttestScore writes (or improves) an address's entry on a game's competitive board for a day.
// Attester-only. The verifier batches a day's results into one multi-msg tx at day close, plus
// spam-capped singles for the "certify now" flow. Re-attesting the same game/address/day only ever
// RAISES the score (Second Wind). A log hash already attested for that game-day for a DIFFERENT
// address is rejected — on a shared daily seed a valid input log is portable, so first-submitter
// wins (replay-theft defense). `stats` is the attester-authored per-game JSON blob (waves, wins,
// levels, …) — never ranked, only echoed by reads.
func AttestScore(cur realm, game string, addr address, day, seed string, score, simVersion int64, stateHash, logHash, stats string) {
	assertNotPaused()
	assertAttester(cur)
	assertEntryShape(game, addr, day, "daily", seed, score, simVersion, stateHash, logHash, stats)

	hashKey := game + "|" + day + "|" + logHash
	if v, ok := logHashes.Get(hashKey); ok && v.(string) != addr.String() {
		panic("duplicate input log: already attested for another address today")
	}
	// The GLOBAL net: a log binds to one address forever, across BOTH buckets —
	// a stolen log can't take a board slot today, a receipt tomorrow, or
	// anything under a different day OR GAME string (the review rationale
	// generalizes: no free-form string may launder a stolen log, so this tree
	// deliberately stays UNSCOPED by game).
	assertHashOwner(logHash, addr)

	key := game + "|" + day + "|" + addr.String()
	if v, ok := boards.Get(key); ok {
		if v.(*Entry).Score >= score {
			panic("existing entry is not improved")
		}
	} else {
		countKey := game + "|" + day
		n := 0
		if c, ok := boardCount.Get(countKey); ok {
			n = c.(int)
		}
		boardCount.Set(countKey, n+1)
	}

	e := &Entry{
		Addr: addr, Game: game, Day: day, Mode: "daily", Seed: seed, Score: score, Stats: stats,
		SimVersion: simVersion, StateHash: stateHash,
		InputLogSha256: logHash, AttestedAt: runtime.ChainHeight(),
	}
	boards.Set(key, e)
	logHashes.Set(hashKey, addr.String())
	hashOwners.Set(logHash, addr.String())
	chain.Emit("ScoreAttested", "game", game, "addr", addr.String(), "day", day,
		"score", itoa64(score), "simVersion", itoa64(simVersion))
}

// AttestReceipt mints a personal training receipt — a verified "I did this run", never ranked.
// Attester-only; capped per address per (game, day) and ring-capped per address. Fulfills (and
// clears) a matching player-paid RequestReceipt if one is staged.
func AttestReceipt(cur realm, game string, addr address, day, seed string, score, simVersion int64, stateHash, logHash, stats string) {
	assertNotPaused()
	assertAttester(cur)
	assertEntryShape(game, addr, day, "practice", seed, score, simVersion, stateHash, logHash, stats)

	var ring []*Entry
	if v, ok := receipts.Get(addr.String()); ok {
		ring = v.([]*Entry)
	}
	sameDay := 0
	for _, r := range ring {
		if r.InputLogSha256 == logHash {
			panic("duplicate receipt for this input log")
		}
		if r.Game == game && r.Day == day {
			sameDay++
		}
	}
	if sameDay >= ReceiptDailyCap {
		panic("receipt cap reached for this day")
	}
	// The same GLOBAL net as the board: a receipt for someone else's attested
	// log is a forged "verified flex" — reject it, and bind first use here too.
	assertHashOwner(logHash, addr)

	e := &Entry{
		Addr: addr, Game: game, Day: day, Mode: "practice", Seed: seed, Score: score, Stats: stats,
		SimVersion: simVersion, StateHash: stateHash,
		InputLogSha256: logHash, AttestedAt: runtime.ChainHeight(),
	}
	ring = append(ring, e)
	if len(ring) > ReceiptsCap {
		ring = ring[len(ring)-ReceiptsCap:] // evict oldest
	}
	receipts.Set(addr.String(), ring)
	hashOwners.Set(logHash, addr.String())
	clearRequest(addr, logHash)
	chain.Emit("ReceiptAttested", "game", game, "addr", addr.String(), "day", day,
		"score", itoa64(score), "simVersion", itoa64(simVersion))
}

// RequestReceipt is the player-paid leg: ANY signer stages an on-chain consent + payment anchor for
// one of their own runs (they pay this call's gas). The backend sees the event, verifies the stored
// log, and fulfills via AttestReceipt. Self-limiting: each request costs the caller gas, and one
// key slot per (addr, hash). Hash-scoped and game-agnostic on purpose — the verifier, not the
// player, decides which game the log replays under.
func RequestReceipt(cur realm, logHash string) {
	assertNotPaused()
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	if logHash == "" {
		panic("logHash must be non-empty")
	}
	caller := cur.Previous().Address()
	key := caller.String() + "|" + logHash
	if _, ok := requests.Get(key); !ok {
		n := 0
		if c, ok := requestCount.Get(caller.String()); ok {
			n = c.(int)
		}
		if n >= RequestCap {
			panic("pending request cap reached — wait for fulfillment")
		}
		requestCount.Set(caller.String(), n+1)
	}
	requests.Set(key, runtime.ChainHeight())
	chain.Emit("ReceiptRequested", "addr", caller.String(), "logHash", logHash)
}

// assertHashOwner enforces the GLOBAL one-log-one-address rule shared by both
// buckets (and by every game), and is idempotent for the rightful owner
// (Second Wind re-attests).
func assertHashOwner(logHash string, addr address) {
	if v, ok := hashOwners.Get(logHash); ok && v.(string) != addr.String() {
		panic("duplicate input log: already bound to another address")
	}
}

// clearRequest removes a fulfilled request and frees the caller's cap slot.
func clearRequest(addr address, logHash string) {
	key := addr.String() + "|" + logHash
	if _, ok := requests.Get(key); !ok {
		return
	}
	requests.Remove(key)
	if c, ok := requestCount.Get(addr.String()); ok {
		if n := c.(int); n > 1 {
			requestCount.Set(addr.String(), n-1)
		} else {
			requestCount.Remove(addr.String())
		}
	}
}

func itoa64(n int64) string { return ufmt.Sprintf("%d", n) }

func boolStr(b bool) string {
	if b {
		return "true"
	}
	return "false"
}

package memba_arcade_leaderboard_v1

import "chain/runtime/unsafe"

// publisherAtLoad captures the AddPackage signer during package initialization.
// Keeping the unsafe load-time primitive separate from crossing entrypoints lets
// privileged calls use only the frame-verified cur.IsCurrent/cur.Previous API.
func publisherAtLoad() address { return unsafe.OriginCaller() }

package memba_arcade_leaderboard_v1

import (
	"strings"

	"gno.land/p/nt/ufmt/v0"
)

// ── Read getters (pure, non-failing; served via vm/qeval or Render) ─────────────

// GetOwner returns the current owner.
func GetOwner() address { return owner }

// IsPaused reports whether attestation is frozen.
func IsPaused() bool { return paused }

// IsAttester reports whether an address is on the attester allowlist.
func IsAttester(addr string) bool { return isAttester(addr) }

// BoardCount returns how many addresses hold an entry on a game's board for a day (O(1)).
func BoardCount(game, day string) int {
	if v, ok := boardCount.Get(game + "|" + day); ok {
		return v.(int)
	}
	return 0
}

// entryJSON emits one entry. `stats` is the attester's opaque JSON blob and is emitted as an
// ESCAPED STRING FIELD — never spliced raw into the document — so a malformed blob can corrupt
// nothing but itself.
func entryJSON(e *Entry) string {
	return ufmt.Sprintf(
		`{"addr":"%s","game":"%s","day":"%s","mode":"%s","score":%d,"stats":"%s","simVersion":%d,"stateHash":"%s","inputLogSha256":"%s","attestedAt":%d}`,
		jsonEscape(e.Addr.String()), jsonEscape(e.Game), jsonEscape(e.Day), jsonEscape(e.Mode),
		e.Score, jsonEscape(e.Stats), e.SimVersion, jsonEscape(e.StateHash),
		jsonEscape(e.InputLogSha256), e.AttestedAt)
}

// GetEntryJSON returns one address's board entry for a game-day, or "null".
func GetEntryJSON(game, day, addr string) string {
	if v, ok := boards.Get(game + "|" + day + "|" + addr); ok {
		return entryJSON(v.(*Entry))
	}
	return "null"
}

// dayEntries collects a game-day's board entries in canonical rank order: score desc,
// then earlier attestation, then address — a total order, so pagination is stable.
func dayEntries(game, day string) []*Entry {
	var out []*Entry
	prefix := game + "|" + day + "|"
	boards.Iterate(prefix, prefix+"~", func(_ string, v any) bool {
		out = append(out, v.(*Entry))
		return false
	})
	// Insertion sort (gno stdlib has no sort.Slice): a day's board is bounded
	// and reads are qeval-side — O(n²) on a few hundred entries is fine.
	for i := 1; i < len(out); i++ {
		e := out[i]
		j := i - 1
		for j >= 0 && ranksAfter(out[j], e) {
			out[j+1] = out[j]
			j--
		}
		out[j+1] = e
	}
	return out
}

// ranksAfter reports whether a should sit AFTER b in rank order — a total
// order (score desc, then earlier attestation, then address) so pagination
// is stable and identical everywhere.
func ranksAfter(a, b *Entry) bool {
	if a.Score != b.Score {
		return a.Score < b.Score
	}
	if a.AttestedAt != b.AttestedAt {
		return a.AttestedAt > b.AttestedAt
	}
	return a.Addr.String() > b.Addr.String()
}

// GetBoardJSON returns a page of a game-day's board, rank-ordered, as
// {"game":…,"day":…,"total":N,"entries":[…]}. Reads sort the day's entries on demand —
// fine for a testnet-scale board; a rank index (points_v1-style) is the v2
// upgrade if daily boards grow past a few thousand entries.
func GetBoardJSON(game, day string, offset, limit int) string {
	all := dayEntries(game, day)
	if offset < 0 {
		offset = 0
	}
	if limit <= 0 || limit > 100 {
		limit = 100
	}
	var sb strings.Builder
	sb.WriteString(ufmt.Sprintf(`{"game":"%s","day":"%s","total":%d,"entries":[`,
		jsonEscape(game), jsonEscape(day), len(all)))
	for i := offset; i < len(all) && i < offset+limit; i++ {
		if i > offset {
			sb.WriteString(",")
		}
		sb.WriteString(entryJSON(all[i]))
	}
	sb.WriteString("]}")
	return sb.String()
}

// GetReceiptsJSON returns a page of one address's training receipts (all games, newest first) as
// {"addr":…,"total":N,"entries":[…]}.
func GetReceiptsJSON(addr string, offset, limit int) string {
	var ring []*Entry
	if v, ok := receipts.Get(addr); ok {
		ring = v.([]*Entry)
	}
	if offset < 0 {
		offset = 0
	}
	if limit <= 0 || limit > 100 {
		limit = 100
	}
	var sb strings.Builder
	sb.WriteString(ufmt.Sprintf(`{"addr":"%s","total":%d,"entries":[`, jsonEscape(addr), len(ring)))
	n := 0
	for i := len(ring) - 1 - offset; i >= 0 && n < limit; i-- {
		if n > 0 {
			sb.WriteString(",")
		}
		sb.WriteString(entryJSON(ring[i]))
		n++
	}
	sb.WriteString("]}")
	return sb.String()
}

// Render serves a human-readable snapshot: `:board/<game>/YYYY-MM-DD` for a game-day's top
// entries, `:receipts/<addr>` for an address's latest receipts.
func Render(path string) string {
	if strings.HasPrefix(path, "board/") {
		rest := path[len("board/"):]
		slash := strings.Index(rest, "/")
		if slash < 0 {
			return "# memba_arcade_leaderboard_v1\n\nUse `:board/<game>/YYYY-MM-DD`.\n"
		}
		game := rest[:slash]
		day := rest[slash+1:]
		all := dayEntries(game, day)
		var sb strings.Builder
		sb.WriteString("# " + jsonEscape(game) + " daily board — " + jsonEscape(day) + "\n\n")
		if len(all) == 0 {
			sb.WriteString("No attested runs yet.\n")
			return sb.String()
		}
		for i, e := range all {
			if i >= 50 {
				sb.WriteString(ufmt.Sprintf("\n…and %d more.\n", len(all)-50))
				break
			}
			line := ufmt.Sprintf("%d. `%s` — **%d**", i+1, e.Addr.String(), e.Score)
			if e.Stats != "" {
				line += " · " + jsonEscape(e.Stats)
			}
			sb.WriteString(line + "\n")
		}
		return sb.String()
	}
	if strings.HasPrefix(path, "receipts/") {
		addr := path[len("receipts/"):]
		return "# Training receipts — " + addr + "\n\n```json\n" + GetReceiptsJSON(addr, 0, 20) + "\n```\n"
	}
	return "# memba_arcade_leaderboard_v1\n\nVerified Memba arcade results — never a client-claimed number.\n\n" +
		"- `:board/<game>/YYYY-MM-DD` — a game's competitive board for a day\n" +
		"- `:receipts/<addr>` — an address's training receipts (all games)\n"
}

// jsonEscape escapes a string for embedding in a JSON string literal (defensive — addresses are
// bech32 and hashes are hex, but the read path escapes regardless; the Render path reuses it to
// neutralize newlines/control chars in attester-authored stats).
func jsonEscape(s string) string {
	var sb strings.Builder
	for _, r := range s {
		switch r {
		case '"':
			sb.WriteString("\\\"")
		case '\\':
			sb.WriteString("\\\\")
		case '\n':
			sb.WriteString("\\n")
		case '\r':
			sb.WriteString("\\r")
		case '\t':
			sb.WriteString("\\t")
		default:
			if r < 0x20 {
				sb.WriteString(ufmt.Sprintf("\\u%04x", r))
			} else {
				sb.WriteString(string(r))
			}
		}
	}
	return sb.String()
}

package memba_dao_channels_v2

// memba_dao_channels — Social feed realm for MembaDAO.
//
// Provides Discord-like channels with threads, replies, and moderation.
// The Render() output MUST match the regex patterns in parser.ts (frontend).
//
// Render() contract (from parser.ts):
//
//   Home — Render(""):
//     # BoardName
//     description
//     ## Channels
//     - [#name](:_channel/name) 📢 (N threads)
//
//   Channel — Render("channelName"):
//     # #channelName
//     ### [Title](:channel/id)
//     by g1addr... | N replies | block H
//
//   Thread — Render("channel/id"):
//     # Title
//     body
//     ---
//     *Posted by g1addr at block H*
//     ## Replies
//     **g1addr...** (block H)
//     reply body
//     ---
//
//   ACL — Render("__acl/channel"):
//     read:role1,role2
//     write:role1,role2,role3
//     type:text
//
// Security:
//   - Ownership starts with the publisher and moves only in two steps: the owner
//     proposes a valid address, that address accepts, and accepting removes every
//     grant the previous owner held
//   - All write operations require membership (AddMember by owner)
//   - PostThread/PostReply check caller's roles against channel WriteRoles
//   - CreateChannel/RemoveThread restricted to owner only
//   - FlagThread requires membership (prevents sybil flagging by non-members)
//   - EditThread/DeleteThread require membership + original author check
//
// Moderation: flag → threshold (3) → auto-hide → DAO vote → remove

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/samcrew/avl"
	"gno.land/p/nt/ufmt/v0"
)

// ── Constants ────────────────────────────────────────────────

const (
	MaxPostLen        = 5000
	MaxTitleLen       = 200
	MaxChannels       = 20
	MaxThreadsPerChan = 500
	FlagThreshold     = 3 // flags before auto-hide

	// AAA-1 B1 — render-DoS bounds for replies (mirrors MaxThreadsPerChan).
	// renderThread must never iterate the monotonic reply counter (post+delete
	// reply spam would inflate it without bound → unbounded render scan →
	// thread permanently unrenderable past maxGasQuery). The live-reply index
	// (replyLive/replyLiveIDs) caps the live set, and renderThread paginates a
	// fixed window over it, so render cost is bounded regardless of churn.
	MaxRepliesPerThread = 500 // live (non-deleted) replies per thread
	ReplyPageSize       = 50  // replies rendered per page
)

// ── Types ────────────────────────────────────────────────────

type ChannelType string

const (
	ChannelText          ChannelType = "text"
	ChannelAnnouncements ChannelType = "announcements"
	ChannelReadonly      ChannelType = "readonly"
)

type Channel struct {
	Name        string
	Description string
	Type        ChannelType
	Archived    bool
	ReadRoles   []string // roles that can read
	WriteRoles  []string // roles that can write
}

type Thread struct {
	ID        uint64
	Channel   string
	Title     string
	Body      string
	Author    address
	BlockH    int64
	Edited    bool
	EditedAt  int64
	Deleted   bool
	FlagCount int
	Hidden    bool
}

type Reply struct {
	ID       uint64
	ThreadID uint64
	Channel  string
	Body     string
	Author   address
	BlockH   int64
	Edited   bool
}

// ── State ────────────────────────────────────────────────────

var (
	channels      *avl.Tree // name -> *Channel
	threads       *avl.Tree // "channel/id" -> *Thread
	replies       *avl.Tree // "channel/threadId/replyId" -> *Reply
	threadCount   *avl.Tree // channel -> uint64 (next thread ID, monotonic)
	threadLive    *avl.Tree // channel -> uint64 (currently live (non-deleted) threads)
	threadLiveIDs *avl.Tree // channel -> []uint64 (live thread IDs, ascending) — bounds renderChannel
	replyCount    *avl.Tree // "channel/threadId" -> uint64 (next reply ID, monotonic)
	replyLive     *avl.Tree // "channel/threadId" -> uint64 (currently live (non-deleted) replies)
	replyLiveIDs  *avl.Tree // "channel/threadId" -> []uint64 (live reply IDs, ascending) — bounds renderThread
	threadTomb    *avl.Tree // channel -> []uint64 (soft-deleted thread IDs awaiting hard-GC via SweepTombstones) — B2
	flags         *avl.Tree // "channel/threadId" -> *avl.Tree (flagger addr -> bool)
	channelOrder  []string  // ordered channel names

	// Membership: address -> comma-separated roles (e.g., "admin,dev")
	members *avl.Tree
	membershipRevision uint64
	paused  bool
	// owner is seeded at package load with the publishing transaction's signer
	// (on gnoland-1 the samcrew namespace multisig). pendingOwner is empty unless
	// the owner has proposed a successor that has not accepted yet.
	owner        address
	pendingOwner address
)

func init() {
	channels = avl.NewTree()
	threads = avl.NewTree()
	replies = avl.NewTree()
	threadCount = avl.NewTree()
	threadLive = avl.NewTree()
	threadLiveIDs = avl.NewTree()
	replyCount = avl.NewTree()
	replyLive = avl.NewTree()
	replyLiveIDs = avl.NewTree()
	threadTomb = avl.NewTree()
	flags = avl.NewTree()
	channelOrder = []string{}
	members = avl.NewTree()
	seedAuthority(unsafe.OriginCaller())

	// Default channels matching MEMBA_DAO_CHANNELS in config.ts
	addChannel("general", "General discussion for all members", ChannelText,
		[]string{"admin", "dev", "ops", "member"}, []string{"admin", "dev", "ops", "member"})
	addChannel("announcements", "Official MembaDAO announcements — admin-write-only", ChannelAnnouncements,
		[]string{"admin", "dev", "ops", "member"}, []string{"admin"})
	addChannel("feature-requests", "Propose and discuss new features", ChannelText,
		[]string{"admin", "dev", "ops", "member"}, []string{"admin", "dev", "ops", "member"})
	addChannel("support", "Help and troubleshooting", ChannelText,
		[]string{"admin", "dev", "ops", "member"}, []string{"admin", "dev", "ops", "member"})
	addChannel("extensions", "Plugin and extension development", ChannelText,
		[]string{"admin", "dev", "ops", "member"}, []string{"admin", "dev", "member"})
	addChannel("partnerships", "Collaboration and partnership proposals", ChannelText,
		[]string{"admin", "dev", "ops", "member"}, []string{"admin", "dev", "ops", "member"})
}

// ── Channel Management ───────────────────────────────────────

func addChannel(name, description string, ctype ChannelType, readRoles, writeRoles []string) {
	ch := &Channel{
		Name:        name,
		Description: description,
		Type:        ctype,
		Archived:    false,
		ReadRoles:   readRoles,
		WriteRoles:  writeRoles,
	}
	channels.Set(name, ch)
	threadCount.Set(name, uint64(0))
	threadLive.Set(name, uint64(0))
	channelOrder = append(channelOrder, name)
}

// seedAuthority grants the publisher ownership and the only initial admin role.
func seedAuthority(publisher address) {
	owner = publisher
	pendingOwner = ""
	members.Set(publisher.String(), "admin")
}

// ── Membership Management ───────────────────────────────────

// AddMember adds an address with specified roles. Only the owner can call this.
// roles is a comma-separated list (e.g., "admin,dev" or "member").
func AddMember(cur realm, addr address, roles string) {
	assertCallerIsOwner()
	if addr == "" {
		panic("address cannot be empty")
	}
	if len(roles) == 0 {
		panic("roles cannot be empty")
	}
	if !isValidRoles(roles) {
		panic("invalid roles: must be comma-separated alphanumeric only")
	}
	members.Set(addr.String(), roles)
	membershipRevision++

	chain.Emit("MemberAdded",
		"address", addr.String(),
		"roles", roles,
	)
}

// RemoveMember removes an address from the membership. Only the owner can call this.
func RemoveMember(cur realm, addr address) {
	assertCallerIsOwner()
	if addr == owner {
		panic("cannot remove owner")
	}
	if _, exists := members.Get(addr.String()); !exists {
		panic("address is not a member: " + addr.String())
	}
	members.Remove(addr.String())
	membershipRevision++

	chain.Emit("MemberRemoved", "address", addr.String())
}

// UpdateMemberRoles updates the roles for an existing member. Only the owner can call this.
func UpdateMemberRoles(cur realm, addr address, newRoles string) {
	assertCallerIsOwner()
	if _, exists := members.Get(addr.String()); !exists {
		panic("address is not a member: " + addr.String())
	}
	if len(newRoles) == 0 {
		panic("roles cannot be empty")
	}
	if !isValidRoles(newRoles) {
		panic("invalid roles: must be comma-separated alphanumeric only")
	}
	members.Set(addr.String(), newRoles)
	membershipRevision++

	chain.Emit("MemberRolesUpdated", "address", addr.String(), "roles", newRoles)
}

// ProposeOwner names a successor owner. Only the owner can call this. Nothing is
// granted until the successor calls AcceptOwnership; a later proposal replaces
// an earlier one.
func ProposeOwner(cur realm, newOwner address) {
	assertCallerIsOwner()
	if !newOwner.IsValid() {
		panic("invalid address: " + newOwner.String())
	}
	if newOwner == owner {
		panic("new owner is the same as current owner")
	}
	pendingOwner = newOwner

	chain.Emit("OwnershipProposed",
		"owner", owner.String(),
		"pendingOwner", newOwner.String(),
	)
}

// CancelPendingOwner withdraws the pending proposal. Only the owner can call this.
func CancelPendingOwner(cur realm) {
	assertCallerIsOwner()
	if pendingOwner == "" {
		panic("no pending owner")
	}
	cancelled := pendingOwner
	pendingOwner = ""

	chain.Emit("OwnershipProposalCancelled", "pendingOwner", cancelled.String())
}

// AcceptOwnership completes the handoff. Only the pending owner can call this,
// so an address that cannot act here can never become owner. The previous
// owner loses membership and every role; the new owner keeps its existing roles
// and gains "admin". It is not pause-gated, like the other owner operations.
func AcceptOwnership(cur realm) {
	caller := unsafe.PreviousRealm().Address()
	if pendingOwner == "" || caller != pendingOwner {
		panic("unauthorized: caller " + caller.String() + " is not the pending owner")
	}
	prevOwner := owner
	existingRoles := GetMemberRoles(caller)
	needsAdmin := !hasRole(caller, "admin")

	members.Remove(prevOwner.String())
	if existingRoles == "" {
		members.Set(caller.String(), "admin")
	} else if needsAdmin {
		members.Set(caller.String(), existingRoles+",admin")
	}
	owner = caller
	pendingOwner = ""
	membershipRevision++

	chain.Emit("OwnershipTransferred",
		"previousOwner", prevOwner.String(),
		"newOwner", caller.String(),
	)
}

// SyncMembers allows the owner to batch-sync membership from the DAO.
// addresses and rolesList are comma-separated, with roles pipe-delimited per address.
// Example: SyncMembers("g1a,g1b", "admin,dev|member")
func SyncMembers(cur realm, addresses string, rolesList string) {
	assertCallerIsOwner()
	addrs := strings.Split(addresses, ",")
	roles := strings.Split(rolesList, "|")
	if len(addrs) != len(roles) {
		panic("addresses and roles count mismatch")
	}
	synced := 0
	for i, addr := range addrs {
		addr = strings.TrimSpace(addr)
		if addr == "" {
			continue
		}
		role := strings.TrimSpace(roles[i])
		if !isValidRoles(role) {
			panic("invalid roles in entry " + strconv.Itoa(i))
		}
		members.Set(addr, role)
		synced++
	}
	membershipRevision++

	chain.Emit("MembersSynced", "count", strconv.Itoa(synced))
}

// PurgeNonMembers removes all members not in the provided comma-separated list.
// The owner is never purged.
func PurgeNonMembers(cur realm, keepAddresses string) {
	assertCallerIsOwner()
	keep := make(map[string]bool)
	for _, addr := range strings.Split(keepAddresses, ",") {
		keep[strings.TrimSpace(addr)] = true
	}
	keep[owner.String()] = true // owner is never purged
	var toRemove []string
	members.Iterate("", "", func(key string, _ interface{}) bool {
		if !keep[key] {
			toRemove = append(toRemove, key)
		}
		return false
	})
	for _, addr := range toRemove {
		members.Remove(addr)
	}
	membershipRevision++

	chain.Emit("MembersPurged", "count", strconv.Itoa(len(toRemove)))
}

// IsMember returns whether an address is a member.
func IsMember(addr address) bool {
	_, exists := members.Get(addr.String())
	return exists
}

// GetMemberRoles returns the roles for a member (comma-separated) or empty string.
func GetMemberRoles(addr address) string {
	val, exists := members.Get(addr.String())
	if !exists {
		return ""
	}
	return val.(string)
}

// GetMemberCount lets the governance adapter detect unrelated membership
// changes before consuming a voted action.
func GetMemberCount() int { return members.Size() }

// GetMembershipRevision changes for every owner-controlled membership write,
// including role updates and batch syncs that leave the count unchanged.
func GetMembershipRevision() uint64 { return membershipRevision }

// GetOwner returns the current realm owner address.
func GetOwner() address {
	return owner
}

// GetPendingOwner returns the proposed successor owner, or an empty address.
func GetPendingOwner() address {
	return pendingOwner
}

// ── Emergency Pause ────────────────────────────────────────
//
// Pause policy (AAA-1 B3 — one policy, enforced everywhere):
//   While paused, every member-facing content write is blocked via
//   assertNotPaused() — PostThread, PostReply, EditThread, DeleteThread/Reply,
//   FlagThread, RemoveThread/Reply, and SweepTombstones.
//
//   Owner-only governance (AddMember/RemoveMember/UpdateMemberRoles/SyncMembers/
//   PurgeNonMembers/ProposeOwner/CancelPendingOwner/AcceptOwnership/CreateChannel)
//   is intentionally NOT gated:
//   pause halts user activity during an incident, but the owner must stay able to
//   fix membership/ownership while paused. This realm holds no funds, so there is
//   no value-exit exemption to carve out.

func assertNotPaused() {
	if paused {
		panic("realm is paused — emergency maintenance")
	}
}

func PauseRealm(cur realm) {
	assertCallerIsOwner()
	paused = true
	chain.Emit("RealmPaused", "by", owner.String())
}

func UnpauseRealm(cur realm) {
	assertCallerIsOwner()
	paused = false
	chain.Emit("RealmUnpaused", "by", owner.String())
}

func IsPaused() bool { return paused }

// ── Channel Management ───────────────────────────────────────

// Value-only reads let a fixed governance adapter verify a voted channel
// creation without exposing the mutable channel record.
func GetChannelState(name string) (int, bool, string, string, string, string) {
	value, exists := channels.Get(name)
	if !exists { return len(channelOrder), false, "", "", "", "" }
	channel := value.(*Channel)
	return len(channelOrder), true, channel.Description, string(channel.Type), strings.Join(channel.ReadRoles, ","), strings.Join(channel.WriteRoles, ",")
}

// CreateChannel adds a new channel. Only the owner (admin) can create channels.
func CreateChannel(cur realm, name, description string, ctype string) {
	assertCallerIsOwner()

	if len(channelOrder) >= MaxChannels {
		panic(ufmt.Sprintf("max channels reached: %d", MaxChannels))
	}
	if _, exists := channels.Get(name); exists {
		panic("channel already exists: " + name)
	}
	if !isValidChannelName(name) {
		panic("invalid channel name: must be 1-50 lowercase alphanumeric characters or hyphens, no leading underscore")
	}

	ct := ChannelText
	switch ctype {
	case "announcements":
		ct = ChannelAnnouncements
	case "readonly":
		ct = ChannelReadonly
	}

	addChannel(name, description, ct,
		[]string{"admin", "dev", "ops", "member"},
		[]string{"admin", "dev", "ops", "member"})

	chain.Emit("ChannelCreated", "name", name, "type", string(ct))
}

// ── Post Management ─────────────────────────────────────────

// PostThread creates a new thread in a channel.
// Caller must be a member with a role listed in the channel's WriteRoles.
func PostThread(cur realm, channel, title, body string) uint64 {
	assertNotPaused()
	caller := unsafe.PreviousRealm().Address()

	// Validate membership and channel write access
	ch := getChannel(channel)
	assertCallerHasWriteAccess(caller, ch)
	if ch.Archived {
		panic("channel is archived")
	}
	// Cap on LIVE (non-deleted) threads so deleted threads free up slots.
	if getLiveThreadCount(channel) >= MaxThreadsPerChan {
		panic(ufmt.Sprintf("channel live thread limit reached: %d — delete old threads to make room", MaxThreadsPerChan))
	}
	if len(title) == 0 || len(title) > MaxTitleLen {
		panic(ufmt.Sprintf("title must be 1-%d characters", MaxTitleLen))
	}
	if len(body) > MaxPostLen {
		panic(ufmt.Sprintf("body too long: %d/%d chars", len(body), MaxPostLen))
	}

	// Get next ID
	nextID := getThreadCount(channel)
	key := channel + "/" + strconv.FormatUint(nextID, 10)

	t := &Thread{
		ID:      nextID,
		Channel: channel,
		Title:   title,
		Body:    body,
		Author:  caller,
		BlockH:  runtime.ChainHeight(),
	}
	threads.Set(key, t)
	threadCount.Set(channel, nextID+1)
	threadLive.Set(channel, getLiveThreadCount(channel)+1)
	addLiveThreadID(channel, nextID)
	replyCount.Set(key, uint64(0))

	chain.Emit("ThreadPosted",
		"channel", channel,
		"threadId", strconv.FormatUint(nextID, 10),
		"author", caller.String(),
	)

	return nextID
}

// PostReply adds a reply to a thread.
// Caller must be a member with a role listed in the channel's WriteRoles.
func PostReply(cur realm, channel string, threadID uint64, body string) {
	assertNotPaused()
	caller := unsafe.PreviousRealm().Address()

	// Validate membership and channel write access
	ch := getChannel(channel)
	assertCallerHasWriteAccess(caller, ch)

	threadKey := channel + "/" + strconv.FormatUint(threadID, 10)
	tval, texists := threads.Get(threadKey)
	if !texists {
		panic("thread not found")
	}
	thread := tval.(*Thread)
	if thread.Deleted {
		panic("cannot reply to a deleted thread")
	}
	if thread.Hidden {
		panic("cannot reply to a hidden thread")
	}

	if len(body) == 0 || len(body) > MaxPostLen {
		panic(ufmt.Sprintf("reply must be 1-%d characters", MaxPostLen))
	}

	// B1: bound the LIVE reply set so renderThread stays under the gas budget.
	// Deleting replies frees slots (mirrors MaxThreadsPerChan / getLiveThreadCount).
	if getLiveReplyCount(threadKey) >= MaxRepliesPerThread {
		panic(ufmt.Sprintf("thread reply limit reached: %d — older replies must be removed", MaxRepliesPerThread))
	}

	nextReplyID := getReplyCount(threadKey)
	replyKey := threadKey + "/" + strconv.FormatUint(nextReplyID, 10)

	r := &Reply{
		ID:       nextReplyID,
		ThreadID: threadID,
		Channel:  channel,
		Body:     body,
		Author:   caller,
		BlockH:   runtime.ChainHeight(),
	}
	replies.Set(replyKey, r)
	replyCount.Set(threadKey, nextReplyID+1)
	// Track the live reply so renderThread iterates only live IDs (bounded set),
	// never the monotonic counter.
	addLiveReplyID(threadKey, nextReplyID)
	replyLive.Set(threadKey, getLiveReplyCount(threadKey)+1)

	chain.Emit("ReplyPosted",
		"channel", channel,
		"threadId", strconv.FormatUint(threadID, 10),
		"replyId", strconv.FormatUint(nextReplyID, 10),
		"author", caller.String(),
	)
}

// dropReply hard-removes a reply: deletes the node (storage reclaimed — B2),
// drops it from the live index, and decrements the live count. Shared by
// DeleteReply and RemoveReply. renderThread only walks the live index, so a
// removed reply is never looked up — no tombstone is needed.
func dropReply(threadKey, replyKey string, replyID uint64) {
	replies.Remove(replyKey)
	removeLiveReplyID(threadKey, replyID)
	if live := getLiveReplyCount(threadKey); live > 0 {
		replyLive.Set(threadKey, live-1)
	}
}

// DeleteReply lets the reply's author delete it. Caller must be a member and the
// original author. The reply node is hard-removed (B2 state-shrink) and a slot is
// freed under MaxRepliesPerThread (B1).
func DeleteReply(cur realm, channel string, threadID, replyID uint64) {
	assertNotPaused()
	caller := unsafe.PreviousRealm().Address()
	assertCallerIsMember(caller)

	threadKey := channel + "/" + strconv.FormatUint(threadID, 10)
	replyKey := threadKey + "/" + strconv.FormatUint(replyID, 10)
	rval, exists := replies.Get(replyKey)
	if !exists {
		panic("reply not found")
	}
	if rval.(*Reply).Author != caller {
		panic("only the author can delete")
	}

	dropReply(threadKey, replyKey, replyID)

	chain.Emit("ReplyDeleted",
		"channel", channel,
		"threadId", strconv.FormatUint(threadID, 10),
		"replyId", strconv.FormatUint(replyID, 10),
		"author", caller.String(),
	)
}

// RemoveReply permanently removes a reply (moderation — admin role only). Hard-
// removes the node like DeleteReply, bounding renderThread (B1) + reclaiming
// storage (B2).
func RemoveReply(cur realm, channel string, threadID, replyID uint64) {
	assertCallerIsAdminRole()
	caller := unsafe.PreviousRealm().Address()

	threadKey := channel + "/" + strconv.FormatUint(threadID, 10)
	replyKey := threadKey + "/" + strconv.FormatUint(replyID, 10)
	if _, exists := replies.Get(replyKey); !exists {
		panic("reply not found")
	}

	dropReply(threadKey, replyKey, replyID)

	chain.Emit("ReplyRemoved",
		"channel", channel,
		"threadId", strconv.FormatUint(threadID, 10),
		"replyId", strconv.FormatUint(replyID, 10),
		"admin", caller.String(),
	)
}

// EditThread allows the original author to edit their thread. Caller must be a member.
func EditThread(cur realm, channel string, threadID uint64, newBody string) {
	assertNotPaused()
	caller := unsafe.PreviousRealm().Address()
	assertCallerIsMember(caller)

	threadKey := channel + "/" + strconv.FormatUint(threadID, 10)
	val, exists := threads.Get(threadKey)
	if !exists {
		panic("thread not found")
	}

	t := val.(*Thread)
	if t.Author != caller {
		panic("only the author can edit")
	}
	if t.Deleted {
		panic("cannot edit a deleted thread")
	}
	if t.Hidden {
		panic("cannot edit a hidden thread")
	}
	if len(newBody) > MaxPostLen {
		panic("body too long")
	}

	t.Body = newBody
	t.Edited = true
	t.EditedAt = runtime.ChainHeight()
	threads.Set(threadKey, t)

	chain.Emit("ThreadEdited",
		"channel", channel,
		"threadId", strconv.FormatUint(threadID, 10),
		"author", caller.String(),
	)
}

// DeleteThread soft-deletes a thread (marks as deleted). Caller must be a member and the original author.
func DeleteThread(cur realm, channel string, threadID uint64) {
	assertNotPaused()
	caller := unsafe.PreviousRealm().Address()
	assertCallerIsMember(caller)

	threadKey := channel + "/" + strconv.FormatUint(threadID, 10)
	val, exists := threads.Get(threadKey)
	if !exists {
		panic("thread not found")
	}

	t := val.(*Thread)
	if t.Author != caller {
		panic("only the author can delete")
	}
	if t.Deleted {
		panic("thread already deleted")
	}

	t.Deleted = true
	t.Title = "[Deleted]"
	t.Body = ""
	threads.Set(threadKey, t)
	// Free a slot for new threads
	live := getLiveThreadCount(channel)
	if live > 0 {
		threadLive.Set(channel, live-1)
	}
	removeLiveThreadID(channel, threadID)
	enqueueThreadTomb(channel, threadID) // B2: queue for hard-GC via SweepTombstones

	chain.Emit("ThreadDeleted",
		"channel", channel,
		"threadId", strconv.FormatUint(threadID, 10),
		"author", caller.String(),
	)
}

// ── Moderation ──────────────────────────────────────────────

// FlagThread flags a thread for moderation review.
// After FlagThreshold flags, the thread is auto-hidden.
// Caller must be a member (any role) to flag content.
func FlagThread(cur realm, channel string, threadID uint64) {
	assertNotPaused()
	caller := unsafe.PreviousRealm().Address()
	assertCallerIsMember(caller)
	threadKey := channel + "/" + strconv.FormatUint(threadID, 10)

	val, exists := threads.Get(threadKey)
	if !exists {
		panic("thread not found")
	}

	t := val.(*Thread)
	if t.Deleted {
		panic("cannot flag a deleted thread")
	}
	if t.Hidden {
		panic("thread is already hidden")
	}

	// Track unique flaggers
	var flagTree *avl.Tree
	if fval, fexists := flags.Get(threadKey); fexists {
		flagTree = fval.(*avl.Tree)
	} else {
		flagTree = avl.NewTree()
	}

	if _, already := flagTree.Get(caller.String()); already {
		panic("already flagged")
	}
	flagTree.Set(caller.String(), true)
	flags.Set(threadKey, flagTree)

	// Update thread flag count and auto-hide.
	// Dynamic threshold: max(FlagThreshold, 5% of members), scales with DAO size.
	t.FlagCount = flagTree.Size()
	dynamicThreshold := FlagThreshold
	fivePct := members.Size() / 20
	if fivePct > dynamicThreshold {
		dynamicThreshold = fivePct
	}
	wasHidden := t.Hidden
	if t.FlagCount >= dynamicThreshold {
		t.Hidden = true
	}
	threads.Set(threadKey, t)

	chain.Emit("ThreadFlagged",
		"channel", channel,
		"threadId", strconv.FormatUint(threadID, 10),
		"flagger", caller.String(),
		"flagCount", strconv.Itoa(t.FlagCount),
	)
	if !wasHidden && t.Hidden {
		chain.Emit("ThreadAutoHidden",
			"channel", channel,
			"threadId", strconv.FormatUint(threadID, 10),
		)
	}
}

// UnhideThread allows the owner or an admin to clear flags and un-hide a thread.
func UnhideThread(cur realm, channel string, threadID uint64) {
	assertCallerIsAdminRole()
	caller := unsafe.PreviousRealm().Address()
	threadKey := channel + "/" + strconv.FormatUint(threadID, 10)

	val, exists := threads.Get(threadKey)
	if !exists {
		panic("thread not found")
	}
	t := val.(*Thread)
	t.Hidden = false
	t.FlagCount = 0
	threads.Set(threadKey, t)
	// Clear flag tree
	flags.Remove(threadKey)

	chain.Emit("ThreadUnhidden",
		"channel", channel,
		"threadId", strconv.FormatUint(threadID, 10),
		"admin", caller.String(),
	)
}

// RemoveThread permanently removes a thread (moderation action — admin role only).
func RemoveThread(cur realm, channel string, threadID uint64) {
	assertCallerIsAdminRole()
	caller := unsafe.PreviousRealm().Address()
	threadKey := channel + "/" + strconv.FormatUint(threadID, 10)
	val, exists := threads.Get(threadKey)
	if !exists {
		panic("thread not found")
	}

	t := val.(*Thread)
	if !t.Deleted {
		live := getLiveThreadCount(channel)
		if live > 0 {
			threadLive.Set(channel, live-1)
		}
		removeLiveThreadID(channel, threadID)
		enqueueThreadTomb(channel, threadID) // B2: queue for hard-GC (skip if already tombstoned)
	}
	t.Deleted = true
	t.Hidden = true
	t.Title = "[Removed by moderation]"
	t.Body = ""
	threads.Set(threadKey, t)

	chain.Emit("ThreadRemoved",
		"channel", channel,
		"threadId", strconv.FormatUint(threadID, 10),
		"admin", caller.String(),
	)
}

// SweepTombstones hard-removes up to `limit` soft-deleted threads in a channel
// (and all of their remaining reply state), reclaiming AVL storage so that
// post+delete spam can no longer accrete permanent state (B2).
//
// Admin role only. The chain refunds the storage deposit of freed bytes to the
// transaction that frees them (gnoland-1 restricts no denom), and a thread's
// remaining replies were paid for by their authors. Restricting the sweep keeps
// thread authors and outsiders from collecting other members' deposits.
//
// Bounded + idempotent: each soft-deleted thread holds at most
// MaxRepliesPerThread reply nodes, so keep `limit` small (1–5) to stay well
// within block gas; re-running drains the next batch and stops at 0.
// Returns the number of threads swept.
func SweepTombstones(cur realm, channel string, limit int) int {
	assertNotPaused()
	assertCallerIsAdminRole()
	if limit <= 0 {
		return 0
	}

	tomb := getThreadTomb(channel)
	n := limit
	if n > len(tomb) {
		n = len(tomb)
	}

	for i := 0; i < n; i++ {
		threadKey := channel + "/" + strconv.FormatUint(tomb[i], 10)
		// Collect-then-remove: read the live reply IDs (a stored slice) and remove
		// each reply node — we never iterate the tree we mutate (AVL footgun).
		for _, rid := range getLiveReplyIDs(threadKey) {
			replies.Remove(threadKey + "/" + strconv.FormatUint(rid, 10))
		}
		replyLiveIDs.Remove(threadKey)
		replyLive.Remove(threadKey)
		replyCount.Remove(threadKey)
		flags.Remove(threadKey)
		threads.Remove(threadKey)
	}

	// Drop the processed prefix; copy the tail into a fresh slice to avoid aliasing.
	remaining := append([]uint64{}, tomb[n:]...)
	if len(remaining) == 0 {
		threadTomb.Remove(channel)
	} else {
		threadTomb.Set(channel, remaining)
	}

	if n > 0 {
		chain.Emit("TombstonesSwept",
			"channel", channel,
			"count", strconv.Itoa(n),
		)
	}
	return n
}

// GetTombstoneCount returns how many soft-deleted threads in a channel are still
// awaiting hard-GC (read-only; lets ops/indexers decide when to call SweepTombstones).
func GetTombstoneCount(channel string) int {
	return len(getThreadTomb(channel))
}

// ── Render ───────────────────────────────────────────────────
// CRITICAL: Output format MUST match parser.ts regex patterns.

func Render(path string) string {
	if path == "" {
		return renderHome()
	}
	if strings.HasPrefix(path, "__acl/") {
		channelName := strings.TrimPrefix(path, "__acl/")
		return renderACL(channelName)
	}
	if strings.HasPrefix(path, "__member/") {
		addr := strings.TrimPrefix(path, "__member/")
		roles := GetMemberRoles(address(addr))
		if roles == "" {
			return "not found"
		}
		return "roles:" + roles
	}
	if strings.HasPrefix(path, "_channel/") {
		channelName := strings.TrimPrefix(path, "_channel/")
		return renderChannel(channelName)
	}

	// Check for "channel/threadId" pattern, optionally with a "?page=N" suffix
	// for reply pagination (B1).
	parts := strings.SplitN(path, "/", 2)
	if len(parts) == 2 {
		idPart := parts[1]
		page := uint64(0)
		if qi := strings.IndexByte(idPart, '?'); qi >= 0 {
			page = parsePageQuery(idPart[qi+1:])
			idPart = idPart[:qi]
		}
		threadID, err := strconv.ParseUint(idPart, 10, 64)
		if err == nil {
			return renderThread(parts[0], threadID, page)
		}
	}

	// Try as channel name directly
	if _, exists := channels.Get(path); exists {
		return renderChannel(path)
	}

	return "# 404\nPage not found: " + path
}

// renderHome produces the board home page.
// Format: parser.ts parseBoardHome() expects:
//   - [#name](:_channel/name) 📢 (N threads)
func renderHome() string {
	var sb strings.Builder
	sb.WriteString("# MembaDAO Channels\n\n")
	sb.WriteString("Community discussion channels for the Memba ecosystem.\n\n")
	sb.WriteString(ufmt.Sprintf("**Owner:** %s | **Members:** %d\n\n", owner, members.Size()))
	sb.WriteString("## Channels\n\n")

	for _, name := range channelOrder {
		val, exists := channels.Get(name)
		if !exists {
			continue
		}
		ch := val.(*Channel)
		if ch.Archived {
			continue
		}

		count := getThreadCount(name)
		typeIcon := ""
		switch ch.Type {
		case ChannelAnnouncements:
			typeIcon = " 📢"
		case ChannelReadonly:
			typeIcon = " 🔒"
		}

		sb.WriteString(ufmt.Sprintf("- [#%s](:_channel/%s)%s (%d threads)\n",
			name, name, typeIcon, count))
	}

	return sb.String()
}

// renderChannel produces a channel's thread list.
// Format: parser.ts parseThreadList() expects:
//   ### [Title](:channel/id)
//   by g1addr... | N replies | block H
func renderChannel(channelName string) string {
	if _, exists := channels.Get(channelName); !exists {
		return "# 404\nChannel not found: " + channelName
	}

	var sb strings.Builder
	sb.WriteString(ufmt.Sprintf("# #%s\n\n", channelName))

	// Iterate the LIVE thread-ID index (bounded by getLiveThreadCount), newest
	// first. Never loop over the monotonic threadCount — a post+delete spam
	// loop inflates it without bound (gas DoS); deleted IDs are not in this index.
	ids := getLiveThreadIDs(channelName)
	if len(ids) == 0 {
		sb.WriteString("*No threads yet. Be the first to post!*\n")
		return sb.String()
	}

	for i := len(ids) - 1; i >= 0; i-- {
		threadKey := channelName + "/" + strconv.FormatUint(ids[i], 10)
		val, exists := threads.Get(threadKey)
		if !exists {
			continue
		}
		t := val.(*Thread)
		if t.Hidden || t.Deleted {
			continue
		}

		// Count live (non-deleted) replies — matches what renderThread shows.
		rCount := getLiveReplyCount(threadKey)
		authorStr := truncAddr(t.Author)

		sb.WriteString(ufmt.Sprintf("### [%s](:%s/%d)\n", sanitizeForRender(t.Title), channelName, t.ID))
		sb.WriteString(ufmt.Sprintf("by %s | %d replies | block %d\n\n", authorStr, rCount, t.BlockH))
	}

	return sb.String()
}

// renderThread produces a single thread with replies.
// Format: parser.ts parseThreadDetail() expects:
//   # Title
//   body
//   ---
//   *Posted by g1addr at block H* *(edited at block M)*
//   ## Replies
//   **g1addr...** (block H) *(edited)*
//   reply body
//   ---
func renderThread(channelName string, threadID, page uint64) string {
	threadKey := channelName + "/" + strconv.FormatUint(threadID, 10)
	val, exists := threads.Get(threadKey)
	if !exists {
		return "# 404\nThread not found"
	}

	t := val.(*Thread)

	// Suppress content for hidden (flag-auto-hidden or admin-hidden) and
	// soft-deleted threads. renderChannel omits these from the list, but the
	// direct path Render("channel/id") must not leak the original title/body.
	if t.Hidden || t.Deleted {
		return "# Thread unavailable\n\n*This thread has been hidden or removed.*\n"
	}

	var sb strings.Builder
	sb.WriteString(ufmt.Sprintf("# %s\n\n", sanitizeForRender(t.Title)))
	sb.WriteString(sanitizeForRender(t.Body) + "\n\n")
	sb.WriteString("---\n\n")
	sb.WriteString(ufmt.Sprintf("*Posted by %s at block %d*", string(t.Author), t.BlockH))
	if t.Edited {
		sb.WriteString(ufmt.Sprintf(" *(edited at block %d)*", t.EditedAt))
	}
	sb.WriteString("\n\n")

	// B1: render only LIVE replies (bounded by MaxRepliesPerThread), paginated to
	// a fixed window so render cost is O(ReplyPageSize) regardless of total churn.
	// Never iterate the monotonic replyCount — that is the render-DoS surface.
	liveIDs := getLiveReplyIDs(threadKey) // ascending (oldest→newest), <= MaxRepliesPerThread
	total := uint64(len(liveIDs))
	if total > 0 {
		totalPages := (total + ReplyPageSize - 1) / ReplyPageSize
		// page 1 = oldest window … totalPages = newest. Default (0) and any
		// out-of-range value snap to the newest page (most-recent replies).
		if page == 0 || page > totalPages {
			page = totalPages
		}
		start := (page - 1) * ReplyPageSize
		end := start + ReplyPageSize
		if end > total {
			end = total
		}

		sb.WriteString("## Replies\n\n")
		if totalPages > 1 {
			sb.WriteString(ufmt.Sprintf(
				"*Showing %d–%d of %d • page %d/%d — older: `?page=%d`, newer: `?page=%d`*\n\n",
				start+1, end, total, page, totalPages, pageClamp(page-1, totalPages), pageClamp(page+1, totalPages)))
		}

		for i := start; i < end; i++ {
			replyKey := threadKey + "/" + strconv.FormatUint(liveIDs[i], 10)
			rval, rexists := replies.Get(replyKey)
			if !rexists {
				continue // live index never points at a removed reply, but stay safe
			}
			r := rval.(*Reply)
			authorStr := truncAddr(r.Author)
			editStr := ""
			if r.Edited {
				editStr = " *(edited)*"
			}
			sb.WriteString(ufmt.Sprintf("**%s** (block %d)%s\n\n", authorStr, r.BlockH, editStr))
			sb.WriteString(sanitizeForRender(r.Body) + "\n\n")
			sb.WriteString("---\n\n")
		}
	}

	return sb.String()
}

// parsePageQuery extracts the page number from a "?page=N" query string (also
// tolerates extra &-separated params). Returns 0 (= default/newest) on absence
// or parse error.
func parsePageQuery(q string) uint64 {
	for _, kv := range strings.Split(q, "&") {
		if strings.HasPrefix(kv, "page=") {
			if n, err := strconv.ParseUint(strings.TrimPrefix(kv, "page="), 10, 64); err == nil {
				return n
			}
		}
	}
	return 0
}

// pageClamp keeps a page link within [1, totalPages].
func pageClamp(p, totalPages uint64) uint64 {
	if p < 1 {
		return 1
	}
	if p > totalPages {
		return totalPages
	}
	return p
}

// renderACL produces the ACL response for a channel.
// Format: parser.ts parseACL() expects:
//   read:role1,role2
//   write:role1,role2,role3
//   type:text
func renderACL(channelName string) string {
	val, exists := channels.Get(channelName)
	if !exists {
		return "not found"
	}
	ch := val.(*Channel)

	var sb strings.Builder
	sb.WriteString("read:" + strings.Join(ch.ReadRoles, ",") + "\n")
	sb.WriteString("write:" + strings.Join(ch.WriteRoles, ",") + "\n")
	sb.WriteString("type:" + string(ch.Type) + "\n")

	return sb.String()
}

// ── Helpers ──────────────────────────────────────────────────

func getChannel(name string) *Channel {
	val, exists := channels.Get(name)
	if !exists {
		panic("channel not found: " + name)
	}
	return val.(*Channel)
}

func getThreadCount(channel string) uint64 {
	val, exists := threadCount.Get(channel)
	if !exists {
		return 0
	}
	return val.(uint64)
}

// getLiveThreadCount returns the number of non-deleted threads in a channel.
// Unlike getThreadCount (monotonic ID counter), this decreases when threads
// are deleted, so deleted threads free up slots under MaxThreadsPerChan.
func getLiveThreadCount(channel string) uint64 {
	val, exists := threadLive.Get(channel)
	if !exists {
		return 0
	}
	return val.(uint64)
}

// ── Live thread-ID index ─────────────────────────────────────
// renderChannel must iterate only live (non-deleted) thread IDs, never the
// monotonic threadCount: a member can post+delete in a loop to inflate
// threadCount without bound (the live cap only limits live threads), turning
// renderChannel into an unbounded O(threadCount) scan (gas DoS). This index
// stays bounded by getLiveThreadCount (<= MaxThreadsPerChan).

func getLiveThreadIDs(channel string) []uint64 {
	if val, exists := threadLiveIDs.Get(channel); exists {
		return val.([]uint64)
	}
	return nil
}

func addLiveThreadID(channel string, id uint64) {
	threadLiveIDs.Set(channel, append(getLiveThreadIDs(channel), id))
}

func removeLiveThreadID(channel string, id uint64) {
	ids := getLiveThreadIDs(channel)
	for i, x := range ids {
		if x == id {
			threadLiveIDs.Set(channel, append(ids[:i], ids[i+1:]...))
			return
		}
	}
}

// ── Live reply-ID index ──────────────────────────────────────
// Same rationale as the thread index, one level down: renderThread must iterate
// only live reply IDs (bounded by MaxRepliesPerThread), never the monotonic
// replyCount, or a member can post+delete replies in a loop to make a thread
// unrenderable. Keyed by "channel/threadId".

func getLiveReplyCount(threadKey string) uint64 {
	if val, exists := replyLive.Get(threadKey); exists {
		return val.(uint64)
	}
	return 0
}

func getLiveReplyIDs(threadKey string) []uint64 {
	if val, exists := replyLiveIDs.Get(threadKey); exists {
		return val.([]uint64)
	}
	return nil
}

func addLiveReplyID(threadKey string, id uint64) {
	replyLiveIDs.Set(threadKey, append(getLiveReplyIDs(threadKey), id))
}

func removeLiveReplyID(threadKey string, id uint64) {
	ids := getLiveReplyIDs(threadKey)
	for i, x := range ids {
		if x == id {
			replyLiveIDs.Set(threadKey, append(ids[:i], ids[i+1:]...))
			return
		}
	}
}

// ── Thread tombstone queue (B2 hard-GC) ──────────────────────
// Soft-deleted thread IDs awaiting permanent removal by SweepTombstones. A queue
// (not a scan of the threads tree) keeps the sweep O(limit) — it never walks the
// unbounded set of past tombstones.

func getThreadTomb(channel string) []uint64 {
	if val, exists := threadTomb.Get(channel); exists {
		return val.([]uint64)
	}
	return nil
}

func enqueueThreadTomb(channel string, id uint64) {
	threadTomb.Set(channel, append(getThreadTomb(channel), id))
}

func getReplyCount(threadKey string) uint64 {
	val, exists := replyCount.Get(threadKey)
	if !exists {
		return 0
	}
	return val.(uint64)
}

func truncAddr(addr address) string {
	s := string(addr)
	if len(s) > 13 {
		return s[:10] + "..."
	}
	return s
}

// isValidRoles validates a comma-separated role list contains only safe characters.
// Allowed: a-z, A-Z, 0-9, hyphen, comma. No spaces, no markdown chars, no null bytes.
func isValidRoles(s string) bool {
	if len(s) > 200 {
		return false
	}
	for _, c := range s {
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '-' || c == ',') {
			return false
		}
	}
	return true
}

// sanitizeForRender strips markdown-sensitive characters to prevent injection.
func sanitizeForRender(s string) string {
	var out strings.Builder
	for _, c := range s {
		switch c {
		case '[', ']', '(', ')', '#', '*', '`', '!', '<', '>', '|', '\\', '_', '~', '\n', '\r', '\t':
			continue
		default:
			out.WriteRune(c)
		}
	}
	return out.String()
}

// ── ACL Enforcement ─────────────────────────────────────────

func assertCallerIsOwner() {
	caller := unsafe.PreviousRealm().Address()
	if caller != owner {
		panic("unauthorized: caller " + caller.String() + " is not the owner")
	}
}

func assertCallerIsMember(caller address) {
	if _, exists := members.Get(caller.String()); !exists {
		panic("unauthorized: caller " + caller.String() + " is not a member")
	}
}

// assertCallerHasWriteAccess checks that the caller is a member AND has at least
// one role that matches the channel's WriteRoles.
func assertCallerHasWriteAccess(caller address, ch *Channel) {
	rolesStr, exists := members.Get(caller.String())
	if !exists {
		panic("unauthorized: caller " + caller.String() + " is not a member")
	}

	callerRoles := strings.Split(rolesStr.(string), ",")
	for _, cr := range callerRoles {
		cr = strings.TrimSpace(cr)
		for _, wr := range ch.WriteRoles {
			if cr == wr {
				return // Access granted
			}
		}
	}

	panic("unauthorized: caller " + caller.String() + " lacks write access to channel " + ch.Name)
}

func hasRole(caller address, role string) bool {
	rolesStr, exists := members.Get(caller.String())
	if !exists {
		return false
	}
	callerRoles := strings.Split(rolesStr.(string), ",")
	for _, cr := range callerRoles {
		if strings.TrimSpace(cr) == role {
			return true
		}
	}
	return false
}

// assertCallerIsAdminRole checks that the caller is a member with the "admin" role.
// Used for moderation actions (RemoveThread, UnhideThread) so any admin can moderate,
// not just the single owner.
func assertCallerIsAdminRole() {
	caller := unsafe.PreviousRealm().Address()
	if !hasRole(caller, "admin") {
		panic("unauthorized: caller " + caller.String() + " does not have admin role")
	}
}

// isValidChannelName validates that a channel name contains only
// lowercase alphanumeric characters and hyphens, and does not start with underscore.
func isValidChannelName(name string) bool {
	if len(name) == 0 || len(name) > 50 {
		return false
	}
	if name[0] == '_' {
		return false // Prevent collision with __acl/, __member/ paths
	}
	for _, c := range name {
		if !((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-') {
			return false
		}
	}
	return true
}

package memba_feed_v1

// GetModeratorCount exposes the exact grant count for DAO postconditions.
func GetModeratorCount() int { return moderators.Size() }

package memba_feed_v1

// memba_feed_v1 — Global social feed realm for Memba (W7.2 P0).
//
// OPEN-WRITE: any wallet may post. This inverts every assumption of the
// DAO-scoped memba_dao_channels_v2 (members-only, 20 channels / 500 threads),
// so the realm is NEW — what is ported VERBATIM from channels_v2 is its
// hardening discipline:
//
//   B1 render-DoS bounds — reads NEVER iterate the monotonic nextPostID.
//     Live (visible) posts are tracked in dedicated AVL indexes and every
//     read path is paginated to a fixed window. channels_v2 used []uint64
//     slices (safe under its 500-per-channel cap); an open feed is unbounded,
//     so the live indexes here are composite-key AVL trees instead —
//     O(log n) insert/remove, O(page) scan, no single node that grows forever.
//   B2 state-shrink — author deletes soft-delete + enqueue a tombstone;
//     SweepTombstones hard-removes nodes (bounded, permissionless GC).
//   B3 pause policy — every user-facing write is blocked while paused;
//     owner/moderation stays operational (no funds in this realm).
//   Flag pipeline — one flag per address per post, threshold auto-hide.
//     Open write invites brigading, so the threshold is higher than
//     channels_v2's 3 and flagging is further gated by account age and a
//     per-day flag budget.
//
// Anti-spam (open write has no membership gate to lean on):
//   - per-address block cooldown between posts, stricter for accounts first
//     seen fewer than YoungAccountBlocks ago;
//   - body length cap; media CID count cap (CIDs stored on-chain only —
//     pinning/serving is the backend's PinMedia pipeline, P2).
//
// Reads: exported *JSON funcs via RPC vm/qeval — cursor-paginated, O(limit)
// at any depth (the app reads from the indexer; these are the fallback).
// Render() is the human gnoweb view: bounded pages with a hard depth cap
// (MaxRenderPage) — deep history belongs to the cursor API, not qrender.
//
// Moderation P0: realm owner only (ModRemovePost / UnhidePost / BanAuthor is
// W8.2's moderation board via a daokit moderator role — p/samcrew/modboard).
// Every moderation action emits for public audit.
//
// This realm holds NO funds: no banker, no OriginSend, no fee lane. A future
// tipping lane is a separate SAFETY_GATED flag + fee-spine lane "feed".

import (
	"strconv"
	"strings"

	"gno.land/p/samcrew/avl"
	"gno.land/p/nt/ufmt/v0"

	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
)

// ── Constants ────────────────────────────────────────────────

const (
	MaxBodyLen   = 1000 // post body (roadmap 4.1)
	MaxMediaCIDs = 4    // stored per post; pin/serve pipeline is P2
	MaxCIDLen    = 128  // defensive cap on a single CID string

	FeedPageSize  = 20  // posts per rendered page / default JSON window
	MaxPageLimit  = 100 // hard cap on any JSON read window (DoS guard)
	MaxRenderPage = 50  // deepest gnoweb page; beyond → use the cursor API

	// B1 reply bound (mirrors channels_v2's MaxRepliesPerThread). Caps the
	// LIVE reply set per post so (a) the byParent index under any one parent is
	// bounded, and (b) SweepTombstones can range-delete a swept parent's reply
	// links in bounded work. Deleting a reply frees a slot.
	MaxRepliesPerPost = 500

	// Flag pipeline. channels_v2 auto-hides at 3 member flags; the feed is
	// open-write, so the threshold starts higher and flagging is rate-limited.
	// These are damping knobs, not a brigade-proof gate: 5 aged sybils can
	// still hide a post (the age gate is one post + a one-time wait, farmable
	// in parallel). They raise the cost and slow coordination; genuine brigade
	// resistance is the W8.2 moderation board (reversible mod actions + audit).
	// All are governance-tunable post-deploy via a future realm version; they
	// are constants here so the adversarial tests pin their behavior.
	FlagThreshold        = 5     // unique flags before auto-hide
	MinAccountAgeForFlag = 1200  // blocks since first post (~1-2h)
	FlagsPerDayBudget    = 10    // per address per BlocksPerDay window
	BlocksPerDay         = 17280 // ~5s blocks; approximation is fine

	// Posting cooldowns (blocks). Young accounts (first seen < YoungAccountBlocks
	// ago) wait longer between posts — cheap sybil throttle.
	MinPostIntervalBlocks      = 2
	YoungMinPostIntervalBlocks = 12
	YoungAccountBlocks         = 17280 // first ~day
)

// ── Types ────────────────────────────────────────────────────

type Post struct {
	ID        uint64
	Author    address
	Body      string
	MediaCIDs []string // IPFS CIDs only; serving goes through the backend proxy
	ReplyTo   uint64   // 0 = top-level
	RepostOf  uint64   // 0 = original (entrypoint lands in P1; field is schema-stable)
	BlockH    int64
	EditedAt  int64 // block height of last edit (0 = never)
	FlagCount int
	Hidden    bool // flag auto-hide or moderation hide
	Deleted   bool // author tombstone (awaiting SweepTombstones hard-GC)
}

type flagBudget struct {
	DayStartH int64
	Used      int
}

// ── State ────────────────────────────────────────────────────

var (
	posts *avl.Tree // padID(id) -> *Post (live + hidden + not-yet-swept tombstones)

	// Live indexes (B1): ONLY visible (not hidden, not deleted) posts.
	// Every read path iterates one of these — never `posts`, never nextPostID.
	liveFeed   *avl.Tree // padID(id) -> true
	byAuthor   *avl.Tree // author + ":" + padID(id) -> true
	byParent   *avl.Tree // padID(parent) + ":" + padID(child) -> true
	liveCount  uint64    // number of keys in liveFeed
	replyCount *avl.Tree // padID(parent) -> uint64 (live replies)

	nextPostID uint64 // monotonic; NEVER iterated by reads

	// Anti-spam / flag state.
	lastPostH  *avl.Tree // addr -> int64 (last CreatePost height)
	firstSeenH *avl.Tree // addr -> int64 (first write interaction height)
	flags      *avl.Tree // padID(id) -> *avl.Tree (flagger addr -> true)
	flagSpend  *avl.Tree // addr -> *flagBudget

	// Reactions (one-per-emoji toggle). padID(id) -> *avl.Tree keyed by
	// reactionSubKey(emoji, addr) -> true. Enforces per-(post,emoji,addr)
	// uniqueness on-chain; per-emoji COUNTS are aggregated off-chain by the
	// indexer from ReactionAdded/ReactionRemoved (no unbounded on-chain scan —
	// B1 render bounds hold; a hot post's reaction set is never iterated here).
	reactions *avl.Tree

	// Soft-deleted post IDs awaiting hard-GC (B2). An AVL tree (not a slice):
	// a slice re-serializes wholesale on every enqueue, so post+delete spam
	// would inflate the gas of every write touching it (a slow write-path DoS).
	// The tree gives O(log n) enqueue and lets the sweep drain a bounded
	// ascending window without rewriting the backlog.
	tombstones *avl.Tree // padID(id) -> true

	// Moderator set (W8.2): owner-granted addresses that can ModRemovePost /
	// UnhidePost WITHOUT owner-multisig-per-post — fast, reversible moderation.
	// Granting/revoking stays owner-only. addr -> true.
	moderators *avl.Tree

	paused bool
	// owner is the publishing transaction's signer, captured at package load
	// (on gnoland-1 the samcrew namespace multisig, the stamped creator at enable
	// time) — same pattern as channels_v2. pendingOwner is the staged successor of
	// a two-step handoff, or empty.
	owner        = unsafe.OriginCaller()
	pendingOwner address
)

func init() {
	posts = avl.NewTree()
	liveFeed = avl.NewTree()
	byAuthor = avl.NewTree()
	byParent = avl.NewTree()
	replyCount = avl.NewTree()
	lastPostH = avl.NewTree()
	firstSeenH = avl.NewTree()
	flags = avl.NewTree()
	flagSpend = avl.NewTree()
	reactions = avl.NewTree()
	moderators = avl.NewTree()
	tombstones = avl.NewTree()
	nextPostID = 1
}

// ── Helpers ──────────────────────────────────────────────────

// padID zero-pads to 12 digits so AVL string order == numeric order.
// 12 digits ≥ 31,000 years of one post per block — effectively unbounded.
func padID(id uint64) string {
	s := strconv.FormatUint(id, 10)
	for len(s) < 12 {
		s = "0" + s
	}
	return s
}

func getPost(id uint64) (*Post, bool) {
	v, ok := posts.Get(padID(id))
	if !ok {
		return nil, false
	}
	return v.(*Post), true
}

func mustGetPost(id uint64) *Post {
	p, ok := getPost(id)
	if !ok {
		panic("post not found: " + strconv.FormatUint(id, 10))
	}
	return p
}

func authorKey(addr address, id uint64) string { return addr.String() + ":" + padID(id) }
func parentKey(parent, child uint64) string    { return padID(parent) + ":" + padID(child) }

func getReplyCount(parent uint64) uint64 {
	if v, ok := replyCount.Get(padID(parent)); ok {
		return v.(uint64)
	}
	return 0
}

// addToLiveIndexes registers a visible post in every live index (B1).
//
// A reply is only linked into its parent's byParent/replyCount indexes when the
// parent is still LIVE. On CreatePost the parent was just verified live, so this
// is always true there. The guard matters on the UnhidePost re-add path: if the
// parent was deleted+swept while the reply sat hidden, re-linking would recreate
// an orphan byParent/replyCount entry under a parent id no longer in `posts`
// (never sweepable again) — the exact leak SweepTombstones' byParent-prefix
// cleanup was added to prevent. An unhidden reply whose parent is gone simply
// becomes standalone live content, which is how a reply to a removed parent is
// already treated everywhere else.
func addToLiveIndexes(p *Post) {
	liveFeed.Set(padID(p.ID), true)
	byAuthor.Set(authorKey(p.Author, p.ID), true)
	liveCount++
	if p.ReplyTo != 0 && liveFeed.Has(padID(p.ReplyTo)) {
		byParent.Set(parentKey(p.ReplyTo, p.ID), true)
		replyCount.Set(padID(p.ReplyTo), getReplyCount(p.ReplyTo)+1)
	}
}

// removeFromLiveIndexes drops a post from every live index (hide/delete).
func removeFromLiveIndexes(p *Post) {
	if _, ok := liveFeed.Get(padID(p.ID)); !ok {
		return // already invisible (e.g. delete after auto-hide)
	}
	liveFeed.Remove(padID(p.ID))
	byAuthor.Remove(authorKey(p.Author, p.ID))
	if liveCount > 0 {
		liveCount--
	}
	if p.ReplyTo != 0 {
		byParent.Remove(parentKey(p.ReplyTo, p.ID))
		if rc := getReplyCount(p.ReplyTo); rc > 0 {
			replyCount.Set(padID(p.ReplyTo), rc-1)
		}
	}
}

func assertNotPaused() {
	if paused {
		panic("realm is paused — emergency maintenance")
	}
}

func assertCallerIsOwner() {
	caller := unsafe.PreviousRealm().Address()
	if caller != owner {
		panic("unauthorized: caller " + caller.String() + " is not the owner")
	}
}

// touchFirstSeen records the first write interaction height for an address.
func touchFirstSeen(addr address, h int64) {
	if _, ok := firstSeenH.Get(addr.String()); !ok {
		firstSeenH.Set(addr.String(), h)
	}
}

func accountAge(addr address, now int64) int64 {
	if v, ok := firstSeenH.Get(addr.String()); ok {
		return now - v.(int64)
	}
	return 0
}

// ── Emergency pause (B3 — one policy, enforced everywhere) ───
// While paused every user-facing content write is blocked. Owner moderation
// and pause management stay live: pause halts user activity during an
// incident, but the owner must stay able to act. No funds here, so there is
// no value-exit exemption to carve out.

func PauseRealm(cur realm) {
	assertCallerIsOwner()
	paused = true
	chain.Emit("RealmPaused", "by", owner.String())
}

func UnpauseRealm(cur realm) {
	assertCallerIsOwner()
	paused = false
	chain.Emit("RealmUnpaused", "by", owner.String())
}

func IsPaused() bool { return paused }

// TransferOwnership stages a successor owner. Nothing moves until that address
// calls AcceptOwnership with its own transaction, so ownership can never land on
// an address that cannot act. A later call replaces the staged address;
// CancelOwnershipTransfer withdraws it.
func TransferOwnership(cur realm, newOwner address) {
	assertCallerIsOwner()
	if newOwner == "" {
		panic("address cannot be empty")
	}
	if !newOwner.IsValid() {
		panic("invalid address: " + newOwner.String())
	}
	if newOwner == owner {
		panic("new owner is the same as current owner")
	}
	pendingOwner = newOwner
	chain.Emit("OwnershipTransferStarted", "pending", newOwner.String())
}

// CancelOwnershipTransfer withdraws a staged handoff. Owner only.
func CancelOwnershipTransfer(cur realm) {
	assertCallerIsOwner()
	if pendingOwner == "" {
		panic("no pending ownership transfer")
	}
	cancelled := pendingOwner
	pendingOwner = ""
	chain.Emit("OwnershipTransferCancelled", "pending", cancelled.String())
}

// AcceptOwnership completes the handoff. Only the staged pendingOwner may call it.
func AcceptOwnership(cur realm) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	caller := cur.Previous().Address()
	if pendingOwner == "" || caller != pendingOwner {
		panic("unauthorized: caller " + caller.String() + " is not the pending owner")
	}
	prev := owner
	owner = caller
	pendingOwner = ""
	chain.Emit("OwnershipTransferred",
		"previousOwner", prev.String(),
		"newOwner", caller.String(),
	)
}

// GetOwner returns the current realm owner address.
func GetOwner() address { return owner }

// GetPendingOwner returns the staged successor, or the empty address.
func GetPendingOwner() address { return pendingOwner }

// ── Writes ───────────────────────────────────────────────────

// CreatePost publishes a post (replyTo == 0) or a reply (replyTo == parent id).
// Open write: any wallet, subject to the block cooldown and body caps.
// Returns the new post id.
func CreatePost(cur realm, body string, replyTo uint64) uint64 {
	assertNotPaused()
	caller := unsafe.PreviousRealm().Address()
	now := runtime.ChainHeight()

	// Cooldown BEFORE touching state: young accounts wait longer.
	touchFirstSeen(caller, now)
	interval := int64(MinPostIntervalBlocks)
	if accountAge(caller, now) < YoungAccountBlocks {
		interval = YoungMinPostIntervalBlocks
	}
	if v, ok := lastPostH.Get(caller.String()); ok {
		if now-v.(int64) < interval {
			panic(ufmt.Sprintf("posting too fast: wait %d blocks between posts", interval))
		}
	}

	if len(body) == 0 || len(body) > MaxBodyLen {
		panic(ufmt.Sprintf("body must be 1-%d characters", MaxBodyLen))
	}

	var parent *Post
	if replyTo != 0 {
		parent = mustGetPost(replyTo)
		if parent.Deleted {
			panic("cannot reply to a deleted post")
		}
		if parent.Hidden {
			panic("cannot reply to a hidden post")
		}
		// B1: bound the LIVE reply set so the byParent index under one parent
		// stays bounded (and a swept parent's link cleanup stays bounded).
		if getReplyCount(replyTo) >= MaxRepliesPerPost {
			panic(ufmt.Sprintf("reply limit reached: %d per post", MaxRepliesPerPost))
		}
	}

	id := nextPostID
	nextPostID++

	p := &Post{
		ID:      id,
		Author:  caller,
		Body:    body,
		ReplyTo: replyTo,
		BlockH:  now,
	}
	posts.Set(padID(id), p)
	addToLiveIndexes(p)
	lastPostH.Set(caller.String(), now)

	chain.Emit("PostCreated",
		"postId", strconv.FormatUint(id, 10),
		"author", caller.String(),
		"replyTo", strconv.FormatUint(replyTo, 10),
		"body", body,
	)
	return id
}

// EditPost lets the author replace the body of a visible post.
func EditPost(cur realm, id uint64, newBody string) {
	assertNotPaused()
	caller := unsafe.PreviousRealm().Address()

	p := mustGetPost(id)
	if p.Author != caller {
		panic("only the author can edit")
	}
	if p.Deleted {
		panic("cannot edit a deleted post")
	}
	if p.Hidden {
		panic("cannot edit a hidden post")
	}
	if len(newBody) == 0 || len(newBody) > MaxBodyLen {
		panic(ufmt.Sprintf("body must be 1-%d characters", MaxBodyLen))
	}

	p.Body = newBody
	p.EditedAt = runtime.ChainHeight()
	posts.Set(padID(id), p)

	chain.Emit("PostEdited",
		"postId", strconv.FormatUint(id, 10),
		"author", caller.String(),
		"body", newBody,
	)
}

// DeletePost soft-deletes the author's own post: content cleared, dropped from
// every live index (frees render slots immediately — B1), queued for hard-GC
// (B2). Replies stay: they render as replies to an unavailable post.
func DeletePost(cur realm, id uint64) {
	assertNotPaused()
	caller := unsafe.PreviousRealm().Address()

	p := mustGetPost(id)
	if p.Author != caller {
		panic("only the author can delete")
	}
	if p.Deleted {
		panic("post already deleted")
	}

	removeFromLiveIndexes(p)
	p.Deleted = true
	p.Body = ""
	p.MediaCIDs = nil
	posts.Set(padID(id), p)
	tombstones.Set(padID(id), true)

	chain.Emit("PostDeleted",
		"postId", strconv.FormatUint(id, 10),
		"author", caller.String(),
	)
}

// ── Flag pipeline ────────────────────────────────────────────

// FlagPost files a community flag. Guards, in order:
//   - flag rights are EARNED BY PARTICIPATION: the caller must have a
//     firstSeen record (anchored by their first successful CreatePost) at
//     least MinAccountAgeForFlag blocks old. A failed flag cannot anchor age
//     itself — an on-chain abort reverts every write in the tx, so recording
//     firstSeen here and then panicking would revert the record and deadlock
//     pure flaggers; requiring a prior post is the honest, implementable
//     account-age gate (realms cannot query global account age);
//   - one flag per address per post;
//   - per-day flag budget per address (blunts coordinated flag-brigades).
//
// At FlagThreshold unique flags the post auto-hides (reversible via UnhidePost).
func FlagPost(cur realm, id uint64) {
	assertNotPaused()
	caller := unsafe.PreviousRealm().Address()
	now := runtime.ChainHeight()

	if accountAge(caller, now) < MinAccountAgeForFlag {
		panic(ufmt.Sprintf("flagging requires having posted at least %d blocks ago", MinAccountAgeForFlag))
	}

	p := mustGetPost(id)
	if p.Deleted {
		panic("cannot flag a deleted post")
	}
	if p.Hidden {
		panic("post is already hidden")
	}

	// Per-day budget window.
	var fb *flagBudget
	if v, ok := flagSpend.Get(caller.String()); ok {
		fb = v.(*flagBudget)
	} else {
		fb = &flagBudget{DayStartH: now}
	}
	if now-fb.DayStartH >= BlocksPerDay {
		fb.DayStartH = now
		fb.Used = 0
	}
	if fb.Used >= FlagsPerDayBudget {
		panic(ufmt.Sprintf("daily flag budget reached: %d per %d blocks", FlagsPerDayBudget, BlocksPerDay))
	}

	// Unique flaggers per post.
	var flagTree *avl.Tree
	if v, ok := flags.Get(padID(id)); ok {
		flagTree = v.(*avl.Tree)
	} else {
		flagTree = avl.NewTree()
	}
	if _, already := flagTree.Get(caller.String()); already {
		panic("already flagged")
	}
	flagTree.Set(caller.String(), true)
	flags.Set(padID(id), flagTree)

	fb.Used++
	flagSpend.Set(caller.String(), fb)

	p.FlagCount = flagTree.Size()
	wasHidden := p.Hidden
	if p.FlagCount >= FlagThreshold {
		p.Hidden = true
		removeFromLiveIndexes(p)
		// A flag-hidden post is deliberately NOT tombstoned: its node and its
		// `flags` subtree (the flagger set) are retained on purpose as the audit
		// trail the W8.2 moderation board reviews (and UnhidePost needs, to
		// reverse a brigade). It leaves the live indexes (B1 render bounds still
		// hold), so this is bounded, intentional retention — not a leak. Author
		// delete / mod-remove are the paths that tombstone for GC.
	}
	posts.Set(padID(id), p)

	chain.Emit("PostFlagged",
		"postId", strconv.FormatUint(id, 10),
		"flagger", caller.String(),
		"flagCount", strconv.Itoa(p.FlagCount),
	)
	if !wasHidden && p.Hidden {
		chain.Emit("PostAutoHidden", "postId", strconv.FormatUint(id, 10))
	}
}

// ── Reactions (one-per-emoji toggle; open-write, gas is the throttle) ─
//
// A wallet may add each supported emoji at most once per post, and remove it
// again. Reactions carry no content (no DoS/GDPR surface like a post body), so
// there is no account-age gate — the per-(post,emoji,addr) dedup plus the gas
// cost of an on-chain tx are the throttle. Per-emoji COUNTS are aggregated
// off-chain by the indexer from the events below; the realm NEVER scans a
// post's reaction set, so the B1 render bounds are untouched.

// reactionEmojis is the fixed on-chain reaction set. Changing it is a realm
// version bump (redeploy), so it is deliberately small and stable.
var reactionEmojis = []string{"👍", "❤️", "😂", "😮", "😢", "🔥", "🎉", "👀", "🚀"}

func isReactionEmoji(e string) bool {
	for _, r := range reactionEmojis {
		if r == e {
			return true
		}
	}
	return false
}

// reactionSubKey namespaces a reactor's entry within a post's reaction tree.
// The NUL separator cannot appear in a fixed-set emoji or a bech32 address, so
// (emoji, addr) round-trips unambiguously.
func reactionSubKey(emoji string, addr address) string {
	return emoji + "\x00" + addr.String()
}

// HasReacted reports whether addr currently has the given emoji on the post.
// O(log n) point lookup — never a scan.
func HasReacted(id uint64, emoji string, addr address) bool {
	v, ok := reactions.Get(padID(id))
	if !ok {
		return false
	}
	_, exists := v.(*avl.Tree).Get(reactionSubKey(emoji, addr))
	return exists
}

// AddReaction records the caller's emoji reaction. A repeat aborts (rather than
// no-op) so an optimistic client's double-tap cannot silently burn gas twice —
// the client gates the button on HasReacted / indexed state.
func AddReaction(cur realm, id uint64, emoji string) {
	assertNotPaused()
	if !isReactionEmoji(emoji) {
		panic("unsupported reaction")
	}
	caller := unsafe.PreviousRealm().Address()
	now := runtime.ChainHeight()

	p := mustGetPost(id)
	if p.Deleted {
		panic("cannot react to a deleted post")
	}
	if p.Hidden {
		panic("cannot react to a hidden post")
	}
	touchFirstSeen(caller, now)

	var tree *avl.Tree
	if v, ok := reactions.Get(padID(id)); ok {
		tree = v.(*avl.Tree)
	} else {
		tree = avl.NewTree()
	}
	key := reactionSubKey(emoji, caller)
	if _, already := tree.Get(key); already {
		panic("already reacted with this emoji")
	}
	tree.Set(key, true)
	reactions.Set(padID(id), tree)

	chain.Emit("ReactionAdded",
		"postId", strconv.FormatUint(id, 10),
		"emoji", emoji,
		"by", caller.String(),
	)
}

// RemoveReaction removes the caller's emoji reaction (toggle-off). Allowed even
// on a hidden/deleted post so a reactor can always retract; aborts if the caller
// had not reacted with that emoji.
func RemoveReaction(cur realm, id uint64, emoji string) {
	assertNotPaused()
	if !isReactionEmoji(emoji) {
		panic("unsupported reaction")
	}
	caller := unsafe.PreviousRealm().Address()
	mustGetPost(id) // aborts if the post never existed

	v, ok := reactions.Get(padID(id))
	if !ok {
		panic("you have not reacted to this post")
	}
	tree := v.(*avl.Tree)
	key := reactionSubKey(emoji, caller)
	if _, exists := tree.Get(key); !exists {
		panic("you have not reacted with this emoji")
	}
	tree.Remove(key)
	if tree.Size() == 0 {
		reactions.Remove(padID(id)) // GC the empty subtree
	} else {
		reactions.Set(padID(id), tree)
	}

	chain.Emit("ReactionRemoved",
		"postId", strconv.FormatUint(id, 10),
		"emoji", emoji,
		"by", caller.String(),
	)
}

// ── Moderator role (W8.2) ────────────────────────────────────
// The owner grants/revokes moderator addresses that can ModRemovePost /
// UnhidePost. Fast (no owner-multisig-per-post) and reversible; grant/revoke
// stays owner-only. Every mutation is emitted for public audit.

func assertCallerIsOwnerOrModerator() {
	caller := unsafe.PreviousRealm().Address()
	if caller == owner {
		return
	}
	if _, ok := moderators.Get(caller.String()); ok {
		return
	}
	panic("unauthorized: caller " + caller.String() + " is not the owner or a moderator")
}

// IsModerator reports whether addr currently holds the moderator role.
func IsModerator(addr address) bool {
	_, ok := moderators.Get(addr.String())
	return ok
}

// AddModerator grants the moderator role (owner only).
func AddModerator(cur realm, addr address) {
	assertCallerIsOwner()
	if addr == "" {
		panic("address cannot be empty")
	}
	moderators.Set(addr.String(), true)
	chain.Emit("ModeratorAdded", "moderator", addr.String(), "by", owner.String())
}

// RemoveModerator revokes the moderator role (owner only).
func RemoveModerator(cur realm, addr address) {
	assertCallerIsOwner()
	if _, ok := moderators.Get(addr.String()); !ok {
		panic("address is not a moderator")
	}
	moderators.Remove(addr.String())
	chain.Emit("ModeratorRemoved", "moderator", addr.String(), "by", owner.String())
}

// ── Moderation (owner OR moderator; W8.2 hot-key lever) ───────

// ModRemovePost permanently hides a post by moderation. Emits an audited
// ModAction. The node is tombstoned for hard-GC like an author delete.
func ModRemovePost(cur realm, id uint64) {
	assertCallerIsOwnerOrModerator()

	p := mustGetPost(id)
	if !p.Deleted {
		removeFromLiveIndexes(p)
		tombstones.Set(padID(id), true)
	}
	p.Deleted = true
	p.Hidden = true
	p.Body = ""
	p.MediaCIDs = nil
	posts.Set(padID(id), p)

	chain.Emit("ModAction",
		"action", "remove",
		"postId", strconv.FormatUint(id, 10),
		"moderator", unsafe.PreviousRealm().Address().String(),
	)
}

// UnhidePost clears flags and restores a flag-hidden post to the live set.
func UnhidePost(cur realm, id uint64) {
	assertCallerIsOwnerOrModerator()

	p := mustGetPost(id)
	if p.Deleted {
		panic("cannot unhide a deleted post")
	}
	if !p.Hidden {
		panic("post is not hidden")
	}
	p.Hidden = false
	p.FlagCount = 0
	posts.Set(padID(id), p)
	flags.Remove(padID(id))
	addToLiveIndexes(p)

	chain.Emit("ModAction",
		"action", "unhide",
		"postId", strconv.FormatUint(id, 10),
		"moderator", unsafe.PreviousRealm().Address().String(),
	)
}

// ── Tombstone sweep (B2 hard-GC, ported from channels_v2) ────

// SweepTombstones hard-removes up to `limit` soft-deleted posts, reclaiming
// AVL storage so post+delete spam cannot accrete permanent state.
// Permissionless by design (state-shrink hygiene primitive, not a refund
// path). Bounded + idempotent: keep `limit` small (1-10); re-running drains
// the next batch and stops at 0. Returns the number of posts swept.
//
// For a swept post that was a PARENT, its surviving replies' byParent links
// (`padID(parent):padID(child)`) would otherwise be orphaned under an id no
// longer in `posts` — a permanent leak plus a read inconsistency (replies
// still enumerable, getReplyCount() disagreeing). So the sweep range-deletes
// that byParent prefix; the reply posts themselves stay as standalone live
// content (their parent was removed by its own author). Bounded because the
// live reply set per post is capped at MaxRepliesPerPost — but a reply-heavy
// parent makes one sweep step do up to that many removes, so keep `limit`
// small (1) when draining known reply-heavy tombstones.
func SweepTombstones(cur realm, limit int) int {
	assertNotPaused()
	if limit <= 0 {
		return 0
	}

	// Collect the oldest `limit` tombstoned ids (ascending), then mutate —
	// never remove from the tree we are iterating (AVL footgun).
	ids := []uint64{}
	tombstones.Iterate("", "", func(key string, _ interface{}) bool {
		ids = append(ids, idFromPadded(key))
		return len(ids) >= limit
	})

	for _, id := range ids {
		// Drop this parent's remaining child links (if any) so no byParent
		// entry outlives its parent. Collect-then-remove over the prefix.
		prefix := padID(id) + ":"
		childKeys := []string{}
		byParent.Iterate(prefix, prefix+"\xff", func(k string, _ interface{}) bool {
			childKeys = append(childKeys, k)
			return false
		})
		for _, k := range childKeys {
			byParent.Remove(k)
		}

		posts.Remove(padID(id))
		flags.Remove(padID(id))
		replyCount.Remove(padID(id))
		tombstones.Remove(padID(id))
	}

	if len(ids) > 0 {
		chain.Emit("TombstonesSwept", "count", strconv.Itoa(len(ids)))
	}
	return len(ids)
}

// GetTombstoneCount returns how many soft-deleted posts await hard-GC.
func GetTombstoneCount() int { return tombstones.Size() }

// ── JSON reads (vm/qeval; cursor-paginated, O(limit) at any depth) ──

// jsonEscape escapes a string for embedding in a JSON string literal.
func jsonEscape(s string) string {
	var sb strings.Builder
	for _, c := range s {
		switch c {
		case '"':
			sb.WriteString("\\\"")
		case '\\':
			sb.WriteString("\\\\")
		case '\n':
			sb.WriteString("\\n")
		case '\r':
			sb.WriteString("\\r")
		case '\t':
			sb.WriteString("\\t")
		default:
			if c < 0x20 {
				continue // drop raw control chars (ufmt has no \uXXXX support)
			}
			sb.WriteRune(c)
		}
	}
	return sb.String()
}

// postJSON is the qeval read fallback. Note it exposes `mediaCids` (P2) and
// `repostOf` (P1) which the CANONICAL indexed path (chain.Emit → backend →
// feed_rpc → UI) does NOT carry yet — PostCreated emits neither, the proto
// reserves repost_of, and there is no media column. A future dev wiring the
// qeval fallback must not assume those two are plumbed end-to-end.
func postJSON(p *Post) string {
	var media strings.Builder
	media.WriteString("[")
	for i, cid := range p.MediaCIDs {
		if i > 0 {
			media.WriteString(",")
		}
		media.WriteString("\"" + jsonEscape(cid) + "\"")
	}
	media.WriteString("]")

	return ufmt.Sprintf(
		`{"id":%d,"author":"%s","body":"%s","mediaCids":%s,"replyTo":%d,"repostOf":%d,"blockH":%d,"editedAt":%d,"flagCount":%d,"hidden":%s,"deleted":%s,"replies":%d}`,
		p.ID, p.Author.String(), jsonEscape(p.Body), media.String(),
		p.ReplyTo, p.RepostOf, p.BlockH, p.EditedAt, p.FlagCount,
		boolStr(p.Hidden), boolStr(p.Deleted), getReplyCount(p.ID),
	)
}

func boolStr(b bool) string {
	if b {
		return "true"
	}
	return "false"
}

func clampLimit(limit int) int {
	if limit <= 0 {
		return FeedPageSize
	}
	if limit > MaxPageLimit {
		return MaxPageLimit
	}
	return limit
}

// GetPostJSON returns one post (any state — the indexer needs tombstones too).
func GetPostJSON(id uint64) string {
	p, ok := getPost(id)
	if !ok {
		return "null"
	}
	return postJSON(p)
}

// listWindow walks `tree` REVERSE (newest first) starting below cursorKey
// ("" = from the newest), collecting up to limit ids via extract.
func listWindow(tree *avl.Tree, cursorKey string, limit int, extract func(key string) uint64) []uint64 {
	ids := []uint64{}
	count := 0
	tree.ReverseIterate("", cursorKey, func(key string, _ interface{}) bool {
		id := extract(key)
		if id != 0 {
			ids = append(ids, id)
			count++
		}
		return count >= limit
	})
	return ids
}

func idFromPadded(key string) uint64 {
	n, err := strconv.ParseUint(key, 10, 64)
	if err != nil {
		return 0
	}
	return n
}

func idFromComposite(key string) uint64 {
	i := strings.LastIndexByte(key, ':')
	if i < 0 {
		return 0
	}
	return idFromPadded(key[i+1:])
}

func idsToJSON(ids []uint64) string {
	var sb strings.Builder
	sb.WriteString("[")
	for i, id := range ids {
		if i > 0 {
			sb.WriteString(",")
		}
		if p, ok := getPost(id); ok {
			sb.WriteString(postJSON(p))
		}
	}
	sb.WriteString("]")
	return sb.String()
}

// ListFeedJSON returns the newest live posts strictly older than cursor
// (cursor == 0 → from the top). Pass the last id of the previous window as
// the next cursor.
//
// ReverseIterate treats BOTH bounds as inclusive (avl/v0 TraverseInRange), so
// "strictly older than cursor" = end bound padID(cursor-1): ids are integers,
// keys are fixed-width, hence key < padID(cursor) ⟺ key ≤ padID(cursor-1).
func ListFeedJSON(cursor uint64, limit int) string {
	limit = clampLimit(limit)
	cursorKey := ""
	if cursor != 0 {
		cursorKey = padID(cursor - 1)
	}
	return idsToJSON(listWindow(liveFeed, cursorKey, limit, idFromPadded))
}

// ListUserJSON returns a user's newest live posts strictly older than cursor
// (same inclusive-bound rule as ListFeedJSON).
func ListUserJSON(addr string, cursor uint64, limit int) string {
	limit = clampLimit(limit)
	cursorKey := ""
	if cursor != 0 {
		cursorKey = addr + ":" + padID(cursor-1)
	} else {
		// End bound just past every "addr:XXXXXXXXXXXX" key: ':' + 0xff.
		cursorKey = addr + ":\xff"
	}
	ids := []uint64{}
	count := 0
	byAuthor.ReverseIterate(addr+":", cursorKey, func(key string, _ interface{}) bool {
		if id := idFromComposite(key); id != 0 {
			ids = append(ids, id)
			count++
		}
		return count >= limit
	})
	return idsToJSON(ids)
}

// ListRepliesJSON returns a post's live replies, OLDEST first (conversation
// order), starting strictly after cursor (0 → from the beginning).
func ListRepliesJSON(parent uint64, cursor uint64, limit int) string {
	limit = clampLimit(limit)
	start := padID(parent) + ":"
	if cursor != 0 {
		start = parentKey(parent, cursor) + "\x00" // strictly after the cursor child
	}
	ids := []uint64{}
	count := 0
	byParent.Iterate(start, padID(parent)+":\xff", func(key string, _ interface{}) bool {
		if id := idFromComposite(key); id != 0 {
			ids = append(ids, id)
			count++
		}
		return count >= limit
	})
	return idsToJSON(ids)
}

// GetStatsJSON returns realm-level counters (monotonic id is informational —
// no read iterates it).
func GetStatsJSON() string {
	return ufmt.Sprintf(`{"livePosts":%d,"nextPostId":%d,"tombstones":%d,"paused":%s}`,
		liveCount, nextPostID, tombstones.Size(), boolStr(paused))
}

// ── Render (gnoweb human view; bounded — B1) ─────────────────
//
// Paths:
//   ""            → newest window (page 1)
//   page/K        → K-th newest window, K ≤ MaxRenderPage
//   user/ADDR     → ADDR's newest window
//   user/ADDR/K   → K-th window of ADDR's posts
//   post/ID       → one post + its newest reply window
//
// Every page scans at most MaxRenderPage*FeedPageSize live-index keys and
// fetches at most FeedPageSize posts — bounded regardless of feed size or
// churn (deleted/hidden posts are not in the live indexes at all).

func Render(path string) string {
	if path == "" {
		return renderFeedPage(1)
	}
	if strings.HasPrefix(path, "page/") {
		k, err := strconv.ParseUint(strings.TrimPrefix(path, "page/"), 10, 64)
		if err != nil || k == 0 {
			return "# 404\nBad page"
		}
		return renderFeedPage(k)
	}
	if strings.HasPrefix(path, "user/") {
		rest := strings.TrimPrefix(path, "user/")
		addr := rest
		k := uint64(1)
		if i := strings.IndexByte(rest, '/'); i >= 0 {
			addr = rest[:i]
			n, err := strconv.ParseUint(rest[i+1:], 10, 64)
			if err != nil || n == 0 {
				return "# 404\nBad page"
			}
			k = n
		}
		return renderUserPage(addr, k)
	}
	if strings.HasPrefix(path, "post/") {
		id, err := strconv.ParseUint(strings.TrimPrefix(path, "post/"), 10, 64)
		if err != nil {
			return "# 404\nBad post id"
		}
		return renderPost(id)
	}
	return "# 404\nPage not found: " + path
}

// collectPage walks a live index reverse and returns the ids for window k
// (1-based). Scan is bounded: k is capped at MaxRenderPage by callers.
func collectPage(tree *avl.Tree, prefix, endKey string, k uint64) []uint64 {
	skip := (k - 1) * FeedPageSize
	ids := []uint64{}
	seen := uint64(0)
	tree.ReverseIterate(prefix, endKey, func(key string, _ interface{}) bool {
		if seen >= skip {
			var id uint64
			if prefix == "" {
				id = idFromPadded(key)
			} else {
				id = idFromComposite(key)
			}
			if id != 0 {
				ids = append(ids, id)
			}
		}
		seen++
		return len(ids) >= FeedPageSize
	})
	return ids
}

func renderPostLine(sb *strings.Builder, p *Post) {
	sb.WriteString(ufmt.Sprintf("**%s** (block %d)", truncAddr(p.Author), p.BlockH))
	if p.EditedAt != 0 {
		sb.WriteString(" *(edited)*")
	}
	if p.ReplyTo != 0 {
		sb.WriteString(ufmt.Sprintf(" — reply to [post %d](:post/%d)", p.ReplyTo, p.ReplyTo))
	}
	sb.WriteString("\n\n")
	sb.WriteString(sanitizeForRender(p.Body) + "\n\n")
	rc := getReplyCount(p.ID)
	sb.WriteString(ufmt.Sprintf("[permalink](:post/%d) | %d replies\n\n---\n\n", p.ID, rc))
}

func renderFeedPage(k uint64) string {
	if k > MaxRenderPage {
		return ufmt.Sprintf("# Memba Feed\n\n*Pages beyond %d are not rendered — use the JSON cursor API (ListFeedJSON) or the Memba app.*\n", MaxRenderPage)
	}
	var sb strings.Builder
	sb.WriteString("# Memba Feed\n\n")
	sb.WriteString(ufmt.Sprintf("**Live posts:** %d\n\n", liveCount))

	ids := collectPage(liveFeed, "", "", k)
	if len(ids) == 0 {
		sb.WriteString("*No posts on this page.*\n")
		return sb.String()
	}
	for _, id := range ids {
		if p, ok := getPost(id); ok {
			renderPostLine(&sb, p)
		}
	}
	sb.WriteString(ufmt.Sprintf("*page %d — older: `:page/%d`*\n", k, k+1))
	return sb.String()
}

func renderUserPage(addr string, k uint64) string {
	if k > MaxRenderPage {
		return ufmt.Sprintf("# Feed — %s\n\n*Pages beyond %d are not rendered — use ListUserJSON or the Memba app.*\n", addr, MaxRenderPage)
	}
	var sb strings.Builder
	sb.WriteString(ufmt.Sprintf("# Feed — %s\n\n", addr))
	ids := collectPage(byAuthor, addr+":", addr+":\xff", k)
	if len(ids) == 0 {
		sb.WriteString("*No posts on this page.*\n")
		return sb.String()
	}
	for _, id := range ids {
		if p, ok := getPost(id); ok {
			renderPostLine(&sb, p)
		}
	}
	sb.WriteString(ufmt.Sprintf("*page %d — older: `:user/%s/%d`*\n", k, addr, k+1))
	return sb.String()
}

func renderPost(id uint64) string {
	p, ok := getPost(id)
	if !ok {
		return "# 404\nPost not found"
	}
	// Same suppression rule as channels_v2: the direct path must not leak
	// hidden/deleted content.
	if p.Hidden || p.Deleted {
		return "# Post unavailable\n\n*This post has been hidden or removed.*\n"
	}

	var sb strings.Builder
	sb.WriteString(ufmt.Sprintf("# Post %d\n\n", p.ID))
	renderPostLine(&sb, p)

	// Newest reply window only (fixed size); full thread = JSON cursor API.
	rc := getReplyCount(p.ID)
	if rc > 0 {
		sb.WriteString("## Replies\n\n")
		if rc > FeedPageSize {
			sb.WriteString(ufmt.Sprintf("*Showing the %d newest of %d — full thread via ListRepliesJSON or the app.*\n\n", FeedPageSize, rc))
		}
		ids := collectPage(byParent, padID(p.ID)+":", padID(p.ID)+":\xff", 1)
		// collectPage walks reverse (newest first); show oldest→newest.
		for i := len(ids) - 1; i >= 0; i-- {
			if r, ok := getPost(ids[i]); ok {
				renderPostLine(&sb, r)
			}
		}
	}
	return sb.String()
}

// ── Shared render helpers (ported verbatim from channels_v2) ─

func truncAddr(addr address) string {
	s := string(addr)
	if len(s) > 13 {
		return s[:10] + "..."
	}
	return s
}

// sanitizeForRender strips markdown-sensitive characters to prevent injection.
func sanitizeForRender(s string) string {
	var out strings.Builder
	for _, c := range s {
		switch c {
		case '[', ']', '(', ')', '#', '*', '`', '!', '<', '>', '|', '\\', '_', '~', '\n', '\r', '\t':
			continue
		default:
			out.WriteRune(c)
		}
	}
	return out.String()
}

package memba_feedback_v2

// memba_dao_channels — Social feed realm for MembaDAO.
//
// Provides Discord-like channels with threads, replies, and moderation.
// The Render() output MUST match the regex patterns in parser.ts (frontend).
//
// Render() contract (from parser.ts):
//
//   Home — Render(""):
//     # BoardName
//     description
//     ## Channels
//     - [#name](:_channel/name) 📢 (N threads)
//
//   Channel — Render("channelName"):
//     # #channelName
//     ### [Title](:channel/id)
//     by g1addr... | N replies | block H
//
//   Thread — Render("channel/id"):
//     # Title
//     body
//     ---
//     *Posted by g1addr at block H*
//     ## Replies
//     **g1addr...** (block H)
//     reply body
//     ---
//
//   ACL — Render("__acl/channel"):
//     read:role1,role2
//     write:role1,role2,role3
//     type:text
//
// Security:
//   - All write operations require membership (AddMember by owner)
//   - PostThread/PostReply check caller's roles against channel WriteRoles
//   - CreateChannel/RemoveThread restricted to owner only
//   - FlagThread requires membership (prevents sybil flagging by non-members)
//   - EditThread/DeleteThread require membership + original author check
//
// Moderation: flag → threshold (3) → auto-hide → DAO vote → remove

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/samcrew/avl"
	"gno.land/p/nt/ufmt/v0"
)

// ── Constants ────────────────────────────────────────────────

const (
	MaxPostLen        = 5000
	MaxTitleLen       = 200
	MaxChannels       = 20
	MaxThreadsPerChan = 500
	FlagThreshold     = 3 // flags before auto-hide

	// AAA-1 B1 — render-DoS bounds for replies (mirrors MaxThreadsPerChan).
	// renderThread must never iterate the monotonic reply counter (post+delete
	// reply spam would inflate it without bound → unbounded render scan →
	// thread permanently unrenderable past maxGasQuery). The live-reply index
	// (replyLive/replyLiveIDs) caps the live set, and renderThread paginates a
	// fixed window over it, so render cost is bounded regardless of churn.
	MaxRepliesPerThread = 500 // live (non-deleted) replies per thread
	ReplyPageSize       = 50  // replies rendered per page
)

// ── Types ────────────────────────────────────────────────────

type ChannelType string

const (
	ChannelText          ChannelType = "text"
	ChannelAnnouncements ChannelType = "announcements"
	ChannelReadonly      ChannelType = "readonly"
)

type Channel struct {
	Name        string
	Description string
	Type        ChannelType
	Archived    bool
	ReadRoles   []string // roles that can read
	WriteRoles  []string // roles that can write
}

type Thread struct {
	ID        uint64
	Channel   string
	Title     string
	Body      string
	Author    address
	BlockH    int64
	Edited    bool
	EditedAt  int64
	Deleted   bool
	FlagCount int
	Hidden    bool
}

type Reply struct {
	ID       uint64
	ThreadID uint64
	Channel  string
	Body     string
	Author   address
	BlockH   int64
	Edited   bool
}

// ── State ────────────────────────────────────────────────────

var (
	channels      *avl.Tree // name -> *Channel
	threads       *avl.Tree // "channel/id" -> *Thread
	replies       *avl.Tree // "channel/threadId/replyId" -> *Reply
	threadCount   *avl.Tree // channel -> uint64 (next thread ID, monotonic)
	threadLive    *avl.Tree // channel -> uint64 (currently live (non-deleted) threads)
	threadLiveIDs *avl.Tree // channel -> []uint64 (live thread IDs, ascending) — bounds renderChannel
	replyCount    *avl.Tree // "channel/threadId" -> uint64 (next reply ID, monotonic)
	replyLive     *avl.Tree // "channel/threadId" -> uint64 (currently live (non-deleted) replies)
	replyLiveIDs  *avl.Tree // "channel/threadId" -> []uint64 (live reply IDs, ascending) — bounds renderThread
	threadTomb    *avl.Tree // channel -> []uint64 (soft-deleted thread IDs awaiting hard-GC via SweepTombstones) — B2
	flags         *avl.Tree // "channel/threadId" -> *avl.Tree (flagger addr -> bool)
	channelOrder  []string  // ordered channel names

	// Membership: address -> comma-separated roles (e.g., "admin,dev")
	members *avl.Tree
	membershipRevision uint64
	paused  bool
	// owner is the publishing transaction's signer, captured at package load (on
	// gnoland-1 the samcrew namespace multisig, the stamped creator at enable
	// time). pendingOwner is the staged successor of a two-step handoff, or empty.
	owner        = unsafe.OriginCaller()
	pendingOwner address
)

func init() {
	channels = avl.NewTree()
	threads = avl.NewTree()
	replies = avl.NewTree()
	threadCount = avl.NewTree()
	threadLive = avl.NewTree()
	threadLiveIDs = avl.NewTree()
	replyCount = avl.NewTree()
	replyLive = avl.NewTree()
	replyLiveIDs = avl.NewTree()
	threadTomb = avl.NewTree()
	flags = avl.NewTree()
	channelOrder = []string{}
	members = avl.NewTree()
	members.Set(owner.String(), "admin")

	// Public feedback board: anyone can post in the open channels (WriteRoles
	// "*"); the frontend reads the "general" channel. "announcements" stays
	// admin-write-only for official responses. Read is open everywhere.
	addChannel("general", "Community feedback — anyone can post", ChannelText,
		[]string{"*"}, []string{"*"})
	addChannel("feature-requests", "Propose and discuss new features", ChannelText,
		[]string{"*"}, []string{"*"})
	addChannel("bugs", "Report bugs and issues", ChannelText,
		[]string{"*"}, []string{"*"})
	addChannel("announcements", "Official Memba announcements — admin-write-only", ChannelAnnouncements,
		[]string{"*"}, []string{"admin"})
}

// ── Channel Management ───────────────────────────────────────

func addChannel(name, description string, ctype ChannelType, readRoles, writeRoles []string) {
	ch := &Channel{
		Name:        name,
		Description: description,
		Type:        ctype,
		Archived:    false,
		ReadRoles:   readRoles,
		WriteRoles:  writeRoles,
	}
	channels.Set(name, ch)
	threadCount.Set(name, uint64(0))
	threadLive.Set(name, uint64(0))
	channelOrder = append(channelOrder, name)
}

// ── Membership Management ───────────────────────────────────

// AddMember adds an address with specified roles. Only the owner can call this.
// roles is a comma-separated list (e.g., "admin,dev" or "member").
func AddMember(cur realm, addr address, roles string) {
	assertCallerIsOwner()
	if addr == "" {
		panic("address cannot be empty")
	}
	if len(roles) == 0 {
		panic("roles cannot be empty")
	}
	if !isValidRoles(roles) {
		panic("invalid roles: must be comma-separated alphanumeric only")
	}
	members.Set(addr.String(), roles)
	membershipRevision++

	chain.Emit("MemberAdded",
		"address", addr.String(),
		"roles", roles,
	)
}

// RemoveMember removes an address from the membership. Only the owner can call this.
func RemoveMember(cur realm, addr address) {
	assertCallerIsOwner()
	if addr == owner {
		panic("cannot remove owner")
	}
	if _, exists := members.Get(addr.String()); !exists {
		panic("address is not a member: " + addr.String())
	}
	members.Remove(addr.String())
	membershipRevision++

	chain.Emit("MemberRemoved", "address", addr.String())
}

// UpdateMemberRoles updates the roles for an existing member. Only the owner can call this.
func UpdateMemberRoles(cur realm, addr address, newRoles string) {
	assertCallerIsOwner()
	if _, exists := members.Get(addr.String()); !exists {
		panic("address is not a member: " + addr.String())
	}
	if len(newRoles) == 0 {
		panic("roles cannot be empty")
	}
	if !isValidRoles(newRoles) {
		panic("invalid roles: must be comma-separated alphanumeric only")
	}
	members.Set(addr.String(), newRoles)
	membershipRevision++

	chain.Emit("MemberRolesUpdated", "address", addr.String(), "roles", newRoles)
}

// TransferOwnership stages a successor owner. Nothing moves until that address
// calls AcceptOwnership with its own transaction, so ownership can never land on
// an address that cannot act. A later call replaces the staged address;
// CancelOwnershipTransfer withdraws it.
func TransferOwnership(cur realm, newOwner address) {
	assertCallerIsOwner()
	if newOwner == "" {
		panic("address cannot be empty")
	}
	if !newOwner.IsValid() {
		panic("invalid address: " + newOwner.String())
	}
	if newOwner == owner {
		panic("new owner is the same as current owner")
	}
	pendingOwner = newOwner
	chain.Emit("OwnershipTransferStarted", "pending", newOwner.String())
}

// CancelOwnershipTransfer withdraws a staged handoff. Owner only.
func CancelOwnershipTransfer(cur realm) {
	assertCallerIsOwner()
	if pendingOwner == "" {
		panic("no pending ownership transfer")
	}
	cancelled := pendingOwner
	pendingOwner = ""
	chain.Emit("OwnershipTransferCancelled", "pending", cancelled.String())
}

// AcceptOwnership completes the handoff. Only the staged pendingOwner may call
// it. The new owner gets "admin" added to their existing roles (not
// overwritten); the old owner is demoted from "admin" to their other roles, or
// to "member" when none remain.
func AcceptOwnership(cur realm) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	caller := cur.Previous().Address()
	if pendingOwner == "" || caller != pendingOwner {
		panic("unauthorized: caller " + caller.String() + " is not the pending owner")
	}
	prevOwner := owner
	// Preserve existing roles for the new owner, ensure they have admin
	existingRoles := GetMemberRoles(caller)
	if existingRoles == "" {
		members.Set(caller.String(), "admin")
	} else if !hasRole(caller, "admin") {
		members.Set(caller.String(), existingRoles+",admin")
	}
	// Remove "admin" from the old owner's roles, keep other roles.
	// If no roles remain, set to "member".
	oldRoles := GetMemberRoles(prevOwner)
	var kept []string
	for _, r := range strings.Split(oldRoles, ",") {
		r = strings.TrimSpace(r)
		if r != "admin" && r != "" {
			kept = append(kept, r)
		}
	}
	if len(kept) == 0 {
		members.Set(prevOwner.String(), "member")
	} else {
		members.Set(prevOwner.String(), strings.Join(kept, ","))
	}
	owner = caller
	pendingOwner = ""
	membershipRevision++

	chain.Emit("OwnershipTransferred",
		"previousOwner", prevOwner.String(),
		"newOwner", caller.String(),
	)
}

// GetPendingOwner returns the staged successor, or the empty address.
func GetPendingOwner() address { return pendingOwner }

// SyncMembers allows the owner to batch-sync membership from the DAO.
// addresses and rolesList are comma-separated, with roles pipe-delimited per address.
// Example: SyncMembers("g1a,g1b", "admin,dev|member")
func SyncMembers(cur realm, addresses string, rolesList string) {
	assertCallerIsOwner()
	addrs := strings.Split(addresses, ",")
	roles := strings.Split(rolesList, "|")
	if len(addrs) != len(roles) {
		panic("addresses and roles count mismatch")
	}
	synced := 0
	for i, addr := range addrs {
		addr = strings.TrimSpace(addr)
		if addr == "" {
			continue
		}
		role := strings.TrimSpace(roles[i])
		if !isValidRoles(role) {
			panic("invalid roles in entry " + strconv.Itoa(i))
		}
		members.Set(addr, role)
		synced++
	}
	membershipRevision++

	chain.Emit("MembersSynced", "count", strconv.Itoa(synced))
}

// PurgeNonMembers removes all members not in the provided comma-separated list.
// The owner is never purged.
func PurgeNonMembers(cur realm, keepAddresses string) {
	assertCallerIsOwner()
	keep := make(map[string]bool)
	for _, addr := range strings.Split(keepAddresses, ",") {
		keep[strings.TrimSpace(addr)] = true
	}
	keep[owner.String()] = true // owner is never purged
	var toRemove []string
	members.Iterate("", "", func(key string, _ interface{}) bool {
		if !keep[key] {
			toRemove = append(toRemove, key)
		}
		return false
	})
	for _, addr := range toRemove {
		members.Remove(addr)
	}
	membershipRevision++

	chain.Emit("MembersPurged", "count", strconv.Itoa(len(toRemove)))
}

// IsMember returns whether an address is a member.
func IsMember(addr address) bool {
	_, exists := members.Get(addr.String())
	return exists
}

// GetMemberRoles returns the roles for a member (comma-separated) or empty string.
func GetMemberRoles(addr address) string {
	val, exists := members.Get(addr.String())
	if !exists {
		return ""
	}
	return val.(string)
}

func GetMemberCount() int { return members.Size() }
func GetMembershipRevision() uint64 { return membershipRevision }

// GetOwner returns the current realm owner address.
func GetOwner() address {
	return owner
}

// ── Emergency Pause ────────────────────────────────────────
//
// Pause policy (AAA-1 B3 — one policy, enforced everywhere):
//   While paused, every member-facing content write is blocked via
//   assertNotPaused() — PostThread, PostReply, EditThread, DeleteThread/Reply,
//   FlagThread, RemoveThread/Reply, and SweepTombstones.
//
//   Owner-only governance (AddMember/RemoveMember/UpdateMemberRoles/SyncMembers/
//   PurgeNonMembers/TransferOwnership/CreateChannel) is intentionally NOT gated:
//   pause halts user activity during an incident, but the owner must stay able to
//   fix membership/ownership while paused. This realm holds no funds, so there is
//   no value-exit exemption to carve out.

func assertNotPaused() {
	if paused {
		panic("realm is paused — emergency maintenance")
	}
}

func PauseRealm(cur realm) {
	assertCallerIsOwner()
	paused = true
	chain.Emit("RealmPaused", "by", owner.String())
}

func UnpauseRealm(cur realm) {
	assertCallerIsOwner()
	paused = false
	chain.Emit("RealmUnpaused", "by", owner.String())
}

func IsPaused() bool { return paused }

// Value-only readback lets a fixed DAO action verify exact channel creation.
func GetChannelState(name string) (int, bool, string, string, string, string) {
	value, exists := channels.Get(name)
	if !exists { return len(channelOrder), false, "", "", "", "" }
	channel := value.(*Channel)
	return len(channelOrder), true, channel.Description, string(channel.Type), strings.Join(channel.ReadRoles, ","), strings.Join(channel.WriteRoles, ",")
}

// ── Channel Management ───────────────────────────────────────

// CreateChannel adds a new channel. Only the owner (admin) can create channels.
func CreateChannel(cur realm, name, description string, ctype string) {
	assertCallerIsOwner()

	if len(channelOrder) >= MaxChannels {
		panic(ufmt.Sprintf("max channels reached: %d", MaxChannels))
	}
	if _, exists := channels.Get(name); exists {
		panic("channel already exists: " + name)
	}
	if !isValidChannelName(name) {
		panic("invalid channel name: must be 1-50 lowercase alphanumeric characters or hyphens, no leading underscore")
	}

	ct := ChannelText
	switch ctype {
	case "announcements":
		ct = ChannelAnnouncements
	case "readonly":
		ct = ChannelReadonly
	}

	addChannel(name, description, ct,
		[]string{"admin", "dev", "ops", "member"},
		[]string{"admin", "dev", "ops", "member"})

	chain.Emit("ChannelCreated", "name", name, "type", string(ct))
}

// ── Post Management ─────────────────────────────────────────

// PostThread creates a new thread in a channel.
// Caller must be a member with a role listed in the channel's WriteRoles.
func PostThread(cur realm, channel, title, body string) uint64 {
	assertNotPaused()
	caller := unsafe.PreviousRealm().Address()

	// Validate membership and channel write access
	ch := getChannel(channel)
	assertCallerHasWriteAccess(caller, ch)
	if ch.Archived {
		panic("channel is archived")
	}
	// Cap on LIVE (non-deleted) threads so deleted threads free up slots.
	if getLiveThreadCount(channel) >= MaxThreadsPerChan {
		panic(ufmt.Sprintf("channel live thread limit reached: %d — delete old threads to make room", MaxThreadsPerChan))
	}
	if len(title) == 0 || len(title) > MaxTitleLen {
		panic(ufmt.Sprintf("title must be 1-%d characters", MaxTitleLen))
	}
	if len(body) > MaxPostLen {
		panic(ufmt.Sprintf("body too long: %d/%d chars", len(body), MaxPostLen))
	}

	// Get next ID
	nextID := getThreadCount(channel)
	key := channel + "/" + strconv.FormatUint(nextID, 10)

	t := &Thread{
		ID:      nextID,
		Channel: channel,
		Title:   title,
		Body:    body,
		Author:  caller,
		BlockH:  runtime.ChainHeight(),
	}
	threads.Set(key, t)
	threadCount.Set(channel, nextID+1)
	threadLive.Set(channel, getLiveThreadCount(channel)+1)
	addLiveThreadID(channel, nextID)
	replyCount.Set(key, uint64(0))

	chain.Emit("ThreadPosted",
		"channel", channel,
		"threadId", strconv.FormatUint(nextID, 10),
		"author", caller.String(),
	)

	return nextID
}

// PostReply adds a reply to a thread.
// Caller must be a member with a role listed in the channel's WriteRoles.
func PostReply(cur realm, channel string, threadID uint64, body string) {
	assertNotPaused()
	caller := unsafe.PreviousRealm().Address()

	// Validate membership and channel write access
	ch := getChannel(channel)
	assertCallerHasWriteAccess(caller, ch)

	threadKey := channel + "/" + strconv.FormatUint(threadID, 10)
	tval, texists := threads.Get(threadKey)
	if !texists {
		panic("thread not found")
	}
	thread := tval.(*Thread)
	if thread.Deleted {
		panic("cannot reply to a deleted thread")
	}
	if thread.Hidden {
		panic("cannot reply to a hidden thread")
	}

	if len(body) == 0 || len(body) > MaxPostLen {
		panic(ufmt.Sprintf("reply must be 1-%d characters", MaxPostLen))
	}

	// B1: bound the LIVE reply set so renderThread stays under the gas budget.
	// Deleting replies frees slots (mirrors MaxThreadsPerChan / getLiveThreadCount).
	if getLiveReplyCount(threadKey) >= MaxRepliesPerThread {
		panic(ufmt.Sprintf("thread reply limit reached: %d — older replies must be removed", MaxRepliesPerThread))
	}

	nextReplyID := getReplyCount(threadKey)
	replyKey := threadKey + "/" + strconv.FormatUint(nextReplyID, 10)

	r := &Reply{
		ID:       nextReplyID,
		ThreadID: threadID,
		Channel:  channel,
		Body:     body,
		Author:   caller,
		BlockH:   runtime.ChainHeight(),
	}
	replies.Set(replyKey, r)
	replyCount.Set(threadKey, nextReplyID+1)
	// Track the live reply so renderThread iterates only live IDs (bounded set),
	// never the monotonic counter.
	addLiveReplyID(threadKey, nextReplyID)
	replyLive.Set(threadKey, getLiveReplyCount(threadKey)+1)

	chain.Emit("ReplyPosted",
		"channel", channel,
		"threadId", strconv.FormatUint(threadID, 10),
		"replyId", strconv.FormatUint(nextReplyID, 10),
		"author", caller.String(),
	)
}

// dropReply hard-removes a reply: deletes the node (storage reclaimed — B2),
// drops it from the live index, and decrements the live count. Shared by
// DeleteReply and RemoveReply. renderThread only walks the live index, so a
// removed reply is never looked up — no tombstone is needed.
func dropReply(threadKey, replyKey string, replyID uint64) {
	replies.Remove(replyKey)
	removeLiveReplyID(threadKey, replyID)
	if live := getLiveReplyCount(threadKey); live > 0 {
		replyLive.Set(threadKey, live-1)
	}
}

// DeleteReply lets the reply's author delete it. Caller must be a member and the
// original author. The reply node is hard-removed (B2 state-shrink) and a slot is
// freed under MaxRepliesPerThread (B1).
func DeleteReply(cur realm, channel string, threadID, replyID uint64) {
	assertNotPaused()
	caller := unsafe.PreviousRealm().Address()
	assertCallerIsMember(caller)

	threadKey := channel + "/" + strconv.FormatUint(threadID, 10)
	replyKey := threadKey + "/" + strconv.FormatUint(replyID, 10)
	rval, exists := replies.Get(replyKey)
	if !exists {
		panic("reply not found")
	}
	if rval.(*Reply).Author != caller {
		panic("only the author can delete")
	}

	dropReply(threadKey, replyKey, replyID)

	chain.Emit("ReplyDeleted",
		"channel", channel,
		"threadId", strconv.FormatUint(threadID, 10),
		"replyId", strconv.FormatUint(replyID, 10),
		"author", caller.String(),
	)
}

// RemoveReply permanently removes a reply (moderation — admin role only). Hard-
// removes the node like DeleteReply, bounding renderThread (B1) + reclaiming
// storage (B2).
func RemoveReply(cur realm, channel string, threadID, replyID uint64) {
	assertCallerIsAdminRole()
	caller := unsafe.PreviousRealm().Address()

	threadKey := channel + "/" + strconv.FormatUint(threadID, 10)
	replyKey := threadKey + "/" + strconv.FormatUint(replyID, 10)
	if _, exists := replies.Get(replyKey); !exists {
		panic("reply not found")
	}

	dropReply(threadKey, replyKey, replyID)

	chain.Emit("ReplyRemoved",
		"channel", channel,
		"threadId", strconv.FormatUint(threadID, 10),
		"replyId", strconv.FormatUint(replyID, 10),
		"admin", caller.String(),
	)
}

// EditThread allows the original author to edit their thread. Caller must be a member.
func EditThread(cur realm, channel string, threadID uint64, newBody string) {
	assertNotPaused()
	caller := unsafe.PreviousRealm().Address()
	assertCallerIsMember(caller)

	threadKey := channel + "/" + strconv.FormatUint(threadID, 10)
	val, exists := threads.Get(threadKey)
	if !exists {
		panic("thread not found")
	}

	t := val.(*Thread)
	if t.Author != caller {
		panic("only the author can edit")
	}
	if t.Deleted {
		panic("cannot edit a deleted thread")
	}
	if t.Hidden {
		panic("cannot edit a hidden thread")
	}
	if len(newBody) > MaxPostLen {
		panic("body too long")
	}

	t.Body = newBody
	t.Edited = true
	t.EditedAt = runtime.ChainHeight()
	threads.Set(threadKey, t)

	chain.Emit("ThreadEdited",
		"channel", channel,
		"threadId", strconv.FormatUint(threadID, 10),
		"author", caller.String(),
	)
}

// DeleteThread soft-deletes a thread (marks as deleted). Caller must be a member and the original author.
func DeleteThread(cur realm, channel string, threadID uint64) {
	assertNotPaused()
	caller := unsafe.PreviousRealm().Address()
	assertCallerIsMember(caller)

	threadKey := channel + "/" + strconv.FormatUint(threadID, 10)
	val, exists := threads.Get(threadKey)
	if !exists {
		panic("thread not found")
	}

	t := val.(*Thread)
	if t.Author != caller {
		panic("only the author can delete")
	}
	if t.Deleted {
		panic("thread already deleted")
	}

	t.Deleted = true
	t.Title = "[Deleted]"
	t.Body = ""
	threads.Set(threadKey, t)
	// Free a slot for new threads
	live := getLiveThreadCount(channel)
	if live > 0 {
		threadLive.Set(channel, live-1)
	}
	removeLiveThreadID(channel, threadID)
	enqueueThreadTomb(channel, threadID) // B2: queue for hard-GC via SweepTombstones

	chain.Emit("ThreadDeleted",
		"channel", channel,
		"threadId", strconv.FormatUint(threadID, 10),
		"author", caller.String(),
	)
}

// ── Moderation ──────────────────────────────────────────────

// FlagThread flags a thread for moderation review.
// After FlagThreshold flags, the thread is auto-hidden.
// Caller must be a member (any role) to flag content.
func FlagThread(cur realm, channel string, threadID uint64) {
	assertNotPaused()
	caller := unsafe.PreviousRealm().Address()
	assertCallerIsMember(caller)
	threadKey := channel + "/" + strconv.FormatUint(threadID, 10)

	val, exists := threads.Get(threadKey)
	if !exists {
		panic("thread not found")
	}

	t := val.(*Thread)
	if t.Deleted {
		panic("cannot flag a deleted thread")
	}
	if t.Hidden {
		panic("thread is already hidden")
	}

	// Track unique flaggers
	var flagTree *avl.Tree
	if fval, fexists := flags.Get(threadKey); fexists {
		flagTree = fval.(*avl.Tree)
	} else {
		flagTree = avl.NewTree()
	}

	if _, already := flagTree.Get(caller.String()); already {
		panic("already flagged")
	}
	flagTree.Set(caller.String(), true)
	flags.Set(threadKey, flagTree)

	// Update thread flag count and auto-hide.
	// Dynamic threshold: max(FlagThreshold, 5% of members), scales with DAO size.
	t.FlagCount = flagTree.Size()
	dynamicThreshold := FlagThreshold
	fivePct := members.Size() / 20
	if fivePct > dynamicThreshold {
		dynamicThreshold = fivePct
	}
	wasHidden := t.Hidden
	if t.FlagCount >= dynamicThreshold {
		t.Hidden = true
	}
	threads.Set(threadKey, t)

	chain.Emit("ThreadFlagged",
		"channel", channel,
		"threadId", strconv.FormatUint(threadID, 10),
		"flagger", caller.String(),
		"flagCount", strconv.Itoa(t.FlagCount),
	)
	if !wasHidden && t.Hidden {
		chain.Emit("ThreadAutoHidden",
			"channel", channel,
			"threadId", strconv.FormatUint(threadID, 10),
		)
	}
}

// UnhideThread allows the owner or an admin to clear flags and un-hide a thread.
func UnhideThread(cur realm, channel string, threadID uint64) {
	assertCallerIsAdminRole()
	caller := unsafe.PreviousRealm().Address()
	threadKey := channel + "/" + strconv.FormatUint(threadID, 10)

	val, exists := threads.Get(threadKey)
	if !exists {
		panic("thread not found")
	}
	t := val.(*Thread)
	t.Hidden = false
	t.FlagCount = 0
	threads.Set(threadKey, t)
	// Clear flag tree
	flags.Remove(threadKey)

	chain.Emit("ThreadUnhidden",
		"channel", channel,
		"threadId", strconv.FormatUint(threadID, 10),
		"admin", caller.String(),
	)
}

// RemoveThread permanently removes a thread (moderation action — admin role only).
func RemoveThread(cur realm, channel string, threadID uint64) {
	assertCallerIsAdminRole()
	caller := unsafe.PreviousRealm().Address()
	threadKey := channel + "/" + strconv.FormatUint(threadID, 10)
	val, exists := threads.Get(threadKey)
	if !exists {
		panic("thread not found")
	}

	t := val.(*Thread)
	if !t.Deleted {
		live := getLiveThreadCount(channel)
		if live > 0 {
			threadLive.Set(channel, live-1)
		}
		removeLiveThreadID(channel, threadID)
		enqueueThreadTomb(channel, threadID) // B2: queue for hard-GC (skip if already tombstoned)
	}
	t.Deleted = true
	t.Hidden = true
	t.Title = "[Removed by moderation]"
	t.Body = ""
	threads.Set(threadKey, t)

	chain.Emit("ThreadRemoved",
		"channel", channel,
		"threadId", strconv.FormatUint(threadID, 10),
		"admin", caller.String(),
	)
}

// SweepTombstones hard-removes up to `limit` soft-deleted threads in a channel
// (and all of their remaining reply state), reclaiming AVL storage so that
// post+delete spam can no longer accrete permanent state (B2).
//
// Permissionless GC by design: anyone may call it. Released storage deposits go
// to the calling tx per the chain's deposit policy (an explicit caller bounty);
// on restricted-denom chains (e.g. test12/test13 `restricted_denoms=["ugnot"]`)
// they route to the StorageFeeCollector instead — so this is a state-shrink/
// hygiene primitive, not a user-refund path (see plan B2 / Q11).
//
// Bounded + idempotent: each soft-deleted thread holds at most
// MaxRepliesPerThread reply nodes, so keep `limit` small (1–5) to stay well
// within block gas; re-running drains the next batch and stops at 0.
// Returns the number of threads swept.
func SweepTombstones(cur realm, channel string, limit int) int {
	assertNotPaused()
	if limit <= 0 {
		return 0
	}

	tomb := getThreadTomb(channel)
	n := limit
	if n > len(tomb) {
		n = len(tomb)
	}

	for i := 0; i < n; i++ {
		threadKey := channel + "/" + strconv.FormatUint(tomb[i], 10)
		// Collect-then-remove: read the live reply IDs (a stored slice) and remove
		// each reply node — we never iterate the tree we mutate (AVL footgun).
		for _, rid := range getLiveReplyIDs(threadKey) {
			replies.Remove(threadKey + "/" + strconv.FormatUint(rid, 10))
		}
		replyLiveIDs.Remove(threadKey)
		replyLive.Remove(threadKey)
		replyCount.Remove(threadKey)
		flags.Remove(threadKey)
		threads.Remove(threadKey)
	}

	// Drop the processed prefix; copy the tail into a fresh slice to avoid aliasing.
	remaining := append([]uint64{}, tomb[n:]...)
	if len(remaining) == 0 {
		threadTomb.Remove(channel)
	} else {
		threadTomb.Set(channel, remaining)
	}

	if n > 0 {
		chain.Emit("TombstonesSwept",
			"channel", channel,
			"count", strconv.Itoa(n),
		)
	}
	return n
}

// GetTombstoneCount returns how many soft-deleted threads in a channel are still
// awaiting hard-GC (read-only; lets ops/indexers decide when to call SweepTombstones).
func GetTombstoneCount(channel string) int {
	return len(getThreadTomb(channel))
}

// ── Render ───────────────────────────────────────────────────
// CRITICAL: Output format MUST match parser.ts regex patterns.

func Render(path string) string {
	if path == "" {
		return renderHome()
	}
	if strings.HasPrefix(path, "__acl/") {
		channelName := strings.TrimPrefix(path, "__acl/")
		return renderACL(channelName)
	}
	if strings.HasPrefix(path, "__member/") {
		addr := strings.TrimPrefix(path, "__member/")
		roles := GetMemberRoles(address(addr))
		if roles == "" {
			return "not found"
		}
		return "roles:" + roles
	}
	if strings.HasPrefix(path, "_channel/") {
		channelName := strings.TrimPrefix(path, "_channel/")
		return renderChannel(channelName)
	}

	// Check for "channel/threadId" pattern, optionally with a "?page=N" suffix
	// for reply pagination (B1).
	parts := strings.SplitN(path, "/", 2)
	if len(parts) == 2 {
		idPart := parts[1]
		page := uint64(0)
		if qi := strings.IndexByte(idPart, '?'); qi >= 0 {
			page = parsePageQuery(idPart[qi+1:])
			idPart = idPart[:qi]
		}
		threadID, err := strconv.ParseUint(idPart, 10, 64)
		if err == nil {
			return renderThread(parts[0], threadID, page)
		}
	}

	// Try as channel name directly
	if _, exists := channels.Get(path); exists {
		return renderChannel(path)
	}

	return "# 404\nPage not found: " + path
}

// renderHome produces the board home page.
// Format: parser.ts parseBoardHome() expects:
//   - [#name](:_channel/name) 📢 (N threads)
func renderHome() string {
	var sb strings.Builder
	sb.WriteString("# MembaDAO Channels\n\n")
	sb.WriteString("Community discussion channels for the Memba ecosystem.\n\n")
	sb.WriteString(ufmt.Sprintf("**Owner:** %s | **Members:** %d\n\n", owner, members.Size()))
	sb.WriteString("## Channels\n\n")

	for _, name := range channelOrder {
		val, exists := channels.Get(name)
		if !exists {
			continue
		}
		ch := val.(*Channel)
		if ch.Archived {
			continue
		}

		count := getThreadCount(name)
		typeIcon := ""
		switch ch.Type {
		case ChannelAnnouncements:
			typeIcon = " 📢"
		case ChannelReadonly:
			typeIcon = " 🔒"
		}

		sb.WriteString(ufmt.Sprintf("- [#%s](:_channel/%s)%s (%d threads)\n",
			name, name, typeIcon, count))
	}

	return sb.String()
}

// renderChannel produces a channel's thread list.
// Format: parser.ts parseThreadList() expects:
//   ### [Title](:channel/id)
//   by g1addr... | N replies | block H
func renderChannel(channelName string) string {
	if _, exists := channels.Get(channelName); !exists {
		return "# 404\nChannel not found: " + channelName
	}

	var sb strings.Builder
	sb.WriteString(ufmt.Sprintf("# #%s\n\n", channelName))

	// Iterate the LIVE thread-ID index (bounded by getLiveThreadCount), newest
	// first. Never loop over the monotonic threadCount — a post+delete spam
	// loop inflates it without bound (gas DoS); deleted IDs are not in this index.
	ids := getLiveThreadIDs(channelName)
	if len(ids) == 0 {
		sb.WriteString("*No threads yet. Be the first to post!*\n")
		return sb.String()
	}

	for i := len(ids) - 1; i >= 0; i-- {
		threadKey := channelName + "/" + strconv.FormatUint(ids[i], 10)
		val, exists := threads.Get(threadKey)
		if !exists {
			continue
		}
		t := val.(*Thread)
		if t.Hidden || t.Deleted {
			continue
		}

		// Count live (non-deleted) replies — matches what renderThread shows.
		rCount := getLiveReplyCount(threadKey)
		authorStr := truncAddr(t.Author)

		sb.WriteString(ufmt.Sprintf("### [%s](:%s/%d)\n", sanitizeForRender(t.Title), channelName, t.ID))
		sb.WriteString(ufmt.Sprintf("by %s | %d replies | block %d\n\n", authorStr, rCount, t.BlockH))
	}

	return sb.String()
}

// renderThread produces a single thread with replies.
// Format: parser.ts parseThreadDetail() expects:
//   # Title
//   body
//   ---
//   *Posted by g1addr at block H* *(edited at block M)*
//   ## Replies
//   **g1addr...** (block H) *(edited)*
//   reply body
//   ---
func renderThread(channelName string, threadID, page uint64) string {
	threadKey := channelName + "/" + strconv.FormatUint(threadID, 10)
	val, exists := threads.Get(threadKey)
	if !exists {
		return "# 404\nThread not found"
	}

	t := val.(*Thread)

	// Suppress content for hidden (flag-auto-hidden or admin-hidden) and
	// soft-deleted threads. renderChannel omits these from the list, but the
	// direct path Render("channel/id") must not leak the original title/body.
	if t.Hidden || t.Deleted {
		return "# Thread unavailable\n\n*This thread has been hidden or removed.*\n"
	}

	var sb strings.Builder
	sb.WriteString(ufmt.Sprintf("# %s\n\n", sanitizeForRender(t.Title)))
	sb.WriteString(sanitizeForRender(t.Body) + "\n\n")
	sb.WriteString("---\n\n")
	sb.WriteString(ufmt.Sprintf("*Posted by %s at block %d*", string(t.Author), t.BlockH))
	if t.Edited {
		sb.WriteString(ufmt.Sprintf(" *(edited at block %d)*", t.EditedAt))
	}
	sb.WriteString("\n\n")

	// B1: render only LIVE replies (bounded by MaxRepliesPerThread), paginated to
	// a fixed window so render cost is O(ReplyPageSize) regardless of total churn.
	// Never iterate the monotonic replyCount — that is the render-DoS surface.
	liveIDs := getLiveReplyIDs(threadKey) // ascending (oldest→newest), <= MaxRepliesPerThread
	total := uint64(len(liveIDs))
	if total > 0 {
		totalPages := (total + ReplyPageSize - 1) / ReplyPageSize
		// page 1 = oldest window … totalPages = newest. Default (0) and any
		// out-of-range value snap to the newest page (most-recent replies).
		if page == 0 || page > totalPages {
			page = totalPages
		}
		start := (page - 1) * ReplyPageSize
		end := start + ReplyPageSize
		if end > total {
			end = total
		}

		sb.WriteString("## Replies\n\n")
		if totalPages > 1 {
			sb.WriteString(ufmt.Sprintf(
				"*Showing %d–%d of %d • page %d/%d — older: `?page=%d`, newer: `?page=%d`*\n\n",
				start+1, end, total, page, totalPages, pageClamp(page-1, totalPages), pageClamp(page+1, totalPages)))
		}

		for i := start; i < end; i++ {
			replyKey := threadKey + "/" + strconv.FormatUint(liveIDs[i], 10)
			rval, rexists := replies.Get(replyKey)
			if !rexists {
				continue // live index never points at a removed reply, but stay safe
			}
			r := rval.(*Reply)
			authorStr := truncAddr(r.Author)
			editStr := ""
			if r.Edited {
				editStr = " *(edited)*"
			}
			sb.WriteString(ufmt.Sprintf("**%s** (block %d)%s\n\n", authorStr, r.BlockH, editStr))
			sb.WriteString(sanitizeForRender(r.Body) + "\n\n")
			sb.WriteString("---\n\n")
		}
	}

	return sb.String()
}

// parsePageQuery extracts the page number from a "?page=N" query string (also
// tolerates extra &-separated params). Returns 0 (= default/newest) on absence
// or parse error.
func parsePageQuery(q string) uint64 {
	for _, kv := range strings.Split(q, "&") {
		if strings.HasPrefix(kv, "page=") {
			if n, err := strconv.ParseUint(strings.TrimPrefix(kv, "page="), 10, 64); err == nil {
				return n
			}
		}
	}
	return 0
}

// pageClamp keeps a page link within [1, totalPages].
func pageClamp(p, totalPages uint64) uint64 {
	if p < 1 {
		return 1
	}
	if p > totalPages {
		return totalPages
	}
	return p
}

// renderACL produces the ACL response for a channel.
// Format: parser.ts parseACL() expects:
//   read:role1,role2
//   write:role1,role2,role3
//   type:text
func renderACL(channelName string) string {
	val, exists := channels.Get(channelName)
	if !exists {
		return "not found"
	}
	ch := val.(*Channel)

	var sb strings.Builder
	sb.WriteString("read:" + strings.Join(ch.ReadRoles, ",") + "\n")
	sb.WriteString("write:" + strings.Join(ch.WriteRoles, ",") + "\n")
	sb.WriteString("type:" + string(ch.Type) + "\n")

	return sb.String()
}

// ── Helpers ──────────────────────────────────────────────────

func getChannel(name string) *Channel {
	val, exists := channels.Get(name)
	if !exists {
		panic("channel not found: " + name)
	}
	return val.(*Channel)
}

func getThreadCount(channel string) uint64 {
	val, exists := threadCount.Get(channel)
	if !exists {
		return 0
	}
	return val.(uint64)
}

// getLiveThreadCount returns the number of non-deleted threads in a channel.
// Unlike getThreadCount (monotonic ID counter), this decreases when threads
// are deleted, so deleted threads free up slots under MaxThreadsPerChan.
func getLiveThreadCount(channel string) uint64 {
	val, exists := threadLive.Get(channel)
	if !exists {
		return 0
	}
	return val.(uint64)
}

// ── Live thread-ID index ─────────────────────────────────────
// renderChannel must iterate only live (non-deleted) thread IDs, never the
// monotonic threadCount: a member can post+delete in a loop to inflate
// threadCount without bound (the live cap only limits live threads), turning
// renderChannel into an unbounded O(threadCount) scan (gas DoS). This index
// stays bounded by getLiveThreadCount (<= MaxThreadsPerChan).

func getLiveThreadIDs(channel string) []uint64 {
	if val, exists := threadLiveIDs.Get(channel); exists {
		return val.([]uint64)
	}
	return nil
}

func addLiveThreadID(channel string, id uint64) {
	threadLiveIDs.Set(channel, append(getLiveThreadIDs(channel), id))
}

func removeLiveThreadID(channel string, id uint64) {
	ids := getLiveThreadIDs(channel)
	for i, x := range ids {
		if x == id {
			threadLiveIDs.Set(channel, append(ids[:i], ids[i+1:]...))
			return
		}
	}
}

// ── Live reply-ID index ──────────────────────────────────────
// Same rationale as the thread index, one level down: renderThread must iterate
// only live reply IDs (bounded by MaxRepliesPerThread), never the monotonic
// replyCount, or a member can post+delete replies in a loop to make a thread
// unrenderable. Keyed by "channel/threadId".

func getLiveReplyCount(threadKey string) uint64 {
	if val, exists := replyLive.Get(threadKey); exists {
		return val.(uint64)
	}
	return 0
}

func getLiveReplyIDs(threadKey string) []uint64 {
	if val, exists := replyLiveIDs.Get(threadKey); exists {
		return val.([]uint64)
	}
	return nil
}

func addLiveReplyID(threadKey string, id uint64) {
	replyLiveIDs.Set(threadKey, append(getLiveReplyIDs(threadKey), id))
}

func removeLiveReplyID(threadKey string, id uint64) {
	ids := getLiveReplyIDs(threadKey)
	for i, x := range ids {
		if x == id {
			replyLiveIDs.Set(threadKey, append(ids[:i], ids[i+1:]...))
			return
		}
	}
}

// ── Thread tombstone queue (B2 hard-GC) ──────────────────────
// Soft-deleted thread IDs awaiting permanent removal by SweepTombstones. A queue
// (not a scan of the threads tree) keeps the sweep O(limit) — it never walks the
// unbounded set of past tombstones.

func getThreadTomb(channel string) []uint64 {
	if val, exists := threadTomb.Get(channel); exists {
		return val.([]uint64)
	}
	return nil
}

func enqueueThreadTomb(channel string, id uint64) {
	threadTomb.Set(channel, append(getThreadTomb(channel), id))
}

func getReplyCount(threadKey string) uint64 {
	val, exists := replyCount.Get(threadKey)
	if !exists {
		return 0
	}
	return val.(uint64)
}

func truncAddr(addr address) string {
	s := string(addr)
	if len(s) > 13 {
		return s[:10] + "..."
	}
	return s
}

// isValidRoles validates a comma-separated role list contains only safe characters.
// Allowed: a-z, A-Z, 0-9, hyphen, comma. No spaces, no markdown chars, no null bytes.
func isValidRoles(s string) bool {
	if len(s) > 200 {
		return false
	}
	for _, c := range s {
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '-' || c == ',') {
			return false
		}
	}
	return true
}

// sanitizeForRender strips markdown-sensitive characters to prevent injection.
func sanitizeForRender(s string) string {
	var out strings.Builder
	for _, c := range s {
		switch c {
		case '[', ']', '(', ')', '#', '*', '`', '!', '<', '>', '|', '\\', '_', '~', '\n', '\r', '\t':
			continue
		default:
			out.WriteRune(c)
		}
	}
	return out.String()
}

// ── ACL Enforcement ─────────────────────────────────────────

func assertCallerIsOwner() {
	caller := unsafe.PreviousRealm().Address()
	if caller != owner {
		panic("unauthorized: caller " + caller.String() + " is not the owner")
	}
}

func assertCallerIsMember(caller address) {
	if _, exists := members.Get(caller.String()); !exists {
		panic("unauthorized: caller " + caller.String() + " is not a member")
	}
}

// assertCallerHasWriteAccess checks that the caller is a member AND has at least
// one role that matches the channel's WriteRoles.
func assertCallerHasWriteAccess(caller address, ch *Channel) {
	// Public channels (WriteRoles contains "*") accept posts from any caller —
	// this is a public feedback board. Non-public channels keep role-based control
	// (e.g. announcements stays admin-only). Mainnet should add rate-limiting.
	for _, wr := range ch.WriteRoles {
		if wr == "*" {
			return
		}
	}
	rolesStr, exists := members.Get(caller.String())
	if !exists {
		panic("unauthorized: caller " + caller.String() + " is not a member")
	}

	callerRoles := strings.Split(rolesStr.(string), ",")
	for _, cr := range callerRoles {
		cr = strings.TrimSpace(cr)
		for _, wr := range ch.WriteRoles {
			if cr == wr {
				return // Access granted
			}
		}
	}

	panic("unauthorized: caller " + caller.String() + " lacks write access to channel " + ch.Name)
}

func hasRole(caller address, role string) bool {
	rolesStr, exists := members.Get(caller.String())
	if !exists {
		return false
	}
	callerRoles := strings.Split(rolesStr.(string), ",")
	for _, cr := range callerRoles {
		if strings.TrimSpace(cr) == role {
			return true
		}
	}
	return false
}

// assertCallerIsAdminRole checks that the caller is a member with the "admin" role.
// Used for moderation actions (RemoveThread, UnhideThread) so any admin can moderate,
// not just the single owner.
func assertCallerIsAdminRole() {
	caller := unsafe.PreviousRealm().Address()
	if !hasRole(caller, "admin") {
		panic("unauthorized: caller " + caller.String() + " does not have admin role")
	}
}

// isValidChannelName validates that a channel name contains only
// lowercase alphanumeric characters and hyphens, and does not start with underscore.
func isValidChannelName(name string) bool {
	if len(name) == 0 || len(name) > 50 {
		return false
	}
	if name[0] == '_' {
		return false // Prevent collision with __acl/, __member/ paths
	}
	for _, c := range name {
		if !((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-') {
			return false
		}
	}
	return true
}

package memba_quest_attestation_v1

// Owner authority and its rotation path.
//
// No owner is compiled in: `owner` is seeded at package load from the
// publishing transaction's signer (on gnoland-1 the samcrew namespace multisig,
// the stamped creator at enable time), and SetSigner reads the mutable `owner`,
// so the address holding ownership can be changed after deployment.
//
// WHY THIS MATTERS ON MAINNET, specifically here. SetSigner is the ONLY
// owner-gated entrypoint, and it installs/rotates the backend's offline signer
// public key — the key every voucher is verified against. Realms are immutable,
// there is no faucet, and mainnet genesis locks ugnot transfers under
// Constitution §126, so a compile-time owner cannot be corrected later, and a
// compile-time testnet owner would freeze the signer at whatever value it last
// held: a compromised backend signer could never be rotated out, and quest
// attestation would have to be abandoned rather than repaired.
//
// TWO-STEP BY DESIGN: the successor must claim the role with its own
// transaction, so ownership can never be handed to an address that cannot
// transact (a typo, or an unfunded address under §126) with no way back.
//
// All owner mutations require a current realm frame and authenticate the
// immediate caller through cur.Previous(), including signer rotation.

import "chain"

var (
	// owner is the LIVE authority, seeded with the publisher at package load.
	// Initialized at declaration so there is no init-ordering question about
	// gates that read it.
	owner address = publisherAtLoad()

	// pendingOwner is the staged successor; "" when none is in flight.
	pendingOwner address
)

// TransferOwnership stages a handoff. Owner only; it takes effect only once
// newOwner calls AcceptOwnership. Calling it again before acceptance replaces
// the staged address, which is how a mistyped proposal is corrected.
func TransferOwnership(cur realm, newOwner address) {
	assertOwner(cur)
	if newOwner == "" {
		panic("newOwner must be non-empty")
	}
	pendingOwner = newOwner
	chain.Emit("OwnershipTransferStarted", "pending", newOwner.String())
}

// AcceptOwnership completes the handoff. Only the staged pendingOwner may call
// it — including against the outgoing owner, so the two steps cannot be
// collapsed into one by the party giving up the role.
func AcceptOwnership(cur realm) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	if pendingOwner == "" {
		panic("no pending ownership transfer")
	}
	if cur.Previous().Address() != pendingOwner {
		panic("unauthorized: only the pending owner may accept")
	}
	owner = pendingOwner
	pendingOwner = ""
	chain.Emit("OwnershipTransferAccepted", "owner", owner.String())
}

// CancelOwnershipTransfer clears a staged handoff. Owner only, so a proposal
// can be aborted without the proposed address cooperating.
func CancelOwnershipTransfer(cur realm) {
	assertOwner(cur)
	if pendingOwner == "" {
		panic("no pending ownership transfer")
	}
	cancelled := pendingOwner
	pendingOwner = ""
	chain.Emit("OwnershipTransferCancelled", "cancelled", cancelled.String())
}

// GetOwner returns the address that currently holds ownership.
func GetOwner() string { return owner.String() }

// GetPendingOwner returns the staged successor ("" when none).
func GetPendingOwner() string { return pendingOwner.String() }

// assertOwner is the gate for this file's entrypoints. It rejects a
// stale/sibling `cur` first, then takes the caller from cur.Previous().
func assertOwner(cur realm) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	if cur.Previous().Address() != owner {
		panic("unauthorized: owner multisig only")
	}
}

// Package memba_quest_attestation_v1 is the on-chain quest/XP attestation realm
// for Memba (audit Q-05, Track A — "Model B" offline-signed voucher).
//
// WHY: Memba quest XP lives in a centralized backend DB; the chain holds no
// verifiable record. This realm makes a quest completion + its XP an independently
// verifiable on-chain fact, WITHOUT giving the backend a hot key that can write
// arbitrary state.
//
// HOW (Model B — offline voucher):
//   - The backend holds an OFFLINE ed25519 signing key; it NEVER broadcasts.
//   - For a server-verified completion it issues a voucher
//     (address, questId, xp, nonce) + ed25519 signature
//     over the canonical message
//     addr "|" questId "|" itoa(xp) "|" nonce            (UTF-8 bytes)
//   - The USER broadcasts RecordCompletion(...) with the voucher (they pay gas).
//   - This realm verifies the signature against the configured signer pubkey,
//     rejects reused nonces (replay), bounds xp, and records the completion +
//     cumulative attested XP.
//
// TRUST MODEL: the signature is the authority, NOT the caller — anyone may
// broadcast a valid voucher (it can only record the backend-attested fact). The
// only privileged action is rotating the signer pubkey (owner multisig).
//
// The canonical message format is a CONTRACT with the backend signer — it MUST
// stay byte-identical on both sides. See canonicalMsg.
package memba_quest_attestation_v1

import (
	"crypto/ed25519"
	"encoding/hex"
	"strconv"
	"strings"

	"gno.land/p/samcrew/avl"
	"gno.land/p/nt/ufmt/v0"

	"chain/runtime"
)

// ── Constants ────────────────────────────────────────────────
const (
	// The realm owner is not a constant: admin.gno seeds it from the publisher
	// at package load and rotates it via TransferOwnership/AcceptOwnership.

	// MaxAttestXP bounds the XP a single voucher can carry. This caps the blast
	// radius if the offline signer key ever leaks: a leaked key can still forge
	// vouchers, but cannot mint unbounded XP in one call. Generous vs the real
	// max single-quest XP (≤100).
	MaxAttestXP = 1000

	pubKeySize = 32 // ed25519 public key length (gno crypto/ed25519 exposes no const)
	sigSize    = 64 // ed25519 signature length
	fieldSep   = "|"
)

// ── State ────────────────────────────────────────────────────
var (
	// signerPubKey is the backend's offline ed25519 PUBLIC key (32 bytes). Set by
	// the owner via SetSigner after deploy; until then NO voucher verifies.
	signerPubKey []byte

	completions *avl.Tree // addr + ":" + questId -> int64 (block height recorded)
	attestedXP  *avl.Tree // addr               -> int   (cumulative attested XP)
	usedNonce   *avl.Tree // nonce              -> true  (replay guard)
)

func init() {
	completions = avl.NewTree()
	attestedXP = avl.NewTree()
	usedNonce = avl.NewTree()
}

// ── Pure helpers (unit-tested) ───────────────────────────────

// canonicalMsg is the EXACT byte string the backend signs offline and this realm
// verifies. It MUST stay byte-identical to the backend signer (ADR Track A / A.3).
// strconv.Itoa gives a canonical decimal with no leading zeros, so both sides
// agree for any xp.
func canonicalMsg(addr, questId string, xp int, nonce string) []byte {
	return []byte(addr + fieldSep + questId + fieldSep + strconv.Itoa(xp) + fieldSep + nonce)
}

func completionKey(addr, questId string) string { return addr + ":" + questId }

// validXP bounds the attestable XP (see MaxAttestXP).
func validXP(xp int) bool { return xp > 0 && xp <= MaxAttestXP }

// fieldsClean rejects any voucher field containing the separator. This makes the
// canonical message PROVABLY unambiguous (no field-injection collision) without
// trusting the backend's nonce charset: with no field able to contain "|", a
// given canonical byte string maps to exactly one (addr, questId, xp, nonce).
func fieldsClean(addr, questId, nonce string) bool {
	return !strings.Contains(addr, fieldSep) &&
		!strings.Contains(questId, fieldSep) &&
		!strings.Contains(nonce, fieldSep)
}

// verifyVoucher reports whether sigHex is a valid ed25519 signature by pub over
// the canonical voucher message. Pure (no state) so it is unit-tested directly
// with offline-generated test vectors.
func verifyVoucher(pub []byte, addr, questId string, xp int, nonce, sigHex string) bool {
	if len(pub) != pubKeySize {
		return false
	}
	sig, err := hex.DecodeString(sigHex)
	if err != nil || len(sig) != sigSize {
		return false
	}
	return ed25519.Verify(pub, canonicalMsg(addr, questId, xp, nonce), sig)
}

// ── Owner: rotate the signer key ─────────────────────────────

// SetSigner installs/rotates the backend's offline signer PUBLIC key (32-byte
// hex). The current owner is authenticated using its live crossing frame.
func SetSigner(cur realm, pubKeyHex string) {
	assertOwner(cur)
	pub, err := hex.DecodeString(pubKeyHex)
	if err != nil || len(pub) != pubKeySize {
		panic("signer pubkey must be 32-byte hex")
	}
	signerPubKey = pub
}

// ── User-broadcast: record a signed completion voucher ───────

// RecordCompletion verifies a backend-signed voucher and records the completion
// + its XP on-chain. Idempotent per (addr, questId); replay-proof per nonce.
// Panics (reverting the tx) on any invalid/again-used/out-of-range voucher.
func RecordCompletion(cur realm, addr, questId string, xp int, nonce, sigHex string) {
	if len(signerPubKey) != pubKeySize {
		panic("attestation signer not configured")
	}
	if addr == "" || questId == "" || nonce == "" {
		panic("missing voucher field")
	}
	if !fieldsClean(addr, questId, nonce) {
		panic("voucher field must not contain the separator")
	}
	if !validXP(xp) {
		panic("xp out of range")
	}
	if _, used := usedNonce.Get(nonce); used {
		panic("nonce already used")
	}
	if !verifyVoucher(signerPubKey, addr, questId, xp, nonce, sigHex) {
		panic("invalid voucher signature")
	}

	// Consume the nonce (replay guard) before the idempotency early-return below,
	// so a replayed voucher always fails even for an already-recorded completion.
	usedNonce.Set(nonce, true)

	// Idempotent on (addr, questId): a second, distinct-nonce voucher for an
	// already-recorded completion must NOT double-count XP.
	ck := completionKey(addr, questId)
	if _, exists := completions.Get(ck); exists {
		return
	}
	completions.Set(ck, runtime.ChainHeight())

	prev := 0
	if v, ok := attestedXP.Get(addr); ok {
		prev = v.(int)
	}
	attestedXP.Set(addr, prev+xp)
}

// ── Public reads ─────────────────────────────────────────────

// GetSigner returns a copied canonical public-key string, or empty before setup.
func GetSigner() string { return hex.EncodeToString(signerPubKey) }

// GetAttestedXP returns addr's cumulative on-chain attested XP (0 if none).
func GetAttestedXP(addr string) int {
	if v, ok := attestedXP.Get(addr); ok {
		return v.(int)
	}
	return 0
}

// GetRecordedCompletions returns addr's attested quest IDs as a comma-separated
// list (empty string if none), in ascending key order.
func GetRecordedCompletions(addr string) string {
	prefix := addr + ":"
	out := []string{}
	completions.Iterate(prefix, addr+";", func(key string, _ interface{}) bool {
		out = append(out, strings.TrimPrefix(key, prefix))
		return false
	})
	return strings.Join(out, ",")
}

// Render is the human/gnoweb view; the authoritative reads are the exported
// Get* funcs (queried via vm/qeval).
func Render(path string) string {
	if path == "" {
		signer := "not configured"
		if len(signerPubKey) == pubKeySize {
			signer = "configured"
		}
		return ufmt.Sprintf(
			"# Memba Quest Attestation\n\nVerifiable on-chain quest/XP records (offline-signed vouchers).\n\n- Completions attested: %d\n- Accounts with attested XP: %d\n- Signer: %s\n",
			completions.Size(), attestedXP.Size(), signer)
	}
	if strings.HasPrefix(path, "user/") {
		addr := strings.TrimPrefix(path, "user/")
		comps := GetRecordedCompletions(addr)
		if comps == "" {
			comps = "(none)"
		}
		return ufmt.Sprintf("# %s\n\n- Attested XP: %d\n- Completions: %s\n", addr, GetAttestedXP(addr), comps)
	}
	return "404"
}

package memba_quest_attestation_v1

import "chain/runtime/unsafe"

// publisherAtLoad captures the AddPackage signer during package initialization.
// Keeping the unsafe load-time primitive separate from crossing entrypoints lets
// privileged calls use only the frame-verified cur.IsCurrent/cur.Previous API.
func publisherAtLoad() address { return unsafe.OriginCaller() }

package memba_reviews_v2

// Moderator authority and its rotation path.
//
// No moderator is compiled in: `moderator` below is seeded at package load from
// the publishing transaction's signer (on gnoland-1 the samcrew namespace
// multisig, the stamped creator at enable time), and assertModerator reads the
// mutable `moderator`, so the address holding moderation can be changed after
// deployment.
//
// WHY THIS MATTERS ON MAINNET. Realms are immutable once published, there is no
// faucet, and mainnet genesis locks ugnot transfers under Constitution §126 — so
// a compile-time moderator cannot be corrected after the fact: a testnet key
// compiled in would permanently disable HideTarget/UnhideTarget/ClearFlags,
// leaving this realm with no way to act on a flagged review ever again.
//
// TWO-STEP BY DESIGN: the successor must claim the role with its own transaction,
// so moderation can never be handed to an address that cannot transact (a typo,
// or an unfunded address under §126) with no way back.
//
// CALLER AUTH here uses `cur.IsCurrent()` + `cur.Previous().Address()`, per
// contract-review checklist #9, matching memba_arcade_leaderboard_v1 /
// memba_points_v1. The realm's existing assertModerator keeps its older
// frame-unverified caller read (grandfathered in
// antipattern-prevrealm-baseline.txt); only the value it compares against
// changed, which is the smallest edit that removes the immutability.

import "chain"

var (
	// moderator is the LIVE authority, seeded with the publisher at package load.
	// Initialized at declaration so there is no init-ordering question about
	// gates that read it.
	moderator address = publisherAtLoad()

	// pendingModerator is the staged successor; "" when none is in flight.
	pendingModerator address
)

// TransferOwnership stages a handoff of the moderator role. Moderator only; it
// takes effect only once newModerator calls AcceptOwnership. Calling it again
// before acceptance replaces the staged address, which is how a mistyped
// proposal is corrected.
func TransferOwnership(cur realm, newModerator address) {
	assertModeratorCur(cur)
	if newModerator == "" {
		panic("newModerator must be non-empty")
	}
	if !newModerator.IsValid() {
		panic("invalid address: " + newModerator.String())
	}
	if newModerator == moderator {
		panic("newModerator is the current moderator")
	}
	pendingModerator = newModerator
	chain.Emit("OwnershipTransferStarted", "pending", newModerator.String())
}

// AcceptOwnership completes the handoff. Only the staged pendingModerator may
// call it — including against the outgoing moderator, so the two steps cannot be
// collapsed into one by the party giving up the role.
func AcceptOwnership(cur realm) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	if pendingModerator == "" {
		panic("no pending ownership transfer")
	}
	if cur.Previous().Address() != pendingModerator {
		panic("unauthorized: only the pending moderator may accept")
	}
	moderator = pendingModerator
	pendingModerator = ""
	chain.Emit("OwnershipTransferAccepted", "moderator", moderator.String())
}

// CancelOwnershipTransfer clears a staged handoff. Moderator only, so a
// proposal can be aborted without the proposed address cooperating.
func CancelOwnershipTransfer(cur realm) {
	assertModeratorCur(cur)
	if pendingModerator == "" {
		panic("no pending ownership transfer")
	}
	cancelled := pendingModerator
	pendingModerator = ""
	chain.Emit("OwnershipTransferCancelled", "cancelled", cancelled.String())
}

// GetModerator returns the address that currently holds moderation.
func GetModerator() string { return moderator.String() }

// GetPendingModerator returns the staged successor ("" when none).
func GetPendingModerator() string { return pendingModerator.String() }

// assertModeratorCur is the gate for this file's entrypoints. Named apart from
// the realm's existing assertModerator so the older call sites keep their
// signature and semantics untouched.
func assertModeratorCur(cur realm) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	if cur.Previous().Address() != moderator {
		panic("unauthorized: moderator multisig only")
	}
}

package memba_reviews_v2

// Memba Reviews / Web-of-Trust realm.
//
// OPEN, on-chain ratings + reviews for any Memba subject (validator/candidate/
// individual address, or an org/DAO realm path). Anyone with a wallet may post
// ONE editable review per subject, react (like/dislike), reply (flat, one
// level), and flag. A running net-likes reputation counter per author drives
// ranking. Moderation = author delete (tombstone) + community flag + multisig
// hide (soft-delete). Text is permanent on-chain; Hide only omits from reads.
//
// Reads: exported *JSON funcs queried via RPC vm/qeval (paginated). Render() is
// a secondary human view for gnoweb.

import (
	"strconv"
	"strings"

	"gno.land/p/samcrew/avl"
	"gno.land/p/nt/ufmt/v0"

	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
)

// ── Constants ────────────────────────────────────────────────
const (
	MaxBodyLen    = 2000 // review body
	MaxCommentLen = 1000 // comment body
	MaxPageLimit  = 100  // hard cap on any paginated read (DoS guard)

	// The moderator is not a constant: admin.gno seeds it from the publisher at
	// package load and rotates it via TransferOwnership/AcceptOwnership.
)

// ── Types ────────────────────────────────────────────────────
type Review struct {
	ID        uint64
	Subject   string  // g1… address OR realm path
	Author    address
	Rating    int     // 1..5
	Body      string  // optional, ≤ MaxBodyLen
	CreatedAt int64   // block height
	EditedAt  int64   // block height of last edit (0 if never)
	Hidden    bool    // multisig soft-delete / auto-hide
	Deleted   bool    // author tombstone
	Likes     uint64
	Dislikes  uint64
	FlagCount uint64
}

type Comment struct {
	ID        uint64
	ReviewID  uint64
	Author    address
	Body      string // ≤ MaxCommentLen
	CreatedAt int64
	EditedAt  int64
	Hidden    bool
	Deleted   bool
	Likes     uint64
	Dislikes  uint64
	FlagCount uint64
}

// ── State ────────────────────────────────────────────────────
var (
	reviews       *avl.Tree // strID(id) -> *Review
	comments      *avl.Tree // strID(id) -> *Comment
	subjectIndex  *avl.Tree // subject -> []uint64 (review IDs, ascending) — bounds reads
	commentIndex  *avl.Tree // strID(reviewID) -> []uint64 (comment IDs, ascending)
	authorSubject *avl.Tree // subject + "\x00" + author -> uint64 (reviewID) — one-per-pair
	reactions     *avl.Tree // strID(targetID) + "/" + addr -> "like"|"dislike"
	flags         *avl.Tree // strID(targetID) + "/" + addr -> true (one flag per acct/target)
	reputation    *avl.Tree // addr -> int64 (Σ likes−dislikes on their reviews+comments)
	flaggedIDs    *avl.Tree // strID(targetID) -> true (visible targets with ≥1 flag, for the mod dashboard)
	// RV-1: O(1) per-subject visible-review counters (visible = !Deleted && !Hidden) so
	// GetSubjectSummaryJSON never scans a sybil-growable review list. Maintained by every
	// transition that changes a review's counted state (post / edit-rating / delete / hide / unhide).
	subjStatCount *avl.Tree // subject -> int64 (# visible reviews)
	subjStatSum   *avl.Tree // subject -> int64 (Σ rating over visible reviews)
	nextID        uint64
)

func init() {
	reviews = avl.NewTree()
	comments = avl.NewTree()
	subjectIndex = avl.NewTree()
	commentIndex = avl.NewTree()
	authorSubject = avl.NewTree()
	reactions = avl.NewTree()
	flags = avl.NewTree()
	reputation = avl.NewTree()
	flaggedIDs = avl.NewTree()
	subjStatCount = avl.NewTree()
	subjStatSum = avl.NewTree()
	nextID = 1
}

// ── RV-1 subject-stat counters (O(1) summary) ────────────────
func getStat(t *avl.Tree, subject string) int64 {
	if v, ok := t.Get(subject); ok {
		return v.(int64)
	}
	return 0
}

// applySubjectStat adjusts the visible-review counters for a subject. Callers apply a delta
// only when a review's *counted* state (visible = !Deleted && !Hidden) actually changes.
func applySubjectStat(subject string, dCount, dSum int64) {
	if dCount != 0 {
		subjStatCount.Set(subject, getStat(subjStatCount, subject)+dCount)
	}
	if dSum != 0 {
		subjStatSum.Set(subject, getStat(subjStatSum, subject)+dSum)
	}
}

// ── Helpers ──────────────────────────────────────────────────
func strID(id uint64) string { return strconv.FormatUint(id, 10) }

func getReview(id uint64) (*Review, bool) {
	v, ok := reviews.Get(strID(id))
	if !ok {
		return nil, false
	}
	return v.(*Review), true
}

func getComment(id uint64) (*Comment, bool) {
	v, ok := comments.Get(strID(id))
	if !ok {
		return nil, false
	}
	return v.(*Comment), true
}

func assertModerator() {
	caller := unsafe.PreviousRealm().Address()
	if caller != moderator {
		panic("unauthorized: moderator multisig only")
	}
}

func getReputation(addr string) int64 {
	if v, ok := reputation.Get(addr); ok {
		return v.(int64)
	}
	return 0
}

func addReputation(addr string, delta int64) {
	reputation.Set(addr, getReputation(addr)+delta)
}

func idList(t *avl.Tree, key string) []uint64 {
	if v, ok := t.Get(key); ok {
		return v.([]uint64)
	}
	return nil
}

// removeID returns ids with the first occurrence of target removed.
func removeID(ids []uint64, target uint64) []uint64 {
	out := make([]uint64, 0, len(ids))
	removed := false
	for _, id := range ids {
		if !removed && id == target {
			removed = true
			continue
		}
		out = append(out, id)
	}
	return out
}

// sanitizeForRender strips markdown/HTML-sensitive chars from user strings used
// inside Render() markdown (defense-in-depth; the frontend also DOMPurifies).
// "&" is escaped FIRST to prevent entity-injection (e.g. "&lt;" → "&amp;lt;").
func sanitizeForRender(s string) string {
	r := strings.NewReplacer(
		"&", "&amp;",
		"<", "&lt;", ">", "&gt;",
		"[", "(", "]", ")",
		"`", "'", "|", "/",
		"\n", " ", "\r", " ",
	)
	return r.Replace(s)
}

// jsonEscape escapes a string for embedding in the realm's hand-built JSON.
func jsonEscape(s string) string {
	var b strings.Builder
	for _, c := range s {
		switch c {
		case '"':
			b.WriteString("\\\"")
		case '\\':
			b.WriteString("\\\\")
		case '\n':
			b.WriteString("\\n")
		case '\r':
			b.WriteString("\\r")
		case '\t':
			b.WriteString("\\t")
		default:
			if c < 0x20 {
				const hexDigits = "0123456789abcdef"
				b.WriteString("\\u00")
				b.WriteByte(hexDigits[int((c>>4)&0xf)])
				b.WriteByte(hexDigits[int(c&0xf)])
			} else {
				b.WriteRune(c)
			}
		}
	}
	return b.String()
}

// ── Validation helpers (pure, no side-effects) ────────────────

func validRating(r int) bool { return r >= 1 && r <= 5 }

func validBody(b string) bool { return len(b) <= MaxBodyLen }

// pairKey returns the authorSubject tree key for a (subject, author) pair.
// The NUL separator prevents prefix collisions between subject and author.
func pairKey(subject string, a address) string { return subject + "\x00" + a.String() }

// ── Write functions ───────────────────────────────────────────

// PostReview creates the caller's review for `subject`, or replaces it in place
// if one already exists (the "one editable review per pair" rule).
func PostReview(cur realm, subject string, rating int, body string) {
	caller := unsafe.PreviousRealm().Address()
	if subject == "" {
		panic("subject required")
	}
	if !validRating(rating) {
		panic("rating must be 1..5")
	}
	if !validBody(body) {
		panic("body too long")
	}

	pk := pairKey(subject, caller)
	if v, ok := authorSubject.Get(pk); ok {
		r, found := getReview(v.(uint64))
		if found && !r.Deleted && !r.Hidden {
			// counted review already exists for this (subject, author): rating change only.
			applySubjectStat(subject, 0, int64(rating)-int64(r.Rating))
			r.Rating = rating
			r.Body = body
			r.EditedAt = runtime.ChainHeight()
			reviews.Set(strID(r.ID), r)
			chain.Emit("ReviewUpdated", "id", strID(r.ID), "subject", subject)
			return
		}
	}

	id := nextID
	nextID++
	r := &Review{
		ID:        id,
		Subject:   subject,
		Author:    caller,
		Rating:    rating,
		Body:      body,
		CreatedAt: runtime.ChainHeight(),
	}
	reviews.Set(strID(id), r)
	authorSubject.Set(pk, id)
	subjectIndex.Set(subject, append(idList(subjectIndex, subject), id))
	applySubjectStat(subject, 1, int64(rating)) // new visible review
	chain.Emit("ReviewPosted", "id", strID(id), "subject", subject, "author", caller.String())
}

// EditReview updates rating + body of an existing non-deleted review.
// Only the original author may edit.
func EditReview(cur realm, reviewID uint64, rating int, body string) {
	caller := unsafe.PreviousRealm().Address()
	r, ok := getReview(reviewID)
	if !ok || r.Deleted {
		panic("review not found")
	}
	if r.Author != caller {
		panic("author only")
	}
	if !validRating(rating) {
		panic("rating must be 1..5")
	}
	if !validBody(body) {
		panic("body too long")
	}
	if !r.Hidden { // counted (r.Deleted is false per the guard above): apply the rating delta
		applySubjectStat(r.Subject, 0, int64(rating)-int64(r.Rating))
	}
	r.Rating = rating
	r.Body = body
	r.EditedAt = runtime.ChainHeight()
	reviews.Set(strID(reviewID), r)
	chain.Emit("ReviewUpdated", "id", strID(reviewID), "subject", r.Subject)
}

// DeleteReview tombstones the caller's review: keeps the ID + reaction history,
// clears the body, and frees the (author, subject) pair for a fresh review.
// Only the original author may delete.
func DeleteReview(cur realm, reviewID uint64) {
	caller := unsafe.PreviousRealm().Address()
	r, ok := getReview(reviewID)
	if !ok || r.Deleted {
		panic("review not found")
	}
	if r.Author != caller {
		panic("author only")
	}
	if !r.Hidden { // was counted (r.Deleted false per guard): drop it from the subject stats
		applySubjectStat(r.Subject, -1, -int64(r.Rating))
	}
	r.Deleted = true
	r.Body = ""
	reviews.Set(strID(reviewID), r)
	authorSubject.Remove(pairKey(r.Subject, caller))
	subjectIndex.Set(r.Subject, removeID(idList(subjectIndex, r.Subject), reviewID))
	flaggedIDs.Remove(strID(reviewID)) // RV-3: don't leave a tombstoned review in the mod dashboard
	chain.Emit("ReviewDeleted", "id", strID(reviewID), "subject", r.Subject)
}

// ── Comment validation (pure, no side-effects) ────────────────

// validComment returns true iff body is non-empty and within MaxCommentLen.
func validComment(b string) bool { return b != "" && len(b) <= MaxCommentLen }

// ── Comment write functions ───────────────────────────────────

// PostComment posts a flat reply to an existing, non-deleted, non-hidden review.
func PostComment(cur realm, reviewID uint64, body string) {
	caller := unsafe.PreviousRealm().Address()
	r, ok := getReview(reviewID)
	if !ok || r.Deleted || r.Hidden {
		panic("review not found")
	}
	if !validComment(body) {
		panic("comment length invalid")
	}
	id := nextID
	nextID++
	c := &Comment{
		ID:        id,
		ReviewID:  reviewID,
		Author:    caller,
		Body:      body,
		CreatedAt: runtime.ChainHeight(),
	}
	comments.Set(strID(id), c)
	commentIndex.Set(strID(reviewID), append(idList(commentIndex, strID(reviewID)), id))
	chain.Emit("CommentPosted", "id", strID(id), "review", strID(reviewID), "author", caller.String())
}

// EditComment updates the body of an existing, non-deleted comment.
// Only the original author may edit.
func EditComment(cur realm, commentID uint64, body string) {
	caller := unsafe.PreviousRealm().Address()
	c, ok := getComment(commentID)
	if !ok || c.Deleted {
		panic("comment not found")
	}
	if c.Author != caller {
		panic("author only")
	}
	if !validComment(body) {
		panic("comment length invalid")
	}
	c.Body = body
	c.EditedAt = runtime.ChainHeight()
	comments.Set(strID(commentID), c)
	chain.Emit("CommentUpdated", "id", strID(commentID))
}

// DeleteComment tombstones the caller's comment: clears the body.
// Only the original author may delete.
func DeleteComment(cur realm, commentID uint64) {
	caller := unsafe.PreviousRealm().Address()
	c, ok := getComment(commentID)
	if !ok || c.Deleted {
		panic("comment not found")
	}
	if c.Author != caller {
		panic("author only")
	}
	c.Deleted = true
	c.Body = ""
	comments.Set(strID(commentID), c)
	flaggedIDs.Remove(strID(commentID)) // RV-3: don't leave a tombstoned comment in the mod dashboard
	chain.Emit("CommentDeleted", "id", strID(commentID))
}

// ── Reaction helpers (pure, no side-effects) ──────────────────

func boolToInt(b bool) int {
	if b {
		return 1
	}
	return 0
}

// reactionDelta returns how a reaction change (old -> newKind, each "" | "like" | "dislike")
// moves the target's like count, dislike count, and the target author's reputation.
// repDelta = likesDelta - dislikesDelta.
func reactionDelta(old, newKind string) (likesDelta, dislikesDelta, repDelta int) {
	likesDelta = boolToInt(newKind == "like") - boolToInt(old == "like")
	dislikesDelta = boolToInt(newKind == "dislike") - boolToInt(old == "dislike")
	repDelta = likesDelta - dislikesDelta
	return
}

// applyDelta adjusts an unsigned counter by ±1-style delta without underflow.
func applyDelta(v uint64, delta int) uint64 {
	if delta < 0 {
		d := uint64(-delta)
		if v < d {
			return 0
		}
		return v - d
	}
	return v + uint64(delta)
}

// ── React ─────────────────────────────────────────────────────

// React records or toggles a like/dislike on a review or comment.
// Re-reacting with the same kind toggles it off; switching kind replaces it.
// Updates the target's Likes/Dislikes counters and the author's reputation by
// Δ(likes−dislikes). Self-reactions are rejected. Deleted/hidden targets are rejected.
func React(cur realm, targetID uint64, kind string) {
	caller := unsafe.PreviousRealm().Address()
	if kind != "like" && kind != "dislike" {
		panic("kind must be like or dislike")
	}

	r, isReview := getReview(targetID)
	c, isComment := getComment(targetID)
	if !isReview && !isComment {
		panic("target not found")
	}

	var author address
	if isReview {
		author = r.Author
		if r.Deleted || r.Hidden {
			panic("target not found")
		}
	} else {
		author = c.Author
		if c.Deleted || c.Hidden {
			panic("target not found")
		}
	}
	if author == caller {
		panic("cannot react to your own review or comment")
	}

	rk := strID(targetID) + "/" + caller.String()
	var old string
	if v, ok := reactions.Get(rk); ok {
		old = v.(string)
	}

	newKind := kind
	if old == kind {
		newKind = "" // toggle off
	}

	likesDelta, dislikesDelta, repDelta := reactionDelta(old, newKind)

	if newKind == "" {
		reactions.Remove(rk)
	} else {
		reactions.Set(rk, newKind)
	}

	if isReview {
		r.Likes = applyDelta(r.Likes, likesDelta)
		r.Dislikes = applyDelta(r.Dislikes, dislikesDelta)
		reviews.Set(strID(targetID), r)
	} else {
		c.Likes = applyDelta(c.Likes, likesDelta)
		c.Dislikes = applyDelta(c.Dislikes, dislikesDelta)
		comments.Set(strID(targetID), c)
	}
	addReputation(author.String(), int64(repDelta))
	chain.Emit("Reacted", "target", strID(targetID), "kind", newKind, "by", caller.String())
}

// ── Flag + moderation ─────────────────────────────────────────

// Flag records one community flag per account per target (review or comment).
// Auto-hide is NOT performed here; takedowns are multisig-only (HideReview/HideComment).
// Deleted/hidden targets are rejected.
func Flag(cur realm, targetID uint64) {
	caller := unsafe.PreviousRealm().Address()
	r, isReview := getReview(targetID)
	c, isComment := getComment(targetID)
	if !isReview && !isComment {
		panic("target not found")
	}
	if isReview && (r.Deleted || r.Hidden) {
		panic("target not found")
	}
	if isComment && (c.Deleted || c.Hidden) {
		panic("target not found")
	}
	fk := strID(targetID) + "/" + caller.String()
	if _, ok := flags.Get(fk); ok {
		panic("already flagged")
	}
	flags.Set(fk, true)

	if isReview {
		r.FlagCount++
		reviews.Set(strID(targetID), r)
	} else {
		c.FlagCount++
		comments.Set(strID(targetID), c)
	}
	flaggedIDs.Set(strID(targetID), true)
	chain.Emit("Flagged", "target", strID(targetID), "by", caller.String())
}

// HideReview soft-deletes a review. Moderator (multisig) only.
func HideReview(cur realm, id uint64) {
	assertModerator()
	r, ok := getReview(id)
	if !ok {
		panic("review not found")
	}
	if !r.Hidden && !r.Deleted { // was counted → drop from subject stats (guard against re-hide)
		applySubjectStat(r.Subject, -1, -int64(r.Rating))
	}
	r.Hidden = true
	reviews.Set(strID(id), r)
	chain.Emit("Hidden", "target", strID(id))
}

// HideComment soft-deletes a comment. Moderator (multisig) only.
func HideComment(cur realm, id uint64) {
	assertModerator()
	c, ok := getComment(id)
	if !ok {
		panic("comment not found")
	}
	c.Hidden = true
	comments.Set(strID(id), c)
	chain.Emit("Hidden", "target", strID(id))
}

// Unhide reverses a hide (manual or auto-flag) on a review or comment.
// Moderator (multisig) only. Also removes the target from the mod dashboard index.
func Unhide(cur realm, targetID uint64) {
	assertModerator()
	if r, ok := getReview(targetID); ok {
		if r.Hidden && !r.Deleted { // becomes counted again → restore to subject stats
			applySubjectStat(r.Subject, 1, int64(r.Rating))
		}
		r.Hidden = false
		reviews.Set(strID(targetID), r)
		flaggedIDs.Remove(strID(targetID))
		chain.Emit("Unhidden", "target", strID(targetID))
		return
	}
	if c, ok := getComment(targetID); ok {
		c.Hidden = false
		comments.Set(strID(targetID), c)
		flaggedIDs.Remove(strID(targetID))
		chain.Emit("Unhidden", "target", strID(targetID))
		return
	}
	panic("target not found")
}

// ── Read helpers ──────────────────────────────────────────────

// clampLimit ensures limit is in [1, MaxPageLimit]. Zero or negative values and
// values above MaxPageLimit are all clamped to MaxPageLimit.
func clampLimit(limit int) int {
	if limit <= 0 || limit > MaxPageLimit {
		return MaxPageLimit
	}
	return limit
}

// window slices ids[offset : offset+limit] safely (no panics on out-of-range).
func window(ids []uint64, offset, limit int) []uint64 {
	limit = clampLimit(limit)
	if offset < 0 {
		offset = 0
	}
	if offset >= len(ids) {
		return nil
	}
	end := offset + limit
	if end > len(ids) {
		end = len(ids)
	}
	return ids[offset:end]
}

func reviewJSON(r *Review) string {
	body := ""
	if !r.Deleted {
		body = jsonEscape(r.Body)
	}
	return ufmt.Sprintf(
		`{"id":%d,"subject":"%s","author":"%s","rating":%d,"body":"%s","createdAt":%d,"editedAt":%d,"deleted":%t,"likes":%d,"dislikes":%d,"flags":%d,"reputation":%d}`,
		r.ID, jsonEscape(r.Subject), jsonEscape(r.Author.String()), r.Rating, body,
		r.CreatedAt, r.EditedAt, r.Deleted, r.Likes, r.Dislikes, r.FlagCount,
		getReputation(r.Author.String()),
	)
}

func commentJSON(c *Comment) string {
	body := ""
	if !c.Deleted {
		body = jsonEscape(c.Body)
	}
	return ufmt.Sprintf(
		`{"id":%d,"reviewId":%d,"author":"%s","body":"%s","createdAt":%d,"editedAt":%d,"deleted":%t,"likes":%d,"dislikes":%d,"flags":%d,"reputation":%d}`,
		c.ID, c.ReviewID, jsonEscape(c.Author.String()), body,
		c.CreatedAt, c.EditedAt, c.Deleted, c.Likes, c.Dislikes, c.FlagCount,
		getReputation(c.Author.String()),
	)
}

// GetReviewsJSON returns a JSON array of a subject's non-hidden reviews (paginated).
// Deleted reviews are included as tombstones (empty body, deleted:true).
func GetReviewsJSON(subject string, offset, limit int) string {
	ids := window(idList(subjectIndex, subject), offset, limit)
	var b strings.Builder
	b.WriteString("[")
	first := true
	for _, id := range ids {
		r, ok := getReview(id)
		if !ok || r.Hidden {
			continue
		}
		if !first {
			b.WriteString(",")
		}
		b.WriteString(reviewJSON(r))
		first = false
	}
	b.WriteString("]")
	return b.String()
}

// GetCommentsJSON returns a JSON array of a review's non-hidden comments (paginated).
func GetCommentsJSON(reviewID uint64, offset, limit int) string {
	ids := window(idList(commentIndex, strID(reviewID)), offset, limit)
	var b strings.Builder
	b.WriteString("[")
	first := true
	for _, id := range ids {
		c, ok := getComment(id)
		if !ok || c.Hidden {
			continue
		}
		if !first {
			b.WriteString(",")
		}
		b.WriteString(commentJSON(c))
		first = false
	}
	b.WriteString("]")
	return b.String()
}

// GetSubjectSummaryJSON returns {"count":N,"average":A,"sum":S} over non-hidden,
// non-deleted reviews for a subject. Average is integer-rounded.
// GetSubjectSummaryJSON returns the count/average/sum of a subject's VISIBLE reviews.
// RV-1: O(1) — reads the maintained per-subject counters instead of scanning the (sybil-
// growable) review list, so it can never exceed the query gas cap.
func GetSubjectSummaryJSON(subject string) string {
	n := getStat(subjStatCount, subject)
	sum := getStat(subjStatSum, subject)
	avg := int64(0)
	if n > 0 {
		avg = (sum + n/2) / n // round to nearest
	}
	return ufmt.Sprintf(`{"count":%d,"average":%d,"sum":%d}`, n, avg, sum)
}

// GetReputation returns the net likes−dislikes reputation for an address.
// Returns 0 for unknown addresses. Queried via vm/qeval (bare int64).
func GetReputation(addr string) int64 { return getReputation(addr) }

// GetFlaggedJSON returns a JSON array of flagged target IDs for the mod dashboard,
// paginated. IDs are returned as bare integers (not quoted strings).
// Uses early-stop iteration to avoid loading the entire tree.
func GetFlaggedJSON(offset, limit int) string {
	limit = clampLimit(limit)
	if offset < 0 {
		offset = 0
	}
	var ids []uint64
	skipped := 0
	flaggedIDs.Iterate("", "", func(key string, _ interface{}) bool {
		if skipped < offset {
			skipped++
			return false
		}
		id, _ := strconv.ParseUint(key, 10, 64)
		ids = append(ids, id)
		return len(ids) >= limit // stop once collected enough
	})
	var b strings.Builder
	b.WriteString("[")
	for i, id := range ids {
		if i > 0 {
			b.WriteString(",")
		}
		b.WriteString(strID(id))
	}
	b.WriteString("]")
	return b.String()
}

// Render — human gnoweb view.
// "" → home (total count); "s/<subject>" → subject review list; else 404.
func Render(path string) string {
	if path == "" {
		return ufmt.Sprintf("# Memba Reviews\n\nOn-chain web-of-trust. %d reviews total.\n", reviews.Size())
	}
	if strings.HasPrefix(path, "s/") {
		subject := strings.TrimPrefix(path, "s/")
		var b strings.Builder
		b.WriteString("# Reviews for " + sanitizeForRender(subject) + "\n\n")
		written := false
		renderedCount := 0
		for _, id := range idList(subjectIndex, subject) {
			if renderedCount >= MaxPageLimit {
				break
			}
			r, ok := getReview(id)
			if !ok || r.Hidden || r.Deleted {
				continue
			}
			b.WriteString(ufmt.Sprintf("**%d/5** by %s\n\n%s\n\n---\n",
				r.Rating, r.Author.String(), sanitizeForRender(r.Body)))
			written = true
			renderedCount++
		}
		if !written {
			b.WriteString("No reviews yet.\n")
		}
		return b.String()
	}
	return "# 404\n"
}

package memba_reviews_v2

import (
	"crypto/sha256"
	"encoding/hex"
)

// ModerationState is a bounded copied snapshot, including hidden/deleted items.
// No pointer or body is exposed. BodyHash binds edits even within the same block.
// Reactions and cumulative flag counts are not moderation authorization inputs.
type ModerationState struct {
	ID        uint64
	Review    bool
	ParentID  uint64
	Subject   string
	Author    address
	Rating    int
	BodyHash  string
	CreatedAt int64
	EditedAt  int64
	Hidden    bool
	Deleted   bool
	Flagged   bool
}

func moderationBodyHash(body string) string {
	sum := sha256.Sum256([]byte(body))
	return hex.EncodeToString(sum[:])
}

// GetModerationState returns a zero value for an absent ID. The flagged-index
// bit is distinct from historical flags; Unhide removes only the index entry.
func GetModerationState(id uint64) ModerationState {
	_, flagged := flaggedIDs.Get(strID(id))
	if r, ok := getReview(id); ok {
		return ModerationState{ID: r.ID, Review: true, Subject: r.Subject, Author: r.Author,
			Rating: r.Rating, BodyHash: moderationBodyHash(r.Body), CreatedAt: r.CreatedAt,
			EditedAt: r.EditedAt, Hidden: r.Hidden, Deleted: r.Deleted, Flagged: flagged}
	}
	if c, ok := getComment(id); ok {
		return ModerationState{ID: c.ID, ParentID: c.ReviewID, Author: c.Author,
			BodyHash: moderationBodyHash(c.Body), CreatedAt: c.CreatedAt, EditedAt: c.EditedAt,
			Hidden: c.Hidden, Deleted: c.Deleted, Flagged: flagged}
	}
	return ModerationState{}
}

package memba_reviews_v2

import "chain/runtime/unsafe"

// publisherAtLoad captures the AddPackage signer during package initialization.
// Keeping the unsafe load-time primitive separate from crossing entrypoints lets
// privileged calls use only the frame-verified cur.IsCurrent/cur.Previous API.
func publisherAtLoad() address { return unsafe.OriginCaller() }

// Package daoauth writes the arguments of a governed action as one typed,
// canonical string. memba_gov stores that string with the proposal and the
// target realm rebuilds it from its real arguments when it consumes the
// approval: the two must be equal byte for byte. Each value has exactly one
// spelling, so equal actions always encode to equal strings.
//
// Fields are joined by "|":
//
//	u:<uint64>        decimal, no sign, no leading zero
//	i:<int64>         decimal, "-" only when negative, no leading zero
//	b:0 or b:1        bool
//	a:<address>       the lowercase bech32 text the chain gives a caller
//	s:<len>:<text>    length-prefixed printable ASCII (0x20-0x7E)
//
// Strings are compared as raw bytes, with no Unicode normalisation; text is
// printable ASCII so that what a voter reads is exactly what executes.
package daoauth

import (
	"errors"
	"strconv"
	"strings"
)

const (
	MaxArgs = 1024 // bytes of one encoded argument string
	MaxText = 512  // bytes of one string field
)

var (
	ErrSyntax  = errors.New("daoauth: malformed argument string")
	ErrAddress = errors.New("daoauth: address is not lowercase bech32")
	ErrText    = errors.New("daoauth: text must be printable ASCII of at most 512 bytes")
	ErrLength  = errors.New("daoauth: arguments exceed 1024 bytes")
)

// Args accumulates fields in order. Methods panic on a value that has no
// canonical form, so a realm can never build an approval nobody can match.
type Args struct{ fields []string }

func New() *Args { return &Args{} }

func (a *Args) Uint(v uint64) *Args { return a.add("u:" + strconv.FormatUint(v, 10)) }
func (a *Args) Int(v int64) *Args   { return a.add("i:" + strconv.FormatInt(v, 10)) }

func (a *Args) Bool(v bool) *Args {
	if v {
		return a.add("b:1")
	}
	return a.add("b:0")
}

func (a *Args) Addr(v address) *Args {
	if !ValidAddress(v) {
		panic(ErrAddress.Error())
	}
	return a.add("a:" + string(v))
}

func (a *Args) Str(v string) *Args {
	if !ValidText(v) {
		panic(ErrText.Error())
	}
	return a.add("s:" + strconv.Itoa(len(v)) + ":" + v)
}

func (a *Args) add(f string) *Args {
	a.fields = append(a.fields, f)
	return a
}

// String returns the encoding. It panics past MaxArgs.
func (a *Args) String() string {
	s := strings.Join(a.fields, "|")
	if len(s) > MaxArgs {
		panic(ErrLength.Error())
	}
	return s
}

// Field is one decoded value: Tag is 'u', 'i', 'b', 'a' or 's', and Value
// is its text, without the length prefix for strings.
type Field struct {
	Tag   byte
	Value string
}

// Parse decodes s and refuses any text that is not the canonical encoding of
// its own fields. The empty string is the encoding of no fields.
func Parse(s string) ([]Field, error) {
	if len(s) > MaxArgs {
		return nil, ErrLength
	}
	var out []Field
	for len(s) > 0 {
		if len(s) < 2 || s[1] != ':' {
			return nil, ErrSyntax
		}
		tag, rest := s[0], s[2:]
		var v string
		if tag == 's' {
			i := strings.IndexByte(rest, ':')
			if i < 1 {
				return nil, ErrSyntax
			}
			n, err := strconv.Atoi(rest[:i])
			if err != nil || n < 0 || strconv.Itoa(n) != rest[:i] || n > len(rest)-i-1 {
				return nil, ErrSyntax
			}
			v, rest = rest[i+1:i+1+n], rest[i+1+n:]
			if !ValidText(v) {
				return nil, ErrText
			}
		} else {
			i := strings.IndexByte(rest, '|')
			if i < 0 {
				i = len(rest)
			}
			v, rest = rest[:i], rest[i:]
			if err := checkScalar(tag, v); err != nil {
				return nil, err
			}
		}
		out = append(out, Field{Tag: tag, Value: v})
		if len(rest) > 0 {
			if rest[0] != '|' || len(rest) == 1 {
				return nil, ErrSyntax
			}
			rest = rest[1:]
		}
		s = rest
	}
	return out, nil
}

func checkScalar(tag byte, v string) error {
	switch tag {
	case 'u':
		n, err := strconv.ParseUint(v, 10, 64)
		if err != nil || strconv.FormatUint(n, 10) != v {
			return ErrSyntax
		}
	case 'i':
		n, err := strconv.ParseInt(v, 10, 64)
		if err != nil || strconv.FormatInt(n, 10) != v {
			return ErrSyntax
		}
	case 'b':
		if v != "0" && v != "1" {
			return ErrSyntax
		}
	case 'a':
		if !ValidAddress(address(v)) {
			return ErrAddress
		}
	default:
		return ErrSyntax
	}
	return nil
}

// ValidText reports whether s is at most MaxText bytes of printable ASCII
// (0x20 to 0x7E): no control, invisible, combining or direction-changing
// character can make a value read differently from what executes.
func ValidText(s string) bool {
	if len(s) > MaxText {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < 0x20 || s[i] > 0x7e {
			return false
		}
	}
	return true
}

// The chain decodes four texts to one address: the lowercase bech32 text it
// gives a caller, that text in capitals, and the bech32m checksum in either
// case. Only the first ever equals cur.Previous().Address(). The check below
// is the one of launchpad meta/v1, copied rather than imported so governance
// does not depend on the Launchpad release. It reads the text instead of
// decoding it.

// bech32Value holds, for each character of the bech32 alphabet, its 5-bit
// value plus one. Zero marks every other byte, capitals included.
var bech32Value = [256]byte{
	'q': 1, 'p': 2, 'z': 3, 'r': 4, 'y': 5, '9': 6, 'x': 7, '8': 8,
	'g': 9, 'f': 10, '2': 11, 't': 12, 'v': 13, 'd': 14, 'w': 15, '0': 16,
	's': 17, '3': 18, 'j': 19, 'n': 20, '5': 21, '4': 22, 'k': 23, 'h': 24,
	'c': 25, 'e': 26, '6': 27, 'm': 28, 'u': 29, 'a': 30, '7': 31, 'l': 32,
}

// bech32Gen[t] is the XOR of the BIP-173 generators selected by the bits of t.
var bech32Gen = [32]uint32{
	0x00000000, 0x3b6a57b2, 0x26508e6d, 0x1d3ad9df,
	0x1ea119fa, 0x25cb4e48, 0x38f19797, 0x039bc025,
	0x3d4233dd, 0x0628646f, 0x1b12bdb0, 0x2078ea02,
	0x23e32a27, 0x18897d95, 0x05b3a44a, 0x3ed9f3f8,
	0x2a1462b3, 0x117e3501, 0x0c44ecde, 0x372ebb6c,
	0x34b57b49, 0x0fdf2cfb, 0x12e5f524, 0x298fa296,
	0x1756516e, 0x2c3c06dc, 0x3106df03, 0x0a6c88b1,
	0x09f74894, 0x329d1f26, 0x2fa7c6f9, 0x14cd914b,
}

// bech32PrefixState is the checksum state after the prefix "g" (3, 0, 7).
const bech32PrefixState uint32 = 0x8c07

// ValidAddress reports whether a is "g1" and 38 lowercase bech32 characters
// whose checksum is the original bech32 one.
func ValidAddress(a address) bool {
	s := string(a)
	if len(s) != 40 || s[0] != 'g' || s[1] != '1' {
		return false
	}
	chk := bech32PrefixState
	for i := 2; i < 40; i++ {
		v := bech32Value[s[i]]
		if v == 0 {
			return false
		}
		chk = (chk&0x1ffffff)<<5 ^ uint32(v-1) ^ bech32Gen[chk>>25]
	}
	return chk == 1
}

// Package memba_gov is the Memba DAO governance core. It holds the roster,
// proposals and votes, and grants nothing by itself: a governed realm asks
// for an approval by crossing-calling Consume before a privileged step, and
// the core checks that the caller is exactly the realm the proposal names,
// with exactly the arguments members voted on. The core never calls another
// realm.
//
// Rules (design note GOV-1, approved 2026-10-06):
//   - members propose, vote and execute by direct calls from their own
//     account, and an invited key joins by its own direct call; only a
//     governed realm's crossing call reaches Consume;
//   - a key counts toward the roster only after it signed Join itself;
//   - one action per proposal, stored by value; approvals are used once;
//   - every executed roster action and every Join invalidates every open
//     proposal, so votes always count against an unchanged roster;
//   - Consume invalidates the other open proposals of its (target, scope).
package memba_gov

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/samcrew/avl"
	"gno.land/p/samcrew/daoauth"
)

const (
	corePath  = "gno.land/r/samcrew/memba_gov"
	MaxSeats  = 25
	MinSeats  = 2
	MaxScope  = 160
	MaxNote   = 280
	MaxAction = 64

	actAddMember      = "AddMember"
	actRemoveMember   = "RemoveMember"
	actSetWeight      = "SetWeight"
	actRecover        = "Recover"
	actRemoveInactive = "RemoveInactive"
	actUninvite       = "Uninvite"

	voteYes     = "yes"
	voteNo      = "no"
	voteAbstain = "abstain"
)

type person struct {
	id         string
	addr       address
	weight     int
	lastActive int64  // unix seconds of the last Propose, Vote, Execute or Join
	rosterPid  uint64 // this person's open roster proposal, if any
}

// invite seats addr as id (a new person) or, for a recovery, gives the
// existing person id the new key addr, once addr itself calls Join.
type invite struct {
	id      string
	addr    address
	weight  int
	expires int64 // unix seconds
}

type ballot struct {
	person string
	vote   string
	since  int64 // unix start of the current uninterrupted YES streak
}

type proposal struct {
	id                    uint64
	target, action, args  string
	scope, note, proposer string
	subject               string // the person a roster action names
	class                 int
	scopeGen, globalGen   uint64
	created               int64 // unix seconds
	ballots               []ballot
	consumed              bool
}

var (
	seated    []*person
	invites   []*invite
	proposals = avl.NewTree() // padded id -> *proposal
	scopes    = avl.NewTree() // target + "\n" + scope -> uint64 generation
	lastID    uint64
	globalGen uint64
)

func init() { seedRoster() }

func seedRoster() {
	t := now()
	for _, s := range seedSeated {
		seated = append(seated, &person{id: s.id, addr: s.addr, weight: s.weight, lastActive: t})
	}
	for _, s := range seedInvited {
		invites = append(invites, &invite{id: s.id, addr: s.addr, weight: s.weight, expires: t + secs(SeedInviteTTL)})
	}
	checkRoster()
}

// now is the block time in unix seconds; every stored time uses it.
func now() int64 { return time.Now().Unix() }

func secs(d time.Duration) int64 { return int64(d / time.Second) }

// ── Writes (direct calls from a member's account) ──────────────────────

// Propose files one action. target is the realm that will consume it, or
// this realm for a roster action; scope is the invalidation key that realm
// computes for the action; class is at least the class it requires.
func Propose(cur realm, target, action, args, scope string, class int, note string) uint64 {
	m := member(cur)
	if !validTarget(target) || !validAction(action) || len(scope) > MaxScope || len(note) > MaxNote ||
		!daoauth.ValidText(scope) || !daoauth.ValidText(note) {
		panic("memba_gov: invalid target, action, scope or note")
	}
	fields, err := daoauth.Parse(args)
	if err != nil {
		panic(err.Error())
	}
	if target == corePath {
		if scope != "" || class != rosterClass(action) {
			panic("memba_gov: a roster action has no scope and a fixed class")
		}
		checkRosterAction(action, fields)
		if m.rosterPid != 0 && isOpen(m.rosterPid) {
			panic("memba_gov: you already have an open roster proposal")
		}
	} else if class < Routine || class > Critical {
		panic("memba_gov: unknown class")
	}
	lastID++
	p := &proposal{id: lastID, target: target, action: action, args: args, scope: scope, note: note,
		proposer: m.id, class: class, scopeGen: scopeGen(target, scope), globalGen: globalGen, created: now()}
	proposals.Set(key(p.id), p)
	if target == corePath {
		p.subject = fields[0].Value
		m.rosterPid = p.id
	}
	m.lastActive = p.created
	return p.id
}

// Vote records yes, no or abstain until the voting deadline. After it, a
// YES can still be withdrawn while the proposal is not executed or expired,
// so members can stop an approval they no longer back.
func Vote(cur realm, pid uint64, choice string) {
	m := member(cur)
	if choice != voteYes && choice != voteNo && choice != voteAbstain {
		panic("memba_gov: vote yes, no or abstain")
	}
	p := mustGet(pid)
	t := now()
	mine := -1
	for i, b := range p.ballots {
		if b.person == m.id {
			mine = i
		}
	}
	st, _ := state(p)
	open := st == stVoting || st == stTimelocked || st == stReady
	withdrawing := mine >= 0 && p.ballots[mine].vote == voteYes && choice != voteYes
	if !open || (t >= p.created+secs(VotingPeriod) && !withdrawing) {
		panic("memba_gov: voting is closed")
	}
	m.lastActive = t
	switch {
	case mine < 0:
		p.ballots = append(p.ballots, ballot{person: m.id, vote: choice, since: t})
	case p.ballots[mine].vote != choice:
		p.ballots[mine] = ballot{person: m.id, vote: choice, since: t}
	}
}

// Join seats the caller's invitation: a new person, or a recovered key.
func Join(cur realm) {
	addr := user(cur)
	t := now()
	for i, inv := range invites {
		if inv.addr != addr || t > inv.expires {
			continue
		}
		invites = append(invites[:i:i], invites[i+1:]...)
		if p := personByID(inv.id); p != nil {
			p.addr = addr
			p.lastActive = t
		} else {
			if len(seated) >= MaxSeats {
				panic("memba_gov: the roster is full (" + strconv.Itoa(MaxSeats) + " seats)")
			}
			seated = append(seated, &person{id: inv.id, addr: addr, weight: inv.weight, lastActive: t})
		}
		globalGen++
		checkRoster()
		return
	}
	panic("memba_gov: no open invitation for " + string(addr))
}

// Execute runs a ready roster action of this realm. The roster it was
// checked against at Propose is unchanged: any change would have
// invalidated it.
func Execute(cur realm, pid uint64) {
	m := member(cur)
	p := mustGet(pid)
	if p.target != corePath {
		panic("memba_gov: only roster actions run here; the target realm consumes the others")
	}
	if st, _ := state(p); st != stReady {
		panic("memba_gov: proposal is " + st)
	}
	fields, _ := daoauth.Parse(p.args)
	id := p.subject
	switch p.action {
	case actAddMember:
		addInvite(id, address(fields[1].Value), weightField(fields[2]), VotedInviteTTL)
	case actRecover:
		addInvite(id, address(fields[1].Value), 0, VotedInviteTTL)
	case actSetWeight:
		personByID(id).weight = weightField(fields[1])
	case actRemoveMember, actRemoveInactive, actUninvite:
		removePerson(id)
	}
	p.consumed = true
	m.lastActive = now()
	globalGen++
	checkRoster()
}

// ── The only cross-realm entry ──────────────────────────────────────────

// Consume is crossing-called by a governed realm right before the step a
// proposal approved. It panics unless the caller is exactly the proposal's
// target, the action, arguments and scope are the voted ones byte for byte,
// the class is at least minClass, the proposal is ready, and executor, the
// account that called the target directly, is a seated member. It marks the
// proposal used and invalidates the other open proposals of (target, scope).
func Consume(cur realm, pid uint64, action, args, scope string, minClass int, executor address) {
	if !cur.IsCurrent() {
		panic("memba_gov: stale realm")
	}
	caller := cur.Previous().PkgPath()
	p := mustGet(pid)
	// A roster action runs only through Execute.
	if caller != p.target || p.target == corePath {
		panic("memba_gov: proposal " + strconv.FormatUint(pid, 10) + " is not for " + caller)
	}
	if action != p.action || args != p.args || scope != p.scope {
		panic("memba_gov: action, arguments or scope differ from the vote")
	}
	if p.class < minClass {
		panic("memba_gov: class below what the target requires")
	}
	if st, _ := state(p); st != stReady {
		panic("memba_gov: proposal is " + st)
	}
	// Being named executor is not activity: the target, not the member,
	// supplies that address.
	if personByAddr(executor) == nil {
		panic("memba_gov: executor is not a seated member")
	}
	p.consumed = true
	scopes.Set(p.target+"\n"+p.scope, scopeGen(p.target, p.scope)+1)
}

// IsMember reports whether addr is a seated member's current key.
func IsMember(addr address) bool { return personByAddr(addr) != nil }

// PersonOf returns the id of the seated member whose current key is addr,
// or "". The id survives a key recovery.
func PersonOf(addr address) string {
	if p := personByAddr(addr); p != nil {
		return p.id
	}
	return ""
}

// ── Helpers ─────────────────────────────────────────────────────────────

// user returns the account that called this realm directly.
func user(cur realm) address {
	if !cur.IsCurrent() {
		panic("memba_gov: stale realm")
	}
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("memba_gov: call directly from your account")
	}
	return prev.Address()
}

func member(cur realm) *person {
	addr := user(cur)
	m := personByAddr(addr)
	if m == nil {
		panic("memba_gov: not a seated member: " + string(addr))
	}
	return m
}

// rosterClass and rosterDelay fix how each roster action passes.
func rosterClass(action string) int {
	switch action {
	case actRemoveInactive:
		return Routine
	case actUninvite: // fast for a leaked invitee key, never a two-person lever
		return Financial
	}
	return Critical
}

func rosterDelay(action string) time.Duration {
	switch action {
	case actUninvite:
		return 0
	case actRemoveInactive:
		return InactiveDelay
	}
	return RosterDelay
}

// checkRosterAction validates a roster action's fields against the roster.
func checkRosterAction(action string, f []daoauth.Field) {
	shape := map[string]string{actAddMember: "sau", actRemoveMember: "s", actSetWeight: "su",
		actRecover: "sa", actRemoveInactive: "s", actUninvite: "s"}[action]
	if shape == "" || len(f) != len(shape) {
		panic("memba_gov: unknown roster action or wrong arguments")
	}
	for i := range f {
		if f[i].Tag != shape[i] {
			panic("memba_gov: wrong roster arguments")
		}
	}
	id := f[0].Value
	p := personByID(id)
	switch action {
	case actAddMember, actUninvite:
		if p != nil || !validID(id) {
			panic("memba_gov: person id taken or invalid")
		}
	default:
		if p == nil {
			panic("memba_gov: no seated person " + id)
		}
	}
	switch action {
	case actAddMember, actRecover:
		if addrTaken(address(f[1].Value), id) {
			panic("memba_gov: address already seated or invited")
		}
	case actUninvite:
		if !invited(id) {
			panic("memba_gov: no open invitation for " + id)
		}
	case actRemoveMember, actRemoveInactive:
		if len(seated) <= MinSeats {
			panic("memba_gov: the roster cannot shrink below " + strconv.Itoa(MinSeats))
		}
	}
	if action == actAddMember {
		weightField(f[2])
	}
	if action == actSetWeight && weightField(f[1]) == p.weight {
		panic("memba_gov: weight unchanged")
	}
	if action == actRemoveInactive && now() <= p.lastActive+secs(InactiveAfter) {
		panic("memba_gov: active within " + strconv.Itoa(int(secs(InactiveAfter)/86400)) + " days")
	}
}

func weightField(f daoauth.Field) int {
	if f.Value != "1" && f.Value != "2" {
		panic("memba_gov: weight is 1 or 2")
	}
	return int(f.Value[0] - '0')
}

func addInvite(id string, addr address, weight int, ttl time.Duration) {
	dropInvite(id)
	invites = append(invites, &invite{id: id, addr: addr, weight: weight, expires: now() + secs(ttl)})
}

func dropInvite(id string) {
	kept := invites[:0:0]
	for _, inv := range invites {
		if inv.id != id {
			kept = append(kept, inv)
		}
	}
	invites = kept
}

func removePerson(id string) {
	kept := seated[:0:0]
	for _, p := range seated {
		if p.id != id {
			kept = append(kept, p)
		}
	}
	seated = kept
	dropInvite(id)
}

// checkRoster enforces the bounds, valid ids, addresses and weights, and the
// uniqueness of ids and of addresses across seats and open invitations. An
// invitation may name a seated id: that is a recovery, with no weight.
func checkRoster() {
	if len(seated) < MinSeats || len(seated) > MaxSeats {
		panic("memba_gov: roster size out of bounds")
	}
	seen := map[string]bool{}
	for _, p := range seated {
		if seen["i"+p.id] || seen["a"+string(p.addr)] || !validID(p.id) || !daoauth.ValidAddress(p.addr) || p.weight < 1 || p.weight > 2 {
			panic("memba_gov: invalid roster")
		}
		seen["i"+p.id], seen["a"+string(p.addr)] = true, true
	}
	t := now()
	for _, inv := range invites {
		if t > inv.expires {
			continue
		}
		recovery := personByID(inv.id) != nil
		if seen["v"+inv.id] || seen["a"+string(inv.addr)] || !validID(inv.id) || !daoauth.ValidAddress(inv.addr) ||
			(!recovery && (inv.weight < 1 || inv.weight > 2)) {
			panic("memba_gov: invalid invitation")
		}
		seen["v"+inv.id], seen["a"+string(inv.addr)] = true, true
	}
}

// addrTaken reports whether a is seated, or invited for someone other than
// id: a newer invitation for id replaces id's own.
func addrTaken(a address, id string) bool {
	if personByAddr(a) != nil {
		return true
	}
	for _, inv := range invites {
		if inv.addr == a && inv.id != id && now() <= inv.expires {
			return true
		}
	}
	return false
}

func invited(id string) bool {
	for _, inv := range invites {
		if inv.id == id && now() <= inv.expires {
			return true
		}
	}
	return false
}

func personByAddr(a address) *person {
	for _, p := range seated {
		if p.addr == a {
			return p
		}
	}
	return nil
}

func personByID(id string) *person {
	for _, p := range seated {
		if p.id == id {
			return p
		}
	}
	return nil
}

func weightOf(id string) int {
	if p := personByID(id); p != nil {
		return p.weight
	}
	return 0
}

func seatedTotals() (w, n int) {
	for _, p := range seated {
		w += p.weight
	}
	return w, len(seated)
}

func scopeGen(target, scope string) uint64 {
	if v, ok := scopes.Get(target + "\n" + scope); ok {
		return v.(uint64)
	}
	return 0
}

func isOpen(pid uint64) bool {
	st, _ := state(mustGet(pid))
	return st == stVoting || st == stTimelocked || st == stReady
}

func mustGet(pid uint64) *proposal {
	v, ok := proposals.Get(key(pid))
	if !ok {
		panic("memba_gov: no proposal " + strconv.FormatUint(pid, 10))
	}
	return v.(*proposal)
}

func key(id uint64) string {
	s := strconv.FormatUint(id, 10)
	return strings.Repeat("0", 20-len(s)) + s
}

// validTarget accepts a realm path: no user ("") or MsgRun (gno.land/e/)
// identity, no sub-realm ("#"), lowercase path characters only.
func validTarget(t string) bool {
	return strings.HasPrefix(t, "gno.land/r/") && len(t) <= 256 && !strings.Contains(t, "//") &&
		!strings.HasSuffix(t, "/") && only(t, lower+digits+"_/.")
}

func validAction(a string) bool {
	return a != "" && len(a) <= MaxAction && only(a, lower+upper+digits+"_.")
}

func validID(id string) bool { return id != "" && len(id) <= 32 && only(id, lower+digits+"_-") }

const (
	lower  = "abcdefghijklmnopqrstuvwxyz"
	upper  = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
	digits = "0123456789"
)

// only reports whether every byte of s is in set.
func only(s, set string) bool {
	for i := 0; i < len(s); i++ {
		if strings.IndexByte(set, s[i]) < 0 {
			return false
		}
	}
	return true
}

package memba_gov

import "time"

// Classes. A target hard-codes the minimum class of each action it governs.
const (
	Routine   = 1
	Financial = 2
	Critical  = 3
)

// A route is one way a proposal passes: a rule on the YES votes of the
// seated roster and the delay that follows. Thresholds are fractions of the
// seated weight W and persons N. Every rule needs at least two persons: the
// critical ones because N is at least 2.
type route struct {
	rule  int
	delay time.Duration
}

const (
	ruleRoutine = iota
	ruleFinancial
	ruleWeighted
	ruleHeadcount
)

func meets(rule, w, p, W, N int) bool {
	switch rule {
	case ruleRoutine: // >= 3/8 of the weight
		return 8*w >= 3*W && p >= 2
	case ruleFinancial: // >= 3/5 of the weight and a majority of persons
		return 5*w >= 3*W && p >= 3 && 2*p > N
	case ruleWeighted: // >= 2/3 of the weight and a majority of persons
		return 3*w >= 2*W && 2*p > N
	case ruleHeadcount: // >= 2/3 of the persons and a majority of the weight
		return 3*p >= 2*N && 2*w > W
	}
	return false
}

// routes returns the ways proposal p passes: its class sets the rules, and
// a roster action of this realm has its own delay on every route.
func routes(p *proposal) []route {
	var rs []route
	switch p.class {
	case Routine:
		rs = []route{{ruleRoutine, 0}}
	case Financial:
		rs = []route{{ruleFinancial, 0}}
	default:
		rs = []route{{ruleWeighted, WeightedDelay}, {ruleHeadcount, HeadcountDelay}}
	}
	if p.target == corePath {
		for i := range rs {
			rs[i].delay = rosterDelay(p.action)
		}
	}
	return rs
}

// A streak is one current YES ballot: when it began and its voter's weight.
type streak struct {
	since  int64
	weight int
}

// yesStreaks returns p's current YES ballots, oldest streak first.
func yesStreaks(p *proposal) []streak {
	var ys []streak
	for _, b := range p.ballots {
		if b.vote != voteYes {
			continue
		}
		x := streak{b.since, weightOf(b.person)}
		ys = append(ys, x)
		i := len(ys) - 1
		for ; i > 0 && ys[i-1].since > x.since; i-- {
			ys[i] = ys[i-1]
		}
		ys[i] = x
	}
	return ys
}

// qualifiedSince returns when (unix seconds) the earliest coalition still
// voting YES without interruption first met rule, or 0. The coalition of a
// start time is every YES streak begun no later; every rule only grows with
// more votes, so the first prefix of ys that meets it ends on that time
// (streaks begun in the same second share it). A voter the rest of the
// coalition does not need cannot postpone the clock by withdrawing and
// rejoining.
func qualifiedSince(ys []streak, rule, W, N int) int64 {
	w, n := 0, 0
	for _, x := range ys {
		w += x.weight
		n++
		if meets(rule, w, n, W, N) {
			return x.since
		}
	}
	return 0
}

// Proposal states, in the order a reader checks them.
const (
	stExecuted    = "executed"
	stInvalidated = "invalidated"
	stExpired     = "expired"
	stReady       = "ready"
	stTimelocked  = "timelocked"
	stVoting      = "voting"
)

// state returns p's status and, once some route qualified, the earliest
// unix time it is or becomes executable (0 before). Voting ends just before
// the deadline second; readyAt and the end of the execution window are
// inclusive.
func state(p *proposal) (string, int64) {
	if p.consumed {
		return stExecuted, 0
	}
	if p.globalGen != globalGen || p.scopeGen != scopeGen(p.target, p.scope) || vetoed(p) {
		return stInvalidated, 0
	}
	t := now()
	W, N := seatedTotals()
	ys := yesStreaks(p)
	var readyAt, longest int64
	for _, r := range routes(p) {
		if d := secs(r.delay); d > longest {
			longest = d
		}
		if since := qualifiedSince(ys, r.rule, W, N); since != 0 {
			if at := since + secs(r.delay); readyAt == 0 || at < readyAt {
				readyAt = at
			}
		}
	}
	deadline := p.created + secs(VotingPeriod)
	if t > deadline+longest+secs(ExecutionWindow) || (readyAt == 0 && t >= deadline) {
		return stExpired, readyAt
	}
	switch {
	case readyAt == 0:
		return stVoting, readyAt
	case t < readyAt:
		return stTimelocked, readyAt
	}
	return stReady, readyAt
}

// vetoed reports whether the member a RemoveInactive names has been active
// since the proposal: proposing, voting, executing or joining vetoes it.
func vetoed(p *proposal) bool {
	if p.target != corePath || p.action != actRemoveInactive {
		return false
	}
	m := personByID(p.subject)
	return m != nil && m.lastActive >= p.created
}

package memba_gov

import (
	"strconv"
	"time"
)

// Reads make no cross-realm call and never start or advance a clock. Ids and
// unix times are JSON strings (clients parse them as big integers). Stored
// text is printable ASCII, so the escapers work byte by byte.

// MaxListed is the most proposals ProposalsJSON and Render return at once.
const MaxListed = 20

// RosterJSON lists seated members and open invitations.
func RosterJSON() string {
	W, N := seatedTotals()
	b := []byte(`{"weight":` + strconv.Itoa(W) + `,"persons":` + strconv.Itoa(N) + `,"members":[`)
	for i, p := range seated {
		if i > 0 {
			b = append(b, ',')
		}
		b = append(b, `{"id":`...)
		b = q(b, p.id)
		b = append(b, `,"address":`...)
		b = q(b, string(p.addr))
		b = append(b, `,"weight":`+strconv.Itoa(p.weight)+`,"lastActive":"`+unix(p.lastActive)+`"}`...)
	}
	b = append(b, `],"invitations":[`...)
	n := 0
	for _, inv := range invites {
		if now() > inv.expires {
			continue
		}
		if n > 0 {
			b = append(b, ',')
		}
		n++
		b = append(b, `{"id":`...)
		b = q(b, inv.id)
		b = append(b, `,"address":`...)
		b = q(b, string(inv.addr))
		b = append(b, `,"weight":`+strconv.Itoa(inv.weight)+`,"expires":"`+unix(inv.expires)+`"}`...)
	}
	return string(append(b, `]}`...))
}

// ProposalJSON returns one proposal with its ballots and current status, or
// null for an unknown id.
func ProposalJSON(pid uint64) string {
	v, ok := proposals.Get(key(pid))
	if !ok {
		return "null"
	}
	return string(proposalJSON(nil, v.(*proposal)))
}

// ConstantsJSON returns the fixed policy: durations in seconds, roster bounds.
func ConstantsJSON() string {
	sec := func(d time.Duration) string { return unix(secs(d)) }
	return `{"votingPeriod":` + sec(VotingPeriod) + `,"executionWindow":` + sec(ExecutionWindow) +
		`,"criticalWeightDelay":` + sec(WeightedDelay) + `,"criticalHeadcountDelay":` + sec(HeadcountDelay) +
		`,"rosterDelay":` + sec(RosterDelay) + `,"inactiveDelay":` + sec(InactiveDelay) +
		`,"inactiveAfter":` + sec(InactiveAfter) + `,"minSeats":` + strconv.Itoa(MinSeats) +
		`,"maxSeats":` + strconv.Itoa(MaxSeats) + `,"maxListed":` + strconv.Itoa(MaxListed) + `}`
}

// ProposalsJSON lists up to limit proposals (at most MaxListed) with ids
// below before, newest first; before = 0 starts from the newest.
func ProposalsJSON(before uint64, limit int) string {
	if limit < 1 || limit > MaxListed {
		limit = MaxListed
	}
	b := []byte(`{"total":"` + strconv.FormatUint(lastID, 10) + `","proposals":[`)
	if before != 1 {
		end := "" // a descending range includes its end
		if before > 1 {
			end = key(before - 1)
		}
		n := 0
		proposals.ReverseIterate("", end, func(_ string, v any) bool {
			if n > 0 {
				b = append(b, ',')
			}
			b = proposalJSON(b, v.(*proposal))
			n++
			return n >= limit
		})
	}
	return string(append(b, `]}`...))
}

func proposalJSON(b []byte, p *proposal) []byte {
	st, readyAt := state(p)
	b = append(b, `{"id":"`+strconv.FormatUint(p.id, 10)+`","target":`...)
	b = q(b, p.target)
	b = append(b, `,"action":`...)
	b = q(b, p.action)
	b = append(b, `,"args":`...)
	b = q(b, p.args)
	b = append(b, `,"scope":`...)
	b = q(b, p.scope)
	b = append(b, `,"class":`+strconv.Itoa(p.class)+`,"proposer":`...)
	b = q(b, p.proposer)
	b = append(b, `,"note":`...)
	b = q(b, p.note)
	b = append(b, `,"created":"`+unix(p.created)+`","deadline":"`+unix(p.created+secs(VotingPeriod))+
		`","status":"`+st+`","readyAt":"`+unix(readyAt)+`","ballots":[`...)
	for i, bl := range p.ballots {
		if i > 0 {
			b = append(b, ',')
		}
		b = append(b, `{"person":`...)
		b = q(b, bl.person)
		b = append(b, `,"vote":"`+bl.vote+`","since":"`+unix(bl.since)+`"}`...)
	}
	return append(b, `]}`...)
}

// Render shows the roster and the latest proposals. Each proposal's line
// holds only fields the realm sets (id, status, class, proposer id); every
// value a proposer wrote follows as its own labelled, escaped item, so none
// can forge a field.
func Render(_ string) string {
	W, N := seatedTotals()
	b := []byte("# Memba DAO governance\n\n## Members: " + strconv.Itoa(N) + " seated, weight " + strconv.Itoa(W) + "\n\n")
	for _, p := range seated {
		b = append(b, "- "...)
		b = md(b, p.id)
		b = append(b, " (weight "+strconv.Itoa(p.weight)+"): "...)
		b = md(b, string(p.addr))
		b = append(b, '\n')
	}
	b = append(b, "\n## Latest proposals\n\n"...)
	n := 0
	proposals.ReverseIterate("", "", func(_ string, v any) bool {
		p := v.(*proposal)
		st, _ := state(p)
		b = append(b, "- #"+strconv.FormatUint(p.id, 10)+" "+st+", class "+strconv.Itoa(p.class)+", by "...)
		b = md(b, p.proposer)
		b = append(b, '\n')
		for _, f := range [][2]string{{"target", p.target}, {"action", p.action}, {"args", p.args}, {"scope", p.scope}, {"proposer's note", p.note}} {
			if f[1] != "" {
				b = append(b, "  - "+f[0]+": "...)
				b = md(b, f[1])
				b = append(b, '\n')
			}
		}
		n++
		return n >= MaxListed
	})
	if n == 0 {
		b = append(b, "None yet.\n"...)
	}
	return string(b)
}

// unix formats a unix-second time (0 = none).
func unix(t int64) string { return strconv.FormatInt(t, 10) }

// grow makes room for n more bytes. The VM's append reallocates to the exact
// length, so appending byte by byte past capacity would copy the whole
// buffer each time; doubling keeps the escapers linear.
func grow(b []byte, n int) []byte {
	if cap(b)-len(b) >= n {
		return b
	}
	nb := make([]byte, len(b), 2*cap(b)+n)
	copy(nb, b)
	return nb
}

// Escaper classes of each ASCII byte, one table lookup per byte: '.' is
// copied, 'b' gets a backslash, 'u' becomes \u00XX, 'e' a numeric
// character reference. Stored text is printable ASCII (0x7f masks the
// index; no other byte reaches here).
const (
	qClass = "uuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuu" +
		"..b...u.....................u.u." +
		"............................b..." +
		"...............................u"
	// Markdown punctuation is backslash-escaped; < > & and g become
	// references, so no HTML, entity or " g1..." address mention (a gnoweb
	// user link) can form.
	mdClass = "eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee" +
		".bbbb.ebbbbb.bbb..........b.ebe." +
		"b..........................bbbbb" +
		"b......e...................bbbbe"
	hexDigits = "0123456789abcdef"
)

// q appends s as a JSON string; < > & are escaped so the text stays inert
// in HTML.
func q(b []byte, s string) []byte {
	b = grow(b, 6*len(s)+2)
	b = append(b, '"')
	for i := 0; i < len(s); i++ {
		switch c := s[i]; qClass[c&0x7f] {
		case '.':
			b = append(b, c)
		case 'b':
			b = append(b, '\\', c)
		default:
			b = append(b, '\\', 'u', '0', '0', hexDigits[c>>4], hexDigits[c&0xf])
		}
	}
	return append(b, '"')
}

// md appends s with every character Markdown, HTML or gnoweb could act on
// made literal.
func md(b []byte, s string) []byte {
	b = grow(b, 6*len(s))
	for i := 0; i < len(s); i++ {
		switch c := s[i]; mdClass[c&0x7f] {
		case '.':
			b = append(b, c)
		case 'b':
			b = append(b, '\\', c)
		default: // &#NN; or &#NNN;
			b = append(b, '&', '#')
			if c >= 100 {
				b = append(b, '0'+c/100)
			}
			b = append(b, '0'+c/10%10, '0'+c%10, ';')
		}
	}
	return b
}

