package memba_bridge_v1

import (
	"chain"
	"chain/banker"
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"strings"

	"gno.land/p/samcrew/daoauth"
	gov "gno.land/r/samcrew/memba_gov"
	escrow "gno.land/r/samcrew/escrow_v4"
	badges "gno.land/r/samcrew/gnobuilders_badges_v2"
	appstore "gno.land/r/samcrew/memba_appstore_v3"
	arcade "gno.land/r/samcrew/memba_arcade_leaderboard_v1"
	channels "gno.land/r/samcrew/memba_dao_channels_v2"
	feed "gno.land/r/samcrew/memba_feed_v1"
	feedback "gno.land/r/samcrew/memba_feedback_v2"
	market "gno.land/r/samcrew/memba_market_config"
	quest "gno.land/r/samcrew/memba_quest_attestation_v1"
	reviews "gno.land/r/samcrew/memba_reviews_v2"
)

// ── Roles: App Store curators, arcade attesters, badge admins, feed
// moderators. Operational work (curating, attesting, minting, moderating)
// is done by the holders the DAO appoints here.

func Grant(cur realm, pid uint64, app string, who address) { role(cur, pid, app, who, true) }

func Revoke(cur realm, pid uint64, app string, who address) { role(cur, pid, app, who, false) }

func role(cur realm, pid uint64, app string, who address, grant bool) {
	approve(cur, pid, rolePlan(app, who, grant))
	switch {
	case app == appAppstore && grant:
		appstore.AddCurator(cross(cur), who)
	case app == appAppstore:
		appstore.RemoveCurator(cross(cur), who)
	case app == appArcade && grant:
		arcade.AddAttester(cross(cur), who)
	case app == appArcade:
		arcade.RemoveAttester(cross(cur), who)
	case app == appBadges && grant:
		badges.AddAdmin(cross(cur), who)
	case app == appBadges:
		badges.RemoveAdmin(cross(cur), who)
	case app == appFeed && grant:
		feed.AddModerator(cross(cur), who)
	default:
		feed.RemoveModerator(cross(cur), who)
	}
}

func rolePlan(app string, who address, grant bool) plan {
	if grant {
		arg(who)
	} else if canonical(who) == self {
		// Revoking its own curator grant would end DAO curation until a hand-over round trip.
		panic("memba_bridge: the bridge keeps its own role")
	}
	// A stale grant held by another protected realm can be revoked.
	if hasRole(app, who) == grant {
		panic("memba_bridge: role already in that state")
	}
	op := "Revoke"
	if grant {
		op = "Grant"
	}
	args := daoauth.New().Addr(who)
	if app == appBadges {
		args.Int(int64(badges.GetAdminCount()))
	}
	return newPlan(app, op, args, app, gov.Critical)
}

func hasRole(app string, who address) bool {
	switch app {
	case appAppstore:
		return appstore.IsCurator(string(who))
	case appArcade:
		return arcade.IsAttester(string(who))
	case appBadges:
		return badges.IsAdmin(who)
	case appFeed:
		return feed.IsModerator(who)
	}
	panic("memba_bridge: " + app + " has no role to grant")
}

// ── App Store ───────────────────────────────────────────────────────────

// Curate runs a curator action on one listing: approve, reject (with a
// reason), delist, restore or clearflags. Every approval binds the listing's
// status; approve and restore, which publish, also bind its content, and
// clearflags binds the flags it clears. Editing or flagging a listing thus
// cannot void a reject or delist vote, and cannot slip new content past one.
func Curate(cur realm, pid uint64, op, pkgPath, reason string) {
	approve(cur, pid, curatePlan(op, pkgPath, reason))
	switch op {
	case "approve":
		appstore.ApproveApp(cross(cur), pkgPath)
	case "reject":
		appstore.RejectApp(cross(cur), pkgPath, reason)
	case "delist":
		appstore.DelistApp(cross(cur), pkgPath)
	case "restore":
		appstore.RestoreApp(cross(cur), pkgPath)
	default:
		appstore.ClearFlags(cross(cur), pkgPath)
	}
}

func curatePlan(op, pkgPath, reason string) plan {
	switch {
	case op != "approve" && op != "reject" && op != "delist" && op != "restore" && op != "clearflags":
		panic("memba_bridge: unknown curation " + op)
	case (op == "reject") != (reason != ""):
		panic("memba_bridge: a reason goes with reject only")
	}
	l := appstore.GetGovernanceListing(pkgPath, op == "clearflags")
	if !l.Exists {
		panic("memba_bridge: no listing " + pkgPath)
	}
	args := daoauth.New().Str(op).Str(pkgPath).Str(reason).Str(l.Status)
	if op == "approve" || op == "restore" {
		args.Str(l.ContentHash)
	}
	if op == "clearflags" {
		keys := sha256.Sum256([]byte(l.ClearKeys))
		args.Int(int64(l.Flags)).Str(hex.EncodeToString(keys[:]))
	}
	return newPlan(appAppstore, "Curate", args, appAppstore+"/l/"+pkgPath, gov.Routine)
}

func SetRegistrationFee(cur realm, pid uint64, fee int64) {
	approve(cur, pid, registrationFeePlan(fee))
	appstore.SetRegistrationFee(cross(cur), fee)
}

func registrationFeePlan(fee int64) plan {
	if fee < 0 || fee > appstore.MaxRegistrationFee {
		panic("memba_bridge: the registration fee is 0 to " + strconv.FormatInt(appstore.MaxRegistrationFee, 10) + " ugnot")
	}
	return newPlan(appAppstore, "SetRegistrationFee", daoauth.New().Int(fee).Int(appstore.GetRegistrationFee()), appAppstore, gov.Financial)
}

// SetTreasury points the fees of market_config (which escrow also pays
// into) or of the App Store at addr.
func SetTreasury(cur realm, pid uint64, app string, addr address) {
	approve(cur, pid, treasuryPlan(app, addr))
	if app == appMarket {
		market.SetTreasury(cross(cur), addr)
	} else {
		appstore.SetTreasury(cross(cur), addr)
	}
}

func treasuryPlan(app string, addr address) plan {
	var current address
	switch app {
	case appMarket:
		current = market.GetTreasury()
	case appAppstore:
		current = appstore.GetTreasury()
	default:
		panic("memba_bridge: " + app + " has no treasury")
	}
	return newPlan(app, "SetTreasury", daoauth.New().Addr(arg(addr)).Str(string(current)), app, gov.Critical)
}

// ── Market config ───────────────────────────────────────────────────────

func SetFee(cur realm, pid uint64, lane string, bps int64) {
	approve(cur, pid, feePlan(lane, bps))
	market.SetFeeBPS(cross(cur), lane, bps)
}

func feePlan(lane string, bps int64) plan {
	if lane == "" || bps < 0 || bps > market.MaxFeeBPS {
		panic("memba_bridge: a fee names its lane and is 0 to " + strconv.FormatInt(market.MaxFeeBPS, 10) + " bps")
	}
	return newPlan(appMarket, "SetFee", daoauth.New().Str(lane).Int(bps).Int(int64(market.GetFeeBPS(lane))), appMarket, gov.Financial)
}

// ── Escrow ──────────────────────────────────────────────────────────────

// ResolveDispute settles one disputed milestone: refund pays the client
// the whole amount, otherwise the freelancer is paid less the fee. Either
// way escrow pays out at most the milestone's amount, which is checked. A
// milestone is disputed at most once (a resolution is final); binding the
// height of that dispute means no approval can be voted before it exists.
func ResolveDispute(cur realm, pid uint64, contractID string, milestone int, refund bool) {
	p, amount := disputePlan(contractID, milestone, refund)
	approve(cur, pid, p)
	before := escrowBalance()
	escrow.ResolveDispute(cross(cur), contractID, milestone, refund)
	if paid := before - escrowBalance(); paid < 0 || paid > amount {
		panic("memba_bridge: escrow paid out more than the milestone")
	}
}

// disputePlan returns the approval and the milestone's amount.
func disputePlan(contractID string, milestone int, refund bool) (plan, int64) {
	c := escrow.GetGovernanceContract(contractID)
	if !c.Exists || milestone < 0 || milestone >= c.Count {
		panic("memba_bridge: no such contract milestone")
	}
	m := c.Milestones[milestone]
	if m.Status != "disputed" {
		panic("memba_bridge: milestone is " + m.Status + ", not disputed")
	}
	args := daoauth.New().Str(contractID).Int(int64(milestone)).Bool(refund).
		Str(m.Status).Str(m.PreDisputeStatus).Int(m.Amount).Int(m.DisputedAt)
	if !refund {
		terms := escrow.GetGovernanceFeeTerms()
		args.Int(terms.EffectiveBPS).Str(string(terms.EffectiveTreasury))
	}
	return newPlan(appEscrow, "ResolveDispute", args, appEscrow+"/c/"+contractID+"/m/"+strconv.Itoa(milestone), gov.Financial), m.Amount
}

func escrowBalance() int64 {
	// One denom only: junk denoms sent to escrow cost nothing to read past.
	return banker.NewReadonlyBanker().GetCoin(chain.PackageAddress("gno.land/r/samcrew/"+appEscrow), "ugnot")
}

// ProposeFeeRecipient stages escrow's fallback fee recipient, used only when
// market_config's treasury is unusable.
func ProposeFeeRecipient(cur realm, pid uint64, addr address) {
	approve(cur, pid, feeRecipientPlan(addr))
	escrow.ProposeFeeRecipient(cross(cur), addr)
}

func feeRecipientPlan(addr address) plan {
	return newPlan(appEscrow, "ProposeFeeRecipient", daoauth.New().Addr(arg(addr)).
		Str(escrow.GetFeeRecipient()).Str(escrow.GetPendingFeeRecipient()), appEscrow, gov.Critical)
}

func CancelFeeRecipient(cur realm, pid uint64) {
	approve(cur, pid, cancelFeeRecipientPlan())
	escrow.CancelFeeRecipientProposal(cross(cur))
}

func cancelFeeRecipientPlan() plan {
	pending := escrow.GetPendingFeeRecipient()
	if pending == "" {
		panic("memba_bridge: no fee recipient staged")
	}
	return newPlan(appEscrow, "CancelFeeRecipient", daoauth.New().Str(pending), appEscrow, gov.Financial)
}

// ── Reviews ─────────────────────────────────────────────────────────────

func HideReview(cur realm, pid uint64, id uint64)  { moderate(cur, pid, "HideReview", id) }
func HideComment(cur realm, pid uint64, id uint64) { moderate(cur, pid, "HideComment", id) }

// Unhide shows an item again and dismisses its flags.
func Unhide(cur realm, pid uint64, id uint64) { moderate(cur, pid, "Unhide", id) }

// moderate binds the item's kind and visibility; Unhide, which shows the
// item again, also binds its content, so an author editing it can neither
// void a hide vote nor slip new text past an unhide vote.
func moderate(cur realm, pid uint64, op string, id uint64) {
	approve(cur, pid, moderationPlan(op, id))
	switch op {
	case "HideReview":
		reviews.HideReview(cross(cur), id)
	case "HideComment":
		reviews.HideComment(cross(cur), id)
	default:
		reviews.Unhide(cross(cur), id)
	}
}

func moderationPlan(op string, id uint64) plan {
	s := reviews.GetModerationState(id)
	switch {
	case s.ID == 0:
		// Ids are predictable: an approval for an item not posted yet would hide whatever takes the id.
		panic("memba_bridge: no review or comment " + strconv.FormatUint(id, 10))
	case op == "HideReview" && !s.Review:
		panic("memba_bridge: item " + strconv.FormatUint(id, 10) + " is a comment, not a review")
	case op == "HideComment" && s.Review:
		panic("memba_bridge: item " + strconv.FormatUint(id, 10) + " is a review, not a comment")
	case op != "Unhide" && (s.Hidden || s.Deleted):
		panic("memba_bridge: already hidden or deleted")
	case op == "Unhide" && !s.Hidden && !s.Flagged:
		panic("memba_bridge: neither hidden nor flagged")
	}
	// The author and creation time pin the item itself.
	args := daoauth.New().Uint(id).Bool(s.Review).Bool(s.Hidden).Bool(s.Deleted).Addr(s.Author).Int(s.CreatedAt)
	if op == "Unhide" {
		// The text is bound by its hash and edit height. Unhide also dismisses
		// flags; the flagged bit is bound, not a count (reviews_v2 exposes none),
		// so a flag added after the vote to an item already flagged is
		// dismissed with the others.
		args.Str(s.BodyHash).Int(s.EditedAt).Bool(s.Flagged)
	}
	return newPlan(appReviews, op, args, appReviews+"/i/"+strconv.FormatUint(id, 10), gov.Routine)
}

// ── Quests ──────────────────────────────────────────────────────────────

// SetQuestSigner rotates the key every quest voucher is checked against.
func SetQuestSigner(cur realm, pid uint64, pubKeyHex string) {
	approve(cur, pid, signerPlan(pubKeyHex))
	quest.SetSigner(cross(cur), pubKeyHex)
}

func signerPlan(pubKeyHex string) plan {
	if len(pubKeyHex) != 64 || strings.Trim(pubKeyHex, "0123456789abcdef") != "" || pubKeyHex == quest.GetSigner() {
		panic("memba_bridge: a new signer is 64 lowercase hex digits")
	}
	return newPlan(appQuest, "SetSigner", daoauth.New().Str(pubKeyHex).Str(quest.GetSigner()), appQuest, gov.Critical)
}

// ── Channels and feedback membership ────────────────────────────────────

// AddMember adds a new member; it never rewrites an existing member's roles.
func AddMember(cur realm, pid uint64, app string, addr address, roles string) {
	member(cur, pid, app, "AddMember", addr, roles)
}

func RemoveMember(cur realm, pid uint64, app string, addr address) {
	member(cur, pid, app, "RemoveMember", addr, "")
}

func SetRoles(cur realm, pid uint64, app string, addr address, roles string) {
	member(cur, pid, app, "SetRoles", addr, roles)
}

func member(cur realm, pid uint64, app, op string, who address, roles string) {
	approve(cur, pid, memberPlan(app, op, who, roles))
	switch {
	case app == appChannels && op == "AddMember":
		channels.AddMember(cross(cur), who, roles)
	case app == appChannels && op == "RemoveMember":
		channels.RemoveMember(cross(cur), who)
	case app == appChannels:
		channels.UpdateMemberRoles(cross(cur), who, roles)
	case op == "AddMember":
		feedback.AddMember(cross(cur), who, roles)
	case op == "RemoveMember":
		feedback.RemoveMember(cross(cur), who)
	default:
		feedback.UpdateMemberRoles(cross(cur), who, roles)
	}
}

func memberPlan(app, op string, who address, roles string) plan {
	if op == "RemoveMember" {
		canonical(who) // a stale membership of a protected realm can be removed
	} else {
		arg(who)
	}
	var revision uint64
	var current string
	switch app {
	case appChannels:
		revision, current = channels.GetMembershipRevision(), channels.GetMemberRoles(who)
	case appFeedback:
		revision, current = feedback.GetMembershipRevision(), feedback.GetMemberRoles(who)
	default:
		panic("memba_bridge: " + app + " has no members")
	}
	if (op == "AddMember") != (current == "") || (op != "RemoveMember" && !validRoles(roles)) {
		panic("memba_bridge: add a non-member, change a member, roles an ordered subset of admin,dev,ops,member")
	}
	return newPlan(app, op, daoauth.New().Addr(who).Str(roles).Uint(revision).Str(current), app, gov.Critical)
}

// validRoles accepts a non-empty, ordered, duplicate-free subset of
// admin,dev,ops,member.
func validRoles(r string) bool {
	names := []string{"admin", "dev", "ops", "member"}
	next := 0
	for _, x := range strings.Split(r, ",") {
		for next < len(names) && names[next] != x {
			next++
		}
		if next == len(names) {
			return false
		}
		next++
	}
	return true
}

// CreateChannel adds a channel. Channels are permanent (at most 20).
func CreateChannel(cur realm, pid uint64, app, name, description, ctype string) {
	approve(cur, pid, channelPlan(app, name, description, ctype))
	if app == appChannels {
		channels.CreateChannel(cross(cur), name, description, ctype)
	} else {
		feedback.CreateChannel(cross(cur), name, description, ctype)
	}
}

func channelPlan(app, name, description, ctype string) plan {
	if ctype != "text" && ctype != "announcements" && ctype != "readonly" || description == "" || len(description) > 200 || !daoauth.ValidText(description) {
		panic("memba_bridge: type text, announcements or readonly; description 1-200 printable ASCII characters")
	}
	var count int
	var exists bool
	switch app {
	case appChannels:
		count, exists, _, _, _, _ = channels.GetChannelState(name)
	case appFeedback:
		count, exists, _, _, _, _ = feedback.GetChannelState(name)
	default:
		panic("memba_bridge: " + app + " has no channels")
	}
	if exists {
		panic("memba_bridge: channel exists")
	}
	if !channelName(name) || count >= 20 {
		panic("memba_bridge: a channel name is 1-50 of a-z, 0-9 or -, and an app holds at most 20 channels")
	}
	return newPlan(app, "CreateChannel", daoauth.New().Str(name).Str(description).Str(ctype).Int(int64(count)), app, gov.Critical)
}

// channelName is the apps' own channel-name rule.
func channelName(name string) bool {
	if name == "" || len(name) > 50 {
		return false
	}
	return strings.Trim(name, "abcdefghijklmnopqrstuvwxyz0123456789-") == ""
}

// Package memba_bridge_v1 governs the ten Memba application realms published
// before memba_gov. It becomes each app's admin through the app's own
// two-step handover, so the apps' code does not change, and turns memba_gov
// approvals into the app's owner-only calls.
//
// Every governed entrypoint is a direct call by a seated member. It reads the
// app's live pre-state, encodes it with the call's arguments and the app's
// tenure (how many times the bridge has accepted it), and consumes exactly
// that approval from memba_gov before calling the app: an approval voted on
// another state, app, action, argument or tenure never matches. Action ids
// are "<app>.<Op>"; the invalidation scope is the app, or an object of it
// where actions are independent.
//
// Accept, ExpirePause and the reads need no vote. EmergencyPause needs a
// seated member, no vote, and expires by itself. Approval tells a proposer
// exactly what an entrypoint call would consume, from the same code.
package memba_bridge_v1

import (
	"chain"
	"strconv"
	"time"

	"gno.land/p/samcrew/daoauth"
	gov "gno.land/r/samcrew/memba_gov"
	escrow "gno.land/r/samcrew/escrow_v4"
	badges "gno.land/r/samcrew/gnobuilders_badges_v2"
	appstore "gno.land/r/samcrew/memba_appstore_v3"
	arcade "gno.land/r/samcrew/memba_arcade_leaderboard_v1"
	channels "gno.land/r/samcrew/memba_dao_channels_v2"
	feed "gno.land/r/samcrew/memba_feed_v1"
	feedback "gno.land/r/samcrew/memba_feedback_v2"
	market "gno.land/r/samcrew/memba_market_config"
	quest "gno.land/r/samcrew/memba_quest_attestation_v1"
	reviews "gno.land/r/samcrew/memba_reviews_v2"
)

const (
	appMarket   = "memba_market_config"
	appEscrow   = "escrow_v4"
	appAppstore = "memba_appstore_v3"
	appReviews  = "memba_reviews_v2"
	appQuest    = "memba_quest_attestation_v1"
	appArcade   = "memba_arcade_leaderboard_v1"
	appBadges   = "gnobuilders_badges_v2"
	appFeed     = "memba_feed_v1"
	appChannels = "memba_dao_channels_v2"
	appFeedback = "memba_feedback_v2"
)

var (
	self = chain.PackageAddress("gno.land/r/samcrew/memba_bridge_v1")
	apps = []string{appMarket, appEscrow, appAppstore, appReviews, appQuest, appArcade, appBadges, appFeed, appChannels, appFeedback}
	// Addresses no governed argument may name: fees sent there are locked
	// for good, and a role given to one of them is unusable.
	protected   = map[address]bool{}
	tenure      = map[string]uint64{}    // app -> times the bridge accepted it
	pausedUntil = map[string]time.Time{} // app -> end of the bridge's pause
	episodes    = map[string]uint64{}    // app -> pauses the bridge started
	lastPause   = map[string]time.Time{} // member id -> last emergency pause
)

func init() {
	for _, path := range []string{"memba_bridge_v1", "memba_gov", "memba_dao", "escrow_v3"} {
		protected[chain.PackageAddress("gno.land/r/samcrew/"+path)] = true
	}
	for _, app := range apps {
		protected[chain.PackageAddress("gno.land/r/samcrew/"+app)] = true
	}
}

// ── Authorisation ───────────────────────────────────────────────────────

// direct returns the account that called the bridge directly.
func direct(cur realm) address {
	if !cur.IsCurrent() || !cur.Previous().IsUserCall() {
		panic("memba_bridge: call directly from your account")
	}
	return cur.Previous().Address()
}

// A plan is the approval one governed call needs: action app.op, args
// (completed by the app's tenure, which voids approvals voted while the app
// was away), the invalidation scope and the minimum class.
type plan struct {
	app, op string
	args    *daoauth.Args
	scope   string
	class   int
}

// newPlan refuses an approval for an app the bridge does not govern now: no
// call could consume it.
func newPlan(app, op string, args *daoauth.Args, scope string, class int) plan {
	if !governs(app) {
		panic("memba_bridge: the bridge does not govern " + app)
	}
	return plan{app, op, args, scope, class}
}

func (p plan) voted() string { return p.args.Uint(tenure[p.app]).String() }

// approve consumes proposal pid for p; memba_gov checks the executor, the
// bridge's direct caller, is a seated member.
func approve(cur realm, pid uint64, p plan) {
	executor := direct(cur)
	gov.Consume(cross(cur), pid, p.app+"."+p.op, p.voted(), p.scope, p.class, executor)
}

// Approval returns, as JSON, the proposal a governed entrypoint call would
// consume if made now: target this realm, with the action, args, scope and
// minimum class given. call is the entrypoint's name and its arguments after
// pid, daoauth-encoded in order (strings s:, addresses a:, integers i: or
// u:, booleans b:). It refuses a call its entrypoint would refuse before
// voting, and holds only while the state it binds is unchanged.
func Approval(call string) string {
	c := parseCall(call)
	var p plan
	switch name := c.str(); name {
	case "TransferAdmin":
		p = transferPlan(c.str(), c.addr())
	case "CancelTransfer":
		p = cancelPlan(c.str())
	case "SetPause":
		p = pausePlan(c.str(), c.i64())
	case "Grant", "Revoke":
		p = rolePlan(c.str(), c.addr(), name == "Grant")
	case "Curate":
		p = curatePlan(c.str(), c.str(), c.str())
	case "SetRegistrationFee":
		p = registrationFeePlan(c.i64())
	case "SetTreasury":
		p = treasuryPlan(c.str(), c.addr())
	case "SetFee":
		p = feePlan(c.str(), c.i64())
	case "ResolveDispute":
		p, _ = disputePlan(c.str(), int(c.i64()), c.flag())
	case "ProposeFeeRecipient":
		p = feeRecipientPlan(c.addr())
	case "CancelFeeRecipient":
		p = cancelFeeRecipientPlan()
	case "HideReview", "HideComment", "Unhide":
		p = moderationPlan(name, c.u64())
	case "SetQuestSigner":
		p = signerPlan(c.str())
	case "AddMember", "SetRoles":
		p = memberPlan(c.str(), name, c.addr(), c.str())
	case "RemoveMember":
		p = memberPlan(c.str(), name, c.addr(), "")
	case "CreateChannel":
		p = channelPlan(c.str(), c.str(), c.str(), c.str())
	default:
		panic("memba_bridge: no governed entrypoint " + name)
	}
	c.done()
	return `{"target":"gno.land/r/samcrew/memba_bridge_v1","action":` + quote(p.app+"."+p.op) +
		`,"args":` + quote(p.voted()) + `,"scope":` + quote(p.scope) + `,"class":` + strconv.Itoa(p.class) + `}`
}

// call reads an Approval call's fields in order, each with its tag.
type call struct{ f []daoauth.Field }

func parseCall(s string) *call {
	f, err := daoauth.Parse(s)
	if err != nil {
		panic(err.Error())
	}
	return &call{f}
}

func (c *call) next(tag byte) string {
	if len(c.f) == 0 || c.f[0].Tag != tag {
		panic("memba_bridge: call argument " + string(tag) + ": expected")
	}
	v := c.f[0].Value
	c.f = c.f[1:]
	return v
}

// daoauth.Parse has checked each value is canonical for its tag.
func (c *call) str() string   { return c.next('s') }
func (c *call) addr() address { return address(c.next('a')) }
func (c *call) i64() int64 {
	n, _ := strconv.ParseInt(c.next('i'), 10, 64)
	return n
}

func (c *call) u64() uint64 {
	n, _ := strconv.ParseUint(c.next('u'), 10, 64)
	return n
}

func (c *call) flag() bool { return c.next('b') == "1" }

func (c *call) done() {
	if len(c.f) != 0 {
		panic("memba_bridge: too many call arguments")
	}
}

// quote returns s, printable ASCII, as a JSON string with < > & escaped.
func quote(s string) string {
	b := make([]byte, 0, 6*len(s)+2)
	b = append(b, '"')
	for i := 0; i < len(s); i++ {
		switch c := s[i]; c {
		case '"', '\\':
			b = append(b, '\\', c)
		case '<', '>', '&':
			b = append(b, `\u00`...)
			b = append(b, "0123456789abcdef"[c>>4], "0123456789abcdef"[c&0xf])
		default:
			b = append(b, c)
		}
	}
	return string(append(b, '"'))
}

func checkApp(app string) {
	for _, a := range apps {
		if a == app {
			return
		}
	}
	panic("memba_bridge: unknown app " + app)
}

// arg refuses a non-canonical or protected address as a recipient of a role,
// membership, admin or fees.
func arg(a address) address {
	if protected[a] {
		panic("memba_bridge: address must not be a governance or app realm")
	}
	return canonical(a)
}

// canonical refuses an address the chain would never give a caller.
func canonical(a address) address {
	if !daoauth.ValidAddress(a) {
		panic("memba_bridge: address must be lowercase bech32")
	}
	return a
}

// ── Admin handover (every app) ──────────────────────────────────────────

// Accept takes the admin role the 2-of-3 nominated the bridge for. It needs
// no vote: the nomination is the decision. A paused app is refused: only a
// pause the bridge started can be ended by its rules.
func Accept(cur realm, app string) {
	checkApp(app)
	if hasPause(app) && isPaused(app) {
		panic("memba_bridge: unpause " + app + " before handing it over")
	}
	switch app {
	case appMarket:
		market.AcceptAdmin(cross(cur))
	case appEscrow:
		escrow.AcceptOwnership(cross(cur))
	case appAppstore:
		appstore.AcceptOwnership(cross(cur))
	case appReviews:
		reviews.AcceptOwnership(cross(cur))
	case appQuest:
		quest.AcceptOwnership(cross(cur))
	case appArcade:
		arcade.AcceptOwnership(cross(cur))
	case appBadges:
		badges.AcceptOwnership(cross(cur))
	case appFeed:
		feed.AcceptOwnership(cross(cur))
	case appChannels:
		channels.AcceptOwnership(cross(cur))
	case appFeedback:
		feedback.AcceptOwnership(cross(cur))
	}
	tenure[app]++
	delete(pausedUntil, app) // a record from an earlier tenure never applies
}

// TransferAdmin stages to as the app's next admin: the 2-of-3, a successor
// bridge, or anyone the DAO names. The recipient accepts by its own call.
func TransferAdmin(cur realm, pid uint64, app string, to address) {
	approve(cur, pid, transferPlan(app, to))
	switch app {
	case appMarket:
		market.TransferAdmin(cross(cur), to)
	case appEscrow:
		escrow.TransferOwnership(cross(cur), to)
	case appAppstore:
		appstore.TransferOwnership(cross(cur), to)
	case appReviews:
		reviews.TransferOwnership(cross(cur), to)
	case appQuest:
		quest.TransferOwnership(cross(cur), to)
	case appArcade:
		arcade.TransferOwnership(cross(cur), to)
	case appBadges:
		badges.TransferOwnership(cross(cur), to)
	case appFeed:
		feed.TransferOwnership(cross(cur), to)
	case appChannels:
		channels.ProposeOwner(cross(cur), to)
	case appFeedback:
		feedback.TransferOwnership(cross(cur), to)
	}
}

func transferPlan(app string, to address) plan {
	checkApp(app)
	return newPlan(app, "TransferAdmin", daoauth.New().Addr(arg(to)).Str(pendingAdmin(app)), app, gov.Critical)
}

// CancelTransfer withdraws a staged admin before the recipient accepts.
func CancelTransfer(cur realm, pid uint64, app string) {
	approve(cur, pid, cancelPlan(app))
	switch app {
	case appMarket:
		market.CancelAdminTransfer(cross(cur))
	case appEscrow:
		escrow.CancelOwnershipTransfer(cross(cur))
	case appAppstore:
		appstore.CancelOwnershipTransfer(cross(cur))
	case appReviews:
		reviews.CancelOwnershipTransfer(cross(cur))
	case appQuest:
		quest.CancelOwnershipTransfer(cross(cur))
	case appArcade:
		arcade.CancelOwnershipTransfer(cross(cur))
	case appBadges:
		badges.CancelOwnershipTransfer(cross(cur))
	case appFeed:
		feed.CancelOwnershipTransfer(cross(cur))
	case appChannels:
		channels.CancelPendingOwner(cross(cur))
	case appFeedback:
		feedback.CancelOwnershipTransfer(cross(cur))
	}
}

func cancelPlan(app string) plan {
	checkApp(app)
	pending := pendingAdmin(app)
	if pending == "" {
		panic("memba_bridge: nothing staged to cancel for " + app)
	}
	return newPlan(app, "CancelTransfer", daoauth.New().Str(pending), app, gov.Financial)
}

// governs reports whether the bridge is app's admin now.
func governs(app string) bool {
	var admin string
	switch app {
	case appMarket:
		admin = string(market.GetAdmin())
	case appEscrow:
		admin = escrow.GetAdmin()
	case appAppstore:
		admin = string(appstore.GetOwner())
	case appReviews:
		admin = reviews.GetModerator()
	case appQuest:
		admin = quest.GetOwner()
	case appArcade:
		admin = string(arcade.GetOwner())
	case appBadges:
		admin = string(badges.GetOwner())
	case appFeed:
		admin = string(feed.GetOwner())
	case appChannels:
		admin = string(channels.GetOwner())
	case appFeedback:
		admin = string(feedback.GetOwner())
	default:
		return false
	}
	return admin == string(self)
}

func pendingAdmin(app string) string {
	switch app {
	case appMarket:
		return string(market.GetPendingAdmin())
	case appEscrow:
		return escrow.GetPendingAdmin()
	case appAppstore:
		return string(appstore.GetPendingOwner())
	case appReviews:
		return reviews.GetPendingModerator()
	case appQuest:
		return quest.GetPendingOwner()
	case appArcade:
		return string(arcade.GetPendingOwner())
	case appBadges:
		return string(badges.GetPendingOwner())
	case appFeed:
		return string(feed.GetPendingOwner())
	case appChannels:
		return string(channels.GetPendingOwner())
	}
	return string(feedback.GetPendingOwner())
}

// ── Pause (escrow, App Store, arcade, badges, feed, channels, feedback) ──

// EmergencyPause pauses app for 7 days, without a vote. Each member may use
// it once per 30 days, so one key cannot keep an app closed.
func EmergencyPause(cur realm, app string) {
	id := gov.PersonOf(direct(cur))
	if id == "" {
		panic("memba_bridge: not a seated member")
	}
	if !governs(app) {
		panic("memba_bridge: the bridge does not govern " + app)
	}
	// A paused app is refused first, and costs no allowance: an emergency
	// pause must never shorten a longer pause members voted.
	if isPaused(app) {
		panic("memba_bridge: already paused")
	}
	now := time.Now()
	if last, ok := lastPause[id]; ok && now.Before(last.Add(PauseAllowance)) {
		panic("memba_bridge: one emergency pause per member per 30 days")
	}
	setPaused(cur, app, true)
	pausedUntil[app] = now.Add(EmergencyPauseFor)
	episodes[app]++
	lastPause[id] = now
}

// SetPause ends the bridge's pause of app now (until = 0) or keeps app
// paused until the unix time until, at most 30 days ahead. The approval names
// the pause episode, so it never ends a later pause.
func SetPause(cur realm, pid uint64, app string, until int64) {
	approve(cur, pid, pausePlan(app, until))
	if until == 0 {
		if isPaused(app) {
			setPaused(cur, app, false)
		}
		delete(pausedUntil, app)
		return
	}
	if !isPaused(app) {
		setPaused(cur, app, true)
		episodes[app]++
	}
	pausedUntil[app] = time.Unix(until, 0)
}

func pausePlan(app string, until int64) plan {
	now := time.Now()
	if end := time.Unix(until, 0); until != 0 && (!end.After(now) || end.After(now.Add(MaxPauseAhead))) {
		panic("memba_bridge: pause end must be within the next 30 days")
	}
	// Governance first: an app the bridge does not govern says so before its pause is read.
	p := newPlan(app, "SetPause", daoauth.New(), app, gov.Financial)
	p.args.Int(until).Bool(isPaused(app)).Uint(episodes[app])
	return p
}

// ExpirePause lets anyone end the bridge's pause of app once it is over. A
// SetPause that keeps app paused longer must execute before then. Once the
// bridge no longer governs app, its record no longer applies: anyone drops
// it, and the app, now its new admin's, is left as it is.
func ExpirePause(cur realm, app string) {
	end, ok := pausedUntil[app]
	if ok && !governs(app) {
		delete(pausedUntil, app)
		return
	}
	if !ok || time.Now().Before(end) {
		panic("memba_bridge: no expired pause for " + app)
	}
	delete(pausedUntil, app)
	if isPaused(app) {
		setPaused(cur, app, false)
	}
}

func hasPause(app string) bool {
	return app != appMarket && app != appReviews && app != appQuest
}

func isPaused(app string) bool {
	switch app {
	case appEscrow:
		return escrow.IsPaused()
	case appAppstore:
		return appstore.IsPaused()
	case appArcade:
		return arcade.IsPaused()
	case appBadges:
		return badges.IsPaused()
	case appFeed:
		return feed.IsPaused()
	case appChannels:
		return channels.IsPaused()
	case appFeedback:
		return feedback.IsPaused()
	}
	panic("memba_bridge: " + app + " has no pause")
}

func setPaused(cur realm, app string, on bool) {
	switch {
	case app == appEscrow && on:
		escrow.Pause(cross(cur))
	case app == appEscrow:
		escrow.Unpause(cross(cur))
	case app == appAppstore:
		appstore.Pause(cross(cur), on)
	case app == appArcade:
		arcade.Pause(cross(cur), on)
	case app == appBadges && on:
		badges.Pause(cross(cur))
	case app == appBadges:
		badges.Unpause(cross(cur))
	case app == appFeed && on:
		feed.PauseRealm(cross(cur))
	case app == appFeed:
		feed.UnpauseRealm(cross(cur))
	case app == appChannels && on:
		channels.PauseRealm(cross(cur))
	case app == appChannels:
		channels.UnpauseRealm(cross(cur))
	case app == appFeedback && on:
		feedback.PauseRealm(cross(cur))
	case app == appFeedback:
		feedback.UnpauseRealm(cross(cur))
	}
}

func unixOf(t time.Time) int64 {
	if t.IsZero() {
		return 0
	}
	return t.Unix()
}

// ── Reads ───────────────────────────────────────────────────────────────

// PausedUntil returns the unix end of the bridge's pause of app, or 0 (also
// once the bridge no longer governs app).
func PausedUntil(app string) int64 {
	if !governs(app) {
		return 0
	}
	return unixOf(pausedUntil[app])
}

// PauseEpisode returns how many pauses of app the bridge has started; a
// SetPause approval binds it.
func PauseEpisode(app string) uint64 { return episodes[app] }

// Tenure returns how many times the bridge has accepted app; every approval
// for app binds it as its last argument.
func Tenure(app string) uint64 { return tenure[app] }

func Render(_ string) string {
	out := "# Memba bridge v1\n\nGoverns the ten Memba apps for memba_gov. Bridge pauses:\n\n"
	n := 0
	for _, app := range apps {
		if end, ok := pausedUntil[app]; ok && governs(app) {
			out += "- " + app + " until unix " + strconv.FormatInt(end.Unix(), 10) + "\n"
			n++
		}
	}
	if n == 0 {
		out += "None.\n"
	}
	return out
}

package memba_bridge_v1

import "time"

// The pause durations, in their own file so a node fixture, which cannot
// wait days, can replace this file alone; TestProductionDurations pins them.
const (
	EmergencyPauseFor = 7 * 24 * time.Hour  // escrow keeps exits closed this long
	PauseAllowance    = 30 * 24 * time.Hour // one emergency pause per member per period
	MaxPauseAhead     = 30 * 24 * time.Hour
)

// Package campaign is the state machine behind Guildhall campaigns: bounties
// with a fixed reward per claim and a fixed number of slots, for small tasks
// many people can do (write a post, translate a page, file a bug report).
//
// Like gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/bounty,
// it holds no funds and moves no coins. Transitions validate who is acting,
// mutate the campaign, and return the transfers the escrow realm must make.
//
// The poster escrows Reward × Slots. Anyone except the poster and the
// reviewers can claim with a link to proof of the work; a pending claim
// reserves a slot. Any one reviewer approves (pays the reward) or rejects
// (frees the slot). Each address holds at most one pending or approved claim.
//
//	Open ──Close (poster, or anyone after the deadline)──▶ Closed (free slots refunded)
//	Open ──(every slot paid)──▶ Closed
//
//	Claim ──Approve──▶ Approved (reward paid)
//	  └────Reject───▶ Rejected (slot freed; refunded if the campaign is closed)
//
// Pending claims can still be reviewed after a campaign closes.
package campaign

import (
	"errors"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Limits keep campaigns renderable and every transition bounded in gas.
const (
	MaxTitleLen       = 120
	MaxDescriptionLen = 8000
	MaxLinkLen        = 300
	MaxNoteLen        = 1000
	MaxSlots          = 1000
	MaxReviewers      = 9
	MaxTags           = 5
	MaxTagLen         = 24
)

var (
	ErrUnauthorized = errors.New("campaign: unauthorized")
	ErrClosed       = errors.New("campaign: closed to new claims")
	ErrBadClaim     = errors.New("campaign: unknown claim")
)

// Status is the lifecycle state of a campaign.
type Status int

const (
	StatusOpen Status = iota
	StatusClosed
)

func (s Status) String() string {
	switch s {
	case StatusOpen:
		return "open"
	case StatusClosed:
		return "closed"
	}
	return "unknown"
}

// ParseStatus is the inverse of Status.String.
func ParseStatus(s string) (Status, bool) {
	for _, st := range []Status{StatusOpen, StatusClosed} {
		if st.String() == s {
			return st, true
		}
	}
	return 0, false
}

// ClaimStatus is the state of a single claim.
type ClaimStatus int

const (
	ClaimPending ClaimStatus = iota
	ClaimApproved
	ClaimRejected
)

func (s ClaimStatus) String() string {
	switch s {
	case ClaimPending:
		return "pending"
	case ClaimApproved:
		return "approved"
	case ClaimRejected:
		return "rejected"
	}
	return "unknown"
}

// ParseClaimStatus is the inverse of ClaimStatus.String.
func ParseClaimStatus(s string) (ClaimStatus, bool) {
	for _, st := range []ClaimStatus{ClaimPending, ClaimApproved, ClaimRejected} {
		if st.String() == s {
			return st, true
		}
	}
	return 0, false
}

// Claim is one person's request to be paid for doing the task once.
type Claim struct {
	Number     int // 1-based, in order of submission
	Claimant   address
	Proof      string
	Status     ClaimStatus
	At         time.Time
	ReviewedBy address
	ReviewedAt time.Time
	Reason     string // why it was rejected
}

// Campaign is a pool of identical, individually paid tasks.
type Campaign struct {
	ID          uint64
	Poster      address
	Title       string
	Description string
	Link        string
	Tags        []string
	Denom       string
	IsGRC20     bool
	Reward      int64
	Slots       int
	Reviewers   []address
	Deadline    time.Time // zero: no deadline
	Status      Status
	CreatedAt   time.Time
	ClosedAt    time.Time

	Paid     int // approved claims
	Pending  int // claims awaiting review
	Rejected int
	Refunded int // slots returned to the poster

	claims     avl.Tree // padded claim number -> *Claim
	byClaimant avl.Tree // address -> latest claim number (int)
}

// Params are the inputs to New.
type Params struct {
	ID          uint64
	Poster      address
	Title       string
	Description string
	Link        string
	Tags        []string
	Denom       string
	IsGRC20     bool
	Reward      int64
	Slots       int
	Reviewers   []address
	Deadline    time.Time
	Now         time.Time
}

// PayoutKind says why escrowed funds move.
type PayoutKind string

const (
	PayoutWork   PayoutKind = "work"
	PayoutRefund PayoutKind = "refund"
)

// Payout is a transfer the escrow realm must execute. Claim is the claim
// number for work payouts and 0 for refunds.
type Payout struct {
	Kind   PayoutKind
	To     address
	Amount int64
	Claim  int
}

// New validates p and returns a funded, open campaign. When no reviewers are
// given, the poster reviews alone.
func New(p Params) (*Campaign, error) {
	if !p.Poster.IsValid() {
		return nil, errors.New("campaign: invalid poster address")
	}
	title := strings.TrimSpace(p.Title)
	if title == "" || len(title) > MaxTitleLen {
		return nil, errorf("campaign: title must be 1..%d bytes", MaxTitleLen)
	}
	if len(p.Description) > MaxDescriptionLen {
		return nil, errorf("campaign: description exceeds %d bytes", MaxDescriptionLen)
	}
	link := strings.TrimSpace(p.Link)
	if len(link) > MaxLinkLen {
		return nil, errorf("campaign: link exceeds %d bytes", MaxLinkLen)
	}
	tags, err := normalizeTags(p.Tags)
	if err != nil {
		return nil, err
	}
	if p.Denom == "" {
		return nil, errors.New("campaign: missing denomination")
	}
	if p.Reward <= 0 {
		return nil, errors.New("campaign: reward must be positive")
	}
	if p.Slots < 1 || p.Slots > MaxSlots {
		return nil, errorf("campaign: slots must be within 1..%d", MaxSlots)
	}
	if p.Reward > (1<<63-1)/int64(p.Slots) {
		return nil, errors.New("campaign: total overflows")
	}

	reviewers := p.Reviewers
	if len(reviewers) == 0 {
		reviewers = []address{p.Poster}
	}
	if len(reviewers) > MaxReviewers {
		return nil, errorf("campaign: at most %d reviewers", MaxReviewers)
	}
	seen := map[address]bool{}
	for _, r := range reviewers {
		if !r.IsValid() {
			return nil, errors.New("campaign: invalid reviewer address " + r.String())
		}
		if seen[r] {
			return nil, errors.New("campaign: duplicate reviewer " + r.String())
		}
		seen[r] = true
	}
	if !p.Deadline.IsZero() && !p.Deadline.After(p.Now) {
		return nil, errors.New("campaign: deadline must be in the future")
	}

	return &Campaign{
		ID:          p.ID,
		Poster:      p.Poster,
		Title:       title,
		Description: p.Description,
		Link:        link,
		Tags:        tags,
		Denom:       p.Denom,
		IsGRC20:     p.IsGRC20,
		Reward:      p.Reward,
		Slots:       p.Slots,
		Reviewers:   append([]address{}, reviewers...),
		Deadline:    p.Deadline,
		Status:      StatusOpen,
		CreatedAt:   p.Now,
	}, nil
}

// Claim records that claimant did the task, with a link to proof, and
// reserves a slot. It returns the claim number.
func (c *Campaign) Claim(claimant address, proof string, now time.Time) (int, error) {
	if c.Status != StatusOpen {
		return 0, ErrClosed
	}
	if c.Expired(now) {
		return 0, errors.New("campaign: the deadline has passed")
	}
	if !claimant.IsValid() {
		return 0, errors.New("campaign: invalid claimant address")
	}
	if claimant == c.Poster || c.IsReviewer(claimant) {
		return 0, errors.New("campaign: the poster and reviewers cannot claim")
	}
	proof = strings.TrimSpace(proof)
	if proof == "" || len(proof) > MaxLinkLen {
		return 0, errorf("campaign: proof link must be 1..%d bytes", MaxLinkLen)
	}
	if prev := c.ClaimOf(claimant); prev != nil && prev.Status != ClaimRejected {
		article := "a "
		if prev.Status == ClaimApproved {
			article = "an "
		}
		return 0, errors.New("campaign: you already have " + article + prev.Status.String() + " claim (#" + strconv.Itoa(prev.Number) + ")")
	}
	if c.FreeSlots() == 0 {
		return 0, errors.New("campaign: every slot is taken or awaiting review")
	}
	n := c.claims.Size() + 1
	c.claims.Set(claimKey(n), &Claim{Number: n, Claimant: claimant, Proof: proof, Status: ClaimPending, At: now})
	c.byClaimant.Set(claimant.String(), n)
	c.Pending++
	return n, nil
}

// Approve pays a pending claim. Any one reviewer may approve. When the last
// slot is paid, the campaign closes.
func (c *Campaign) Approve(caller address, number int, now time.Time) ([]Payout, error) {
	cl, err := c.pendingClaim(caller, number)
	if err != nil {
		return nil, err
	}
	cl.Status = ClaimApproved
	cl.ReviewedBy = caller
	cl.ReviewedAt = now
	c.Pending--
	c.Paid++
	if c.Status == StatusOpen && c.Paid == c.Slots {
		c.Status = StatusClosed
		c.ClosedAt = now
	}
	return []Payout{{Kind: PayoutWork, To: cl.Claimant, Amount: c.Reward, Claim: number}}, nil
}

// Reject turns down a pending claim and frees its slot. If the campaign has
// closed, the slot's reward goes back to the poster. The claimant may claim
// again while the campaign is open.
func (c *Campaign) Reject(caller address, number int, reason string, now time.Time) ([]Payout, error) {
	cl, err := c.pendingClaim(caller, number)
	if err != nil {
		return nil, err
	}
	reason = strings.TrimSpace(reason)
	if len(reason) > MaxNoteLen {
		return nil, errorf("campaign: reason exceeds %d bytes", MaxNoteLen)
	}
	cl.Status = ClaimRejected
	cl.ReviewedBy = caller
	cl.ReviewedAt = now
	cl.Reason = reason
	c.Pending--
	c.Rejected++
	if c.Status == StatusClosed {
		c.Refunded++
		return []Payout{{Kind: PayoutRefund, To: c.Poster, Amount: c.Reward}}, nil
	}
	return nil, nil
}

// Close stops new claims and refunds every slot that is neither paid nor
// awaiting review. The poster can close at any time; anyone can close once
// the deadline has passed.
func (c *Campaign) Close(caller address, now time.Time) ([]Payout, error) {
	if c.Status != StatusOpen {
		return nil, errors.New("campaign: already closed")
	}
	if caller != c.Poster && !c.Expired(now) {
		return nil, ErrUnauthorized
	}
	free := c.FreeSlots()
	c.Status = StatusClosed
	c.ClosedAt = now
	if free == 0 {
		return nil, nil
	}
	c.Refunded += free
	return []Payout{{Kind: PayoutRefund, To: c.Poster, Amount: c.Reward * int64(free)}}, nil
}

func (c *Campaign) pendingClaim(caller address, number int) (*Claim, error) {
	if !c.IsReviewer(caller) {
		return nil, ErrUnauthorized
	}
	cl := c.GetClaim(number)
	if cl == nil {
		return nil, ErrBadClaim
	}
	if cl.Status != ClaimPending {
		return nil, errors.New("campaign: claim #" + strconv.Itoa(number) + " is already " + cl.Status.String())
	}
	return cl, nil
}

// Total is the amount escrowed when the campaign was posted.
func (c *Campaign) Total() int64 { return c.Reward * int64(c.Slots) }

// Escrowed is the amount still held for this campaign.
func (c *Campaign) Escrowed() int64 {
	return c.Reward * int64(c.Slots-c.Paid-c.Refunded)
}

// PaidOut is the amount paid to claimants so far.
func (c *Campaign) PaidOut() int64 { return c.Reward * int64(c.Paid) }

// FreeSlots is how many more claims an open campaign can take.
func (c *Campaign) FreeSlots() int {
	if c.Status != StatusOpen {
		return 0
	}
	return c.Slots - c.Paid - c.Pending - c.Refunded
}

// Expired reports whether the campaign has a deadline that has passed.
func (c *Campaign) Expired(now time.Time) bool {
	return !c.Deadline.IsZero() && !now.Before(c.Deadline)
}

// IsReviewer reports whether addr may approve and reject claims.
func (c *Campaign) IsReviewer(addr address) bool {
	for _, r := range c.Reviewers {
		if r == addr {
			return true
		}
	}
	return false
}

// ClaimCount is the number of claims ever submitted.
func (c *Campaign) ClaimCount() int { return c.claims.Size() }

// GetClaim returns claim number (1-based), or nil.
func (c *Campaign) GetClaim(number int) *Claim {
	if number < 1 {
		return nil
	}
	v := c.claims.Get(claimKey(number))
	if v == nil {
		return nil
	}
	return v.(*Claim)
}

// ClaimOf returns addr's most recent claim, or nil.
func (c *Campaign) ClaimOf(addr address) *Claim {
	v := c.byClaimant.Get(addr.String())
	if v == nil {
		return nil
	}
	return c.GetClaim(v.(int))
}

// Claims returns up to limit claims, newest first, after skipping offset
// claims. With a status filter, only matching claims are counted.
func (c *Campaign) Claims(status *ClaimStatus, offset, limit int) (out []*Claim, more bool) {
	c.claims.ReverseIterate("", "", func(_ string, v any) bool {
		cl := v.(*Claim)
		if status != nil && cl.Status != *status {
			return false
		}
		if offset > 0 {
			offset--
			return false
		}
		if len(out) == limit {
			more = true
			return true
		}
		out = append(out, cl)
		return false
	})
	return out, more
}

// ParseAddresses splits a comma or whitespace separated address list.
func ParseAddresses(s string) []address {
	var out []address
	for _, f := range strings.FieldsFunc(s, func(r rune) bool { return r == ',' || r == ' ' || r == '\n' }) {
		out = append(out, address(f))
	}
	return out
}

func normalizeTags(in []string) ([]string, error) {
	var out []string
	seen := map[string]bool{}
	for _, t := range in {
		t = strings.ToLower(strings.TrimSpace(t))
		if t == "" || seen[t] {
			continue
		}
		if len(t) > MaxTagLen {
			return nil, errorf("campaign: tag %q exceeds %d bytes", t, MaxTagLen)
		}
		for _, r := range t {
			if !(r >= 'a' && r <= 'z' || r >= '0' && r <= '9' || r == '-') {
				return nil, errors.New("campaign: tags may only contain a-z, 0-9 and '-'")
			}
		}
		seen[t] = true
		out = append(out, t)
	}
	if len(out) > MaxTags {
		return nil, errorf("campaign: at most %d tags", MaxTags)
	}
	return out, nil
}

func claimKey(n int) string {
	s := strconv.Itoa(n)
	for len(s) < 6 {
		s = "0" + s
	}
	return s
}

func errorf(format string, args ...any) error {
	return errors.New(ufmt.Sprintf(format, args...))
}

package campaigns

import (
	"chain"
	"net/url"
	"strconv"
	"strings"

	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/campaign/v0"
	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/jsonw/v0"
	"gno.land/p/nt/avl/v0"
	"gno.land/r/nt/grc20reg/v0"
)

const (
	apiMaxLimit = 50
	apiMaxScan  = 2000
)

// renderAPI serves JSON for the web app, under Render("api/..."):
//
//	api/stats                                       counts, escrow totals, council, paused
//	api/campaigns?status=&tag=&page=&limit=         newest first; status "all" or empty for every campaign
//	api/campaign/<id>                               one campaign
//	api/campaign/<id>/claims?status=&page=&limit=   its claims, newest first
//	api/campaign/<id>/claimant/<address>            {"claim": an address's latest claim, or null}
//	api/user/<address>?page=&limit=                 campaigns an address is involved in, with roles and their claim
func renderAPI(route string, q url.Values) string {
	parts := strings.Split(route, "/")
	switch {
	case route == "api/stats":
		return apiStats()
	case route == "api/campaigns":
		status := q.Get("status")
		if _, ok := campaign.ParseStatus(status); status != "" && status != "all" && !ok {
			return apiError("unknown status")
		}
		limit := limitOf(q)
		list, more := scan(status, strings.ToLower(q.Get("tag")), (pageOf(q)-1)*limit, limit)
		items := make([]string, len(list))
		for i, c := range list {
			items[i] = campaignJSON(c, false)
		}
		return jsonw.Obj("items", jsonw.Arr(items), "more", jsonw.Bool(more))
	case len(parts) >= 3 && len(parts) <= 5 && parts[1] == "campaign":
		id, err := strconv.ParseUint(parts[2], 10, 64)
		if err != nil {
			return apiError("invalid id")
		}
		c := getCampaign(id)
		if c == nil {
			return apiError("not found")
		}
		if len(parts) == 3 {
			return campaignJSON(c, true)
		}
		if len(parts) == 4 && parts[3] == "claims" {
			return apiClaims(c, q)
		}
		if len(parts) == 5 && parts[3] == "claimant" {
			addr := address(parts[4])
			if !addr.IsValid() {
				return apiError("invalid address")
			}
			mine := jsonw.Null
			if cl := c.ClaimOf(addr); cl != nil {
				mine = claimJSON(cl)
			}
			return jsonw.Obj("claim", mine)
		}
		return apiError("unknown endpoint")
	case len(parts) == 3 && parts[1] == "user":
		return apiUser(address(parts[2]), q)
	}
	return apiError("unknown endpoint")
}

func apiStats() string {
	var escrow []string
	escrowed.Iterate("", "", func(k string, v any) bool {
		if amt := v.(int64); amt > 0 {
			escrow = append(escrow, jsonw.Obj(append([]string{"amount", jsonw.Int(amt)}, denomFields(k, grc20reg.Get(k) != nil)...)...))
		}
		return false
	})
	return jsonw.Obj(
		"total", jsonw.Int(int64(campaigns.Size())),
		"open", jsonw.Int(int64(statusCount[campaign.StatusOpen])),
		"closed", jsonw.Int(int64(statusCount[campaign.StatusClosed])),
		"escrow", jsonw.Arr(escrow),
		"council", jsonw.String(council.Owner().String()),
		"paused", jsonw.Bool(paused),
		"realmAddress", jsonw.String(chain.PackageAddress(realmPath).String()),
		"claimShareBps", jsonw.Int(ClaimShareBps),
		"maxSlots", jsonw.Int(campaign.MaxSlots),
	)
}

func apiClaims(c *campaign.Campaign, q url.Values) string {
	var st *campaign.ClaimStatus
	if s := q.Get("status"); s != "" && s != "all" {
		parsed, ok := campaign.ParseClaimStatus(s)
		if !ok {
			return apiError("unknown status")
		}
		st = &parsed
	}
	limit := limitOf(q)
	list, more := c.Claims(st, (pageOf(q)-1)*limit, limit)
	items := make([]string, len(list))
	for i, cl := range list {
		items[i] = claimJSON(cl)
	}
	return jsonw.Obj("items", jsonw.Arr(items), "more", jsonw.Bool(more))
}

func apiUser(addr address, q url.Values) string {
	if !addr.IsValid() {
		return apiError("invalid address")
	}
	limit := limitOf(q)
	var items []string
	more := false
	if v := byUser.Get(addr.String()); v != nil {
		ids := v.(*avl.Tree)
		ids.ReverseIterateByOffset((pageOf(q)-1)*limit, limit, func(k string, _ any) bool {
			if cv := campaigns.Get(k); cv != nil {
				c := cv.(*campaign.Campaign)
				mine := jsonw.Null
				if cl := c.ClaimOf(addr); cl != nil {
					mine = claimJSON(cl)
				}
				items = append(items, jsonw.Obj("campaign", campaignJSON(c, false), "roles", jsonw.Strings(roles(c, addr)), "claim", mine))
			}
			return false
		})
		more = ids.Size() > pageOf(q)*limit
	}
	return jsonw.Obj("items", jsonw.Arr(items), "more", jsonw.Bool(more))
}

func campaignJSON(c *campaign.Campaign, full bool) string {
	fields := []string{
		"id", jsonw.Uint(c.ID),
		"title", jsonw.String(c.Title),
		"tags", jsonw.Strings(c.Tags),
		"status", jsonw.String(c.Status.String()),
		"poster", jsonw.String(c.Poster.String()),
		"reward", jsonw.Int(c.Reward),
		"slots", jsonw.Int(int64(c.Slots)),
		"paid", jsonw.Int(int64(c.Paid)),
		"pending", jsonw.Int(int64(c.Pending)),
		"rejected", jsonw.Int(int64(c.Rejected)),
		"refunded", jsonw.Int(int64(c.Refunded)),
		"freeSlots", jsonw.Int(int64(c.FreeSlots())),
		"claims", jsonw.Int(int64(c.ClaimCount())),
		"total", jsonw.Int(c.Total()),
		"escrowed", jsonw.Int(c.Escrowed()),
		"paidOut", jsonw.Int(c.PaidOut()),
		"deadline", jsonw.Time(c.Deadline),
		"createdAt", jsonw.Time(c.CreatedAt),
	}
	fields = append(fields, denomFields(c.Denom, c.IsGRC20)...)
	if full {
		fields = append(fields,
			"description", jsonw.String(c.Description),
			"link", jsonw.String(c.Link),
			"reviewers", jsonw.Addresses(c.Reviewers),
			"closedAt", jsonw.Time(c.ClosedAt),
			"claimShareBps", jsonw.Int(ClaimShareBps),
		)
	}
	return jsonw.Obj(fields...)
}

func claimJSON(cl *campaign.Claim) string {
	reviewer := ""
	if cl.ReviewedBy != "" {
		reviewer = cl.ReviewedBy.String()
	}
	return jsonw.Obj(
		"number", jsonw.Int(int64(cl.Number)),
		"claimant", jsonw.String(cl.Claimant.String()),
		"proof", jsonw.String(cl.Proof),
		"status", jsonw.String(cl.Status.String()),
		"at", jsonw.Time(cl.At),
		"reviewedBy", jsonw.String(reviewer),
		"reviewedAt", jsonw.Time(cl.ReviewedAt),
		"reason", jsonw.String(cl.Reason),
	)
}

// denomFields describes how to display amounts of denom.
func denomFields(denom string, isGRC20 bool) []string {
	symbol, decimals := symbolOf(denom, isGRC20)
	return []string{
		"denom", jsonw.String(denom),
		"isGRC20", jsonw.Bool(isGRC20),
		"symbol", jsonw.String(symbol),
		"decimals", jsonw.Int(int64(decimals)),
	}
}

func limitOf(q url.Values) int {
	n, err := strconv.Atoi(q.Get("limit"))
	if err != nil || n < 1 {
		return 20
	}
	if n > apiMaxLimit {
		return apiMaxLimit
	}
	return n
}

func apiError(msg string) string {
	return jsonw.Obj("error", jsonw.String(msg))
}

// Package campaigns is Guildhall's escrow for many-hands tasks: a fixed
// reward per claim, a fixed number of slots, and one reviewer approval per
// claim. "10 GNOT each to the first 100 people who write about X" is one
// campaign holding 1000 GNOT.
//
// Each approved claim pays the claimant and writes a reputation record to
// gno.land/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/reputation
// at ClaimShareBps of a normal record's weight, vouched for by the reviewer
// who approved it. Small, repeatable tasks therefore count for something
// without outweighing reviewed bounty work.
//
// The rules live in gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/campaign.
// This realm holds the funds, authenticates callers, moves coins, and
// renders the campaigns.
package campaigns

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"

	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/campaign/v0"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ownable/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/reputation"
	"gno.land/r/nt/grc20reg/v0"
)

const (
	// ClaimShareBps is the weight of a claim's reputation record relative to
	// a fully approved bounty milestone (10000).
	ClaimShareBps = 500

	maxDeadlineDays = 365
)

var (
	campaigns   avl.Tree // padded id -> *campaign.Campaign
	lastID      uint64
	byUser      avl.Tree // address -> *avl.Tree(padded id -> struct{})
	statusCount = map[campaign.Status]int{}
	escrowed    avl.Tree // denom key -> int64 currently held

	council *ownable.Ownable
	paused  bool
)

// InitialCouncil owns this namespace and is the only key that can deploy
// here. It can pause new campaigns until TransferCouncil hands the seat on.
const InitialCouncil address = "g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm"

func init() {
	council = ownable.NewWithAddress(InitialCouncil)
}

// ---------------------------------------------------------------------------
// Posting

// PostCampaign posts a campaign funded with the native coins sent along with
// the call, which must equal reward × slots. reviewers is a comma-separated
// address list (empty means the poster reviews alone); any one of them can
// approve a claim. deadlineDays closes the campaign to new claims after that
// many days (0: no deadline).
func PostCampaign(cur realm, title, description, link, tags, reviewers string, reward int64, slots, deadlineDays int) uint64 {
	assertNotPaused()
	if !cur.Previous().IsUserCall() {
		panic("campaigns: native campaigns must be posted directly by a user (maketx call with -send)")
	}
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Amount <= 0 {
		panic("campaigns: send exactly one coin denomination to fund the campaign")
	}
	c := newCampaign(cur, sent[0].Denom, false, title, description, link, tags, reviewers, reward, slots, deadlineDays)
	if c.Total() != sent[0].Amount {
		panic(ufmt.Sprintf("campaigns: %d slots × %d is %d%s but %d%s was sent",
			c.Slots, c.Reward, c.Total(), c.Denom, sent[0].Amount, sent[0].Denom))
	}
	return store(c)
}

// PostCampaignGRC20 posts a campaign funded with a registered GRC20 token.
// The caller must first approve this realm's address for reward × slots on
// the token; this call pulls the funds into escrow.
func PostCampaignGRC20(cur realm, tokenKey, title, description, link, tags, reviewers string, reward int64, slots, deadlineDays int) uint64 {
	assertNotPaused()
	if grc20reg.Get(tokenKey) == nil {
		panic("campaigns: unknown token " + strconv.Quote(tokenKey))
	}
	if len(unsafe.OriginSend()) > 0 && cur.Previous().IsUserCall() {
		panic("campaigns: do not send native coins with a GRC20 campaign")
	}
	c := newCampaign(cur, tokenKey, true, title, description, link, tags, reviewers, reward, slots, deadlineDays)
	grc20reg.TransferFrom(0, cur, tokenKey, c.Poster, cur.Address(), c.Total())
	return store(c)
}

func newCampaign(cur realm, denom string, isGRC20 bool, title, description, link, tags, reviewers string, reward int64, slots, deadlineDays int) *campaign.Campaign {
	if deadlineDays < 0 || deadlineDays > maxDeadlineDays {
		panic(ufmt.Sprintf("campaigns: deadline must be 0..%d days", maxDeadlineDays))
	}
	now := time.Now()
	var deadline time.Time
	if deadlineDays > 0 {
		deadline = now.Add(time.Duration(deadlineDays) * 24 * time.Hour)
	}
	c, err := campaign.New(campaign.Params{
		ID:          lastID + 1,
		Poster:      cur.Previous().Address(),
		Title:       title,
		Description: description,
		Link:        link,
		Tags:        strings.Split(tags, ","),
		Denom:       denom,
		IsGRC20:     isGRC20,
		Reward:      reward,
		Slots:       slots,
		Reviewers:   campaign.ParseAddresses(reviewers),
		Deadline:    deadline,
		Now:         now,
	})
	check(err)
	return c
}

func store(c *campaign.Campaign) uint64 {
	lastID = c.ID
	campaigns.Set(idKey(c.ID), c)
	statusCount[c.Status]++
	addEscrow(c, c.Total())
	index(c.Poster, c.ID)
	for _, r := range c.Reviewers {
		index(r, c.ID)
	}
	emit("CampaignPosted", c,
		"poster", c.Poster.String(),
		"denom", c.Denom,
		"reward", strconv.FormatInt(c.Reward, 10),
		"slots", strconv.Itoa(c.Slots))
	return c.ID
}

// ---------------------------------------------------------------------------
// Claims

// Claim asks to be paid for doing the task once. proof is a link to the work
// (the post, the PR, the page). It reserves a slot until a reviewer decides.
// Returns the claim number.
func Claim(cur realm, id uint64, proof string) int {
	c := mustGet(id)
	caller := cur.Previous().Address()
	n, err := c.Claim(caller, proof, time.Now())
	check(err)
	index(caller, id)
	emit("CampaignClaimed", c, "claim", strconv.Itoa(n), "claimant", caller.String())
	return n
}

// ApproveClaim pays a pending claim. Any reviewer of the campaign.
func ApproveClaim(cur realm, id uint64, claim int) {
	c := mustGet(id)
	before := c.Status
	caller := cur.Previous().Address()
	payouts, err := c.Approve(caller, claim, time.Now())
	check(err)
	settle(0, cur, c, payouts, caller)
	moved(c, before)
}

// RejectClaim turns down a pending claim and frees its slot. Any reviewer of
// the campaign.
func RejectClaim(cur realm, id uint64, claim int, reason string) {
	c := mustGet(id)
	caller := cur.Previous().Address()
	payouts, err := c.Reject(caller, claim, reason, time.Now())
	check(err)
	emit("CampaignClaimRejected", c, "claim", strconv.Itoa(claim), "reviewer", caller.String())
	settle(0, cur, c, payouts, caller)
}

// Close stops new claims and refunds the free slots to the poster. The
// poster can close at any time; anyone can close after the deadline. Pending
// claims can still be approved or rejected afterwards.
func Close(cur realm, id uint64) {
	c := mustGet(id)
	before := c.Status
	payouts, err := c.Close(cur.Previous().Address(), time.Now())
	check(err)
	settle(0, cur, c, payouts, "")
	moved(c, before)
	emit("CampaignClosed", c)
}

// ---------------------------------------------------------------------------
// Council

// Council is the address that can pause new campaigns.
func Council() address {
	return council.Owner()
}

// TransferCouncil hands the council seat to another address. Council only.
func TransferCouncil(cur realm, newCouncil address) {
	if err := council.TransferOwnership(0, cur, newCouncil); err != nil {
		panic(err.Error())
	}
	chain.Emit("CampaignsCouncilChanged", "council", newCouncil.String())
}

// SetPaused stops or resumes new campaigns. Existing campaigns, claims and
// payouts are never paused. Council only.
func SetPaused(cur realm, p bool) {
	council.AssertOwnedBy(cur.Previous().Address())
	paused = p
	chain.Emit("CampaignsPaused", "paused", strconv.FormatBool(p))
}

// ---------------------------------------------------------------------------
// Queries

// Count is the number of campaigns ever posted.
func Count() int {
	return campaigns.Size()
}

// CountByStatus counts campaigns in a status ("open" or "closed").
func CountByStatus(status string) int {
	s, ok := campaign.ParseStatus(status)
	if !ok {
		return 0
	}
	return statusCount[s]
}

// Escrowed is the amount of denom (a native denom or a grc20reg key) held.
func Escrowed(denom string) int64 {
	if v := escrowed.Get(denom); v != nil {
		return v.(int64)
	}
	return 0
}

// IsPaused reports whether new campaigns are paused.
func IsPaused() bool {
	return paused
}

// ---------------------------------------------------------------------------
// Internals

func settle(_ int, rlm realm, c *campaign.Campaign, payouts []campaign.Payout, reviewer address) {
	for _, p := range payouts {
		transfer(0, rlm, c, p.To, p.Amount)
		addEscrow(c, -p.Amount)
		emit("CampaignPayout", c,
			"kind", string(p.Kind),
			"to", p.To.String(),
			"amount", strconv.FormatInt(p.Amount, 10),
			"claim", strconv.Itoa(p.Claim))
		if p.Kind != campaign.PayoutWork {
			continue
		}
		cl := c.GetClaim(p.Claim)
		reputation.AddRecord(cross(rlm),
			p.To,
			c.Poster,
			[]address{reviewer},
			ClaimShareBps,
			p.Amount,
			c.Denom,
			clip(c.Title, 300),
			cl.Proof,
			ufmt.Sprintf("c%d/%d", c.ID, p.Claim),
			false,
		)
	}
}

func transfer(_ int, rlm realm, c *campaign.Campaign, to address, amount int64) {
	if amount <= 0 {
		return
	}
	if c.IsGRC20 {
		grc20reg.Transfer(0, rlm, c.Denom, to, amount)
		return
	}
	bk := banker.NewBanker(banker.BankerTypeRealmSend, rlm)
	bk.SendCoins(rlm.Address(), to, chain.Coins{{Denom: c.Denom, Amount: amount}})
}

func mustGet(id uint64) *campaign.Campaign {
	c := getCampaign(id)
	if c == nil {
		panic("campaigns: campaign " + strconv.FormatUint(id, 10) + " not found")
	}
	return c
}

func getCampaign(id uint64) *campaign.Campaign {
	v := campaigns.Get(idKey(id))
	if v == nil {
		return nil
	}
	return v.(*campaign.Campaign)
}

func moved(c *campaign.Campaign, before campaign.Status) {
	if c.Status != before {
		statusCount[before]--
		statusCount[c.Status]++
	}
}

func addEscrow(c *campaign.Campaign, delta int64) {
	cur := int64(0)
	if v := escrowed.Get(c.Denom); v != nil {
		cur = v.(int64)
	}
	escrowed.Set(c.Denom, cur+delta)
}

func index(addr address, id uint64) {
	if addr == "" {
		return
	}
	var t *avl.Tree
	if v := byUser.Get(addr.String()); v != nil {
		t = v.(*avl.Tree)
	} else {
		t = avl.NewTree()
		byUser.Set(addr.String(), t)
	}
	t.Set(idKey(id), struct{}{})
}

func assertNotPaused() {
	if paused {
		panic("campaigns: posting is paused by the council")
	}
}

func check(err error) {
	if err != nil {
		panic(err.Error())
	}
}

func emit(event string, c *campaign.Campaign, kv ...string) {
	attrs := append([]string{"id", strconv.FormatUint(c.ID, 10), "status", c.Status.String()}, kv...)
	chain.Emit(event, attrs...)
}

func idKey(id uint64) string {
	s := strconv.FormatUint(id, 10)
	for len(s) < 12 {
		s = "0" + s
	}
	return s
}

func clip(s string, n int) string {
	if len(s) <= n {
		return s
	}
	for n > 0 && !utf8.RuneStart(s[n]) {
		n--
	}
	return s[:n]
}

package campaigns

import (
	"chain"
	"net/url"
	"strconv"
	"strings"

	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/campaign/v0"
	"gno.land/p/moul/txlink/v0"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/reputation"
	"gno.land/r/nt/grc20reg/v0"
)

const (
	realmPath = "gno.land/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/campaigns"
	realmURL  = "/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/campaigns"
	repURL    = "/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/reputation"
	pageSize  = 20
)

// Render serves the campaigns:
//
//	""             every campaign (?status=open|closed|all, ?tag=x, ?page=N)
//	<id>           a campaign and its claims (?claims=pending|approved|rejected|all, ?page=N)
//	u/<address>    campaigns an address posted, reviews or claimed
//	post           how to post a campaign
func Render(path string) string {
	route, query := splitQuery(path)
	parts := strings.Split(route, "/")
	switch {
	case parts[0] == "api":
		return renderAPI(route, query)
	case route == "":
		return renderBoard(query)
	case route == "post":
		return renderPost()
	case len(parts) == 2 && parts[0] == "u":
		return renderUser(address(parts[1]), pageOf(query))
	case len(parts) == 1:
		id, err := strconv.ParseUint(strings.TrimPrefix(parts[0], "c"), 10, 64)
		if err != nil {
			return notFound()
		}
		return renderCampaign(id, query)
	}
	return notFound()
}

func renderBoard(q url.Values) string {
	status := q.Get("status")
	if status == "" {
		status = "open"
	}
	tag := strings.ToLower(q.Get("tag"))
	page := pageOf(q)

	var b strings.Builder
	b.WriteString("# Guildhall Campaigns\n\n")
	b.WriteString("A fixed reward for each person who does a task, up to a set number of people. A reviewer checks each claim before it pays.\n\n")
	b.WriteString(ufmt.Sprintf("**%d** open · **%d** closed · **%s** in escrow\n\n",
		statusCount[campaign.StatusOpen], statusCount[campaign.StatusClosed], escrowSummary()))
	if paused {
		b.WriteString("> Posting new campaigns is paused by the council. Existing campaigns are unaffected.\n\n")
	} else {
		b.WriteString("[+ Post a campaign](" + realmURL + ":post)\n\n")
	}

	var tabs []string
	for _, s := range []string{"open", "closed", "all"} {
		label := s
		if s == status {
			label = "**" + s + "**"
		}
		link := realmURL + "?status=" + s
		if tag != "" {
			link += "&tag=" + url.QueryEscape(tag)
		}
		tabs = append(tabs, "["+label+"]("+link+")")
	}
	b.WriteString(strings.Join(tabs, " · "))
	if tag != "" {
		b.WriteString(" · tag: `" + sanitize.InlineText(tag) + "` ([clear](" + realmURL + "?status=" + url.QueryEscape(status) + "))")
	}
	b.WriteString("\n\n")

	list, more := scan(status, tag, (page-1)*pageSize, pageSize)
	if len(list) == 0 {
		b.WriteString("_No campaigns here yet._\n")
	} else {
		b.WriteString("| # | Campaign | Reward each | Slots paid | Free | Status | Poster |\n|---:|---|---:|---:|---:|---|---|\n")
		for _, c := range list {
			b.WriteString(ufmt.Sprintf("| %d | [%s](%s:%d)%s | %s | %d/%d | %d | %s | %s |\n",
				c.ID, sanitize.TableCell(c.Title), realmURL, c.ID, tagSuffix(c), formatAmount(c, c.Reward),
				c.Paid, c.Slots, c.FreeSlots(), c.Status.String(), person(c.Poster)))
		}
	}

	var nav []string
	if page > 1 {
		nav = append(nav, "[← newer]("+boardLink(status, tag, page-1)+")")
	}
	if more {
		nav = append(nav, "[older →]("+boardLink(status, tag, page+1)+")")
	}
	if len(nav) > 0 {
		b.WriteString("\n" + strings.Join(nav, " · ") + "\n")
	}
	return b.String()
}

// scan lists campaigns newest first, filtered by status ("", "all" or a
// status name) and tag.
func scan(status, tag string, skip, limit int) (list []*campaign.Campaign, more bool) {
	want, filtered := campaign.ParseStatus(status)
	scanned := 0
	campaigns.ReverseIterate("", "", func(_ string, v any) bool {
		scanned++
		if scanned > apiMaxScan {
			more = true
			return true
		}
		c := v.(*campaign.Campaign)
		if filtered && c.Status != want {
			return false
		}
		if tag != "" && !hasTag(c, tag) {
			return false
		}
		if skip > 0 {
			skip--
			return false
		}
		if len(list) == limit {
			more = true
			return true
		}
		list = append(list, c)
		return false
	})
	return list, more
}

func renderCampaign(id uint64, q url.Values) string {
	c := getCampaign(id)
	if c == nil {
		return notFound()
	}
	var b strings.Builder
	b.WriteString(ufmt.Sprintf("# Campaign %d: %s\n\n", c.ID, sanitize.InlineText(c.Title)))
	b.WriteString(ufmt.Sprintf("**%s** · %s each · %d of %d slots paid · posted %s",
		strings.ToUpper(c.Status.String()), formatAmount(c, c.Reward), c.Paid, c.Slots, c.CreatedAt.UTC().Format("2006-01-02")))
	if len(c.Tags) > 0 {
		var ts []string
		for _, t := range c.Tags {
			ts = append(ts, "["+t+"]("+realmURL+"?status=all&tag="+url.QueryEscape(t)+")")
		}
		b.WriteString(" · " + strings.Join(ts, " "))
	}
	b.WriteString("\n\n")

	if c.Description != "" {
		b.WriteString(sanitize.Block(c.Description) + "\n\n")
	}
	if c.Link != "" {
		b.WriteString("Reference: " + linkOrText(c.Link) + "\n\n")
	}

	b.WriteString("| | |\n|---|---|\n")
	b.WriteString("| Posted by | " + person(c.Poster) + " |\n")
	var revs []string
	for _, r := range c.Reviewers {
		revs = append(revs, person(r))
	}
	b.WriteString("| Reviewers (any one approves) | " + strings.Join(revs, ", ") + " |\n")
	b.WriteString(ufmt.Sprintf("| Slots | %d paid · %d awaiting review · %d free · %d refunded |\n", c.Paid, c.Pending, c.FreeSlots(), c.Refunded))
	if !c.Deadline.IsZero() {
		b.WriteString("| Claims close | " + c.Deadline.UTC().Format("2006-01-02 15:04 UTC") + " |\n")
	}
	b.WriteString("| Escrow | " + formatAmount(c, c.Escrowed()) + " held · " + formatAmount(c, c.PaidOut()) + " paid |\n")
	b.WriteString(ufmt.Sprintf("| Reputation | each paid claim is a record at %s weight |\n\n", bps(ClaimShareBps)))

	b.WriteString(renderActions(c))

	filter := q.Get("claims")
	if filter == "" {
		filter = "all"
	}
	page := pageOf(q)
	var tabs []string
	for _, s := range []string{"pending", "approved", "rejected", "all"} {
		label := s
		if s == filter {
			label = "**" + s + "**"
		}
		tabs = append(tabs, "["+label+"]("+realmURL+":"+idStr(c)+"?claims="+s+")")
	}
	b.WriteString(ufmt.Sprintf("## Claims (%d)\n\n", c.ClaimCount()))
	b.WriteString(strings.Join(tabs, " · ") + "\n\n")

	var st *campaign.ClaimStatus
	if s, ok := campaign.ParseClaimStatus(filter); ok {
		st = &s
	}
	list, more := c.Claims(st, (page-1)*pageSize, pageSize)
	if len(list) == 0 {
		b.WriteString("_No claims here yet._\n")
		return b.String()
	}
	b.WriteString("| # | Claimant | Proof | Status | |\n|---:|---|---|---|---|\n")
	for _, cl := range list {
		status := claimStatus(cl)
		action := ""
		if cl.Status == campaign.ClaimPending {
			n := strconv.Itoa(cl.Number)
			action = "[approve](" + txlink.NewLink("ApproveClaim").AddArgs("id", idStr(c), "claim", n).URL() + ") · " +
				"[reject](" + txlink.NewLink("RejectClaim").AddArgs("id", idStr(c), "claim", n, "reason", "").URL() + ")"
		} else if cl.Status == campaign.ClaimRejected && cl.Reason != "" {
			action = sanitize.TableCell(cl.Reason)
		}
		b.WriteString(ufmt.Sprintf("| %d | %s | %s | %s | %s |\n", cl.Number, person(cl.Claimant), linkOrText(cl.Proof), status, action))
	}
	if page > 1 || more {
		var nav []string
		if page > 1 {
			nav = append(nav, ufmt.Sprintf("[← newer](%s:%s?claims=%s&page=%d)", realmURL, idStr(c), filter, page-1))
		}
		if more {
			nav = append(nav, ufmt.Sprintf("[older →](%s:%s?claims=%s&page=%d)", realmURL, idStr(c), filter, page+1))
		}
		b.WriteString("\n" + strings.Join(nav, " · ") + "\n")
	}
	return b.String()
}

// renderActions lists the transactions anyone might want to send, as gnoweb
// transaction links. The chain enforces who may call them.
func renderActions(c *campaign.Campaign) string {
	if c.Status != campaign.StatusOpen {
		return ""
	}
	var acts []string
	if c.FreeSlots() > 0 {
		acts = append(acts, "[Claim a slot]("+txlink.NewLink("Claim").AddArgs("id", idStr(c), "proof", "").URL()+")")
	}
	acts = append(acts, "[Close and refund free slots (poster)]("+txlink.NewLink("Close").AddArgs("id", idStr(c)).URL()+")")
	return "## Actions\n\n" + strings.Join(acts, " · ") + "\n\n"
}

func renderUser(addr address, page int) string {
	if !addr.IsValid() {
		return notFound()
	}
	var b strings.Builder
	b.WriteString("# Campaigns for " + addr.String() + "\n\n")
	b.WriteString(ufmt.Sprintf("Reputation: **%d** (%s) · [profile](%s:u/%s)\n\n",
		reputation.Score(addr), reputation.Level(addr), repURL, addr.String()))
	v := byUser.Get(addr.String())
	if v == nil {
		b.WriteString("_Not involved in any campaign yet._\n")
		return b.String()
	}
	ids := v.(*avl.Tree)
	b.WriteString("| # | Campaign | Role | Reward each | Their claim | Status |\n|---:|---|---|---:|---|---|\n")
	ids.ReverseIterateByOffset((page-1)*pageSize, pageSize, func(k string, _ any) bool {
		cv := campaigns.Get(k)
		if cv == nil {
			return false
		}
		c := cv.(*campaign.Campaign)
		mine := "-"
		if cl := c.ClaimOf(addr); cl != nil {
			mine = ufmt.Sprintf("#%d %s", cl.Number, cl.Status.String())
		}
		b.WriteString(ufmt.Sprintf("| %d | [%s](%s:%d) | %s | %s | %s | %s |\n",
			c.ID, sanitize.TableCell(c.Title), realmURL, c.ID, strings.Join(roles(c, addr), ", "), formatAmount(c, c.Reward), mine, c.Status.String()))
		return false
	})
	if ids.Size() > page*pageSize {
		b.WriteString(ufmt.Sprintf("\n[older →](%s:u/%s?page=%d)\n", realmURL, addr.String(), page+1))
	}
	return b.String()
}

